#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <boost/log/core.hpp>
#include <boost/log/trivial.hpp>
#include <boost/log/expressions.hpp>
#include <boost/log/sinks/sync_frontend.hpp>
#include <boost/log/sinks/text_file_backend.hpp>
#include <boost/log/utility/setup/common_attributes.hpp>

using namespace boost::asio;
using namespace boost::log;
using namespace boost::log::trivial;
using namespace boost::log::expressions;
using namespace boost::log::sinks;

class MonitoringClient {
public:
    MonitoringClient(const std::string& server_url, const std::string& server_port) :
        m_server_url(server_url), m_server_port(server_port) {}

    void start() {
        // Start a new thread for each client request
        boost::thread([this] { this->makeRequest(); });
    }

private:
    void makeRequest() {
        try {
            // Create an IO service to handle HTTP requests
            io_service service;

            // Set up logging
            boost::log::core::get()->set_filter(severity >= info);
            text_file_backend backend(keywords::file_name = "monitoring_client.log");
            shared_ptr<sinks::synchronous_sink<sinks::text_file_backend>> sink(new sinks::synchronous_sink<sinks::text_file_backend>(backend));
            core::get()->add_sink(sink);

            // Set up rate limiting
            int max_requests = 10;
            int requests_per_minute = 5;
            std::chrono::seconds one_minute(60);

            while (true) {
                // Make a GET request to the server
                auto response = co_await http::async_get(service, m_server_url + ":" + m_server_port, "/monitoring");

                // Check if the response is valid
                bool valid_response = false;
                if (response.result() == http::status::ok) {
                    std::string body = co_await async_read(service, response);
                    auto json = nlohmann::json::parse(body);
                    if (json["valid"] == true) {
                        valid_response = true;
                    }
                }

                // Log the request and response status
                info("Request made to server");
                info("Response status: " + std::to_string(response.result()));
                if (valid_response) {
                    info("Response is valid");
                } else {
                    warning("Response is not valid");
                }

                // Enforce rate limiting
                auto current_time = std::chrono::system_clock::now();
                int requests_made = 0;
                for (auto& it : m_request_times) {
                    if (current_time - it < one_minute) {
                        requests_made++;
                    } else {
                        break;
                    }
                }
                if (requests_made >= max_requests) {
                    info("Reached rate limit. Sleeping for " + std::to_string(one_minute));
                    co_await sleep_for(one_minute);
                } else {
                    m_request_times.push_back(current_time);
                }
            }
        } catch (const boost::system::error_code& ec) {
            error("Error making request: " + ec.message());
        }
    }

    std::string m_server_url;
    std::string m_server_port;
    std::vector<std::chrono::time_point<std::chrono::system_clock>> m_request_times;
};
