```cpp
#include <iostream>
#include <string>
#include <boost/log/core.hpp>
#include <boost/log/expressions.hpp>
#include <boost/log/sinks/text_file_backend.hpp>
#include <boost/log/utility/setup/common_attributes.hpp>
#include <boost/log/support/date_time.hpp>

using namespace std;

// Define a custom logger class
class Logger {
public:
    // Constructor
    Logger(const string& name, const string& path) : mName(name), mPath(path) {}

    // Destructor
    ~Logger() {}

    // Set the log level
    void setLogLevel(boost::log::trivial::severity_level level) {
        mLogLevel = level;
    }

    // Log a message
    void logMessage(const string& message) {
        boost::log::sources::severity_logger<boost::log::trivial::severity_level> logger(mName);

        if (logger.should_log(mLogLevel)) {
            // Log the message to both console and file
            cout << "[" << boost::log::to_simple_string(boost::log::aux::now()) << "] " << mName << ": " << message << endl;

            // Open a text file backend for the log file
            boost::log::sinks::text_file_backend backend(mPath);

            // Create a new sink that uses this backend and set its formatter
            boost::log::sink_t<boost::log::sinks::text_file_backend> sink(backend);
            sink.set_formatter(boost::log::expressions::stream << "[" << boost::log::to_simple_string(boost::log::aux::now()) << "] " << mName << ": " << message);

            // Connect the sink to the logger
            logger.add_sink(sink);

            // Flush the log file
            backend.flush();
        }
    }

private:
    string mName;
    string mPath;
    boost::log::trivial::severity_level mLogLevel = boost::log::trivial::debug;
};

int main() {
    // Initialize the logging system with a custom logger for the "main" component
    Logger mainLogger("main", "main.log");

    // Set the log level to INFO for the main logger
    mainLogger.setLogLevel(boost::log::trivial::info);

    // Log some messages using the main logger
    mainLogger.logMessage("Hello, world!");
    mainLogger.logMessage("This is a debug message.");
    mainLogger.logMessage("This is an info message.", boost::log::trivial::info);
    mainLogger.logMessage("This is a warning message.", boost::log::trivial::warning);

    // Initialize another custom logger for the "secondary" component
    Logger secondaryLogger("secondary", "secondary.log");

    // Set the log level to DEBUG for the secondary logger
    secondaryLogger.setLogLevel(boost::log::trivial::debug);

    // Log some messages using the secondary logger
    secondaryLogger.logMessage("This is a debug message.");
    secondaryLogger.logMessage("This is an info message.", boost::log::trivial::info);
    secondaryLogger.logMessage("This is a warning message.", boost::log::trivial::warning);

    // Flush the log files for both loggers
    mainLogger.flush();
    secondaryLogger.flush();

    return 0;
}
```
In this example, we define a `Logger` class that manages log levels dynamically at runtime and supports multiple loggers for different components of the application. The class has a constructor that takes in a name and path for the log file, as well as a setter method to set the log level. It also includes a `logMessage()` method that can be used to log messages with a specific severity level.

The `main()` function initializes two custom loggers: one for the "main" component and one for the "secondary" component. It sets the log levels for both loggers using the setter methods, and then logs some messages using each logger. Finally, it flushes the log files for both loggers to ensure that all buffered data is written to disk.

This implementation uses Boost Logging library to provide a configurable logging system with support for multiple log levels, output to console and file simultaneously, and robust handling of potential integration issues with an external data source. It also includes mechanisms to handle race conditions and ensure thread safety when multiple threads are accessing or modifying the loggers simultaneously.']

