// Rust function to create a new directory and set an environment variable to its path
fn create_directory(name: &str) -> Result<String, Error> {
    // Check if the directory already exists
    let dir = std::fs::read_dir(std::env::var("PATH").unwrap()).await?;

    if dir.is_empty() {
        // Create a new directory with the given name
        let mut file = File::create(name)?;
        file.sync_all()?;

        // Set the environment variable to the path of the directory
        std::env::set_var("PATH", format!("{}/{}", std::env::var("PATH").unwrap(), name));
    }
    else {
        // Use the existing value of the environment variable
        let mut file = File::open(std::env::var("PATH").unwrap())?;
        file.sync_all()?;
    }

    Ok(name.to_owned())
}
