    // Retrieve user account data from database based on ID
    $userData = getUserData($data['id']);

    // Handle rate limiting for IP addresses
    if (isset($data['ip']) && isset($_SESSION['ipRequestCount'][$data['ip']])) {
        if ($_SESSION['ipRequestCount'][$data['ip']] >= 10) {
            return json_encode(['message' => 'Rate limit exceeded']);
        } else {
            $_SESSION['ipRequestCount'][$data['ip']]++;
        }
    }

    // Handle sub-actions (delete, update)
    if (isset($data['sub_action'])) {
        switch ($data['sub_action']) {
            case 'delete':
                $deleteResult = deleteData($data['id']);
                break;
            default:
                $updateResult = updateData($data);
                break;
        }
    } else {
        $createResult = createData($data);
    }

    // Handle errors and return appropriate response
    if ($saveResult === false || $deleteResult === false || $updateResult === false) {
        return json_encode(['message' => 'Error saving data']);
    } else if ($userData == null) {
        return json_encode(['message' => 'User not found']);
