    public class HttpPostController : ControllerBase
    {
        private readonly IElementService _elementService;
        private readonly ILogger<HttpPostController> _logger;

        public HttpPostController(IElementService elementService, ILogger<HttpPostController> logger)
        {
            _elementService = elementService;
            _logger = logger;
        }

        [HttpPost]
        public async Task<ActionResult> UpdateElement([FromQuery] int pageSectionId, [FromQuery] int elementId, [FromBody] string htmlContent)
        {
            try
            {
                // Validate input parameters
                if (pageSectionId < 1 || elementId < 1)
                {
                    return BadRequest("Invalid input parameters");
                }

                // Use caching mechanism to minimize database hits
                var cacheKey = $"{pageSectionId}-{elementId}";
                var cachedContent = HttpRuntime.Cache[cacheKey] as string;
                if (cachedContent != null)
                {
                    _logger.LogInformation($"Using cached content for element {elementId} in page section {pageSectionId}");
                    return Ok(cachedContent);
                }

                // Update element using service class
                var updatedHtml = await _elementService.UpdateElementAsync(pageSectionId, elementId, htmlContent);

                // Cache updated content for future requests
                HttpRuntime.Cache[cacheKey] = updatedHtml;

                // Log update for auditing purposes
                _logger.LogInformation($"Updated element {elementId} in page section {pageSectionId}");

                return Ok(updatedHtml);
            }
            catch (Exception ex)
            {
                // Retry operation up to 3 times before failing
                if (ex is InvalidOperationException || ex is TimeoutException)
                {
                    _logger.LogError($"Failed to update element {elementId} in page section {pageSectionId}: {ex.Message}");

                    return await UpdateElement(pageSectionId, elementId, htmlContent);
                }
                else
                {
                    // Log and throw exception for further handling
                    _logger.LogError($"Failed to update element {elementId} in page section {pageSectionId}: {ex.Message}");

                    throw ex;
                }
            }
        }
    }
}
```
