public class MoSTState {
    private static final String DEFAULT_THEME_DIR = "theme";
    private static final int THEME_CACHE_SIZE = 10;
    private static final List<String> IGNORED_FILES = Arrays.asList("file1", "file2");

    // Cache for theme bitmaps
    private static Map<String, Bitmap> themeCache = new HashMap<>();

    public static MoSTState loadState(File stateFile) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(stateFile))) {
            // Check if theme bitmap is recycled and set it to null
            String bitmapName = (String) ois.readObject();
            Bitmap bitmap = themeCache.get(bitmapName);
            if (bitmap != null && !bitmap.isRecycled()) {
                bitmap.recycle();
                themeCache.put(bitmapName, null);
            }

            // Verify default theme directory is set and set it to a specified default value if not
            String themeDir = (String) ois.readObject();
            if (themeDir == null || !new File(themeDir).exists()) {
                themeDir = DEFAULT_THEME_DIR;
            }

            // Parse PNG file from cache root directory and put it in theme cache
            String fileName = (String) ois.readObject();
            if (!IGNORED_FILES.contains(fileName)) {
                File pngFile = new File(Paths.get(cacheRootDirectory, themeDir, fileName).toString());
                Bitmap bitmap = BitmapFactory.decodeFile(pngFile.getAbsolutePath());
                themeCache.put(fileName, bitmap);
            }
        } catch (IOException | ClassNotFoundException e) {
            // Handle exceptions appropriately
            e.printStackTrace();
        } finally {
            try {
                ois.close();
            } catch (IOException e) {
                // Handle exceptions appropriately
                e.printStackTrace();
            }
        }
    }
}
