import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.logging.Logger;

public class ThemeCache {
    private static final Logger logger = Logger.getLogger(ThemeCache.class.getName());

    // Map to store the themes in the cache, using a ConcurrentHashMap for thread-safety
    private final ConcurrentHashMap<String, byte[]> themeCache;

    // ScheduledExecutorService to manage caching operations and prevent UI blocking
    private final ScheduledExecutorService executorService;

    public ThemeCache() {
        this.themeCache = new ConcurrentHashMap<>();
        this.executorService = Executors.newScheduledThreadPool(1);
    }

    // Add a theme to the cache, using an image processing library for complex transformations
    public void addTheme(String name, byte[] data) {
        executorService.submit(() -> {
            try {
                // Use external image processing library to handle complex transformations
                data = ImageProcessingLibrary.transformImage(data);
            } catch (Exception e) {
                logger.severe("Error transforming theme: " + name);
            }
            themeCache.put(name, data);
        });
    }

    // Get a theme from the cache, returning null if not found
    public byte[] getTheme(String name) {
        return themeCache.get(name);
    }

    // Remove a theme from the cache
    public void removeTheme(String name) {
        themeCache.remove(name);
    }

    // Clear all themes from the cache
    public void clear() {
        themeCache.clear();
    }
}
