import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceManager {
    private static final int MAX_RETRY_ATTEMPTS = 5;
    private static final long RETRY_INTERVAL = 1000L; // milliseconds
    private static final int LOGGING_LEVEL = 2; // INFO level

    private ScheduledExecutorService executor;
    private Service service;
    private boolean running;

    public ServiceManager(Service service, long delayInterval) {
        this.service = service;
        this.delayInterval = delayInterval;
        this.running = false;
        this.executor = Executors.newSingleThreadScheduledExecutor();
    }

    public void start() {
        if (this.running) {
            return;
        }
        this.running = true;
        executor.scheduleAtFixedRate(this::stop, delayInterval, delayInterval, TimeUnit.MILLISECONDS);
    }

    public void stop() {
        if (!this.running) {
            return;
        }
        this.running = false;
        executor.scheduleAtFixedRate(this::sendMessage, RETRY_INTERVAL, RETRY_INTERVAL, TimeUnit.MILLISECONDS);
    }

    private void sendMessage() {
        try {
            // Send message to external messaging system
        } catch (Exception e) {
            if (retryAttempts < MAX_RETRY_ATTEMPTS) {
                retryAttempts++;
                executor.scheduleAtFixedRate(this::sendMessage, RETRY_INTERVAL, RETRY_INTERVAL, TimeUnit.MILLISECONDS);
            } else {
                // Give up and log the error
            }
        }
    }

    private void logAction(String action) {
        if (LOGGING_LEVEL >= 2) {
            System.out.println("[" + new Date() + "] " + action);
        }
    }
}
```
