['```rust
use std::sync::Arc;
use tokio::time::{Duration, Instant};
use hyper::client::HttpConnector;
use hyper_proxy::ProxyConnector;
use hyper::{Request, Body, Response};
use hyper_tls::HttpsConnector;
use std::collections::HashMap;
use std::thread;

struct HttpClient {
    connector: HttpsConnector<HttpConnector<ProxyConnector>>,
    headers: HashMap<String, String>,
    timeout: Duration,
    max_attempts: u8,
    retry_delay: Duration,
}

impl HttpClient {
    pub fn new(connector: HttpsConnector<HttpConnector<ProxyConnector>>) -> Self {
        let headers = HashMap::new();
        let timeout = Duration::from_secs(30);
        let max_attempts = 5;
        let retry_delay = Duration::from_millis(250);

        HttpClient { connector, headers, timeout, max_attempts, retry_delay }
    }

    pub fn set_headers(&mut self, headers: HashMap<String, String>) -> &mut Self {
        self.headers = headers;
        self
    }

    pub fn setTimeout(&mut self, timeout: Duration) -> &mut Self {
        self.timeout = timeout;
        self
    }

    pub fn set_max_attempts(&mut self, max_attempts: u8) -> &mut Self {
        self.max_attempts = max_attempts;
        self
    }

    pub fn set_retry_delay(&mut self, retry_delay: Duration) -> &mut Self {
        self.retry_delay = retry_delay;
        self
    }

    async fn request(
        &self,
        url: String,
        method: hyper::Method,
        body: Body,
        headers: HashMap<String, String>,
        timeout: Duration,
        max_attempts: u8,
        retry_delay: Duration,
    ) -> Result<Response<Body>, Error> {
        let mut current_attempt = 0;
        let mut delay = retry_delay;
        loop {
            match self.send(url.clone(), method, body.clone(), headers.clone(), timeout).await {
                Ok(response) => return response,
                Err(error) => if current_attempt >= max_attempts {
                    break Err(error);
                } else {
                    current_attempt += 1;
                    thread::sleep(delay);
                    delay *= 2;
                },
            }
        }
    }

    async fn send(
        &self,
        url: String,
        method: hyper::Method,
        body: Body,
        headers: HashMap<String, String>,
        timeout: Duration,
    ) -> Result<Response<Body>, Error> {
        let request = Request::builder()
            .method(method)
            .uri(url)
            .body(body)?;

        let client = self.connector.clone();
        let mut response = client
            .request(request)
            .await?;

        match hyper::body::to_bytes(response.body_mut()).await {
            Ok(bytes) => return Ok(Response::builder()
                .status(response.status())
                .header("content-type", response.headers().get("content-type"))
                .body(bytes)?),
            Err(_) => return Err(Error::from(HyperError::BodyRead)),
        };
    }
}
```']

