function collectPrivateKeyAndCertificate(oauthRequest) {
  const stream = oauthRequest.stream;
  const privateKey = await stream.readFile('private_key');
  const certificate = await stream.readFile('certificate');

  // validate certificate with external API
  const validationResult = await fetch(`https://external-api.com/validate-certificate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ certificate })
  });

  if (!validationResult.ok) {
    throw new Error(`Certificate validation failed with status ${validationResult.status}`);
  }

  const combinedPem = `${privateKey}${certificate}`;

  // handle pause and resume functionality using standard library functions
  stream.pause();
  await delay(5000); // simulate network latency
  stream.resume();

  return combinedPem;
}
```
Note: This code assumes that the `oauthRequest` object has a `stream` property that can be used to read the private key and certificate from the OAuth request. The `fetch` function is used to validate the certificate with an external API, and the `delay` function is used to simulate network latency."]

