function updateUserPassword($userId, $newPassword) {
    // Validate input parameters
    if (!is_numeric($userId)) {
        throw new Exception('Invalid user ID');
    }
    if (!is_string($newPassword) || strlen($newPassword) < 8) {
        throw new Exception('Invalid password');
    }

    // Validate the password strength using a custom function
    $passwordStrength = validatePasswordStrength($newPassword);
    if ($passwordStrength === false) {
        throw new Exception('Weak password');
    }

    // Check if the user has access to update their password based on role-based access control (RBAC) rules
    $user = getUserById($userId);
    if (!$user->canUpdatePassword()) {
        throw new Exception('Insufficient permissions');
    }

    // Handle rate limiting for brute-force attacks
    $rateLimitKey = 'password_update_'.$userId;
    $rateLimitWindow = 30 * 60; // 30 minutes in seconds
    $rateLimitBucketSize = 100; // maximum number of requests per window
    if (checkRateLimit($rateLimitKey, $rateLimitWindow, $rateLimitBucketSize)) {
        throw new Exception('Too many password updates');
    }

    // Update the user's password in the database using a DAO class
    try {
        $dao = new UserDAO();
        $dao->updateUserPassword($userId, $newPassword);
    } catch (Exception $e) {
        throw new Exception('Error updating password');
    }

    // Log all actions and errors for auditing purposes
    $logger = new Logger();
    $logger->log('info', 'Updated user password', ['userId' => $userId, 'newPassword' => $newPassword]);

    return true;
}

/**
 * Checks if the rate limit has been exceeded for a given key and window.
 * @param string $key The rate limit key (e.g., 'password_update_123456').
 * @param int $window The time window in seconds (e.g., 30 minutes).
 * @param int $bucketSize The maximum number of requests per window (e.g., 100).
