// State structure to represent a state in the FSA
struct State {
    int id; // Unique ID of the state
    char *name; // Name of the state
    struct Transition **transitions; // Array of transitions from this state
};

// Transition structure to represent a transition between two states
struct Transition {
    struct State *source; // Source state of the transition
    struct State *target; // Target state of the transition
    int label; // Label of the transition (e.g., input symbol)
};

// FSA structure to represent a finite state automaton
struct FSA {
    struct State **states; // Array of states in the FSA
    int num_states; // Number of states in the FSA
    struct Transition **transitions; // Array of transitions between states
};

// Function to dynamically construct a state list from an FSA
struct StateList* constructStateList(struct FSA *fsa, int last_state) {
    if (fsa == NULL || fsa->num_states <= 0) {
        return NULL;
    }

    // Allocate memory for the state list
    struct StateList *list = malloc(sizeof(struct StateList));
    if (list == NULL) {
        return NULL;
    }

    // Initialize the state list
    list->num_states = fsa->num_states;
    list->states = malloc(sizeof(struct State) * list->num_states);
    if (list->states == NULL) {
        free(list);
        return NULL;
    }

    // Copy the states from the FSA into the state list
    for (int i = 0; i < fsa->num_states; ++i) {
        struct State *state = &fsa->states[i];
        struct State *new_state = &list->states[i];
        new_state->id = state->id;
        new_state->name = strdup(state->name);
        if (new_state->name == NULL) {
            free(new_state);
            return NULL;
        }
        new_state->transitions = malloc(sizeof(struct Transition *) * state->num_transitions);
        if (new_state->transitions == NULL) {
            free(new_state->name);
            free(new_state);
            return NULL;
        }
        int j = 0;
        for (int k = 0; k < state->num_transitions; ++k) {
            struct Transition *transition = &state->transitions[k];
            if (transition->source->id == last_state || transition->target->id == last_state) {
                new_state->transitions[j++] = transition;
            }
        }
        new_state->num_transitions = j;
    }

    // Update the 'next' pointer of the last state in the list to point to the newly created state list
    if (last_state >= 0 && last_state < fsa->num_states) {
        struct State *last_state_ptr = &fsa->states[last_state];
        for (int i = 0; i < last_state_ptr->num_transitions; ++i) {
            if (last_state_ptr->transitions[i]->target->id == fsa->num_states) {
                last_state_ptr->transitions[i]->target = list;
            }
        }
    }

    return list;
}

// Function to validate a state provided in the FSA
bool validateState(struct FSA *fsa, int state_id) {
    if (state_id < 0 || state_id >= fsa->num_states) {
        return false;
    }
    struct State *state = &fsa->states[state_id];
    return true;
}

