#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

// Define the structure for storing packet metadata
struct Packet {
    uint32_t id; // Packet ID
    uint64_t timestamp; // Timestamp of when the packet was received
    uint8_t priority; // Priority level of the packet (0-7)
};

// Define the structure for storing queue metadata
struct Queue {
    struct Packet *packets; // Array of packets in the queue
    size_t count; // Number of packets in the queue
    uint64_t max_age; // Maximum age of packets in the queue (in milliseconds)
    uint8_t max_priority; // Maximum priority level of packets in the queue (0-7)
};

// Function to manage the packet queue, filtering based on age and priority
struct Packet *manageQueue(struct Queue *queue, struct Packet *packet) {
    // If the queue is full, remove the oldest packet
    if (queue->count >= MAX_QUEUE_SIZE) {
        uint64_t min_timestamp = UINT64_MAX;
        size_t min_index = 0;

        for (size_t i = 0; i < queue->count; i++) {
            if (queue->packets[i].timestamp < min_timestamp) {
                min_timestamp = queue->packets[i].timestamp;
                min_index = i;
            }
        }

        free(queue->packets[min_index].data); // Free the data buffer
        queue->count--;
    }

    // Add the new packet to the end of the queue
    struct Packet *new_packet = malloc(sizeof(struct Packet));
    memcpy(new_packet, packet, sizeof(struct Packet));
    queue->packets[queue->count++] = *new_packet;

    // Update metrics
    if (queue->max_age < packet->timestamp - new_packet->timestamp) {
        queue->max_age = packet->timestamp - new_packet->timestamp;
    }

    if (queue->max_priority < packet->priority) {
        queue->max_priority = packet->priority;
    }

    return queue->packets[0]; // Return the maximum priority level and ID of the packet
}
