char* append_slash(const char* str, size_t limit, size_t max_recursive) {
    // Check if the input string exceeds the size limit or maximum number of recursive calls
    if (strlen(str) > limit || max_recursive == 0) {
        return NULL;
    }

    // Create a new string with the input string and a slash appended to the end
    char* new_str = malloc(sizeof(char) * (strlen(str) + 2));
    strcpy(new_str, str);
    strcat(new_str, "/");

    // Return the new string
