JavaScript Recursive Function:
```javascript
function traverseDOM(node, selector) {
    let elements = [];

    if (node.matches(selector)) {
        elements.push(node);
    }

    for (let child of node.children) {
        elements = elements.concat(traverseDOM(child, selector));
    }

    return elements;
}
