Here is a C# function that takes a string input (the path to a TIFF file) and returns its MD5 hash using a standard library cryptographic hash function:
```
using System;
using System.IO;
using System.Security.Cryptography;

public static string GetMD5Hash(string path) {
    // Read the contents of the file into a byte array
    byte[] fileBytes = File.ReadAllBytes(path);

    // Create a new instance of the MD5 hash algorithm
    var md5 = MD5.Create();

    // Compute the hash of the file contents and return it as a string
    byte[] hashBytes = md5.ComputeHash(fileBytes);
    return BitConverter.ToString(hashBytes).Replace("-", "");
}
```
And here is a C function that parses a TIFF image file and extracts information about the image's bits per sample and sample per pixel:
```
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <tiffio.h>

// Define a struct to hold the extracted information
struct TIFFMetadata {
    int bitsPerSample;
    int samplesPerPixel;
};

// Function to parse a TIFF image file and extract metadata
TIFFMetadata* ParseTIFF(const char* path) {
    // Open the TIFF file for reading
    TIFF *tif = TIFFOpen(path, "r");

    // Check if the file was opened successfully
    if (tif == NULL) {
        fprintf(stderr, "Error: Could not open TIFF file %s\n", path);
        return NULL;
    }

    // Read the image metadata from the TIFF file
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);

    // Close the TIFF file
    TIFFClose(tif);

    // Allocate memory for the struct and initialize it with the extracted metadata
    TIFFMetadata* metadata = malloc(sizeof(TIFFMetadata));
    if (metadata == NULL) {
        fprintf(stderr, "Error: Could not allocate memory for TIFF metadata\n");
        return NULL;
    }
    metadata->bitsPerSample = bitsPerSample;
    metadata->samplesPerPixel = samplesPerPixel;

    // Return the struct with the extracted information
    return metadata;
}
```
Note that this code assumes that the TIFF file is in the same directory as the executable, and it also assumes that the file path is passed as a null-terminated string. In practice, you may want to handle cases where the file path is not specified or is not found, and you may also want to add error handling for other errors that could occur during the parsing process.']

