using System;
using System.Security.Cryptography;
using System.Text;

public string DecryptTripleDES(string base64EncodedMessage, byte[] key, byte[] iv)
{
    // Validate input parameters
    if (base64EncodedMessage == null || key == null || iv == null)
    {
        throw new ArgumentNullException("Invalid input parameter");
    }

    if (key.Length != 16 && key.Length != 24)
    {
        throw new ArgumentOutOfRangeException("Key length must be 16 or 24 bytes");
    }

    if (iv.Length != 8 && iv.Length != 16)
    {
        throw new ArgumentOutOfRangeException("IV length must be 8 or 16 bytes");
    }

    // Decode Base64 string and validate format
    byte[] messageBytes = Convert.FromBase64String(base64EncodedMessage);
    if (messageBytes == null || messageBytes.Length <= 0)
    {
        throw new FormatException("Invalid base64 encoded message");
    }

    // Create TripleDES algorithm with specified key and IV
    using (TripleDESCryptoServiceProvider crypto = new TripleDESCryptoServiceProvider())
    {
        crypto.Key = key;
        crypto.IV = iv;

        // Decrypt message using TripleDES algorithm
        byte[] decryptedMessageBytes = crypto.CreateDecryptor().TransformFinalBlock(messageBytes, 0, messageBytes.Length);

        return Encoding.UTF8.GetString(decryptedMessageBytes);
    }
}
```
