using System;
using System.Security.Cryptography;
using System.Text;

namespace CodingAssistant
{
    public class AESCBCDecryption
    {
        private readonly SymmetricAlgorithm _algorithm;
        private readonly PaddingMode _paddingMode;
        private readonly MACAlgorithm _macAlgorithm;
        private readonly int _ivLength;
        private readonly int _keyLength;

        public AESCBCDecryption(SymmetricAlgorithm algorithm, PaddingMode paddingMode, MACAlgorithm macAlgorithm, int ivLength = 16, int keyLength = 32)
        {
            _algorithm = algorithm ?? throw new ArgumentNullException(nameof(algorithm));
            _paddingMode = paddingMode;
            _macAlgorithm = macAlgorithm;
            _ivLength = ivLength;
            _keyLength = keyLength;
        }

        public byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector)
        {
            if (ciphertext == null || encryptionKey == null || initializationVector == null)
                throw new ArgumentNullException();

            try
            {
                // validate MAC
                var mac = GetMAC(ciphertext, encryptionKey);
                if (!mac.SequenceEqual(_macAlgorithm.ComputeHash(ciphertext)))
                    throw new InvalidOperationException("Invalid MAC");

                // remove padding
                var paddedCiphertext = RemovePadding(ciphertext, _paddingMode);

                // decrypt ciphertext
                using (var aes = CreateAES(_algorithm, encryptionKey))
                {
                    return aes.Decrypt(paddedCiphertext, initializationVector);
                }
            }
            catch (Exception ex)
            {
                LogError(ex);
                throw;
            }
        }

        private byte[] GetMAC(byte[] ciphertext, byte[] encryptionKey)
        {
            using (var hmac = _macAlgorithm.Create(_algorithm))
            {
                hmac.Key = encryptionKey;
                return hmac.ComputeHash(ciphertext);
            }
        }

        private byte[] RemovePadding(byte[] ciphertext, PaddingMode paddingMode)
        {
            using (var aes = CreateAES(_algorithm, _keyLength))
            {
                var blockSize = aes.BlockSize / 8;
                var paddedCiphertext = new byte[ciphertext.Length - blockSize];
                Array.Copy(ciphertext, 0, paddedCiphertext, 0, ciphertext.Length - blockSize);
                return paddedCiphertext;
            }
        }

        private Aes CreateAES(SymmetricAlgorithm algorithm, int keyLength)
        {
            var aes = new AesCryptoServiceProvider
            {
                BlockSize = _algorithm.BlockSize,
                KeySize = keyLength,
                Mode = CipherMode.CBC,
                Padding = _paddingMode,
                IV = initializationVector,
                Algorithm = algorithm
            };
            return aes;
        }

        private void LogError(Exception ex)
        {
            // TODO: implement logging system
        }
    }
}
```
