        {
            try
            {
                if (cache.ContainsKey(key))
                {
                    return DeserializeCustomDataStructure(cache[key]);
                }
                else
                {
                    byte[] data = File.ReadAllBytes(FILE_PATH);
                    cache[key] = data;
                    return DeserializeCustomDataStructure(data);
                }
            }
            catch (FileNotFoundException ex)
            {
                // log the exception and handle it gracefully
                Console.WriteLine($"File not found: {ex.FileName}");
                return null;
            }
        }

        private static CustomDataStructure DeserializeCustomDataStructure(byte[] data)
        {
            try
            {
                using (MemoryStream ms = new MemoryStream(data))
                {
                    BinaryFormatter bf = new BinaryFormatter();
                    return (CustomDataStructure)bf.Deserialize(ms);
                }
            }
            catch (SerializationException ex)
            {
                // log the exception and handle it gracefully
                Console.WriteLine($"Error deserializing data: {ex.Message}");
                return null;
            }
        }
    }
}
