use std::env;
use std::fs;
use std::path::PathBuf;

fn create_dir(name: &str) -> Result<(), String> {
    // Check if the environment variable is already set
    let existing_value = env::var("MY_DIR").ok();
    if let Some(existing_value) = existing_value {
        // Use the existing value if it is set
        return Ok(());
    }

    // Create a new directory with the given name
    let dir_path = PathBuf::from(name);
    fs::create_dir(&dir_path).map_err(|e| format!("Failed to create directory: {}", e))?;

    // Set the environment variable to the path of the new directory
    env::set_var("MY_DIR", dir_path.to_str().unwrap());

    // Log successful operation
    log::info!("Created directory: {}", &dir_path.display());

    Ok(())
}
