    ~RandomNumberGen() = default;

    static std::random_device rd_;
    static std::mt19937 gen_;
    static std::uniform_real_distribution<double> dis_;

    void generate(int size) {
        // validate input parameters
        if (size <= 0) {
            throw std::invalid_argument("Size must be a positive integer.");
        }

        // allocate memory for the offset and key arrays
        int* offsets = new int[size];
        int* keys = new int[size];

        // initialize the arrays with random values within the given range
        for (int i = 0; i < size; i++) {
            offsets[i] = dis_(gen_);
            keys[i] = dis_(gen_);
        }

        // allocate memory for the record structures
        std::vector<record> records(size);

        // set the value of each record's int field to a random value within the given range
        for (int i = 0; i < size; i++) {
            records[i].int_field = dis_(gen_);
        }

        // free the memory allocated for the arrays and the record structures when they are no longer needed
        delete[] offsets;
        delete[] keys;
        records.clear();
    }

private:
    struct record {
        int int_field;
    };
};

std::random_device RandomNumberGen::rd_;
std::mt19937 RandomNumberGen::gen_;
std::uniform_real_distribution<double> RandomNumberGen::dis_;

} // namespace random_number_gen
```
