import java.util.*;
import java.net.URL;
import java.io.IOException;
import javax.net.ssl.HttpsURLConnection;

public class DisjointPairs {
  private UnionFind uf;
  private int count = 0;
  private long startTime;

  public DisjointPairs(int[] arr) {
    this.uf = new UnionFind(arr);
  }

  public int getCount() {
    return this.count;
  }

  public void fetchMetadata(int index, String url) throws IOException {
    URL apiUrl = new URL(url);
    HttpsURLConnection conn = (HttpsURLConnection) apiUrl.openConnection();

    // Set timeouts and certificate validation parameters
    conn.setConnectTimeout(5000);
    conn.setReadTimeout(5000);
    conn.setSSLSocketFactory(createSslSocketFactory());

    // Send request and handle response
    int status = conn.getResponseCode();
    if (status == 200) {
      InputStream is = conn.getInputStream();
      JSONObject json = new JSONObject(is);
      this.uf.union(index, json.getInt("id"));
      is.close();
    } else {
      throw new IOException("Error: " + status);
    }
  }

  public void checkDisjointPairs() throws IOException {
    for (int i = 0; i < this.uf.getSize(); i++) {
      int root1 = this.uf.find(i);
      for (int j = i + 1; j < this.uf.getSize(); j++) {
        int root2 = this.uf.find(j);
        if (root1 == root2) {
          this.count++;
          System.out.println("Disjoint pair: " + i + ", " + j);
        }
      }
    }
  }

  public void printTimeTaken() {
    long endTime = System.currentTimeMillis();
    long timeTaken = endTime - this.startTime;
    System.out.println("Time taken: " + timeTaken + " ms");
  }

  private SSLSocketFactory createSslSocketFactory() throws IOException {
    // Create an SSL socket factory that trusts all certificates
    TrustManager[] trustAllCerts = new TrustManager[] {
      new X509TrustManager() {
        public java.security.cert.X509Certificate[] getAcceptedIssuers() {
          return null;
        }

        public void checkClientTrusted(java.security.cert.X509Certificate[] certs, String authType) {}

        public void checkServerTrusted(java.security.cert.X509Certificate[] certs, String authType) {}
      }
    };

    SSLContext sslContext = null;
    try {
      sslContext = SSLContext.getInstance("TLS");
      sslContext.init(null, trustAllCerts, new java.security.SecureRandom());
    } catch (NoSuchAlgorithmException | KeyManagementException e) {
      throw new IOException("Error: " + e);
    }

    return sslContext.getSocketFactory();
  }
}
