#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <time.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void processNetworkData(int pid) {
    // Set up environment variables and libraries for the background command
    setenv("VAR1", "value1", 1);
    setenv("VAR2", "value2", 1);
    dlopen("libnetwork.so", RTLD_LAZY | RTLD_GLOBAL);

    // Populate list of NFAPI_CRC_INDICATION_PDU_T structures
    int n = 100; // Arbitrary number of items in the list
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; i++) {
        list[i].RX_UE_INFORMATION_TAG = i + 1;
        list[i].RNTI = i + 2;
        list[i].CRCFLAG = rand() % 2 ? 1 : 0; // Randomly set CRCFLAG to 1 or 0
    }

    // Run the background command for each item in the list
    for (int i = 0; i < n; i++) {
        pid_t child_pid = fork();
        if (child_pid == 0) { // Child process
            execlp("background_command", "background_command", NULL);
        } else { // Parent process
