class SandeshClient {
public:
  SandeshClient(const string& hostname, int port) : hostname_(hostname), port_(port) {}

  // Function to perform DNS resolution for a given hostname using standard library functions
  u_char* ResolveDns(const string& hostname) {
    struct addrinfo hints;
    struct addrinfo *res, *addr;

    // Get IP address from DNS server
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // Use IPv4 for now
    hints.ai_socktype = SOCK_STREAM;
    if (getaddrinfo(hostname.c_str(), NULL, &hints, &res) != 0) {
      return NULL;
    }

    // Get the first address and convert it to a u_char array
    addr = res;
    u_char* ip_address = new u_char[4];
    for (int i = 0; i < 4; ++i) {
      ip_address[i] = (u_char)((addr->ai_addr)->sa_data[i]);
    }
    freeaddrinfo(res);

    return ip_address;
  }

  // Function to send a series of GET requests to the server and handle errors
  void SendGetRequests() {
