        http::client::request request(http::client::request::http);
        request.set_method("GET");
        request.set_path("/");
        http::client::response response = http::client::sync_client::do_request(socket, request);
        if (response.status() != 200) {
          std::cout << "Error: HTTP status code " << response.status() << std::endl;
        } else {
          std::cout << "Received response: " << response.body() << std::endl;
        }
      }
    } catch (const boost::system::error_code& e) {
      std::cout << "Error: " << e.message() << std::endl;
    }
  }

private:
