public class MD5Hasher {
    private static final ExecutorService executor = Executors.newFixedThreadPool(10); // configure this to prevent resource exhaustion
    private static final int TIMEOUT_SECONDS = 60; // adjust this based on your needs

    public static String hashString(String input) throws InterruptedException, HashingException {
        try {
            return MessageDigest.getInstance("MD5").digest(input.getBytes()).toString();
        } catch (NoSuchAlgorithmException e) {
            throw new HashingException("Unable to hash string", e);
        } finally {
            executor.shutdown(); // shut down the executor after a certain time
        }
    }

    private static class HashingException extends RuntimeException {
        public HashingException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
