```c
#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <stdlib.h>

// Structure to hold the cipher context and semaphore
typedef struct {
    EVP_CIPHER_CTX *ctx;
    sem_t *sem;
} CipherContext;

// Function to initialize the AES-256-CBC cipher with a given password
void initAes256Cbc(const char *password, int ivLen, int keyLen) {
    // Create a new cipher context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Error: Failed to create cipher context\n");
        exit(1);
    }

    // Set the IV length and key length
    EVP_CIPHER_CTX_set_iv_length(ctx, ivLen);
    EVP_CIPHER_CTX_set_key_length(ctx, keyLen);

    // Derive the encryption key from the password using SHA-1
    unsigned char key[64];
    SHA_CTX sha;
    SHA1_Init(&sha);
    SHA1_Update(&sha, (unsigned char *)password, strlen(password));
    SHA1_Final(key, &sha);

    // Initialize the cipher with the derived key and IV
    if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, NULL)) {
        fprintf(stderr, "Error: Failed to initialize AES-256-CBC cipher\n");
        exit(1);
    }

    // Create a semaphore for synchronizing access to the cipher context
    sem_t *sem = sem_open("cipher", O_CREAT, 0644, 1);
    if (sem == SEM_FAILED) {
        fprintf(stderr, "Error: Failed to create semaphore\n");
        exit(1);
    }

    // Store the cipher context and semaphore in a structure
    CipherContext *cc = malloc(sizeof(CipherContext));
    cc->ctx = ctx;
    cc->sem = sem;

    return cc;
}

// Function to clean up and disable the AES-256-CBC cipher
void cleanupAes256Cbc(CipherContext *cc) {
    // Release the semaphore
    if (sem_close(cc->sem) == -1) {
        fprintf(stderr, "Error: Failed to close semaphore\n");
    }

    // Destroy the cipher context
    EVP_CIPHER_CTX_free(cc->ctx);
}
```
