int create_ue_context(int num_ues, int num_traffic_flows) {
    // Check if the input parameters are valid
    if (num_ues <= 0 || num_traffic_flows <= 0) {
        printf("Invalid input parameters. num_ues: %d, num_traffic_flows: %d\n", num_ues, num_traffic_flows);
        return -1;
    }

    // Allocate memory for the list of UE Context structures
    lte_ue_context *ue_list = malloc(sizeof(lte_ue_context) * num_ues);
    if (!ue_list) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Allocate memory for the list of Traffic Flow Info structures
    lte_tnl_flow_info **traffic_flows = malloc(sizeof(lte_tnl_flow_info) * num_traffic_flows);
    if (!traffic_flows) {
        printf("Memory allocation failed\n");
        free(ue_list);
        return -1;
    }

    // Initialize the list of UE Context structures
    for (int i = 0; i < num_ues; i++) {
        ue_list[i].ue_id = i + 1;
        ue_list[i].rnti = i + 1;
        ue_list[i].traffic_flows = traffic_flows;
    }

    // Initialize the list of Traffic Flow Info structures
    for (int j = 0; j < num_traffic_flows; j++) {
        traffic_flows[j].flow_id = j + 1;
        traffic_flows[j].s1_perf_tunnel = j + 1;
        traffic_flows[j].s5_perf_tunnel = j + 1;
        traffic_flows[j].s1_perf_tunnel_name = "s1-perf-tunnel";
        traffic_flows[j].s5_perf_tunnel_name = "s5-perf-tunnel";
    }

    // Return the list of UE Context structures and Traffic Flow Info structures
    return ue_list;
}

// Define the function to update traffic flow data in real-time
void update_traffic_flow(lte_ue_context *ue, int num_traffic_flows) {
    // Check if the input parameters are valid
    if (!ue || num_traffic_flows <= 0) {
        printf("Invalid input parameters. ue: %p, num_traffic_flows: %d\n", ue, num_traffic_flows);
        return;
    }

    // Allocate memory for the updated list of Traffic Flow Info structures
    lte_tnl_flow_info **updated_traffic_flows = malloc(sizeof(lte_tnl_flow_info) * num_traffic_flows);
    if (!updated_traffic_flows) {
        printf("Memory allocation failed\n");
        return;
    }

    // Copy the existing list of Traffic Flow Info structures
    for (int i = 0; i < num_traffic_flows; i++) {
        updated_traffic_flows[i] = ue->traffic_flows[i];
    }

    // Update the list of Traffic Flow Info structures with new data
    for (int j = 0; j < num_traffic_flows; j++) {
        updated_traffic_flows[j].s1_perf_tunnel = j + 1;
        updated_traffic_flows[j].s5_perf_tunnel = j + 1;
    }

    // Free the existing list of Traffic Flow Info structures
    free(ue->traffic_flows);

    // Set the updated list of Traffic Flow Info structures as the new value for the UE context structure
    ue->traffic_flows = updated_traffic_flows;
}
