// Define constants for the supported AES modes
#define MODE_ECB 0
#define MODE_CBC 1
#define MODE_CFB 2
#define MODE_OFB 3

// Define a structure to hold the encryption parameters
typedef struct {
    int mode; // AES mode (ECB, CBC, CFB, OFB)
    unsigned char key[32]; // AES key
    unsigned char iv[16]; // initialization vector (IV)
} aes_params_t;

// Define a function to generate the necessary round keys for AES-256 encryption
void gen_round_keys(unsigned char *key, int num_rounds) {
    // Generate the round keys using the AES key expansion algorithm
    unsigned char temp[32];
    memset(temp, 0, 32);
    for (int i = 0; i < 4; i++) {
        temp[i] = key[i];
        temp[4 + i] = key[8 + i];
        temp[12 + i] = key[12 + i];
        temp[16 + i] = key[16 + i];
    }
    for (int i = 0; i < num_rounds - 9; i++) {
        unsigned char *temp_ptr = &temp[i * 4];
        AES_KEY aes_key;
        AES_set_encrypt_key(temp_ptr, 256, &aes_key);
        temp[i + 17] = temp[i + 9];
        temp[i + 18] = temp[i + 10];
        temp[i + 19] = temp[i + 11];
        temp[i + 20] = temp[i + 12];
    }
}

// Define a function to encrypt the input string using AES-256 encryption in ECB mode
void encrypt_ecb(unsigned char *input, int input_len, unsigned char *key, unsigned char *output) {
    // Generate the round keys for the given key and IV
    gen_round_keys(key, 10);
    // Initialize the AES context with the generated round keys
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_ecb(), NULL, key, iv);
    // Encrypt the input string using the AES-256 ECB encryption algorithm
    int len = 0;
    if (EVP_EncryptUpdate(ctx, output, &len, input, input_len) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        ERR_print_errors_fp(stderr);
        return;
    }
    // Finalize the encryption operation and retrieve the ciphertext
    int final_len = 0;
    if (EVP_EncryptFinal_ex(ctx, output + len, &final_len) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        ERR_print_errors_fp(stderr);
        return;
    }
    // Free the AES context and return the ciphertext
    EVP_CIPHER_CTX_free(ctx);
}

// Define a function to encrypt the input string using AES-256 encryption in CBC mode
