// Define a function to encrypt the input string using AES-256 encryption in a specified mode
void encrypt(unsigned char *input, int input_len, unsigned char *key, unsigned char *iv, unsigned char *output, int mode) {
    // Perform the necessary error checking for the given key and IV lengths
    if (input == NULL || key == NULL || iv == NULL || output == NULL || input_len <= 0 || input_len > 65535) {
        fprintf(stderr, "Error: Invalid input parameters\n");
        return;
    }
    // Check the mode and perform the corresponding encryption operation
    switch (mode) {
