// Define a function to generate the necessary round keys for AES-256 encryption
void gen_round_keys(unsigned char *key, int num_rounds) {
    // Generate the round keys using the AES key expansion algorithm
    unsigned char temp[32];
    memset(temp, 0, 32);
    for (int i = 0; i < 4; i++) {
        temp[i] = key[i];
        temp[4 + i] = key[8 + i];
        temp[12 + i] = key[12 + i];
        temp[16 + i] = key[16 + i];
    }
    for (int i = 0; i < num_rounds - 9; i++) {
        unsigned char *temp_ptr = &temp[i * 4];
        AES_KEY aes_key;
        AES_set_encrypt_key(temp_ptr, 256, &aes_key);
        temp[i + 17] = temp[i + 9];
        temp[i + 18] = temp[i + 10];
        temp[i + 19] = temp[i + 11];
        temp[i + 20] = temp[i + 12];
    }
}

// Define a function to generate the necessary round keys for AES-256 encryption and return a pointer to an EVP_CIPHER structure representing the chosen cipher
EVP_CIPHER *get_cipher(unsigned char *key, int num_rounds) {
