// DynamicValueGenerator class for generating random values within specified boundaries
class DynamicValueGenerator {
public:
    // Constructor with configuration settings
    DynamicValueGenerator(bool inclusive, bool exclusive, std::string external_data_source) : inclusive_(inclusive), exclusive_(exclusive), external_data_source_(external_data_source) {}

    // Generate a random value within specified boundaries
    template <typename T> T generateValue() {
        T min = getMinimumValue();
        T max = getMaximumValue();

        if (inclusive_) {
            return min + ((rand() % (max - min + 1)) + min);
        } else {
            return min + ((rand() % (max - min)) + min) + 1;
        }
    }

    // Fetch minimum and maximum values from an external data source
    template <typename T> std::pair<T, T> getMinMaxValues() {
        try {
            std::string url = external_data_source_ + "/minmax";
            auto response = makeHttpRequest(url);
            return std::make_pair(response.min, response.max);
        } catch (std::exception& e) {
            printf("Failed to fetch minimum and maximum values: %s\n", e.what());
            return std::make_pair(T(), T());
        }
    }

private:
    // Get minimum value from an external data source
    template <typename T> T getMinimumValue() {
        auto min_max = getMinMaxValues<T>();
        if (min_max.first > 0) {
            return min_max.first;
        } else {
            printf("Failed to fetch minimum value\n");
            return T();
        }
    }

    // Get maximum value from an external data source
    template <typename T> T getMaximumValue() {
        auto min_max = getMinMaxValues<T>();
        if (min_max.second > 0) {
            return min_max.second;
        } else {
            printf("Failed to fetch maximum value\n");
            return T();
        }
    }

    // Make an HTTP request to the external data source
    std::string makeHttpRequest(std::string url) {
        try {
            auto response = curl_easy_perform(url.c_str());
            return response;
        } catch (std::exception& e) {
            printf("Failed to perform HTTP request: %s\n", e.what());
            return "";
        }
    }

private:
    // Configuration settings for inclusive/exclusive boundaries and external data source URL
    bool inclusive_;
    bool exclusive_;
    std::string external_data_source_;
};
