    // Bind the supervisor ID parameter
    rc = sqlite3_bind_int(stmt, 1, num_records);
    if (rc != SQLITE_OK) {
        printf("Error: Failed to bind supervisor ID parameter\n");
        return;
    }

    // Step through the result set and retrieve the employee name, city, and address
    while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
