    uint32_t maxAllowedEntries;
} ConfigurationStruct;

// Define a logging mechanism for debugging purposes
#define LOG(message) printf("[%d] %s\n", __LINE__, message);

// Initialize and populate the list of CellularUeInfo_PDU_T structures
void initializeAndPopulateList(CellularUeInfo_PDU_T **list, uint32_t numEntries, ConfigurationStruct *config) {
    // Validate input parameters
    if (list == NULL || numEntries == 0 || config == NULL) {
        LOG("Invalid input parameters");
        return;
    }

    // Allocate memory for the list and its elements
    *list = malloc(numEntries * sizeof(CellularUeInfo_PDU_T));
    if (*list == NULL) {
        LOG("Memory allocation failed");
        return;
    }

    // Initialize each element of the list with a valid UE ID and RNTI, and set CrcIndication to a randomly set value
    for (uint32_t i = 0; i < numEntries; i++) {
        (*list)[i].UE_ID = i + 1; // start with 1 to avoid conflict with RNTI
