        (*list)[i].CrcIndication = (bool)(rand() % 2); // set CrcIndication to a randomly set value
    }

    // Log each operation for debugging purposes
    LOG("Allocated memory for list");

    // Dynamically resize the list based on input size requirements
    if (numEntries > config->maxAllowedEntries) {
        uint32_t newSize = numEntries * config->growthFactor;
        CellularUeInfo_PDU_T *newList = realloc(*list, newSize * sizeof(CellularUeInfo_PDU_T));
        if (newList == NULL) {
            LOG("Memory reallocation failed");
            return;
        }
        *list = newList;
        LOG("Reallocated memory for list with new size %d", newSize);
    }
}

// Release the memory allocated for the list and its elements
void releaseList(CellularUeInfo_PDU_T **list) {
    // Validate input parameters
    if (list == NULL || *list == NULL) {
        LOG("Invalid input parameters");
        return;
    }

    // Release memory for the list and its elements
    free(*list);
    *list = NULL;

    // Log each operation for debugging purposes
    LOG("Released memory for list");
}

// Thread-safe function to add an element to the end of the list
void addElementToEnd(CellularUeInfo_PDU_T **list, uint32_t UE_ID, uint16_t RNTI) {
    // Validate input parameters
    if (list == NULL || *list == NULL) {
        LOG("Invalid input parameters");
        return;
    }

    // Acquire lock to ensure thread-safety
    pthread_mutex_lock(&listMutex);

    // Check if the list is full and needs to be resized
    uint32_t currentSize = getListSize(*list);
    if (currentSize >= config->maxAllowedEntries) {
        uint32_t newSize = currentSize * config->growthFactor;
        CellularUeInfo_PDU_T *newList = realloc(*list, newSize * sizeof(CellularUeInfo_PDU_T));
        if (newList == NULL) {
            LOG("Memory reallocation failed");
            pthread_mutex_unlock(&listMutex);
            return;
        }
        *list = newList;
        LOG("Reallocated memory for list with new size %d", newSize);
    }

    // Add the element to the end of the list
    (*list)[currentSize].UE_ID = UE_ID;
    (*list)[currentSize].RNTI = RNTI;
    LOG("Added element to end of list");

    // Release lock
    pthread_mutex_unlock(&listMutex);
}

// Thread-safe function to remove an element from the end of the list
void removeElementFromEnd(CellularUeInfo_PDU_T **list) {
    // Validate input parameters
    if (list == NULL || *list == NULL) {
        LOG("Invalid input parameters");
        return;
    }

    // Acquire lock to ensure thread-safety
    pthread_mutex_lock(&listMutex);

    // Check if the list is empty and needs to be freed
    uint32_t currentSize = getListSize(*list);
    if (currentSize == 0) {
        releaseList(list);
        LOG("Released memory for list");
    } else {
        // Remove the element from the end of the list
        (*list)[currentSize - 1].UE_ID = 0;
        (*list)[currentSize - 1].RNTI = 0;
        (*list)[currentSize - 1].CrcIndication = false;
        LOG("Removed element from end of list");
    }

    // Release lock
    pthread_mutex_unlock(&listMutex);
}

// Function to get the size of the list
uint32_t getListSize(CellularUeInfo_PDU_T **list) {
