// Define the LTE UE Context structure
typedef struct {
    uint32_t ue_id;
    uint16_t rnti;
    bool srb1_status_flag;
} lte_ue_context_t;

// Define a linked list node to store the contexts
typedef struct context_node {
    lte_ue_context_t *context;
    struct context_node *next;
} context_node_t;

// Define a global variable to store the head of the linked list
static context_node_t *head = NULL;

// Define a semaphore for thread safety
semaphore_t mutex;

// Define a function to create and populate a new LTE UE Context structure
lte_ue_context_t *create_context(uint32_t ue_id, uint16_t rnti) {
    // Allocate memory for the context
    lte_ue_context_t *context = malloc(sizeof(lte_ue_context_t));
    if (context == NULL) {
        return NULL;
    }

    // Set the UE ID and RNTI in the context
    context->ue_id = ue_id;
    context->rnti = rnti;

    // Generate a random value for the SRB1 Status Transfer flag
    context->srb1_status_flag = (rand() % 2) == 0;

    return context;
}

// Define a function to add a new context to the linked list
void add_context(lte_ue_context_t *context) {
    // Allocate memory for the node
    context_node_t *node = malloc(sizeof(context_node_t));
    if (node == NULL) {
        free(context);
        return;
    }

    // Set the next pointer of the new node to the head
    node->next = head;

    // Set the context in the new node
    node->context = context;

    // Update the head of the linked list to point to the new node
    head = node;
}

// Define a function to remove a context from the linked list
void remove_context(lte_ue_context_t *context) {
    // If the head is NULL, there are no contexts to remove
    if (head == NULL) {
        return;
    }

    // If the head points to the context we want to remove, update the head and return
    if (head->context == context) {
        context_node_t *old_head = head;
        head = head->next;
        free(old_head);
        return;
    }

    // Search for the node containing the context we want to remove
    context_node_t *current = head;
    while (current != NULL && current->next != NULL) {
        if (current->next->context == context) {
            break;
        }
        current = current->next;
    }

    // If the node was not found, there are no contexts to remove
    if (current == NULL || current->next == NULL) {
        return;
    }

    // Remove the node containing the context we want to remove
    context_node_t *old_node = current->next;
    current->next = old_node->next;
    free(old_node);
}

// Define a function to get the number of contexts in use
size_t get_num_contexts() {
    size_t num_contexts = 0;
    context_node_t *current = head;
    while (current != NULL) {
        num_contexts++;
        current = current->next;
    }
    return num_contexts;
}

// Define a function to log any attempts to exceed the maximum number of contexts
void log_context_limit() {
    printf("Maximum number of contexts reached. Exceeding this limit may cause performance issues.\n");
}

// Define a function to create and populate a list of LTE UE Context structures
lte_ue_context_t *create_list(size_t num_contexts) {
    // Create an array of contexts
    lte_ue_context_t **contexts = malloc(num_contexts * sizeof(lte_ue_context_t *));
    if (contexts == NULL) {
        return NULL;
    }

    // Populate the array with new contexts
    for (size_t i = 0; i < num_contexts; i++) {
        lte_ue_context_t *context = create_context(i, i);
        if (context == NULL) {
            free(contexts);
            return NULL;
        }
        contexts[i] = context;
    }

    // Add the contexts to the linked list
    for (size_t i = 0; i < num_contexts; i++) {
        add_context(contexts[i]);
    }

    // Return the array of contexts
    return contexts;
}

// Define a function to destroy and free a list of LTE UE Context structures
void destroy_list(lte_ue_context_t **contexts, size_t num_contexts) {
    // Remove each context from the linked list
    for (size_t i = 0; i < num_contexts; i++) {
        remove_context(contexts[i]);
    }

    // Free the array of contexts
    free(contexts);
}
