}

// Function to calculate and print the average of all integers in the array
void print_average(Array *arr) {
    int i, sum = 0;
    for (i = 0; i < arr->size; i++) {
        sum += arr->data[i]; // Calculate the sum of all integers in the array
    }
    double average = (double)sum / arr->size; // Calculate the average of the integers
    printf("Average: %f\n", average); // Print the average
}

int main() {
    Array arr = {{NULL}, 0}; // Initialize an empty array with a size of 0
    read_integers(&arr); // Read a list of integers from standard input and store them in the array
    print_largest(&arr); // Print the largest integer in the array
    print_average(&arr); // Calculate and print the average of all integers in the array
    return 0;
}
```
