void init_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    list->entries = malloc(INITIAL_LIST_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list->entries == NULL) {
        // Handle memory allocation failure gracefully
        return;
    }
    list->num_entries = 0;
    list->max_entries = INITIAL_LIST_SIZE;
}

int add_entry(NFAPI_CRC_INDICATION_LIST_T* list, uint32_t rx_ue_information_tag, uint32_t rnti, uint32_t crc_indication_rel8_tag, bool crcflag) {
