    if (list->num_entries == list->max_entries) {
        // Resize the list if necessary
        if (list->max_entries < RESIZE_THRESHOLD * INITIAL_LIST_SIZE) {
            NFAPI_CRC_INDICATION_PDU_T* new_entries = realloc(list->entries, 2 * list->max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_entries == NULL) {
