void InitializeNetworkNodes(int nodeCount, NetworkNodeInfo_PDU_T** nodes) {
    // Validate input parameters
    if (nodeCount < 0 || !nodes) {
        printf("Invalid input parameter\n");
        return;
    }

    // Allocate memory for the list of NetworkNodeInfo_PDU_T structures
    *nodes = malloc(sizeof(NetworkNodeInfo_PDU_T*) * nodeCount);
    if (!*nodes) {
        printf("Failed to allocate memory for nodes\n");
        return;
    }

    // Initialize each NetworkNodeInfo_PDU_T structure
    for (int i = 0; i < nodeCount; ++i) {
        (*nodes)[i].NodeID = i + 1;
        (*nodes)[i].NodeName = malloc(sizeof(char) * 64);
        sprintf((*nodes)[i].NodeName, "Node %d", i + 1);
        (*nodes)[i].ServiceCount = 0;
        (*nodes)[i].Services = NULL;
    }
}

void UpdateNetworkNodes(int nodeCount, NetworkNodeInfo_PDU_T** nodes) {
    // Validate input parameters
    if (nodeCount < 0 || !nodes) {
        printf("Invalid input parameter\n");
        return;
    }

    // Allocate memory for the list of ServiceDetails structures
    ServiceDetails** services = malloc(sizeof(ServiceDetails*) * nodeCount);
    if (!services) {
        printf("Failed to allocate memory for service details\n");
        return;
    }

    // Update each NetworkNodeInfo_PDU_T structure with the new service data
    for (int i = 0; i < nodeCount; ++i) {
        // Allocate memory for the list of ServiceDetails structures
        if ((*nodes)[i].ServiceCount > 0) {
            free((*nodes)[i].Services);
            (*nodes)[i].Services = NULL;
        }

        int serviceCount = (*nodes)[i].ServiceCount + 1;
        (*nodes)[i].Services = malloc(sizeof(ServiceDetails*) * serviceCount);
        if (!(*nodes)[i].Services) {
            printf("Failed to allocate memory for service details\n");
            return;
        }

        // Update the ServiceDetails structure with the new data
        (*nodes)[i].ServiceCount = serviceCount;
        (*nodes)[i].Services[serviceCount - 1] = malloc(sizeof(ServiceDetails));
        if (!(*nodes)[i].Services[serviceCount - 1]) {
            printf("Failed to allocate memory for service details\n");
            return;
        }

        // Populate the ServiceDetails structure with the new data
        (*nodes)[i].Services[serviceCount - 1]->ServiceType = 0;
        (*nodes)[i].Services[serviceCount - 1]->ServiceUpdateFrequency = 10;
        (*nodes)[i].Services[serviceCount - 1]->ServiceData = malloc(sizeof(int));
        if (!(*nodes)[i].Services[serviceCount - 1]->ServiceData) {
            printf("Failed to allocate memory for service data\n");
            return;
        }

        // Free the allocated memory when done
        free((*nodes)[i].Services[serviceCount - 1]->ServiceData);
    }
}

void FreeNetworkNodes(int nodeCount, NetworkNodeInfo_PDU_T** nodes) {
    // Validate input parameters
    if (nodeCount < 0 || !nodes) {
        printf("Invalid input parameter\n");
        return;
    }

    // Free the allocated memory for the list of NetworkNodeInfo_PDU_T structures
    for (int i = 0; i < nodeCount; ++i) {
        if ((*nodes)[i].ServiceCount > 0) {
            free((*nodes)[i].Services[(*nodes)[i].ServiceCount - 1]->ServiceData);
            free((*nodes)[i].Services[(*nodes)[i].ServiceCount - 1]);
            (*nodes)[i].Services[(*nodes)[i].ServiceCount - 1] = NULL;
        }

        if ((*nodes)[i].ServiceCount > 0) {
            free((*nodes)[i].Services);
            (*nodes)[i].Services = NULL;
        }

        free((*nodes)[i].NodeName);
        (*nodes)[i].NodeName = NULL;
    }

    free(*nodes);
    *nodes = NULL;
}
