#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_LINE_LENGTH 1024
#define MAX_HOSTNAME_LENGTH 256
#define MAX_IP_ADDRESS_LENGTH 16

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    char ip_address[MAX_IP_ADDRESS_LENGTH];
} Host;

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <input file> <output file>\n", argv[0]);
        return 1;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];

    FILE *fptr = fopen(input_file, "r");
    if (fptr == NULL) {
        perror("Error opening input file");
        return 1;
    }

    FILE *wptr = fopen(output_file, "w");
    if (wptr == NULL) {
        perror("Error opening output file");
        fclose(fptr);
        return 1;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, fptr)) {
        Host host;
        strcpy(host.hostname, line);

        int status = dnsResolve(&host.ip_address, host.hostname);
        if (status != 0) {
            fprintf(stderr, "Error resolving DNS for %s\n", host.hostname);
            continue;
        }

        // Calculate average of last two fields
        char *fields[2];
        int num_fields = splitLine(line, ',', 2, fields);
        if (num_fields < 2) {
            fprintf(stderr, "Invalid line format: %s\n", line);
            continue;
        }

        char *field1 = fields[0];
        char *field2 = fields[1];

        int field1_val = atoi(field1);
        int field2_val = atoi(field2);

        int average = (field1_val + field2_val) / 2;

        fprintf(wptr, "%s,%d\n", host.ip_address, average);
    }

    fclose(fptr);
    fclose(wptr);

    return 0;
}

int dnsResolve(char *ip_address, const char *hostname) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", gai_strerror(status));
        return 1;
    }

    struct in_addr *addr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;
    inet_ntop(AF_INET, addr, ip_address, MAX_IP_ADDRESS_LENGTH);

    freeaddrinfo(res);

    return 0;
}

int splitLine(char *line, char delimiter, int num_fields, char **fields) {
    int i = 0;
    char *token = strtok(line, &delimiter);

    while (token != NULL && i < num_fields) {
        fields[i] = token;
        token = strtok(NULL, &delimiter);
        i++;
    }

    return i;
}']

