    size_t rnti_len = sizeof(rnti_array) / sizeof(*rnti_array);

    // Create a new list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * rnti_len);

    // Initialize the list and populate each element with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (size_t i = 0; i < rnti_len; i++) {
        crc_indication_list[i].rx_ue_information_tag = rx_ue_information_tag;
        crc_indication_list[i].rnti = rnti_array[i];
        crc_indication_list[i].crc_indication_rel8_tag = crc_indication_rel8_tag;
        crc_indication_list[i].crcflag = rand() % 2 ? true : false; // Set CRCFLAG randomly
    }

    // Verify the integrity of each structure in the list
    for (size_t i = 0; i < rnti_len; i++) {
        if (crc_indication_list[i].rx_ue_information_tag != rx_ue_information_tag ||
            crc_indication_list[i].rnti != rnti_array[i] ||
            crc_indication_list[i].crc_indication_rel8_tag != crc_indication_rel8_tag) {
                // If the integrity check fails, release the memory and return NULL
                free(crc_indication_list);
                return NULL;
        }
    }

    // Link each element to the next in the list
    for (size_t i = 0; i < rnti_len - 1; i++) {
        crc_indication_list[i].next = &crc_indication_list[i + 1];
    }

    // Return the populated list of NFAPI_CRC_INDICATION_PDU_T structures
    return crc_indication_list;
}
