int load_config(const char *server, const char *filepath) {
    // Initialize variables
    CURL *curl;
    FILE *fp;
    struct curl_slist *chunk = NULL;
    struct stat fileinfo;
    long filesize;
    int record_count = 0;
    int *records = NULL;
    char *buf = NULL;
    bool success = false;

    // Create a new cURL handle
    curl = curl_easy_init();

    // Set the URL and HTTP method
    curl_easy_setopt(curl, CURLOPT_URL, server);
    curl_easy_setopt(curl, CURLOPT_HTTPGET, 1L);

    // Add the filepath header to the request
    chunk = curl_slist_append(chunk, "filepath");
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, chunk);

    // Set the response callback function
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, &write_callback);

    // Perform the request and get the response data
    fp = fopen(filepath, "wb");
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        // Error handling code here
        success = false;
    } else {
        // Get the file size and allocate memory for it
        fstat(fileno(fp), &fileinfo);
        filesize = fileinfo.st_size;
        records = malloc(filesize * sizeof(int));
        if (records == NULL) {
            success = false;
        } else {
            // Read the response data into memory
            buf = malloc(filesize * sizeof(char));
            if (buf == NULL) {
                success = false;
            } else {
                size_t nread = fread(buf, 1, filesize, fp);
                if (nread < filesize) {
                    success = false;
                } else {
                    // Parse the response data and allocate memory for records
                    record_count = parse_response(buf, filesize, records);
                    if (record_count <= 0) {
                        success = false;
                    } else {
                        success = true;
                    }
                }
            }
        }
    }

    // Clean up resources
    curl_slist_free_all(chunk);
    fclose(fp);
    free(buf);
    if (records != NULL) {
        free(records);
    }

    // Return the number of records in the configuration file
    return success ? record_count : 0;
}

// Write callback function for cURL response data
