#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <sqlite3.h>

// Structure to store RX_UE_INFORMATION_TAG and RNTI information
typedef struct {
  int rnti;
  char* ue_information;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variable to keep track of the number of attempts for memory allocation
int num_attempts = 0;

// Global variable to keep track of the total number of RNTIs in the list
int total_rntis = 0;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int num_elements) {
  // Initialize the list head
  NFAPI_CRC_INDICATION_PDU_T* head = NULL;

  // Allocate memory for each structure and populate it with random data
  for (int i = 0; i < num_elements; i++) {
    NFAPI_CRC_INDICATION_PDU_T* new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_element) {
      // Log error and return NULL on failure to allocate memory
      num_attempts++;
      printf("Error: Failed to allocate memory for element %d\n", i);
      fflush(stdout);
      if (num_attempts > 3) {
        return NULL;
      }
    } else {
      // Set RNTI and CRC flag randomly
      new_element->rnti = rand() % 10000;
      new_element->crc_indication_rel8.crc_flag = (rand() % 2 == 0) ? true : false;

      // Add the element to the list head
      if (!head) {
        head = new_element;
      } else {
        new_element->next = head;
        head = new_element;
      }
    }
  }

  return head;
}

// Function to fetch UE information from an external database based on RNTI
int get_ue_information(NFAPI_CRC_INDICATION_PDU_T* element) {
  // Initialize the database connection
  sqlite3* db = NULL;
  char* error_message = NULL;

  // Open the database and check for errors
  if (sqlite3_open("ue_information.db", &db)) {
    error_message = "Error: Failed to open database";
    printf("%s\n", error_message);
    fflush(stdout);
    return -1;
  }

  // Prepare the SQL query and check for errors
  sqlite3_stmt* statement;
  char* query = "SELECT ue_information FROM ue_table WHERE rnti=?";
  if (sqlite3_prepare(db, query, -1, &statement, NULL)) {
    error_message = "Error: Failed to prepare SQL query";
    printf("%s\n", error_message);
    fflush(stdout);
    return -1;
  }

  // Bind the RNTI value and execute the query
  if (sqlite3_bind_int(statement, 1, element->rnti)) {
    error_message = "Error: Failed to bind RNTI value";
    printf("%s\n", error_message);
    fflush(stdout);
    return -1;
  }
  if (sqlite3_step(statement) != SQLITE_ROW) {
    error_message = "Error: No row found for the given RNTI";
    printf("%s\n", error_message);
    fflush(stdout);
    return -1;
  }

  // Retrieve the UE information and update the list element
  const unsigned char* ue_information = sqlite3_column_text(statement, 0);
  if (!ue_information) {
    error_message = "Error: Failed to retrieve UE information";
    printf("%s\n", error_message);
    fflush(stdout);
    return -1;
  }
  element->ue_information = strdup((const char*)ue_information);

  // Close the database connection and free the statement object
  sqlite3_finalize(statement);
  sqlite3_close(db);

  return 0;
}

// Thread-safe function to fetch UE information for a given RNTI
int get_ue_information_thread_safe(NFAPI_CRC_INDICATION_PDU_T* element) {
  // Lock the mutex to prevent concurrent access to the database connection
  pthread_mutex_lock(&database_mutex);

  int ret = get_ue_information(element);

  // Unlock the mutex and return the result of the function
  pthread_mutex_unlock(&database_mutex);
  return ret;
}

// Function to clean up memory allocated for the list elements
void destroy_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T* head) {
  // Iterate through the list and free each element's memory
  while (head) {
    NFAPI_CRC_INDICATION_PDU_T* next = head->next;
    free(head);
    head = next;
  }
}

// Function to log relevant information for debugging and monitoring purposes
void log_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T* head) {
  // Iterate through the list and log each element's RNTI and CRC flag
  while (head) {
    printf("RNTI: %d, CRC Flag: %d\n", head->rnti, head->crc_indication_rel8.crc_flag);
    fflush(stdout);
    head = head->next;
  }
}
```
