    // Check if inputs are valid
    if (num_ues <= 0 || ue_ids == NULL || mac_configs == NULL || dl_transmission_configs == NULL) {
        return -1;
    }

    // Allocate memory for list of LTE_MAC_Config structures
    int num_mac_configs = sizeof(LTE_MAC_Config) * num_ues;
    LTE_MAC_Config *mac_config_list = (LTE_MAC_Config *)malloc(num_mac_configs);
    if (mac_config_list == NULL) {
        return -2;
    }

    // Populate list of LTE_MAC_Config structures with random values for UL_Duplex_Mode and RRM settings
