        mac_config_list[i].UE_ID = ue_ids[i];
        mac_config_list[i].MAC_config.transmit_power = rand() % 100 + 100; // Randomly set transmit power between 100 and 200
        mac_config_list[i].MAC_config.receive_sensitivity = rand() % 50 + 50; // Randomly set receive sensitivity between 50 and 100
        mac_config_list[i].DL_transmission_config.UL_duplex_mode = (rand() % 2) ? FDD : TDD; // Randomly set UL_Duplex_Mode to FDD or TDD
        mac_config_list[i].DL_transmission_config.buffer_size = rand() % 1000 + 500; // Randomly set buffer size between 500 and 1500
    }

    // Copy list of LTE_MAC_Config structures to output parameters
    memcpy(mac_configs, mac_config_list, num_mac_configs);
    memcpy(dl_transmission_configs, dl_transmission_configs, num_ues * sizeof(DL_Transmission_Config));

    // Clean up memory allocated for list of LTE_MAC_Config structures
    free(mac_config_list);

    return 0;
}

// Define function to log configuration details to a file
int log_configuration_details(const char *filename, int num_ues, LTE_MAC_Config *mac_configs) {
    // Check if inputs are valid
    if (filename == NULL || num_ues <= 0 || mac_configs == NULL) {
        return -1;
    }

    // Open file for writing configuration details
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        return -2;
    }

    // Write configuration details to file
    for (int i = 0; i < num_ues; i++) {
        fprintf(fp, "UE ID: %d\n", mac_configs[i].UE_ID);
        fprintf(fp, "Transmit Power: %d\n", mac_configs[i].MAC_config.transmit_power);
        fprintf(fp, "Receive Sensitivity: %d\n", mac_configs[i].MAC_config.receive_sensitivity);
        fprintf(fp, "UL Duplex Mode: %s\n", (mac_configs[i].DL_transmission_config.UL_duplex_mode == FDD) ? "FDD" : "TDD");
        fprintf(fp, "Buffer Size: %d\n", mac_configs[i].DL_transmission_config.buffer_size);
    }

    // Close file
    fclose(fp);

    return 0;
}
