    // Reallocate memory for the list of UE configurations
    LTE_UE_Config *new_config = realloc(*config, sizeof(LTE_UE_Config) * new_size);
    if (new_config == NULL) {
        fprintf(stderr, "Failed to resize the list of UE configurations\n");
        return -1;
    }
    *config = new_config;

    // Initialize the new elements with empty configuration structures
    for (int i = *size; i < new_size; i++) {
