int* read_input(int* count) {
    // Check if the input is valid
    if (count == NULL) {
        return NULL;
    }

    // Initialize the array to hold the input values
    int* input = (int*)malloc(*count * sizeof(int));
    if (input == NULL) {
        return NULL;
    }

    // Read the input from standard input and store it in the array
    for (int i = 0; i < *count; i++) {
        scanf("%d", &input[i]);
    }

    // Find the average signal strength in the array
