            throw new Exception("Environment variable not set: {$param}");
        }
    }

    return $params;
}

// Function to update an existing resource using the HTTP PUT method and return the updated resource
function updateResource($url, $data) {
    // Create a new cURL session
    $ch = curl_init();

    // Set the URL, POST data, and other options for the request
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, array('Content-Type: application/x-www-form-urlencoded'));

    // Perform the request and handle the response
    $response = curl_exec($ch);
    if (curl_errno($ch) > 0) {
        throw new Exception("cURL error: " . curl_error($ch));
    }

    // Close the cURL session
    curl_close($ch);

    return $response;
}

// Function to handle the deletion of resources using the HTTP DELETE method and return new resources with default values
function deleteResource($url) {
    // Create a new cURL session
    $ch = curl_init();

    // Set the URL, POST data, and other options for the request
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_CUSTOMREQUEST, "DELETE");
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_HTTPHEADER, array('Content-Type: application/x-www-form-urlencoded'));

    // Perform the request and handle the response
    $response = curl_exec($ch);
    if (curl_errno($ch) > 0) {
        throw new Exception("cURL error: " . curl_error($ch));
    }

    // Close the cURL session
    curl_close($ch);

    return $response;
}

// Main function to handle external API calls and resource updates
function main() {
    // Fetch the necessary configuration parameters from an external data source
    $params = fetchConfigParams($env);

    // Initialize the list of structures for RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    $list = createAndPopulateList(1000);
    if ($list == NULL) {
        throw new Exception("Failed to allocate memory for the list of structures");
    }

    // Loop through each structure in the list and perform an HTTP PUT request for each one
    foreach ($list as $structure) {
        $data = array(
            'rx_ue_information_tag' => $structure->rx_ue_information_tag,
            'rnti' => $structure->rnti,
            'crc_indication_rel8_tag' => $structure->crc_indication_rel8_tag
        );
        try {
            updateResource($url, $data);
        } catch (Exception $e) {
            echo "Error updating resource: {$e->getMessage()}\n";
        }
    }

    // Free the memory allocated for the list of structures
    free($list);

    // Loop through each structure in the list and perform an HTTP DELETE request for each one that has a CRCFLAG value of 1
    foreach ($list as $structure) {
        if ($structure->crc_indication_rel8_tag == 1) {
            try {
                deleteResource($url);
            } catch (Exception $e) {
                echo "Error deleting resource: {$e->getMessage()}\n";
            }
        }
    }
}
