// C function for initializing and populating a list of CellularUeInfo_PDU_T structures with randomized CrcIndications
void init_ue_info_list(struct CellularUeInfo_PDU_T **ue_info_list, int num_ues) {
    // Check input parameters for validity
    if (ue_info_list == NULL || num_ues <= 0) {
        return;
    }

    // Dynamic resizing of the list based on input size requirements
    *ue_info_list = malloc(sizeof(struct CellularUeInfo_PDU_T) * num_ues);
    if (*ue_info_list == NULL) {
        return;
    }

    // Initialize each element of the list with a valid UE ID and RNTI, and a randomized CrcIndication
    for (int i = 0; i < num_ues; ++i) {
        (*ue_info_list)[i].UE_ID = i + 1; // Start from 1 to avoid duplicate UE IDs
        (*ue_info_list)[i].RNTI = rand() % 1000000; // Randomize RNTI within a range of 1-1,000,000
        (*ue_info_list)[i].CrcIndication = (rand() % 2) == 0; // Randomize CrcIndication with 50% probability of 0 or 1
