#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include "nfapi_types.h"

// Structure to hold information about each CRC indication PDU
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    bool crcflag; // Set to 1 for every second structure in the list
} crc_indication_pdu_t;

// Function to create and populate a list of CRC indication PDUs
int populate_crc_indications(crc_indication_pdu_t **list, int num_rx_ues) {
    // Allocate memory for the list
    *list = (crc_indication_pdu_t *)malloc(sizeof(crc_indication_pdu_t) * num_rx_ues);
    if (*list == NULL) {
        return -1; // Memory allocation failed
    }

    // Initialize the list elements
    for (int i = 0; i < num_rx_ues; i++) {
        (*list)[i].pdu.rx_ue_information_tag = (uint8_t)(i + 1);
        (*list)[i].pdu.rnti = (uint16_t)(i * 2);
        (*list)[i].crcflag = i % 2 == 0; // Set crcflag to 1 for every second structure in the list
    }

    // Validate that each RX_UE_INFORMATION_TAG and RNTI are unique within the list
    for (int i = 0; i < num_rx_ues - 1; i++) {
        if ((*list)[i].pdu.rx_ue_information_tag == (*list)[i + 1].pdu.rx_ue_information_tag ||
                (*list)[i].pdu.rnti == (*list)[i + 1].pdu.rnti) {
            return -2; // Duplicate RX_UE_INFORMATION_TAG or RNTI found
        }
    }

    return num_rx_ues; // Return the number of elements in the list
}

// Function to update the CRCFLAG of a CRC indication PDU
void update_crcflag(crc_indication_pdu_t *pdu, bool crcflag) {
    pdu->crcflag = crcflag;
}

// Function to retrieve the CRCFLAG of a CRC indication PDU
bool get_crcflag(const crc_indication_pdu_t *pdu) {
    return pdu->crcflag;
}

// Function to free the memory allocated for a list of CRC indication PDUs
