#include <string.h>
#include <errno.h>

typedef struct {
    int key;
    float data;
    long *offset;
} dataRecord;

int readCSV(const char *filename, dataRecord **records, size_t *numRecords) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return -1; // error opening file
    }

    long *offsets = malloc(sizeof(long) * 3);
    int *keys = malloc(sizeof(int) * 3);
    float *dataValues = malloc(sizeof(float) * 3);
    if (offsets == NULL || keys == NULL || dataValues == NULL) {
        free(offsets);
        free(keys);
        free(dataValues);
        return -2; // error allocating memory
    }

    size_t numRecords = 0;
    while (fscanf(file, "%ld,%d,%f", &offsets[numRecords], &keys[numRecords], &dataValues[numRecords]) == 3) {
        ++numRecords;
    }

    if (ferror(file)) {
        free(offsets);
        free(keys);
        free(dataValues);
        return -3; // error reading from file
    }

    dataRecord *recordArray = malloc(sizeof(dataRecord) * numRecords);
    if (recordArray == NULL) {
        free(offsets);
        free(keys);
        free(dataValues);
        return -4; // error allocating memory
    }

    for (size_t i = 0; i < numRecords; ++i) {
        recordArray[i].key = keys[i];
        recordArray[i].data = dataValues[i];
        recordArray[i].offset = &offsets[i];
    }

    *records = recordArray;
    *numRecords = numRecords;

    free(offsets);
    free(keys);
    free(dataValues);

    return 0; // success
}
```
