CRC_INDICATION_LIST_T* crc_indication_list_create(size_t initial_capacity, CRC_INDICATION_CONFIG_T* config) {
    if (initial_capacity == 0 || config == NULL) {
        log_error("Invalid input parameters");
        return NULL;
    }

    // Create the list with the specified initial capacity and growth factor
    CRC_INDICATION_LIST_T* list = malloc(sizeof(CRC_INDICATION_LIST_T));
    if (list == NULL) {
        log_error("Failed to allocate memory for the list");
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    list->data = malloc(sizeof(CRC_INDICATION_DATA_T) * list->capacity);
    if (list->data == NULL) {
        log_error("Failed to allocate memory for the list data");
        free(list);
        return NULL;
    }

    // Initialize the list with the specified configuration parameters
    list->config = config;

    return list;
}

// Define the function to add a new entry to the list of NFAPI_CRC_INDICATION_PDU_T structures
void crc_indication_list_add(CRC_INDICATION_LIST_T* list, uint32_t rnti, void* data) {
    if (list == NULL || rnti == 0 || data == NULL) {
        log_error("Invalid input parameters");
        return;
    }

    // Check if the list is full and needs to be resized
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * list->config.growth_factor;
        if (new_capacity > list->config.maximum_allowed_entries) {
            log_error("The list is full and cannot be resized any further");
            return;
        }
        CRC_INDICATION_DATA_T* new_data = realloc(list->data, sizeof(CRC_INDICATION_DATA_T) * new_capacity);
        if (new_data == NULL) {
            log_error("Failed to resize the list");
            return;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    // Create a new entry and populate it with the RNTI and data
    CRC_INDICATION_DATA_T* entry = malloc(sizeof(CRC_INDICATION_DATA_T));
    if (entry == NULL) {
        log_error("Failed to allocate memory for the new entry");
        return;
    }
    entry->rnti = rnti;
    memcpy(&entry->crc_indication, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add the entry to the list and update the size
    list->data[list->size++] = *entry;
}

// Define the function to free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures
void crc_indication_list_free(CRC_INDICATION_LIST_T* list) {
    if (list == NULL) {
        log_error("Invalid input parameters");
        return;
    }

    // Free the memory allocated for the list data and the list structure itself
    free(list->data);
    free(list);
}
