import java.security.MessageDigest;

public class StringHasher {
    public static void main(String[] args) {
        // Create a new instance of the MessageDigest class with the SHA-256 algorithm
        MessageDigest digester = null;
        try {
            digester = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            System.out.println("Failed to initialize the hash function: " + e.getMessage());
        }

        // Hash the input string using the MessageDigest class
        String input = args[0];
        try {
            byte[] hash = digester.digest(input.getBytes());
            System.out.println("The MD5 hash of the input string is: " + bytesToHex(hash));
        } catch (Exception e) {
            System.out.println("Failed to generate the MD5 hash: " + e.getMessage());
        }
    }

    // Convert a byte array to a hexadecimal string representation
    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
