void read_integer_array(int** array, int max_size) {
    // Allocate memory for the array
    *array = (int*)malloc(max_size * sizeof(int));
    if (*array == NULL) {
        printf("Error: failed to allocate memory for the integer array\n");
        return;
    }

    // Read the integers from standard input and store them in the array
