// Function to create and populate a new UE Context structure
struct ue_context* create_ue_context(int id, long tmsi, char* nas_security_parameters) {
    // Allocate memory for the new UE context
    struct ue_context* new_context = (struct ue_context*)malloc(sizeof(struct ue_context));
    if (!new_context) {
        printf("Error: Failed to allocate memory for new UE context!\n");
        return NULL;
    }

    // Initialize the UE context fields
    new_context->id = id;
    new_context->tmsi = tmsi;
    new_context->nas_security_parameters = nas_security_parameters;

    // Add the new UE context to the list
    pthread_mutex_lock(&context_list_mutex);
    if (context_list == NULL) {
        context_list = (struct ue_context*)malloc(sizeof(struct ue_context));
        if (!context_list) {
            printf("Error: Failed to allocate memory for UE context list!\n");
            return NULL;
        }
    } else {
        struct ue_context* current = context_list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_context;
    }
    pthread_mutex_unlock(&context_list_mutex);

    return new_context;
}

// Function to retrieve a UE Context structure from the list by ID
struct ue_context* get_ue_context(int id) {
    struct ue_context* current = context_list;
    while (current != NULL) {
        if (current->id == id) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Function to clear the UE Context list when it is no longer needed
void clear_ue_contexts() {
    pthread_mutex_lock(&context_list_mutex);
    struct ue_context* current = context_list;
    while (current != NULL) {
        struct ue_context* next = current->next;
        free(current);
        current = next;
    }
    context_list = NULL;
    pthread_mutex_unlock(&context_list_mutex);
}

// Function to handle memory allocation failures
