// Define the function to calculate the modulation scheme based on the current network load and interference levels
uint8_t calculate_modulation_scheme(LTE_PHY_RX_FRAME_INFO* lte_rx_frame_info, int num_frames) {
    // Calculate the average PHR value across all frames
    float avg_phr = 0;
    for (int i = 0; i < num_frames; i++) {
        avg_phr += lte_rx_frame_info[i].phr;
    }
    avg_phr /= num_frames;

    // Calculate the modulation scheme based on the average PHR value and network load
    uint8_t modulation_scheme = MODULATION_QPSK;
    if (avg_phr < -20) {
        modulation_scheme = MODULATION_16QAM;
    } else if (avg_phr < 0 && avg_phr >= -20) {
        modulation_scheme = MODULATION_8PSK;
    }

    // Return the calculated modulation scheme
    return modulation_scheme;
}
