  rx_frame_list->capacity = num_frames;
  rx_frame_list->data = malloc(sizeof(LTE_PHY_RX_FRAME_INFO) * num_frames);
  if (rx_frame_list->data == NULL) {
    free(rx_frame_list);
    return NULL;
  }

  // Populate the list with random data
  srand((unsigned int)time(NULL));
  for (int i = 0; i < num_frames; i++) {
    LTE_PHY_RX_FRAME_INFO* rx_frame = &rx_frame_list->data[i];
    rx_frame->ue_id = rand() % 10000;
    rx_frame->phr = rand() % 50;
