// Define a function for adding LTE PHY RX frame information to the list
void add_rx_frame(LTE_PHY_RX_FRAME_LIST* rx_frame_list, int ue_id, int phr) {
  // Lock the mutex variable to synchronize access to the list data structure
  pthread_mutex_lock(&list_lock);

  // Check if the list has enough capacity for another entry
  if (rx_frame_list->size == rx_frame_list->capacity) {
    // If not, reallocate memory for the list data structure with doubled size
    int new_capacity = rx_frame_list->capacity * 2;
    LTE_PHY_RX_FRAME_INFO* new_data = realloc(rx_frame_list->data, sizeof(LTE_PHY_RX_FRAME_INFO) * new_capacity);
    if (new_data == NULL) {
      pthread_mutex_unlock(&list_lock);
      return;
    }
    rx_frame_list->data = new_data;
    rx_frame_list->capacity = new_capacity;
  }

  // Add the new entry to the list
  LTE_PHY_RX_FRAME_INFO* rx_frame = &rx_frame_list->data[rx_frame_list->size];
  rx_frame->ue_id = ue_id;
  rx_frame->phr = phr;
  rx_frame->timestamp = time(NULL);
  rx_frame->error_correction_status = (rand() % 2) ? 1 : 0;
  rx_frame_list->size++;

  // Unlock the mutex variable
  pthread_mutex_unlock(&list_lock);
}

