  if (dl_sch_list->size == dl_sch_list->capacity) {
    // If not, reallocate memory for the list data structure with doubled size
    int new_capacity = dl_sch_list->capacity * 2;
    LTE_PHY_DL_SCH_BLOCK* new_data = realloc(dl_sch_list->data, sizeof(LTE_PHY_DL_SCH_BLOCK) * new_capacity);
    if (new_data == NULL) {
      pthread_mutex_unlock(&list_lock);
      return;
    }
    dl_sch_list->data = new_data;
    dl_sch_list->capacity = new_capacity;
  }

  // Add the new entry to the list
