int encrypt_decrypt(EVP_CIPHER* cipher, const uint8_t* input, int ilen, uint8_t* output, int olen) {
  // Check if the specified encryption mode is supported
  if (cipher == NULL) {
    return -1;
  }

  // Encrypt or decrypt the data using the specified cryptographic cipher and key length
  EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
  if (ctx == NULL) {
    return -1;
  }
  int outlen = 0;
  int rv = EVP_EncryptInit(ctx, cipher, NULL, output);
  if (rv != 1) {
    return -1;
  }
  rv = EVP_EncryptUpdate(ctx, output, &outlen, input, ilen);
  if (rv != 1) {
    return -1;
  }
  int outlen2 = 0;
  rv = EVP_EncryptFinal(ctx, output + outlen, &outlen2);
  if (rv != 1) {
    return -1;
  }
  outlen += outlen2;
  EVP_CIPHER_CTX_free(ctx);
  return outlen;
}

