// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *populate_list(void) {
    // Allocate memory for the list
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_LIST_SIZE);

    if (list == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    // Initialize the list with a random CRCFLAG value
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        list[i].CRCFLAG = rand() % 256;
    }

    // Populate the list with UE information from the external data source
    int count = 0;
    for (int i = 0; i < MAX_LIST_SIZE && count < ue_information->num_ues; i++) {
        NFAPI_UE_INFORMATION_ENTRY_T *entry = &ue_information->entries[i];
        list[count].RX_UE_INFORMATION_TAG = entry->rx_ue_information_tag;
        list[count].RNTI = entry->rnti;
        count++;
    }

    // Sort the list based on the RNTI values in ascending order
    qsort(list, MAX_LIST_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);

    return list;
}

// Function to handle data source failures and implement retry logic
int get_ue_information(void) {
    // Try to retrieve the UE information from the external data source
    int ret = ue_information_get();

    if (ret == 0) {
        return 1;
    } else if (ret == -1) {
        // Handle data source failure
        return -1;
    } else {
        // Retry after a random interval to prevent overloading the data source
        int retry_interval = rand() % 30 + 1;
        sleep(retry_interval);
        return get_ue_information();
    }
}

// Function to invalidate the cache and update it with new UE information
void update_cache(void) {
    // Invalidate the cache if there is a change in the number of UEs or if the external data source fails
    if (ue_information->num_ues != ue_information_cache.num_ues || ret == -1) {
        memset(&ue_information_cache, 0, sizeof(NFAPI_UE_INFORMATION_T));
    }
}

// Function to retrieve UE information from the cache or update it if necessary
int get_cached_ue_information(void) {
    // Check if the cache is invalid and needs to be updated
    if (ue_information_cache.num_ues == 0) {
        update_cache();
    }

    // Return the UE information from the cache or an error if it could not be retrieved
    if (ue_information_cache.num_ues > 0) {
        return &ue_information_cache;
    } else {
        return -1;
    }
}

// Function to compare RNTIs in ascending order
int compare_rnti(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T *pda = (NFAPI_CRC_INDICATION_PDU_T *) a;
    NFAPI_CRC_INDICATION_PDU_T *pdb = (NFAPI_CRC_INDICATION_PDU_T *) b;
    return pda->RNTI - pdb->RNTI;
}

// Function to sort the list based on the RNTIs in ascending order
void sort_list(NFAPI_CRC_INDICATION_PDU_T *list) {
    qsort(list, MAX_LIST_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_rnti);
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures with caching and retry logic
NFAPI_CRC_INDICATION_PDU_T *populate_list(void) {
    // Try to retrieve the UE information from the cache or update it if necessary
    int ret = get_cached_ue_information();

    if (ret == -1) {
        // Handle data source failure
        return NULL;
    } else if (ret == 0) {
        // Retrieve the UE information from the external data source with retry logic
        ret = get_ue_information();

        if (ret == -1) {
            // Handle data source failure
            return NULL;
        }
    }

    // Populate the list with the UE information
    NFAPI_CRC_INDICATION_PDU_T *list = populate_list();

    if (list != NULL) {
        sort_list(list);
    }

    return list;
}
