int insert_crc_ind(crc_ind_list_t* list, NFAPI_CRC_INDICATION_PDU_T crc_ind) {
    // Check if the list is null or empty
    if (list == NULL || list->size == 0) {
        return 1; // Error: List is not initialized or empty
    }

    // Increment the size of the list by one
    list->size++;

    // Check if the capacity of the list has been exceeded
    if (list->size > list->capacity) {
        return 2; // Error: List capacity exceeded
    }

    // Dynamically allocate memory for the new crc_ind_t structure
    crc_ind_t* new_element = (crc_ind_t*)malloc(sizeof(crc_ind_t));
    if (new_element == NULL) {
        return 3; // Error: Memory allocation failed
    }

    // Copy the contents of the crc_ind structure to the new element
    memcpy(&(new_element->crc_ind), &crc_ind, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Set the CRCFLAG to a randomly set value
    new_element->crcflag_set = false;

    // Add the new element to the end of the list
    list->data[list->size - 1] = *new_element;

    return 0; // Success: Element added successfully
}

// Function to clean up stale entries in the list (e.g., older than 5 seconds)
int cleanup_crc_ind(crc_ind_list_t* list, int max_age) {
    // Check if the list is null or empty
    if (list == NULL || list->size == 0) {
        return 1; // Error: List is not initialized or empty
    }

    // Get the current time in seconds
    time_t now = time(NULL);

    // Iterate through the list and remove stale entries
    for (int i = list->size - 1; i >= 0; i--) {
        if (difftime(now, list->data[i].crc_ind.header.timestamp) > max_age) {
            // Remove the entry from the list
            memmove(&list->data[i], &list->data[i + 1], sizeof(crc_ind_t));
            list->size--;
        }
    }

    return 0; // Success: Stale entries cleaned up successfully
}

