char* allocate_arrays(int num_offsets, int num_keys) {
    // Allocate memory for the three arrays
    long* offsets = (long*) malloc(num_offsets * sizeof(long));
    int* keys = (int*) malloc(num_keys * sizeof(int));
    struct record* records = (struct record*) malloc(sizeof(struct record) * num_keys);

    // Initialize the arrays with appropriate values
    for (int i = 0; i < num_offsets; i++) {
        offsets[i] = i * 10;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i] = i * 2;
    }
    for (int i = 0; i < num_keys; i++) {
        records[i].value = i * 3;
        strcpy(records[i].array, "Hello World");
    }

    // Handle allocation failure
    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return "Memory allocation failed";
    }

    // Ensure proper alignment and null-termination of the 'char' arrays
    for (int i = 0; i < num_keys; i++) {
        records[i].array[9] = '\0';
    }

    return "Memory allocation succeeded";
}']

