    int numServiceRequests;
} NetworkNode;

// Function to create a new PDU with service requests
NetworkNode* createNetworkNodePDU(int nodeID, int numServiceRequests) {
    // Allocate memory for the network node structure
    NetworkNode *pdu = (NetworkNode *)malloc(sizeof(NetworkNode));
    if (!pdu) {
        printf("Error: unable to allocate memory for PDU\n");
        return NULL;
    }

    // Initialize the node ID and service request list
    pdu->nodeID = nodeID;
    pdu->numServiceRequests = numServiceRequests;
    pdu->serviceRequests = (ServiceRequest *)malloc(numServiceRequests * sizeof(ServiceRequest));
    if (!pdu->serviceRequests) {
        printf("Error: unable to allocate memory for service requests\n");
        free(pdu);
        return NULL;
    }

    // Randomly set QoS levels for each service request
    srand(time(NULL));
    for (int i = 0; i < numServiceRequests; i++) {
        pdu->serviceRequests[i].UE_ID = rand();
        pdu->serviceRequests[i].QoS = rand() % 5; // Random QoS level
