#include <unistd.h>

#define MAX_NFAPI_CRC_INDICATION_PDU 1000
#define RX_UE_INFORMATION_TAG "RX_UE_INFORMATION"
#define RNTI "RNTI"
#define CRC_INDICATION_REL8_TAG "CRC_INDICATION_REL8"
#define CRCFLAG "CRCFlag"
#define MAX_RNTI 1000

typedef struct {
    char *rx_ue_information_tag;
    uint16_t rnti;
    char *crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfapi_create_crc_indication_pdu(size_t num_pdu) {
    if (num_pdu > MAX_NFAPI_CRC_INDICATION_PDU) {
        printf("Error: Number of CRC indication PDUs exceeds maximum capacity\n");
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *pdu = calloc(num_pdu, sizeof(*pdu));
    if (!pdu) {
        printf("Error: Failed to allocate memory for CRC indication PDUs\n");
        return NULL;
    }
    size_t i;
    for (i = 0; i < num_pdu; ++i) {
        pdu[i].rx_ue_information_tag = calloc(1, strlen(RX_UE_INFORMATION_TAG) + 1);
        if (!pdu[i].rx_ue_information_tag) {
            printf("Error: Failed to allocate memory for RX UE information tag\n");
            goto error;
        }
        strcpy(pdu[i].rx_ue_information_tag, RX_UE_INFORMATION_TAG);
        pdu[i].rnti = rand() % MAX_RNTI + 1;
        pdu[i].crc_indication_rel8_tag = calloc(1, strlen(CRC_INDICATION_REL8_TAG) + 1);
        if (!pdu[i].crc_indication_rel8_tag) {
            printf("Error: Failed to allocate memory for CRC indication REL8 tag\n");
            goto error;
        }
        strcpy(pdu[i].crc_indication_rel8_tag, CRC_INDICATION_REL8_TAG);
        pdu[i].crcflag = rand() % 256;
    }
    return pdu;
error:
    for (size_t j = i - 1; j >= 0; --j) {
        free(pdu[j].rx_ue_information_tag);
        free(pdu[j].crc_indication_rel8_tag);
    }
    free(pdu);
    return NULL;
}

void nfapi_free_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, size_t num_pdu) {
    if (!pdu) return;
    size_t i;
    for (i = 0; i < num_pdu; ++i) {
        free(pdu[i].rx_ue_information_tag);
        free(pdu[i].crc_indication_rel8_tag);
    }
    free(pdu);
}

void *nfapi_crc_indication_thread(void *args) {
    size_t num_pdu = 10;
    NFAPI_CRC_INDICATION_PDU_T *pdu = nfapi_create_crc_indication_pdu(num_pdu);
    if (!pdu) return NULL;
    size_t i;
    for (i = 0; i < num_pdu; ++i) {
        printf("CRC Indication PDU %zu: RX UE Information Tag: %s, RNTI: %u, CRC Indication REL8 Tag: %s, CRCFlag: %u\n", i + 1, pdu[i].rx_ue_information_tag, pdu[i].rnti, pdu[i].crc_indication_rel8_tag, pdu[i].crcflag);
    }
    nfapi_free_crc_indication_pdu(pdu, num_pdu);
    return NULL;
}

int main() {
    pthread_t thread;
    if (pthread_create(&thread, NULL, nfapi_crc_indication_thread, NULL)) {
        printf("Error: Failed to create CRC indication thread\n");
        return 1;
    }
    pthread_join(thread, NULL);
    return 0;
}
