// Define a struct to represent an LTE UE Context
typedef struct {
  uint32_t ue_id; // Unique ID for the UE
  uint16_t cell_id; // Cell ID where the UE is attached
  int8_t rlc_status_reports[MAX_RLC_STATUS_REPORTS]; // Array of RLC status reports
} ue_context_t;

// Define a global variable to store the list of LTE UE Contexts
ue_context_t *ue_contexts = NULL;

// Function to initialize and populate an LTE UE Context
void init_ue_context(uint32_t ue_id, uint16_t cell_id) {
  // Check if the UE ID is already in use
  for (int i = 0; i < MAX_UE_CONTEXT; i++) {
    if (ue_contexts[i].ue_id == ue_id) {
      return; // Return early if the UE ID is already in use
    }
  }

  // Initialize a new LTE UE Context
  ue_context_t *new_context = malloc(sizeof(ue_context_t));
  new_context->ue_id = ue_id;
  new_context->cell_id = cell_id;
  for (int i = 0; i < MAX_RLC_STATUS_REPORTS; i++) {
    new_context->rlc_status_reports[i] = -1; // Set all RLC status reports to -1
  }

  // Add the new context to the list of UE Contexts
  ue_contexts = realloc(ue_contexts, (MAX_UE_CONTEXT + 1) * sizeof(ue_context_t));
  memcpy(&ue_contexts[MAX_UE_CONTEXT], new_context, sizeof(ue_context_t));
  MAX_UE_CONTEXT++;
}

// Function to generate a random SN for an RLC status report
int8_t gen_sn() {
  return (rand() % 100) - 50; // Generate a random number between -50 and +50
}

// Function to update the RLC status reports for a given UE Context
void update_rlc_reports(ue_context_t *context) {
  int8_t sn = gen_sn(); // Generate a new SN
  context->rlc_status_reports[0] = sn; // Set the first RLC status report to the new SN
}
