// Global variables
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER; // Lock for synchronizing access to the list
static int num_allocated_structures = 0; // Number of allocated structures in the list
static int num_used_structures = 0; // Number of used structures in the list
static NFAPI_CRC_INDICATION_PDU_T *list = NULL; // List of NFAPI_CRC_INDICATION_PDU_T structures

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures.
// Each structure contains a valid RX_UE_INFORMATION_TAG and RNTI,
// and a CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG.
NFAPI_CRC_INDICATION_PDU_T *create_and_populate_list(int num_structures) {
  // Initialize the list
  list = (NFAPI_CRC_INDICATION_PDU_T *) malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (list == NULL) {
    printf("Error: Failed to allocate memory for the list\n");
    return NULL;
  }
  num_allocated_structures = num_structures;
  num_used_structures = 0;

  // Populate the list with random values
  int i, j;
  for (i = 0; i < num_allocated_structures; i++) {
    // Generate a valid RX_UE_INFORMATION_TAG and RNTI
    NFAPI_CRC_INDICATION_PDU_T *structure = &list[i];
    structure->rx_ue_information_tag = generate_random_rx_ue_information_tag();
    structure->rnti = generate_random_rnti();

    // Generate a random CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
    NFAPI_CRC_INDICATION_REL8_T *crc_indication_rel8 = &structure->crc_indication_rel8;
    crc_indication_rel8->crc_flag = generate_random_crc_flag();
  }

  return list;
}

// Function to add a new structure to the list.
// The function will resize the list if it is full and reallocate memory for the new structure.
void add_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
  // Acquire the lock to prevent concurrent access to the list
  pthread_mutex_lock(&list_lock);

  // Check if the list is full and resize it if necessary
  if (num_used_structures == num_allocated_structures) {
    num_allocated_structures *= 2; // Double the size of the list
    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, num_allocated_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list == NULL) {
      printf("Error: Failed to reallocate memory for the list\n");
      pthread_mutex_unlock(&list_lock);
      return;
    } else {
      list = new_list;
    }
  }

  // Copy the structure into the list
  NFAPI_CRC_INDICATION_PDU_T *new_structure = &list[num_used_structures++];
  memcpy(new_structure, structure, sizeof(NFAPI_CRC_INDICATION_PDU_T));

  // Release the lock and return
  pthread_mutex_unlock(&list_lock);
}

// Function to delete a structure from the list.
// The function will remove the structure from the list and resize it if necessary.
void delete_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
  // Acquire the lock to prevent concurrent access to the list
  pthread_mutex_lock(&list_lock);

  // Find the structure in the list and remove it
  int i;
  for (i = 0; i < num_used_structures; i++) {
    if (&list[i] == structure) {
      break;
    }
  }
  if (i < num_used_structures) { // Structure found
    num_used_structures--; // Decrement the number of used structures
    memmove(&list[i], &list[i + 1], (num_used_structures - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T)); // Shift the list to fill the gap
  } else {
    printf("Error: Structure not found in the list\n");
  }

  // Check if the list is more than half full and resize it if necessary
  if (num_used_structures < num_allocated_structures / 2) {
    num_allocated_structures /= 2; // Half the size of the list
    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, num_allocated_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list == NULL) {
      printf("Error: Failed to reallocate memory for the list\n");
      pthread_mutex_unlock(&list_lock);
      return;
    } else {
      list = new_list;
    }
  }

  // Release the lock and return
  pthread_mutex_unlock(&list_lock);
}

// Function to retrieve a structure from the list.
// The function will return NULL if the structure is not found in the list.
NFAPI_CRC_INDICATION_PDU_T *get_structure(int index) {
  // Acquire the lock to prevent concurrent access to the list
  pthread_mutex_lock(&list_lock);

  // Check if the index is valid and return the structure if found
  if (index >= num_used_structures) {
    printf("Error: Index out of bounds\n");
    pthread_mutex_unlock(&list_lock);
    return NULL;
  } else {
    NFAPI_CRC_INDICATION_PDU_T *structure = &list[index];
    pthread_mutex_unlock(&list_lock);
    return structure;
  }
}

// Function to generate a random RX_UE_INFORMATION_TAG.
RX_UE_INFORMATION_TAG generate_random_rx_ue_information_tag() {
  // Generate a random integer between 0 and 16384 (inclusive)
  int tag = rand() % 16385;
  return (RX_UE_INFORMATION_TAG)tag;
}

// Function to generate a random RNTI.
RNTI generate_random_rnti() {
  // Generate a random integer between 0 and 4096 (inclusive)
  int rnti = rand() % 4097;
  return (RNTI)rnti;
}

// Function to generate a random CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG.
CRC_INDICATION_REL8_TAG generate_random_crc_flag() {
  // Generate a random integer between 0 and 1 (inclusive)
  int crc = rand() % 2;
  return (CRC_INDICATION_REL8_TAG){ .crc_flag = crc };
}

// Function to track the number of allocated structures and prevent memory leaks.
void track_allocated_structures(int num_structures) {
  // Acquire the lock to prevent concurrent access to the list
  pthread_mutex_lock(&list_lock);

  // Increment the number of allocated structures
  num_allocated_structures += num_structures;

  // Release the lock and return
  pthread_mutex_unlock(&list_lock);
}

// Function to optimize memory usage by reusing memory blocks whenever possible.
void optimize_memory_usage() {
  // Acquire the lock to prevent concurrent access to the list
  pthread_mutex_lock(&list_lock);

  // Reallocate memory for the list if necessary
  NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, num_used_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (new_list == NULL) {
    printf("Error: Failed to reallocate memory for the list\n");
    pthread_mutex_unlock(&list_lock);
    return;
  } else {
    list = new_list;
  }

