typedef struct {
    int key;
    double value;
} record;

int main() {
    // User input for n (size of arrays)
    int n = 10;

    // Allocate memory for offset, keys and values arrays
    long *offset_arr = malloc(sizeof(long) * n);
    int *key_arr = malloc(sizeof(int) * n);
    double *value_arr = malloc(sizeof(double) * n);

    // Initialize arrays with random values
    for (int i = 0; i < n; i++) {
        offset_arr[i] = rand() % 100 + 1;
        key_arr[i] = rand() % 100 + 1;
        value_arr[i] = (double)rand() / RAND_MAX * 100;
    }

    // Allocate memory for record array
    record *records = malloc(sizeof(record) * n);

    // Initialize records with random values
    for (int i = 0; i < n; i++) {
        records[i].key = key_arr[i];
        records[i].value = value_arr[i];
    }

    // Connect to database
    sqlite3 *db;
    char *zErrMsg = 0;
    int rc = sqlite3_open("Employees.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error opening database: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Prepare SQL query
    char *query = "SELECT name, city, address FROM Employees WHERE supervisor_id IN (";
    for (int i = 0; i < n; i++) {
        query += std::to_string(key_arr[i]) + ", ";
    }
    query.erase(query.length() - 2, 2);
    query += ")";

    // Execute SQL query and retrieve result
    sqlite3_stmt *stmt;
    rc = sqlite3_prepare_v2(db, query.c_str(), -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error preparing statement: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Loop through results and print them
    while (sqlite3_step(stmt) == SQLITE_ROW) {
        char *name = (char*)sqlite3_column_text(stmt, 0);
        char *city = (char*)sqlite3_column_text(stmt, 1);
        char *address = (char*)sqlite3_column_text(stmt, 2);
        printf("%s, %s, %s\n", name, city, address);
    }

    // Clean up
    sqlite3_finalize(stmt);
    sqlite3_close(db);

    return 0;
}
