        strcpy(new_instance->supported_rrc_versions, supported_rrc_versions);
        list_insert(capability_info_list, new_instance);
    }
    fclose(file);

    // Release the semaphore
    sem_post(LTE_RRC_Capability_Info_sem);

    return capability_info_list;
}
