// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    uint16_t rx_ue_information_tag; // RX_UE_INFORMATION_TAG of the CRC indication
    uint32_t rnti;                  // RNTI of the UE that transmitted the signal
    uint8_t crcflag;                // CRCFLAG set for the CRC indication
} NFAPI_CRC_INDICATION_PDU_T;

// Define the hash table structure for quick RX_UE_INFORMATION_TAG lookups during insertion operations
typedef struct {
    uint16_t rx_ue_information_tag; // Key for the hash table
    NFAPI_CRC_INDICATION_PDU_T *pdu; // Pointer to the corresponding CRC indication PDU
} RX_UE_INFORMATION_TAG_HASH_ENTRY;

// Function that creates and populates a list of NFAPI_CRC_INDICATION_PDU_T structures from an external configuration file
NFAPI_CRC_INDICATION_PDU_T* populate_crc_indication_list(const char *config_file) {
    // Open the configuration file and read its contents
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        printf("Error: unable to open configuration file %s\n", config_file);
        return NULL;
    }

    // Allocate memory for the list of CRC indications and initialize it to empty
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_list = NULL;
    size_t crc_indication_count = 0;

    // Read the configuration file line by line
    char line[1024];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Ignore blank lines and comments
        if (line[0] == '\n' || line[0] == '#') {
            continue;
        }

        // Parse the current line to extract the RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG values
        uint16_t rx_ue_information_tag = 0;
        uint32_t rnti = 0;
        uint8_t crcflag = 0;
        sscanf(line, "%"SCNu16",%"SCNu32",%"SCNu8, &rx_ue_information_tag, &rnti, &crcflag);

        // Check if the RX_UE_INFORMATION_TAG is already in the list of CRC indications
        NFAPI_CRC_INDICATION_PDU_T *pdu = crc_indication_list;
        while (pdu != NULL) {
            if (pdu->rx_ue_information_tag == rx_ue_information_tag) {
                // The RX_UE_INFORMATION_TAG is already in the list, so we update its CRCFLAG value and exit the loop
                pdu->crcflag = crcflag;
                break;
            }
            pdu = pdu->next;
        }

        // If the RX_UE_INFORMATION_TAG is not in the list, we add it to the end of the list
        if (pdu == NULL) {
            NFAPI_CRC_INDICATION_PDU_T *new_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_pdu == NULL) {
                printf("Error: unable to allocate memory for CRC indication PDU\n");
                return NULL;
            }
            new_pdu->rx_ue_information_tag = rx_ue_information_tag;
            new_pdu->rnti = rnti;
            new_pdu->crcflag = crcflag;
            if (crc_indication_list == NULL) {
                // The list is empty, so we set the first entry to point to the new PDU
                crc_indication_list = new_pdu;
            } else {
                // We add the new PDU at the end of the list
                NFAPI_CRC_INDICATION_PDU_T *last_pdu = crc_indication_list;
                while (last_pdu->next != NULL) {
                    last_pdu = last_pdu->next;
                }
                last_pdu->next = new_pdu;
            }
            ++crc_indication_count;
        }
    }

    // Close the configuration file
    fclose(fp);

    // Return the list of CRC indications
    return crc_indication_list;
}
