    // Check input parameter validity
    if (num_ues <= 0 || num_ues > 1000) {
        return NULL;
    }

    // Allocate memory for the list of UE information structures
    NFAPI_CRC_INDICATION_PDU_T* ue_info = malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!ue_info) {
        return NULL;
