    for (int i = 0; i < num_ues; i++) {
        ue_info[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        ue_info[i].rnti = i + 1; // Set the RNTI for each UE to its index in the list
        ue_info[i].crc_indication_rel8.crflag = rand() % 2; // Set a random CRCFLAG value for each UE
    }

    return ue_info;
}

// Function to add an element to the list of UE information structures
void nfapi_add_ue_info(NFAPI_CRC_INDICATION_PDU_T* ue_info, int num_ues) {
    // Check input parameter validity
    if (!ue_info || num_ues <= 0 || num_ues > 1000) {
        return;
    }

    // If the list is full, resize it to accommodate more elements
    if (num_ues == ue_info->max_num_ues) {
        int new_size = num_ues * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_ue_info = realloc(ue_info, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_ue_info) {
            return;
        }
        ue_info = new_ue_info;
    }

    // Add a new element to the list and initialize it properly
    int new_index = num_ues - 1;
    memset(&(ue_info[new_index]), 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    ue_info[new_index].rx_ue_information_tag = RX_UE_INFORMATION_TAG;
    ue_info[new_index].rnti = new_index + 1; // Set the RNTI for the new UE to its index in the list
    ue_info[new_index].crc_indication_rel8.crflag = rand() % 2; // Set a random CRCFLAG value for the new UE

    // Update the maximum number of elements in the list
    ue_info->max_num_ues++;
}

// Function to delete an element from the list of UE information structures
void nfapi_del_ue_info(NFAPI_CRC_INDICATION_PDU_T* ue_info, int num_ues) {
    // Check input parameter validity
    if (!ue_info || num_ues <= 0 || num_ues > 1000) {
        return;
    }

    // If the list is empty, do nothing
    if (num_ues == 0) {
        return;
    }

    // Decrement the maximum number of elements in the list
    ue_info->max_num_ues--;

    // Move all elements after the deleted element to fill the gap
    for (int i = num_ues - 1; i < ue_info->max_num_ues; i++) {
        memcpy(&(ue_info[i]), &(ue_info[i + 1]), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
}

// Function to retrieve an element from the list of UE information structures by index
NFAPI_CRC_INDICATION_PDU_T* nfapi_get_ue_info(NFAPI_CRC_INDICATION_PDU_T* ue_info, int index) {
    // Check input parameter validity
    if (!ue_info || index < 0 || index >= ue_info->max_num_ues) {
        return NULL;
    }

    return &(ue_info[index]);
}

// Function to free the memory allocated for the list of UE information structures
void nfapi_free_ue_info(NFAPI_CRC_INDICATION_PDU_T* ue_info) {
    // Check input parameter validity
    if (!ue_info) {
        return;
    }

    free(ue_info);
}
