#include <iostream>
#include <forward_list>
#include <string>
#include <cstdlib>
#include <cassert>
#include <memory>

struct NFAPI_CRC_INDICATION_PDU_T {
    std::string rx_ue_information_tag;
    int rnti;
    std::string crc_indication_rel8_tag;
};

int insert_after_first(std::forward_list<std::string> &list, const std::string &key, const std::string &value) {
    // Find the first occurrence of the key in the list
    auto it = list.begin();
    while (it != list.end() && *it != key) ++it;

    if (it == list.end()) {
        // Key not found, insert at the end of the list
        list.push_back(value);
    } else {
        // Insert after the first occurrence of the key
        auto next = it;
        ++next;
        list.insert_after(it, value);
    }

    return 0;
}

int main() {
    // Create a forward list of strings
    std::forward_list<std::string> list;

    // Add some elements to the list
    list.push_back("apple");
    list.push_back("banana");
    list.push_back("cherry");

    // Create an NFAPI_CRC_INDICATION_PDU_T structure
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.rx_ue_information_tag = "RX_UE_INFORMATION_TAG";
    pdu.rnti = 12345;
    pdu.crc_indication_rel8_tag = "CRC_INDICATION_REL8_TAG";

    // Insert the NFAPI_CRC_INDICATION_PDU_T structure after the first occurrence of "banana" in the list
    insert_after_first(list, "banana", pdu);

    // Print the contents of the list
    for (const auto &s : list) {
        std::cout << s << ' ';
    }
    std::cout << '\n';

    return 0;
}
