int create_crc_indication_list(NFAPI_CRC_INDICATION_PDU **pdu_list, size_t *size) {
    // Check if the input parameters are valid
    if (pdu_list == NULL || size == NULL) {
        return -1;
    }

    // Initialize the list with a maximum size of MAX_LIST_SIZE
    *size = 0;
    NFAPI_CRC_INDICATION_PDU *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU) * MAX_LIST_SIZE);
    if (list == NULL) {
        return -1;
    }

    // Populate the list with random RX_UE_INFORMATION_TAG and RNTI values
    for (int i = 0; i < MAX_LIST_SIZE; i++) {
        // Set a random RX_UE_INFORMATION_TAG value
        RX_UE_INFORMATION_TAG rx_ue_info_tag = { .value = rand() % 10 };

        // Set a random RNTI value
        RNTI rnti = { .value = rand() % 10000 };

        // Initialize the CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
        crc_indication_rel8_tag.crc_flag = rand() % 2 ? true : false;

        // Initialize the NFAPI_CRC_INDICATION_PDU structure with the random values
        list[i] = (NFAPI_CRC_INDICATION_PDU) { .rx_ue_info_tag = rx_ue_info_tag, .rnti = rnti, .crc_indication_rel8_tag = crc_indication_rel8_tag };
