    // Calculate the OFDM_SUBCARRIER_SPACING and RF_CARRIER_CENTER_FREQ for each carrier
    for (int i = 0; i < numCarriers; i++) {
        unsigned short OFDM_SUBCARRIER_SPACING = 275 * pow(2, i / 18);
        float RF_CARRIER_CENTER_FREQ = frequencyBand - (OFDM_SUBCARRIER_SPACING / 2.0f);
        carriers[i].OFDM_SUBCARRIER_SPACING = OFDM_SUBCARRIER_SPACING;
        carriers[i].RF_CARRIER_CENTER_FREQ = RF_CARRIER_CENTER_FREQ;
    }

    // Calculate the PHASE_NOISE_LEVEL and RSSI values for each carrier
    for (int i = 0; i < numCarriers; i++) {
        unsigned short PHASE_NOISE_LEVEL = noiseLevel * pow(2, i / 18);
        float RSSI = -10.0f * log10(PHASE_NOISE_LEVEL);
        carriers[i].PHASE_NOISE_LEVEL = PHASE_NOISE_LEVEL;
        carriers[i].RSSI = RSSI;
    }
