// C function to create and populate a list of LTE UE Context structures
LTE_UEContext* createAndPopulateUeContext(int ueId, int rnti, int srb1StatusTransfer) {
    // Check if the maximum number of contexts has been reached
    if (maxNumContextsReached()) {
        logError("Maximum number of UE Contexts reached");
        return NULL;
    }

    // Allocate memory for the new context
    LTE_UEContext* newContext = malloc(sizeof(LTE_UEContext));
    if (newContext == NULL) {
        logError("Failed to allocate memory for new UE Context");
        return NULL;
    }

    // Populate the fields of the new context
    newContext->ueId = ueId;
    newContext->rnti = rnti;
    newContext->srb1StatusTransfer = srb1StatusTransfer;

    // Add the new context to the list of contexts
    pthread_mutex_lock(&contextListMutex);
    if (contextList == NULL) {
        contextList = newContext;
    } else {
        LTE_UEContext* currentContext = contextList;
        while (currentContext->next != NULL) {
            currentContext = currentContext->next;
        }
        currentContext->next = newContext;
    }
    pthread_mutex_unlock(&contextListMutex);

    return newContext;
}

