typedef struct {
    unsigned int TransmitPowerLimit;
    unsigned int ReceiveSensitivity;
    unsigned int BufferSize;
} RRM_Settings;

// Define the UL_Duplex_Mode enumeration
enum UL_Duplex_Mode {
    DUPLEX_MODE_FDD,
    DUPLEX_MODE_TDD
};

// Function to create and populate a list of LTE_MAC_Config structures
int create_LTE_MAC_config(unsigned int num_UEs, unsigned int custom_transmit_power_limit, bool enable_logging) {
    // Allocate memory for the list of LTE_MAC_Config structures
    LTE_MAC_Config **config_list = (LTE_MAC_Config **)malloc(sizeof(LTE_MAC_Config *) * num_UEs);
    if (!config_list) {
        // Handle memory allocation error
        printf("Error: Out of memory\n");
        return -1;
    }

    // Initialize the list of LTE_MAC_Config structures
    for (unsigned int i = 0; i < num_UEs; ++i) {
        config_list[i] = (LTE_MAC_Config *)malloc(sizeof(LTE_MAC_Config));
        if (!config_list[i]) {
            // Handle memory allocation error
            printf("Error: Out of memory\n");
            return -1;
        }

        config_list[i]->UE_ID = i + 1;
        config_list[i]->DL_Transmission_Config.UL_Duplex_Mode = DUPLEX_MODE_FDD;
        config_list[i]->RRM_Settings.TransmitPowerLimit = custom_transmit_power_limit;
        config_list[i]->RRM_Settings.ReceiveSensitivity = 10;
        config_list[i]->RRM_Settings.BufferSize = 32;
    }

    // Log configuration details to a file
    if (enable_logging) {
        FILE *log_file = fopen("LTE_MAC_config.txt", "w");
        for (unsigned int i = 0; i < num_UEs; ++i) {
            fprintf(log_file, "UE ID: %u\nDL Duplex Mode: FDD\nTransmit Power Limit: %u dBm\nReceive Sensitivity: -103 dBm\nBuffer Size: 32 bytes\n", config_list[i]->UE_ID, config_list[i]->RRM_Settings.TransmitPowerLimit);
        }
        fclose(log_file);
    }

    // Return the list of LTE_MAC_Config structures
    return 0;
}

// Function to validate MAC_Config parameters before they are added to the list
bool validate_MAC_config(LTE_MAC_Config *config) {
    if (config->UE_ID < 1 || config->UE_ID > 65535) {
        // Handle invalid UE ID
        printf("Error: Invalid UE ID\n");
        return false;
    }

    if (config->DL_Transmission_Config.UL_Duplex_Mode != DUPLEX_MODE_FDD && config->DL_Transmission_Config.UL_Duplex_Mode != DUPLEX_MODE_TDD) {
        // Handle invalid UL duplex mode
        printf("Error: Invalid UL duplex mode\n");
        return false;
    }

    if (config->RRM_Settings.TransmitPowerLimit < 1 || config->RRM_Settings.TransmitPowerLimit > 63) {
        // Handle invalid transmit power limit
        printf("Error: Invalid transmit power limit\n");
        return false;
    }

    if (config->RRM_Settings.ReceiveSensitivity < -108 || config->RRM_Settings.ReceiveSensitivity > -30) {
        // Handle invalid receive sensitivity
        printf("Error: Invalid receive sensitivity\n");
        return false;
    }

    if (config->RRM_Settings.BufferSize < 1 || config->RRM_Settings.BufferSize > 65535) {
        // Handle invalid buffer size
        printf("Error: Invalid buffer size\n");
        return false;
    }

    return true;
}

// Function to dynamically adjust RRM settings based on real-time network conditions
void adjust_RRM_settings(LTE_MAC_Config *config, float network_load) {
    // Calculate the desired transmit power limit and buffer size based on network load
    config->RRM_Settings.TransmitPowerLimit = (unsigned int)(network_load * 63);
    config->RRM_Settings.BufferSize = (unsigned int)(network_load * 65535);
}

// Function to manage multiple instances of LTE_MAC_Config lists simultaneously
void manage_LTE_MAC_config(LTE_MAC_Config **config_list, unsigned int num_UEs) {
    // Allocate memory for the list of LTE_MAC_Config structures
    config_list = (LTE_MAC_Config **)malloc(sizeof(LTE_MAC_Config *) * num_UEs);
    if (!config_list) {
        // Handle memory allocation error
        printf("Error: Out of memory\n");
        return;
    }

    // Initialize the list of LTE_MAC_Config structures
    for (unsigned int i = 0; i < num_UEs; ++i) {
        config_list[i] = (LTE_MAC_Config *)malloc(sizeof(LTE_MAC_Config));
        if (!config_list[i]) {
            // Handle memory allocation error
            printf("Error: Out of memory\n");
            return;
        }

        config_list[i]->UE_ID = i + 1;
        config_list[i]->DL_Transmission_Config.UL_Duplex_Mode = DUPLEX_MODE_FDD;
        config_list[i]->RRM_Settings.TransmitPowerLimit = custom_transmit_power_limit;
        config_list[i]->RRM_Settings.ReceiveSensitivity = 10;
        config_list[i]->RRM_Settings.BufferSize = 32;
    }
}

// Function to load RRM settings from an external configuration file
void load_RRM_settings(LTE_MAC_Config **config_list, unsigned int num_UEs) {
    // Load the RRM settings from an external configuration file
    FILE *config_file = fopen("rrm_config.txt", "r");
    if (!config_file) {
        // Handle error opening the configuration file
        printf("Error: Unable to open rrm_config.txt\n");
        return;
    }

    // Parse the configuration file and load the RRM settings
    for (unsigned int i = 0; i < num_UEs; ++i) {
        if (!config_list[i]) {
            // Handle invalid UE ID
            printf("Error: Invalid UE ID\n");
            return;
        }

        // Load the RRM settings for this UE from the configuration file
        fscanf(config_file, "%u %u %u %u", &config_list[i]->UE_ID, &config_list[i]->DL_Transmission_Config.UL_Duplex_Mode, &config_list[i]->RRM_Settings.TransmitPowerLimit, &config_list[i]->RRM_Settings.ReceiveSensitivity);
    }

    fclose(config_file);
}

// Function to handle potential errors gracefully
void handle_error(int error) {
    // Handle different types of errors differently
    switch (error) {
        case -1:
            printf("Error: Out of memory\n");
            break;
        case -2:
            printf("Error: Invalid UE ID\n");
            break;
        case -3:
            printf("Error: Invalid UL duplex mode\n");
            break;
        default:
            // Handle other types of errors
            printf("Error: Unknown error\n");
            break;
    }
