    int crc_indication_rel8_tag;
    bool crcflag;
};

// Array to store the current list of UE contexts
struct ue_context *contexts[MAX_CONTEXTS];

// Semaphore to manage access to the contexts array
sem_t sem;

// Function to validate input parameters and update the UE context
int handle_http_post(int page_section_id, int element_id, char *html_content) {
    // Validate input parameters
    if (page_section_id < 0 || page_section_id > MAX_CONTEXTS) {
        printf("Invalid page section ID\n");
        return -1;
    }
    if (element_id < 0 || element_id >= MAX_CONTEXTS) {
        printf("Invalid element ID\n");
        return -2;
    }
    if (!html_content) {
        printf("Invalid HTML content\n");
        return -3;
    }

    // Acquire the semaphore to access the contexts array
    sem_wait(&sem);

    // Update the UE context
    struct ue_context *context = &contexts[page_section_id];
    context->rx_ue_information_tag = element_id;
    context->crc_indication_rel8_tag = rand(); // Randomly set CRCFLAG
    context->crcflag = true;

    // Release the semaphore
    sem_post(&sem);

    return 0;
}

// Function to manage and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
int update_nfapi_crc_indication_pdu(struct nfapi_crc_indication_pdu *pdu) {
    // Acquire the semaphore to access the contexts array
    sem_wait(&sem);

    // Iterate over the list of UE contexts and populate the NFAPI CRC indication PDU
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        struct ue_context *context = &contexts[i];
        if (context->rx_ue_information_tag != -1 && context->crcflag) {
            // Populate the NFAPI CRC indication PDU
            pdu->rnti = context->rx_ue_information_tag;
            pdu->crc_indication_rel8.crc_flag = true;
        }
    }

    // Release the semaphore
    sem_post(&sem);

    return 0;
}

// Function to handle dynamic memory allocation and deallocation for the UE contexts array
void *allocate_ue_context(int page_section_id) {
    // Acquire the semaphore to access the contexts array
    sem_wait(&sem);

    // Allocate memory for the UE context
    struct ue_context *context = malloc(sizeof(struct ue_context));
    if (!context) {
        printf("Failed to allocate memory for UE context\n");
        return NULL;
    }

    // Initialize the UE context
    context->rx_ue_information_tag = -1;
    context->crc_indication_rel8_tag = 0;
    context->crcflag = false;

    // Store the allocated memory in the contexts array
    contexts[page_section_id] = context;

    // Release the semaphore
    sem_post(&sem);

    return (void *)context;
}

// Function to handle dynamic memory deallocation for the UE contexts array
void deallocate_ue_context(int page_section_id) {
    // Acquire the semaphore to access the contexts array
    sem_wait(&sem);

    // Free the allocated memory for the UE context
    free(contexts[page_section_id]);

    // Reset the corresponding entry in the contexts array
    contexts[page_section_id] = NULL;

    // Release the semaphore
    sem_post(&sem);
}
```
