    if (cache->count == CACHE_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* entry = cache->head;
        cache->head = entry->next;
        free(entry);
    }

    // Allocate a new cache entry and populate it with the provided PDU
    NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(entry, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add the new cache entry to the end of the list
    if (cache->tail == NULL) {
        cache->head = entry;
    } else {
        cache->tail->next = entry;
    }
    cache->tail = entry;
}

void removeNFAPI_CRC_INDICATION_PDU_T(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Find the cache entry that matches the provided PDU
    NFAPI_CRC_INDICATION_PDU_T* entry = NULL;
