        if (memcmp(pdu, entry, sizeof(NFAPI_CRC_INDICATION_PDU_T)) == 0) {
            break;
        }
    }

    // Remove the found cache entry from the list
    if (entry != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* prev = NULL;
        for (prev = cache->head; prev != NULL && prev->next != entry; prev = prev->next);
        free(entry);
        prev->next = entry->next;
    }
}
