import json
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
from typing import Dict, Any

class JSONParser:
    def __init__(self):
        self._encryption_key = None
        self._decryption_key = None

    def set_encryption_key(self, key: bytes) -> None:
        """Sets the encryption key for symmetric encryption."""
        if not isinstance(key, bytes) or len(key) != 32:
            raise ValueError("Invalid encryption key. Must be a 32-byte string.")
        self._encryption_key = key

    def set_decryption_key(self, key: bytes) -> None:
        """Sets the decryption key for symmetric encryption."""
        if not isinstance(key, bytes) or len(key) != 32:
            raise ValueError("Invalid decryption key. Must be a 32-byte string.")
        self._decryption_key = key

    def encrypt(self, data: Dict[str, Any]) -> str:
        """Encrypts the given JSON data using AES in CBC mode."""
        if not isinstance(data, dict):
            raise ValueError("Invalid data. Must be a dictionary.")
        # Convert the dictionary to a JSON string
        json_string = json.dumps(data)
        # Encrypt the JSON string using AES in CBC mode
        cipher = AES.new(self._encryption_key, AES.MODE_CBC)
        encrypted_json = cipher.encrypt(json_string.encode())
        return encrypted_json.hex()

    def decrypt(self, encrypted_data: str) -> Dict[str, Any]:
