#include <stdlib.h>
#include <time.h>

// Define the maximum size of the list
#define MAX_LIST_SIZE 1024

// Define the maximum value for RNTI
#define MAX_RNTI 0xFFFF

// Define the structure to hold the NFAPI_CRC_INDICATION_PDU_T data
typedef struct nfapi_crc_indication_pdu {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} nfapi_crc_indication_pdu_t;

// Define the Union-Find data structure to check for disjointness among RNTI values
typedef struct uf_node {
    int rank;
    int parent;
} uf_node_t;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int create_crc_indication_list(nfapi_crc_indication_pdu_t** crc_indication_list, int num_elements) {
    // Validate the input parameters
    if (num_elements > MAX_LIST_SIZE || num_elements <= 0) {
        printf("Invalid number of elements: %d\n", num_elements);
        return -1;
    }

    // Allocate memory for the list and initialize it to NULL
    *crc_indication_list = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t) * num_elements);
    if (*crc_indication_list == NULL) {
        printf("Failed to allocate memory for the list\n");
        return -1;
    }

    // Initialize the Union-Find data structure
    uf_node_t* root = (uf_node_t*)malloc(sizeof(uf_node_t) * num_elements);
    if (root == NULL) {
        printf("Failed to allocate memory for the Union-Find data structure\n");
        return -1;
    }
    for (int i = 0; i < num_elements; i++) {
        root[i].rank = 0;
        root[i].parent = i;
    }

    // Iterate over each element in the list and validate the RNTI value
    clock_t start = clock();
    for (int i = 0; i < num_elements; i++) {
        nfapi_crc_indication_pdu_t* crc_indication = &((*crc_indication_list)[i]);
        int rnti = crc_indication->rnti;
        if (rnti < 0x0001 || rnti > MAX_RNTI) {
            printf("Invalid RNTI value: %d\n", rnti);
            return -1;
        }
        int find_root = i;
        while (find_root != root[find_root].parent) {
            find_root = root[find_root].parent;
        }
        if (find_root != root[i].parent) {
            uf_node_t temp = root[i];
            root[i] = root[find_root];
            root[find_root] = temp;
        }
    }
    clock_t end = clock();
    printf("Validation time: %ld ms\n", (end - start) * 1000 / CLOCKS_PER_SEC);

    // Check for disjointness among the RNTI values and handle error cases
    int num_disjoint_rnti = 0;
    for (int i = 0; i < num_elements; i++) {
        if (root[i].parent == i) {
            num_disjoint_rnti++;
        } else {
            printf("RNTI values are not disjoint: %d and %d\n", root[i].parent, i);
            return -1;
        }
    }
    if (num_disjoint_rnti != num_elements) {
        printf("Not all RNTI values are disjoint: %d/%d\n", num_disjoint_rnti, num_elements);
        return -1;
    }

    // Populate the list with random CRCFLAG values
    srand(time(NULL));
    start = clock();
    for (int i = 0; i < num_elements; i++) {
        crc_indication_list[i]->crcflag = rand() & 1;
    }
    end = clock();
    printf("Population time: %ld ms\n", (end - start) * 1000 / CLOCKS_PER_SEC);

    return num_elements;
}

