    time_t current_time = time(NULL);
    if (cache != NULL && cache_size < MAX_NFAPI_CRC_INDICATION_SIZE && current_time - cache_last_updated < RETRY_INTERVAL) {
        return cache; // Return the cached PDUs
    }

