void caching_function(int num_records) {
    int *keys = malloc(num_records * sizeof(int));
    long *offsets = malloc(num_records * sizeof(long));
    if (!keys || !offsets) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize each key and offset with a random value
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 100;
        offsets[i] = rand() % 100000000;
    }

    // Use a cache to store the most frequently accessed records
    int *cache = malloc(num_records * sizeof(int));
    if (!cache) {
        printf("Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < num_records; i++) {
        cache[i] = keys[i];
    }
}
