struct record {
    int value;
};

void *initialize_data(char *command, char **parameters) {
    // Check if the command is valid and has the correct number of parameters
    if (strcmp(command, "init") != 0 || strlen(parameters[0]) != 2) {
        return NULL;
    }

    // Allocate memory for the arrays of long offsets and int keys
    size_t num_records = atoi(parameters[1]);
    long *offsets = calloc(num_records, sizeof(long));
    int *keys = calloc(num_records, sizeof(int));

    // Initialize the arrays of offsets and keys to random values within the specified range
    for (size_t i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1024;
        keys[i] = rand() % 1023;
    }

    // Allocate memory for the array of records and initialize each record with a random value within the specified range
    struct record *records = calloc(num_records, sizeof(struct record));
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = rand() % 1023;
    }

    // Allocate memory for the cipher object and initialize it with the random values from the arrays of offsets and keys
    AES_KEY *cipher = calloc(1, sizeof(AES_KEY));
    AES_set_encrypt_key(keys, 256, cipher);
    for (size_t i = 0; i < num_records; i++) {
        records[i].value = AES_encrypt(offsets[i], cipher);
    }

    // Free the memory allocated for the arrays of offsets and keys, as it is no longer needed
    free(offsets);
    free(keys);

    return cipher;
}
