// Define the structure for UE status information
typedef struct {
    int UE_ID;
    int Cell_ID;
    float Measurement_Report;
} UE_Status_T;

// Function to create and populate a list of UE status structures
void populate_UE_statuses(int num_users, int max_cells, bool use_cache) {
    // Allocate memory for the list of UE statuses
    UE_Status_T *ue_statuses = (UE_Status_T *)malloc(sizeof(UE_Status_T) * num_users);
    if (!ue_statuses) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    // Initialize the list of UE statuses with random signal strength values
    srand(time(NULL));
    for (int i = 0; i < num_users; ++i) {
        ue_statuses[i].UE_ID = i + 1;
        ue_statuses[i].Cell_ID = rand() % max_cells + 1;
        ue_statuses[i].Measurement_Report = (float)(rand() % 100) / 10;
    }

    // If caching is enabled, save the UE statuses to a local file
    if (use_cache) {
        FILE *file = fopen("ue_statuses.bin", "wb");
        if (!file) {
            fprintf(stderr, "Failed to open file for writing\n");
            free(ue_statuses);
            return;
        }
        fwrite(ue_statuses, sizeof(UE_Status_T), num_users, file);
        fclose(file);
    }

    // Free the memory allocated for the list of UE statuses
    free(ue_statuses);
}

// Function to retrieve a single UE status structure from the database
void get_UE_status(int UE_ID, int *cell_ID, float *measurement_report) {
    // Open the external database connection
    sqlite3 *db = NULL;
    sqlite3_open("database.db", &db);
    if (!db) {
        fprintf(stderr, "Failed to open database\n");
        return;
    }

    // Prepare a SQL query for retrieving the UE status
    char *query = "SELECT cell_id, measurement_report FROM ue_status WHERE UE_ID = ?";
    sqlite3_stmt *stmt = NULL;
    sqlite3_prepare(db, query, -1, &stmt, NULL);

    // Bind the UE ID to the SQL query
    sqlite3_bind_int(stmt, 1, UE_ID);

    // Execute the SQL query and retrieve the result
    int ret = sqlite3_step(stmt);
    if (ret != SQLITE_ROW) {
        fprintf(stderr, "Failed to retrieve UE status\n");
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return;
    }

    // Retrieve the cell ID and measurement report from the result
    *cell_ID = sqlite3_column_int(stmt, 0);
    *measurement_report = (float)sqlite3_column_double(stmt, 1);

    // Finalize the SQL query and close the database connection
    sqlite3_finalize(stmt);
    sqlite3_close(db);
}

// Function to retrieve all UE status structures from the database
void get_all_UE_statuses(int **ue_statuses, int *num_users) {
    // Open the external database connection
    sqlite3 *db = NULL;
    sqlite3_open("database.db", &db);
    if (!db) {
        fprintf(stderr, "Failed to open database\n");
        return;
    }

    // Prepare a SQL query for retrieving all UE statuses
    char *query = "SELECT UE_ID, cell_id, measurement_report FROM ue_status";
    sqlite3_stmt *stmt = NULL;
    sqlite3_prepare(db, query, -1, &stmt, NULL);

    // Execute the SQL query and retrieve the result
    int ret = sqlite3_step(stmt);
    if (ret != SQLITE_ROW) {
        fprintf(stderr, "Failed to retrieve all UE statuses\n");
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return;
    }

    // Allocate memory for the list of UE statuses
    *ue_statuses = (int *)malloc(sizeof(int) * (*num_users));
    if (!*ue_statuses) {
        fprintf(stderr, "Memory allocation failed\n");
        sqlite3_finalize(stmt);
        sqlite3_close(db);
        return;
    }

    // Populate the list of UE statuses with the results from the SQL query
    int i = 0;
    while (sqlite3_step(stmt) == SQLITE_ROW) {
        (*ue_statuses)[i].UE_ID = sqlite3_column_int(stmt, 0);
        (*ue_statuses)[i].Cell_ID = sqlite3_column_int(stmt, 1);
        (*ue_statuses)[i].Measurement_Report = (float)sqlite3_column_double(stmt, 2);
        i++;
    }
    *num_users = i;

    // Finalize the SQL query and close the database connection
    sqlite3_finalize(stmt);
    sqlite3_close(db);
}
