// Define data structure manager for list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    size_t capacity; // current number of elements in the list
    size_t count; // number of elements currently used in the list
    NFAPI_CRC_INDICATION_PDU_T *elements; // array of elements in the list
} NFAPI_CRC_INDICATION_LIST_T;

// Initialize data structure manager with a given size (in elements)
void init_list(NFAPI_CRC_INDICATION_LIST_T *list, size_t size) {
    // Validate input parameters
    if (size <= 0 || size > 1000) {
        printf("Error: Invalid list size provided\n");
        return;
    }

    list->capacity = size;
    list->count = 0;
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
}

// Add a new element to the end of the list
void add_element(NFAPI_CRC_INDICATION_LIST_T *list, uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI, uint8_t CRCFLAG) {
    // Validate input parameters
    if (RX_UE_INFORMATION_TAG > 0xFFFF || RNTI > 0xFFFFFF || CRCFLAG > 1) {
        printf("Error: Invalid input parameter provided\n");
        return;
    }

    // Check if list is full, if so resize it
    if (list->count == list->capacity) {
        resize_list(list);
    }

    // Add new element to the end of the list
    NFAPI_CRC_INDICATION_PDU_T *element = &list->elements[list->count];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRCFLAG = CRCFLAG;
    list->count++;
}

// Remove the last element from the list
void remove_element(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Check if list is empty, if so return
    if (list->count == 0) {
        printf("Error: Attempted to remove an element from an empty list\n");
        return;
    }

    // Decrease the count and deallocate memory of last element
    list->count--;
    free(list->elements[list->count].RX_UE_INFORMATION_TAG);
}

// Iterate over all elements in the list
void iterate_over_list(NFAPI_CRC_INDICATION_LIST_T *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    // Check if list is empty, if so return
    if (list->count == 0) {
        printf("Error: Attempted to iterate over an empty list\n");
        return;
    }

    // Iterate over all elements in the list and call callback function for each element
    for (size_t i = 0; i < list->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = &list->elements[i];
        callback(element);
    }
}

// Resize the list to accommodate more elements
void resize_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Check if list is full, if so return
    if (list->count == list->capacity) {
        printf("Error: Attempted to resize a full list\n");
        return;
    }

    // Increase the capacity by 50% and reallocate memory for the new elements
    size_t new_size = (list->capacity * 3) / 2;
    NFAPI_CRC_INDICATION_PDU_T *new_elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_size);

    // Copy existing elements to the new array and deallocate memory of old elements
    for (size_t i = 0; i < list->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = &list->elements[i];
        new_elements[i] = *element;
        free(element);
    }

    // Update the list with the new elements and capacity
    list->capacity = new_size;
    list->elements = new_elements;
}

// Periodically check integrity of each element in the list
void periodic_validation(NFAPI_CRC_INDICATION_LIST_T *list) {
    // Check if list is empty, if so return
    if (list->count == 0) {
