/*
 * Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures.
 *
 * Input:
 *  - N: number of NFAPI_CRC_INDICATION_PDU_T structures to create (must be within the range of 1 to 1000)
 *  - UE_IDs: array of UE IDs for each RX_UE_INFORMATION_TAG (must have same length as N)
 *  - PDCP_SNs: array of PDCP sequence numbers for each RRC_PDU (must have same length as N)
 *
 * Output:
 *  - list: a list of NFAPI_CRC_INDICATION_PDU_T structures, each containing a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
 */

int populate_nfaapi_crc_pdu_list(int N, int *UE_IDs, int *PDCP_SNs) {
    // Validate input parameters
    if (N < 1 || N > 1000) {
        return -1;
    }
    if (UE_IDs == NULL || PDCP_SNs == NULL) {
        return -2;
    }
    if (sizeof(int) != sizeof(void*)) {
        return -3;
    }

    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures
    int i;
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        return -4;
    }

    // Populate each structure with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = UE_IDs[i];
        list[i].RNTI = rand() % 1000; // randomly set RNTI
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // randomly set CRCFLAG
    }

    // Create a list of LTE_PHY_PDU structures, each containing a valid UE_ID and a list of RRC_PDU structures
    int j;
    LTE_PHY_PDU *phy_pdu_list = malloc(N * sizeof(LTE_PHY_PDU));
    if (phy_pdu_list == NULL) {
        return -5;
    }
    for (i = 0; i < N; i++) {
        phy_pdu_list[i].UE_ID = UE_IDs[i];
        phy_pdu_list[i].pdcp_list = malloc(PDCP_SNs[i] * sizeof(struct { int PDCP_SN; int ACK_NACK; }));
        if (phy_pdu_list[i].pdcp_list == NULL) {
            return -6;
        }
        for (j = 0; j < PDCP_SNs[i]; j++) {
            phy_pdu_list[i].pdcp_list[j].PDCP_SN = rand() % 1000; // randomly set PDCP sequence number
            phy_pdu_list[i].pdcp_list[j].ACK_NACK = rand() % 2; // randomly set ACK/NACK flag
        }
    }

    return list;
}
