#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <pthread.h>

// Define the structure for holding the CRC indication data
typedef struct {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function that creates and populates a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(uint16_t num_pdu) {
    // Check if the requested number of PDUs exceeds the limit
    if (num_pdu > 1000) {
        return NULL;
    }

    // Allocate memory for the list of PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdu);
    if (pdu_list == NULL) {
        fprintf(stderr, "Error: Unable to allocate memory for PDU list. %s\n", strerror(errno));
        return NULL;
    }

    // Initialize each structure in the list
    for (int i = 0; i < num_pdu; i++) {
        pdu_list[i].rx_ue_information_tag = rand() % UINT16_MAX;
        pdu_list[i].rnti = rand() % UINT16_MAX;
        pdu_list[i].crc_indication_rel8_tag = rand() % UINT8_MAX;
    }

    return pdu_list;
}

// Define the function that handles data from external sources and populates the PDU list
void process_data(void* data, size_t len) {
    // Check if the data is valid
    if (data == NULL || len == 0) {
        return;
    }

    // Create a temporary buffer to store the incoming data
    uint8_t* temp_buf = malloc(len);
    memcpy(temp_buf, data, len);

    // Extract the number of PDUs from the incoming data
    int num_pdu = 0;
    for (int i = 0; i < len; i++) {
        if (temp_buf[i] == '\n') {
            num_pdu++;
        }
    }

    // Check if the number of PDUs exceeds the limit
    if (num_pdu > 1000) {
        return;
    }

    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures and populate it with data from the incoming buffer
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_crc_indication_list(num_pdu);
    if (pdu_list == NULL) {
        fprintf(stderr, "Error: Unable to allocate memory for PDU list. %s\n", strerror(errno));
        return;
    }

    // Copy the data from the incoming buffer into the PDU list
    int pdu_index = 0;
    for (int i = 0; i < len; i++) {
        if (temp_buf[i] == '\n') {
            // Parse the current line and populate the corresponding PDU structure in the list
            NFAPI_CRC_INDICATION_PDU_T* pdu = &pdu_list[pdu_index];

            char* token = strtok(temp_buf + i, "\n");
            while (token != NULL) {
                if (strncmp(token, "rx_ue_information_tag", 19) == 0) {
                    pdu->rx_ue_information_tag = atoi(token + 20);
                } else if (strncmp(token, "rnti", 4) == 0) {
                    pdu->rnti = atoi(token + 5);
                } else if (strncmp(token, "crc_indication_rel8_tag", 21) == 0) {
                    pdu->crc_indication_rel8_tag = atoi(token + 22);
                }

                token = strtok(NULL, "\n");
            }

            // Increment the PDU index and check if we have reached the end of the list
            pdu_index++;
            if (pdu_index == num_pdu) {
                break;
            }
        }
    }

    free(temp_buf);
}

// Define the function that handles synchronization and thread safety issues when processing data from multiple sources
void process_data_threadsafe(void* data, size_t len) {
    // Check if the data is valid
    if (data == NULL || len == 0) {
        return;
    }

    // Lock the mutex to ensure that only one thread can access the shared data at a time
    pthread_mutex_lock(&mutex);

    // Process the incoming data and populate the PDU list
    process_data(data, len);

    // Unlock the mutex to allow other threads to access the shared data
    pthread_mutex_unlock(&mutex);
}

// Define the function that ensures proper error handling when processing data from external sources
