void insertIntoForwardList(std::forward_list<std::string>& list, const std::string& str1, const std::string& str2, int index) {
    // Check if the first string is already in the list
    auto it = std::find(list.begin(), list.end(), str1);
    if (it != list.end()) {
        // If the first string is found, insert the second string after it
        list.insert_after(it, str2);
    } else {
        // If the first string is not found, check if the index is valid
        if (index >= 0 && index <= list.size()) {
            // If the index is valid, insert the second string at that position
            list.insert_after(list.begin() + index, str2);
        } else {
            // If the index is invalid, insert the second string at the end of the list
            list.push_back(str2);
        }
    }

    // Check if there are more than 5 elements in the list and insert consecutively
    int count = 0;
    for (auto it = list.begin(); it != list.end(); ++it) {
        if (*it == str2) {
            count++;
            if (count > 5) {
                // If there are more than 5 elements, insert the second string at the end of the list
                list.push_back(str2);
                break;
            }
        } else {
            count = 0;
        }
    }
}
