#define LTE_UE_CONTEXT_STRUCTURE_SIZE 200
#define UE_ID_LENGTH 15
#define IMSI_LENGTH 16
#define UPLINK_TRANSPORT_BLOCKS_COUNT 8
#define CRC_FLAG_LENGTH 20

typedef struct LTE_UE_Context {
    char imsi[IMSI_LENGTH];
    int ue_id;
    bool crc_flag[UPLINK_TRANSPORT_BLOCKS_COUNT];
} LTE_UE_Context;

void update_ue_context(LTE_UE_Context *ue_context, char *imsis, int imsi_length) {
    // Check if the IMSI is valid
    if (imsi_length != IMSI_LENGTH) {
        printf("Invalid IMSI length: %d\n", imsi_length);
        return;
    }

    strcpy(ue_context->imsi, imsis);
}

void update_crc_flag(LTE_UE_Context *ue_context, int transport_block_index) {
    // Check if the transport block index is valid
    if (transport_block_index >= UPLINK_TRANSPORT_BLOCKS_COUNT) {
        printf("Invalid transport block index: %d\n", transport_block_index);
        return;
    }

    ue_context->crc_flag[transport_block_index] = true;
}

void add_ue_to_context(LTE_UE_Context *ue_context) {
    // Check if the UE context is valid
    if (ue_context == NULL) {
        printf("Invalid UE context\n");
        return;
    }

    // Allocate memory for the UE context structure
    LTE_UE_Context *new_ue_context = malloc(LTE_UE_CONTEXT_STRUCTURE_SIZE);
    if (new_ue_context == NULL) {
        printf("Failed to allocate memory for new UE context\n");
        return;
    }

    // Initialize the CRC flag array
    for (int i = 0; i < UPLINK_TRANSPORT_BLOCKS_COUNT; i++) {
        ue_context->crc_flag[i] = false;
    }

    // Add the new UE context to the list of UE contexts
    new_ue_context->next = ue_context->next;
    ue_context->next = new_ue_context;
}

void delete_ue_from_context(LTE_UE_Context *ue_context) {
    // Check if the UE context is valid
    if (ue_context == NULL) {
        printf("Invalid UE context\n");
        return;
    }

    // Find the previous node in the list of UE contexts
    LTE_UE_Context *prev = ue_context->next;
    while (prev != NULL && prev->next != ue_context) {
        prev = prev->next;
    }

    if (prev == NULL) {
        printf("Failed to find previous node in UE context list\n");
        return;
    }

    // Remove the UE context from the list
    prev->next = ue_context->next;

    // Deallocate memory for the UE context structure
    free(ue_context);
}

void update_context(LTE_UE_Context *ue_context, char *imsis, int imsi_length) {
    // Check if the IMSI is valid
    if (imsi_length != IMSI_LENGTH) {
        printf("Invalid IMSI length: %d\n", imsi_length);
        return;
    }

    strcpy(ue_context->imsi, imsis);
}

void update_crc_flags(LTE_UE_Context *ue_context) {
    // Check if the UE context is valid
    if (ue_context == NULL) {
        printf("Invalid UE context\n");
        return;
    }

    for (int i = 0; i < UPLINK_TRANSPORT_BLOCKS_COUNT; i++) {
        ue_context->crc_flag[i] = false;
    }
}

void manage_ue_status(LTE_UE_Context *ue_context, char *imsis, int imsi_length) {
    // Check if the IMSI is valid
    if (imsi_length != IMSI_LENGTH) {
        printf("Invalid IMSI length: %d\n", imsi_length);
        return;
    }

    // Check if the UE context exists
    LTE_UE_Context *temp = ue_context->next;
    while (temp != NULL && strcmp(temp->imsi, imsis) != 0) {
        temp = temp->next;
    }

    if (temp == NULL) {
        // Add the new UE context to the list of UE contexts
        add_ue_to_context(ue_context);
    } else {
        // Update the existing UE context with the new IMSI and CRC flags
        update_ue_context(temp, imsis, imsi_length);
        update_crc_flags(temp);
    }
}

void manage_uplink_data(LTE_UE_Context *ue_context, char *imsis, int imsi_length) {
    // Check if the IMSI is valid
    if (imsi_length != IMSI_LENGTH) {
        printf("Invalid IMSI length: %d\n", imsi_length);
        return;
    }

    // Find the corresponding UE context in the list of UE contexts
    LTE_UE_Context *temp = ue_context->next;
    while (temp != NULL && strcmp(temp->imsi, imsis) != 0) {
        temp = temp->next;
    }

    if (temp == NULL) {
        // Ignore the uplink data if the UE context is not found
        return;
    }

    // Update the CRC flag for the corresponding transport block
    int transport_block_index = get_transport_block_index(ue_context, imsis);
    update_crc_flag(temp, transport_block_index);
}

void manage_concurrency(LTE_UE_Context *ue_context) {
    // Check if the UE context is valid
    if (ue_context == NULL) {
        printf("Invalid UE context\n");
        return;
    }

    LTE_UE_Context *temp = ue_context->next;
    while (temp != NULL && temp->next != NULL) {
        // Check for race conditions in the list of UE contexts
        if (strcmp(temp->imsi, temp->next->imsi) == 0) {
            printf("Race condition detected: Duplicate IMSI found\n");
            return;
        }

        temp = temp->next;
    }
}

int get_transport_block_index(LTE_UE_Context *ue_context, char *imsis) {
    // Check if the UE context is valid
    if (ue_context == NULL) {
        printf("Invalid UE context\n");
        return -1;
    }

    // Find the corresponding transport block index in the list of UE contexts
    LTE_UE_Context *temp = ue_context->next;
    while (temp != NULL && strcmp(temp->imsi, imsis) != 0) {
        temp = temp->next;
    }

    if (temp == NULL) {
        // Ignore the uplink data if the UE context is not found
        return -1;
    }

    for (int i = 0; i < UPLINK_TRANSPORT_BLOCKS_COUNT; i++) {
        if (temp->crc_flag[i]) {
            // Return the corresponding transport block index
            return i;
        }
    }

    return -1;
}

int main() {
    LTE_UE_Context *ue_context = malloc(LTE_UE_CONTEXT_STRUCTURE_SIZE);
    if (ue_context == NULL) {
        printf("Failed to allocate memory for UE context\n");
        return 1;
    }

    char imsis[] = "123456789012345";
    int imsi_length = sizeof(imsis);

    // Add the new UE context to the list of UE contexts
    add_ue_to_context(ue_context);

    // Update the existing UE context with the new IMSI and CRC flags
    update_ue_context(ue_context, imsis, imsi_length);

    // Ignore the uplink data if the UE context is not found
    manage_uplink_data(ue_context, imsis, imsi_length);

    // Manage concurrency issues to prevent race conditions
    manage_concurrency(ue_context);

    // Free the memory allocated for the UE context structure
    free(ue_context);

    return 0;
}']

