    int ivLength = 0;
    switch (mode) {
        case ECB:
            blockSize = AES_BLOCK_SIZE;
            ivLength = 0;
            break;
        case CBC:
            blockSize = AES_BLOCK_SIZE;
            ivLength = AES_BLOCK_SIZE;
            break;
        case CTR:
            blockSize = AES_BLOCK_SIZE;
            ivLength = AES_BLOCK_SIZE;
            break;
        case GCM:
            blockSize = AES_BLOCK_SIZE;
            ivLength = AES_GCM_IV_LENGTH;
            break;
    }

    // allocate memory for the encrypted data and initialization vector
    char *encryptedData = (char *)malloc(dataLen + blockSize);
    char *iv = (char *)malloc(ivLength);

    // generate a random IV if not provided
    if (ivLen == 0) {
        for (int i = 0; i < ivLength; i++) {
            iv[i] = rand() % 256;
        }
    } else {
        memcpy(iv, iv, ivLen);
    }

    // derive the key using PBKDF2
    char *derivedKey = (char *)malloc(keyLen);
    pbkdf2(password, salt, iterationCount, derivedKey, keyLen);

    // encrypt the data using the appropriate cipher mode and derived key
    switch (mode) {
        case ECB:
            aes_ecb_encrypt(data, encryptedData, key, dataLen, blockSize);
            break;
        case CBC:
            aes_cbc_encrypt(data, encryptedData, key, dataLen, blockSize, iv);
            break;
        case CTR:
            aes_ctr_encrypt(data, encryptedData, key, dataLen, blockSize, iv);
            break;
        case GCM:
            aes_gcm_encrypt(data, encryptedData, key, dataLen, blockSize, iv, ivLength, salt, iterationCount);
            break;
    }

    // free memory allocated for the derived key and initialization vector
    free(derivedKey);
    free(iv);

    // return the encrypted data
    return encryptedData;
}

// implementation of PBKDF2 using OpenSSL library
void pbkdf2(const char *password, const char *salt, int iterationCount, char *derivedKey, int keyLen) {
    // validate input parameters
    if (password == NULL || salt == NULL || derivedKey == NULL || keyLen <= 0) {
        return;
    }

    // determine the appropriate password and salt buffer lengths based on the input parameters
    int passwordLength = strlen(password);
    int saltLength = strlen(salt);

    // allocate memory for the derived key
    char *derivedKeyBuffer = (char *)malloc(keyLen);

    // derive the key using PBKDF2
    PKCS5_PBKDF2_HMAC(password, passwordLength, salt, saltLength, iterationCount, EVP_sha1(), keyLen, derivedKeyBuffer);

    // copy the derived key to the output buffer
    memcpy(derivedKey, derivedKeyBuffer, keyLen);

    // free memory allocated for the derived key buffer
    free(derivedKeyBuffer);
}']

