NFAPI_CRC_INDICATION_PDU_T *create_list(size_t num_pdu, const char *csv_file_path) {
    // Check input parameters
    if (num_pdu > 1000 || !csv_file_path) {
        printf("Invalid input parameters\n");
        return NULL;
    }

    // Open the CSV file
    FILE *csv_file = fopen(csv_file_path, "r");
    if (!csv_file) {
        printf("Failed to open CSV file: %s\n", csv_file_path);
        return NULL;
    }

    // Initialize a list of PDU structures
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = malloc(num_pdu * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        printf("Failed to allocate memory for PDU list\n");
        return NULL;
    }

    // Read the RNTIs from the CSV file and populate the PDU structures
    char rnti[10];
    bool crc_flag;
    size_t i = 0;
    while (fgets(rnti, sizeof(rnti), csv_file) && i < num_pdu) {
        // Check for valid RNTI
        if (strlen(rnti) != 9 || rnti[0] != '0' || rnti[1] != 'x') {
            printf("Invalid RNTI format: %s\n", rnti);
            free(pdu_list);
            return NULL;
        }

        // Extract the CRC flag from the CSV file
        crc_flag = atoi(rnti + 2) & 0x1;

        // Populate the PDU structure with the RNTI and CRC flag
        populate_pdu(&pdu_list[i], rnti, crc_flag);
        i++;
    }

    // Close the CSV file
    fclose(csv_file);

    return pdu_list;
}

int main() {
    // Test case 1: Create a list of PDUs with 3 elements and populate them using a CSV file
    NFAPI_CRC_INDICATION_PDU_T *pdu_list = create_list(3, "test.csv");
    if (!pdu_list) {
        printf("Failed to create PDU list\n");
        return 1;
    }

    // Check that the RNTIs are unique and the CRC flags are correctly set
    assert(pdu_list[0].rnti == 0x12345678);
    assert(pdu_list[0].crc_flag == false);
    assert(pdu_list[1].rnti == 0x90abcdef);
    assert(pdu_list[1].crc_flag == true);
    assert(pdu_list[2].rnti == 0xfedcba98);
    assert(pdu_list[2].crc_flag == false);

    // Test case 2: Create a list of PDUs with 1000 elements and populate them using a CSV file
    pdu_list = create_list(1000, "test.csv");
    if (!pdu_list) {
        printf("Failed to create PDU list\n");
        return 1;
    }

    // Check that the RNTIs are unique and the CRC flags are correctly set for all elements
    for (size_t i = 0; i < 1000; i++) {
        assert(pdu_list[i].rnti == 0x12345678);
        assert(pdu_list[i].crc_flag == false);
    }

    // Test case 3: Create a list of PDUs with 0 elements and populate them using a CSV file
    pdu_list = create_list(0, "test.csv");
    if (!pdu_list) {
        printf("Failed to create PDU list\n");
        return 1;
    }

    // Check that the list is empty
    assert(pdu_list == NULL);

    return 0;
}
