['```java
import java.util.*;

public class UnionFind {
    private Map<Integer, Integer> parents;
    private Map<Integer, List<String>> attributes;

    public UnionFind(List<CustomObject> objects) {
        this.parents = new HashMap<>();
        this.attributes = new HashMap<>();

        for (int i = 0; i < objects.size(); i++) {
            CustomObject object = objects.get(i);
            parents.put(object.id, i);
            attributes.put(object.id, object.attributes);
        }
    }

    public int find(int id) {
        if (parents.containsKey(id)) {
            return find(parents.get(id));
        }
        return id;
    }

    public boolean connected(int id1, int id2) {
        return find(id1) == find(id2);
    }

    public void union(int id1, int id2) {
        int root1 = find(id1);
        int root2 = find(id2);
        if (root1 != root2) {
            parents.put(root1, root2);
        }
    }
}

public class CustomObject {
    private int id;
    private List<String> attributes;

    public CustomObject(int id, List<String> attributes) {
        this.id = id;
        this.attributes = attributes;
    }

    public String getId() {
        return id;
    }

    public List<String> getAttributes() {
        return attributes;
    }
}
