    while (true) {
        // Check if the list has reached its maximum capacity
        size_t currentSize = (*list)->crcIndication.rxUeInformationTag - 1;
        if (currentSize >= maxCapacity) {
            break;
        }

        // Dynamically allocate memory for a new list element and copy the existing elements
        CrcIndicationListElement* newElement = realloc(*list, sizeof(CrcIndicationListElement) * (currentSize + 1));
