// Define the structure for CellularUeInfo_PDU_T
typedef struct {
    int UE_ID;
    int RNTI;
    bool CrcIndication;
} CellularUeInfo_PDU_T;

// Define a list of CellularUeInfo_PDU_T structures
struct List {
    CellularUeInfo_PDU_T* data;
    int capacity;
};

// Implement the function to initialize and populate a list of CellularUeInfo_PDU_T structures
void initializeList(struct List* list, int initialCapacity) {
    // Allocate memory for the list
    list->data = (CellularUeInfo_PDU_T*)malloc(initialCapacity * sizeof(CellularUeInfo_PDU_T));
    if (list->data == NULL) {
        printf("Failed to allocate memory for list\n");
        return;
    }

    // Initialize the capacity and size of the list
    list->capacity = initialCapacity;
    list->size = 0;
}

// Implement the function to add a new entry to the list
void addEntry(struct List* list, int UE_ID, int RNTI, bool CrcIndication) {
    // Check if the list is full and needs to be resized
    if (list->size == list->capacity) {
        // Resize the list by a factor of 2
        list->capacity *= 2;
        CellularUeInfo_PDU_T* newData = (CellularUeInfo_PDU_T*)realloc(list->data, list->capacity * sizeof(CellularUeInfo_PDU_T));
        if (newData == NULL) {
            printf("Failed to resize list\n");
            return;
        }
        list->data = newData;
    }

    // Add the new entry to the list
    CellularUeInfo_PDU_T entry = { UE_ID, RNTI, CrcIndication };
    list->data[list->size++] = entry;
}

// Implement the function to check if an UE_ID or RNTI already exists in the list
bool containsEntry(struct List* list, int UE_ID, int RNTI) {
    // Check each entry in the list for a match with the given UE_ID and RNTI
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].UE_ID == UE_ID && list->data[i].RNTI == RNTI) {
            return true;
        }
    }

    // If no match is found, return false
    return false;
}

// Implement the function to remove an entry from the list
void removeEntry(struct List* list, int UE_ID, int RNTI) {
    // Check each entry in the list for a match with the given UE_ID and RNTI
    for (int i = 0; i < list->size; i++) {
        if (list->data[i].UE_ID == UE_ID && list->data[i].RNTI == RNTI) {
            // Shift all subsequent entries in the list back one position
            for (int j = i; j < list->size - 1; j++) {
                list->data[j] = list->data[j + 1];
            }

            // Decrement the size of the list by one
            list->size--;
        }
    }
}

// Implement the function to free all memory allocated for the list
void freeList(struct List* list) {
    free(list->data);
}

// Implement the function to handle external data sources for UE_IDs and RNTIs
void loadExternalData(struct List* list, char* UE_ID_file, char* RNTI_file) {
    // Open the files containing the UE_IDs and RNTIs
    FILE* UE_ID_fp = fopen(UE_ID_file, "r");
    FILE* RNTI_fp = fopen(RNTI_file, "r");

    if (UE_ID_fp == NULL || RNTI_fp == NULL) {
        printf("Failed to open files for loading external data\n");
        return;
    }

    // Read the UE_IDs and RNTIs from the files
    char* line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, UE_ID_fp)) != -1) {
        // Parse the UE_ID and RNTI from the line
        int UE_ID = atoi(strtok(line, ","));
        int RNTI = atoi(strtok(NULL, ","));

        // Add the entry to the list
        addEntry(list, UE_ID, RNTI, false);
    }

    free(line);
    fclose(UE_ID_fp);
    fclose(RNTI_fp);
}

// Implement the function to handle errors related to external data sources
void handleExternalDataError(struct List* list, char* errorMessage) {
    printf("An error occurred while loading external data: %s\n", errorMessage);
    freeList(list);
}

// Implement the function to implement logging for errors or warnings related to memory allocation failures, invalid input parameters, and issues with external data sources
void logError(char* errorMessage) {
    printf("An error occurred: %s\n", errorMessage);
}

// Implement unit tests to verify the correctness of your implementation
void testAddEntry() {
    struct List list;
    initializeList(&list, 10);
    addEntry(&list, 1, 2, true);
    assert(containsEntry(&list, 1, 2));
    freeList(&list);
}

void testRemoveEntry() {
    struct List list;
    initializeList(&list, 10);
    addEntry(&list, 1, 2, true);
    removeEntry(&list, 1, 2);
    assert(!containsEntry(&list, 1, 2));
    freeList(&list);
}

void testLoadExternalData() {
    struct List list;
    initializeList(&list, 10);
    loadExternalData(&list, "UE_IDs.csv", "RNTIs.csv");
    assert(containsEntry(&list, 1, 2));
    freeList(&list);
}

void testHandleExternalDataError() {
    struct List list;
    initializeList(&list, 10);
    handleExternalDataError(&list, "An error occurred while opening the file");
    assert(isEmpty(&list));
    freeList(&list);
}
