    CRC_CHECK_RESULT CRC_STATUS;
} LTE_PHY_MESG_T;

// Function to create and populate a list of LTE_PHY_MESG_T structures
LTE_PHY_MESG_T *create_and_populate_list(int num_msgs) {
    // Create an empty list
    LTE_PHY_MESG_T *list = malloc(sizeof(LTE_PHY_MESG_T));

    // Initialize the list with randomly set CRC_STATUS values
    for (int i = 0; i < num_msgs; i++) {
        LTE_PHY_MESG_T *msg = malloc(sizeof(LTE_PHY_MESG_T));
        msg->UE_ID = rand();
        msg->PHY_MSG = PHY_LAYER_MESSAGE();
        msg->CRC_STATUS = CRC_CHECK_RESULT();
        list[i] = *msg;
    }

    return list;
}

// Function to add a new element to the list, minimizing memory fragmentation
void add_element(LTE_PHY_MESG_T **list, int num_msgs) {
    // Create a new element with randomly set CRC_STATUS values
    LTE_PHY_MESG_T *new_msg = malloc(sizeof(LTE_PHY_MESG_T));
    new_msg->UE_ID = rand();
    new_msg->PHY_MSG = PHY_LAYER_MESSAGE();
    new_msg->CRC_STATUS = CRC_CHECK_RESULT();

    // Add the new element to the list
    *list[num_msgs] = *new_msg;
}

// Function to remove an element from the list, if it exists
void remove_element(LTE_PHY_MESG_T **list, int num_msgs) {
    // Check if the list is empty
    if (num_msgs == 0) {
        return;
    }

    // Remove the last element from the list
    LTE_PHY_MESG_T *removed_msg = list[num_msgs - 1];
    free(removed_msg);

    // Decrease the size of the list by one
    num_msgs--;
}

// Function to invalidate previously added messages, ensuring freshness of data
void invalidate_messages(LTE_PHY_MESG_T **list, int num_msgs) {
    // Check if the list is empty
    if (num_msgs == 0) {
        return;
    }

    // Invalidate all elements in the list
    for (int i = 0; i < num_msgs; i++) {
        LTE_PHY_MESG_T *msg = list[i];
        msg->CRC_STATUS.status = CRC_STATUS_INVALID;
    }
}

// Function to resize the list dynamically, without reallocating all elements
void resize_list(LTE_PHY_MESG_T **list, int *num_msgs) {
    // Calculate the new size of the list
    int new_size = 2 * (*num_msgs);

    // Create a new list with the new size
    LTE_PHY_MESG_T *new_list = malloc(sizeof(LTE_PHY_MESG_T) * new_size);

    // Copy all elements from the old list to the new list
    for (int i = 0; i < *num_msgs; i++) {
        LTE_PHY_MESG_T *msg = list[i];
        new_list[i] = *msg;
    }

    // Free the old list
    free(*list);

    // Set the new list as the current list
    *list = new_list;
}

// Function to handle memory allocation and deallocation properly
void malloc_and_free(LTE_PHY_MESG_T **list, int num_msgs) {
    // Allocate memory for the list
    *list = malloc(sizeof(LTE_PHY_MESG_T));

    // Check if allocation failed
    if (*list == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the list with a randomly set CRC_STATUS value
    LTE_PHY_MESG_T *msg = malloc(sizeof(LTE_PHY_MESG_T));
    msg->UE_ID = rand();
    msg->PHY_MSG = PHY_LAYER_MESSAGE();
    msg->CRC_STATUS = CRC_CHECK_RESULT();
    *list[0] = *msg;

    // Deallocate the memory for the message
    free(msg);
}
