#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>
#include <pthread.h>

#define MAX_UE_IDS 1000
#define CACHE_SIZE 50

typedef struct LTE_PHY_MESG_T {
    int UE_ID;
    char PHY_LAYER_MESSAGE[MAX_MESSAGE_LENGTH];
    int CRC_CHECK_RESULT;
} LTE_PHY_MESG_T;

typedef struct UE_ID_CACHE {
    int UE_IDs[CACHE_SIZE];
    int size;
    pthread_mutex_t lock;
} UE_ID_CACHE;

UE_ID_CACHE *ue_id_cache = NULL;
pthread_mutex_t ue_id_lock = PTHREAD_MUTEX_INITIALIZER;

void populate_ue_id_cache(void) {
    int i, j;
    for (i = 0; i < MAX_UE_IDS; i++) {
        UE_ID_CACHE *cache = malloc(sizeof(UE_ID_CACHE));
        cache->size = 0;
        pthread_mutex_init(&cache->lock, NULL);
        for (j = 0; j < CACHE_SIZE; j++) {
            int UE_ID = get_next_ue_id();
            if (UE_ID != -1) {
                cache->UE_IDs[j] = UE_ID;
                cache->size++;
            } else {
                break;
            }
        }
