void handle_http_post(int page_section_id, int element_id, char *html_content) {
  // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
  struct NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu_list = NULL;

  // Populate the list with randomly set CRCFLAG and handle potential failures
  for (int i = 0; i < 1000; i++) {
    struct NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    crc_indication_pdu->valid = 1;
    crc_indication_pdu->RX_UE_INFORMATION_TAG = i;
    crc_indication_pdu->RNTI = rand() % 10000;
    crc_indication_pdu->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 0 : 1;
    crc_indication_pdu_list[i] = *crc_indication_pdu;
  }

