// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int populate_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T **list, size_t num_structures) {
    // Check if the input parameters are valid
    if (list == NULL || num_structures == 0) {
        return -1;
    }

    // Initialize the list to NULL
    *list = NULL;

    // Create a memory pool for dynamic memory allocation
    size_t pool_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures;
    void *pool = malloc(pool_size);

    // Initialize the counter for number of structures created
    size_t count = 0;

    // Create a thread-safe lock for synchronizing access to the list
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Asynchronously fetch RX_UE_INFORMATION_TAG and RNTI from external database
    External external = {
        .get_rx_ue_information_tag = get_rx_ue_information_tag,
        .get_rnti = get_rnti
    };

    // Fetch RX_UE_INFORMATION_TAG and RNTI from external database in a separate thread
    pthread_t fetcher;
    int error = pthread_create(&fetcher, NULL, fetch_rx_ue_information, &external);

    // If creating the thread failed, log an error message and return -1
    if (error != 0) {
        printf("Error creating thread: %s\n", strerror(error));
        pthread_mutex_destroy(&mutex);
        free(pool);
        return -1;
    }

    // Wait for the fetcher thread to finish
    error = pthread_join(fetcher, NULL);

    // If joining the thread failed, log an error message and return -1
    if (error != 0) {
        printf("Error joining thread: %s\n", strerror(error));
        pthread_mutex_destroy(&mutex);
        free(pool);
        return -1;
    }

    // Iterate over the RX_UE_INFORMATION_TAG and RNTI list
    int *rx_ue_information_tag_list = external.get_rx_ue_information_tag();
    size_t rx_ue_information_tag_list_size = external.get_rx_ue_information_tag_size();
    for (int i = 0; i < rx_ue_information_tag_list_size; i++) {
        // Get the RX_UE_INFORMATION_TAG and RNTI from the list
        int rx_ue_information_tag = rx_ue_information_tag_list[i];
        int rnti = external.get_rnti(rx_ue_information_tag);

        // Allocate memory for the CRC indication PDU structure
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *) pool;
        size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        pool += pdu_size;

        // Initialize the CRC indication PDU structure
        pdu->rx_ue_information_tag = rx_ue_information_tag;
        pdu->rnti = rnti;
        pdu->crc_indication_rel8_tag = (rand() % 2) ? 1 : 0;

        // Add the CRC indication PDU structure to the list
        pthread_mutex_lock(&mutex);
        *list = realloc(*list, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * (count + 1));
        (*list)[count] = pdu;
        count++;
        pthread_mutex_unlock(&mutex);
    }

    // Free the memory pool
    free(pool);

    // Return the number of structures created
    return count;
}

// Function to fetch RX_UE_INFORMATION_TAG and RNTI from external database in a separate thread
void *fetch_rx_ue_information(void *args) {
    External *external = (External *) args;

    // Initialize the list of RX_UE_INFORMATION_TAG and RNTI
    int rx_ue_information_tag_list[1024];
    size_t rx_ue_information_tag_list_size = 0;

    // Fetch RX_UE_INFORMATION_TAG and RNTI from external database
    while (rx_ue_information_tag_list_size < 1024) {
        int rx_ue_information_tag = (*external->get_rx_ue_information_tag)();
        if (rx_ue_information_tag == -1) {
            break;
        }
        int rnti = (*external->get_rnti)(rx_ue_information_tag);
        if (rnti == -1) {
            continue;
        }
        rx_ue_information_tag_list[rx_ue_information_tag_list_size++] = rx_ue_information_tag;
    }

    // Return the list of RX_UE_INFORMATION_TAG and RNTI
    return rx_ue_information_tag_list;
}
