// Command line options and help message
const std::string USAGE = "Usage: mersenne_twister [options]\n"
                          "Options:\n"
                          "-h, --help            Show this help message and exit\n"
                          "-s, --seed <integer>  Set the seed value for the random number generator (default: 0)\n"
                          "-d, --distribution <name>  Set the distribution type (default: uniform)\n"
                          "--output_file=<filename>    Save output to a file\n";

// Namespace and class definition
namespace MersenneTwister {
class RandomNumberGenerator {
private:
    static std::mt19937 gen_; // generate random numbers using the mersenne twister algorithm
public:
    RandomNumberGenerator(unsigned int seed = 0) { gen_.seed(seed); }
    ~RandomNumberGenerator() {}

    double getRandomNumber(std::string dist_type = "uniform") {
        if (dist_type == "uniform") {
            return std::uniform_real_distribution<double>(0.0, 1.0)(gen_);
        } else if (dist_type == "normal") {
            return std::normal_distribution<double>(0.0, 1.0)(gen_);
        } else if (dist_type == "exponential") {
            return std::exponential_distribution<double>(1.0)(gen_);
        } else {
            throw std::invalid_argument("Invalid distribution type");
        }
    }
};
} // namespace MersenneTwister

// Parse command line arguments and configure the random number generator
int main(int argc, char **argv) {
    unsigned int seed = 0;
    std::string dist_type = "uniform";
    std::string output_file;
    for (int i = 1; i < argc; ++i) {
        if (std::string(argv[i]) == "-h" || std::string(argv[i]) == "--help") {
            std::cout << USAGE;
            return 0;
        } else if (std::string(argv[i]).substr(1, 2) == "-s" && i + 1 < argc) {
            seed = atoi(argv[++i]);
        } else if (std::string(argv[i]).substr(1, 2) == "-d" && i + 1 < argc) {
            dist_type = std::string(argv[++i]);
        } else if (std::string(argv[i]) == "--output_file" && i + 1 < argc) {
            output_file = std::string(argv[++i]);
        }
    }

    // Open the output file and set up the random number generator
    std::ofstream out;
    if (output_file != "") {
        out.open(output_file);
        if (!out) {
            std::cerr << "Error: Could not open output file\n";
            return 1;
        }
    }
    MersenneTwister::RandomNumberGenerator rng(seed);

    // Read input from a file and generate random numbers based on the specified distribution parameters
    if (argc == 2) {
        std::ifstream in(argv[1]);
        if (!in) {
            std::cerr << "Error: Could not open input file\n";
            return 1;
        }
        double num;
        while (in >> num) {
            out << rng.getRandomNumber(dist_type) << "\n";
        }
    } else {
        std::cout << "Error: Invalid input file\n";
        return 1;
    }

    // Close the output file and clean up resources
    if (output_file != "") {
        out.close();
    }
    return 0;
}']

