void create_ue_context_list(int N, char* filepath) {
    // Initialize an empty list
    UE_Context_T *list = malloc(sizeof(UE_Context_T));
    size_t list_size = 0;

    // Load initial context data from a file if available
    if (filepath != NULL) {
        FILE *fp = fopen(filepath, "r");
        if (fp == NULL) {
            printf("Error: Failed to open file for reading\n");
            return;
        }
        // Read the initial context data from the file
        while (!feof(fp)) {
            UE_Context_T context = {0};
            fscanf(fp, "%d %d %d", &context.UE_ID, &context.mac_config.encryption_algorithm, &context.rrc_info.security_mode);
            // Add the context to the list
            list[list_size++] = context;
        }
        fclose(fp);
    }

    // Ensure that the list size does not exceed the maximum size
    if (N > MAX_LIST_SIZE) {
        N = MAX_LIST_SIZE;
    }

    // Truncate the list if necessary
    if (list_size > N) {
        list_size = N;
    }

    // Randomly set encryption algorithm for each UE context
    srand(time(NULL));
    for (int i = 0; i < list_size; i++) {
        int rand_num = rand() % INT_MAX;
        list[i].mac_config.encryption_algorithm = rand_num;
    }

    // Save the current context data to a file before returning
    if (filepath != NULL) {
        FILE *fp = fopen(filepath, "w");
        if (fp == NULL) {
            printf("Error: Failed to open file for writing\n");
            return;
        }
        // Write the current context data to the file
