    uint8_t crc_indication_rel8_tag;
    bool crcflag;
};

void create_crc_indication_pdu(const char *json_config) {
    // Parse JSON configuration file and retrieve number of elements to be created
    json_object *root = json_tokener_parse(json_config);
    if (root == NULL) {
        fprintf(stderr, "Failed to parse JSON config: %s\n", json_config);
        return;
    }

    int num_elements = 0;
    json_object *num_elems = json_object_get_object(root, "num_elements");
    if (num_elems != NULL) {
        num_elements = json_object_get_int(num_elems);
    } else {
        fprintf(stderr, "Missing 'num_elements' field in JSON config\n");
        return;
    }

    // Allocate memory for the list of CRC_INDICATION_PDU structures
    struct CRC_INDICATION_PDU *crc_list = calloc(num_elements, sizeof(*crc_list));
    if (crc_list == NULL) {
        fprintf(stderr, "Failed to allocate memory for CRC list\n");
        return;
    }

    // Initialize each element in the list with a valid RX_UE_INFORMATION_TAG and RNTI
    for (int i = 0; i < num_elements; i++) {
        crc_list[i].rx_ue_information_tag = NFAPI_RX_UE_INFORMATION_TAG_CRC;
        crc_list[i].rnti = i + 1;
    }

    // Set CRCFLAG to a random value for each element in the list
    for (int i = 0; i < num_elements; i++) {
        crc_list[i].crcfalg = rand() % 2;
    }

    // Create a JSON object for the CRC_INDICATION_PDU structures and print it to stdout
    json_object *crc_json = json_object_new_array();
    for (int i = 0; i < num_elements; i++) {
        struct CRC_INDICATION_PDU *pdu = &crc_list[i];
        json_object *pdu_json = json_object_new_object();
        json_object_object_add(pdu_json, "rx_ue_information_tag", json_object_new_int(pdu->rx_ue_information_tag));
        json_object_object_add(pdu_json, "rnti", json_object_new_uint(pdu->rnti));
        json_object_object_add(pdu_json, "crc_indication_rel8_tag", json_object_new_int(pdu->crc_indication_rel8_tag));
        json_object_object_add(pdu_json, "crcfalg", json_object_new_boolean(pdu->crcflag));
        json_object_array_add(crc_json, pdu_json);
    }
    printf("%s\n", json_object_to_json_string(crc_json));

    // Clean up memory and return the list of CRC_INDICATION_PDU structures
    free(crc_list);
}
