    if (!msg) {
        // handle memory allocation error
        return;
    }

    msg->next = *messages;
    *messages = msg;
}

void populate_dl_ccch_messages(LTE_DL_CCCH_Message **messages, char **cause_values) {
    for (int i = 0; cause_values[i]; ++i) {
        // validate each cause value before adding it to the list
        if (!validate_cause_value(cause_values[i])) {
            continue;
        }

        add_dl_ccch_message(messages, atoi(cause_values[i]));
    }
}

void destroy_dl_ccch_messages(LTE_DL_CCCH_Message **messages) {
    LTE_DL_CCCH_Message *cur = *messages;
    while (cur) {
        LTE_DL_CCCH_Message *next = cur->next;
        free(cur);
        cur = next;
    }
