int create_list(struct LTE_RRC_CTRLLNK_UL_CCCH_PDU *pdu_list, uint16_t max_entries) {
  // Initialize the list with a null pointer
  struct LTE_RRC_CTRLLNK_UL_CCCH_PDU *current = NULL;

  // Allocate memory for the list entries
  for (uint16_t i = 0; i < max_entries; i++) {
    current = (struct LTE_RRC_CTRLLNK_UL_CCCH_PDU *)malloc(sizeof(struct LTE_RRC_CTRLLNK_UL_CCCH_PDU));
    if (!current) {
      // Memory allocation failed, return error code
      return -1;
    }

    current->UE_ID = get_ue_id(); // Fetch UE ID from external data source
    current->UL_CCCH_message.PDCP_SN = generate_pdcp_sn(); // Set a random PDCP SN for each entry
    current->valid = 1; // Mark the entry as valid

    // Add the new entry to the list
    if (!pdu_list) {
      pdu_list = current;
    } else {
      struct LTE_RRC_CTRLLNK_UL_CCCH_PDU *next = pdu_list->next;
      pdu_list->next = current;
      pdu_list = next;
    }
  }

  return 0; // Return success code
}

// Free the memory allocated for the list entries
void free_list(struct LTE_RRC_CTRLLNK_UL_CCCH_PDU *pdu_list) {
  struct LTE_RRC_CTRLLNK_UL_CCCH_PDU *current = pdu_list;

  while (current != NULL) {
    struct LTE_RRC_CTRLLNK_UL_CCCH_PDU *next = current->next;
    free(current);
    current = next;
  }
}

