    uint16_t rnti;
    uint8_t crcFlag;
} nfapi_crc_indication_pdu_t;

// Thread-safe list for storing NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    pthread_mutex_t lock;
    uint32_t size;
    nfapi_crc_indication_pdu_t *data;
} thread_safe_list_t;

// Initialize a thread-safe list for storing NFAPI_CRC_INDICATION_PDU_T structures
void init_thread_safe_list(thread_safe_list_t *list) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&list->lock, &attr);
    list->size = 0;
    list->data = NULL;
}

// Add a new NFAPI_CRC_INDICATION_PDU_T structure to the thread-safe list
void add_to_thread_safe_list(thread_safe_list_t *list, nfapi_crc_indication_pdu_t *pdu) {
    pthread_mutex_lock(&list->lock);
    list->data = realloc(list->data, (list->size + 1) * sizeof(nfapi_crc_indication_pdu_t));
    if (!list->data) {
        // Handle memory allocation failure gracefully by cleaning up partially populated structures
        for (int i = 0; i < list->size; i++) {
            free(list->data[i].rnti);
            free(list->data[i].crc_indication_rel8.crc_flag);
        }
        free(list->data);
        pthread_mutex_unlock(&list->lock);
        return;
    }
    list->data[list->size++] = *pdu;
    pthread_mutex_unlock(&list->lock);
}

// Populate a list of NFAPI_CRC_INDICATION_PDU_T structures with valid RX_UE_INFORMATION_TAG and RNTI values
void populate_crc_indication_pdu_list(thread_safe_list_t *list) {
    uint16_t rnti;
