            if (rnti > 0xffff) {
                break;
            }
        }
        // Add a new NFAPI_CRC_INDICATION_PDU_T structure to the thread-safe list with the validated RX_UE_INFORMATION_TAG and RNTI values
        nfapi_crc_indication_pdu_t pdu;
        pdu.rnti = rnti;
        pdu.crc_indication_rel8.crc_flag = rand() & 1; // Randomly set CRCFLAG value
        add_to_thread_safe_list(list, &pdu);
