<?php

function authenticateUser($username, $password) {
    // Initialize the OAuth 2.0 client and get an access token
    $client = new \GuzzleHttp\Client();
    $response = $client->request('POST', 'https://oauth.example.com/token', [
        'form_params' => [
            'grant_type' => 'password',
            'username' => $username,
            'password' => $password,
            'scope' => 'profile email',
        ],
    ]);
    $accessToken = $response->getBody()->getContents();

    // Store the access token in a session variable for future use
    $_SESSION['access_token'] = $accessToken;

    // Retrieve user information using the access token
    $client = new \GuzzleHttp\Client();
    $response = $client->request('GET', 'https://api.example.com/users/me', [
        'headers' => [
            'Authorization' => 'Bearer ' . $_SESSION['access_token'],
        ],
    ]);
    $userInfo = json_decode($response->getBody()->getContents(), true);

    return $userInfo;
}

