    $response = $client->request('GET', 'https://api.example.com/users', [
        'headers' => [
            'Authorization' => 'Bearer ' . $_SESSION['access_token'],
        ],
    ]);
    $userInfoList = json_decode($response->getBody()->getContents(), true);

    // Populate the GNBCUUEContext list with user information from the external API
    $list = initializeGNBCUUEContextList();
    foreach ($userInfoList as $userInfo) {
        if (count($list) >= $maxEntries) {
            break;
        }
        $ueId = $userInfo['id'];
        $rrcConnectionId = null; // TODO: retrieve RRC connection ID from external API
        $s1apMmeTeid = null; // TODO: retrieve S1AP MME TEID from external API
        $list[] = new \GNBCUUE_CONTEXT_T($ueId, $rrcConnectionId, $s1apMmeTeid);
    }

    return $list;
}

function freeGNBCUUEContextList(\SplFixedArray $list) {
    // Free all memory allocated to the list of GNBCUUE_CONTEXT structures
    for ($i = 0; $i < count($list); $i++) {
        unset($list[$i]);
    }
}
