// Function to handle error checking and memory management for the list of UE_PDU_T structures
void update_ue_list() {
    // Dynamically allocate memory for the list of UE_PDU_T structures
    UE_PDU_T *ue_list = malloc(sizeof(UE_PDU_T) * NUM_UES);
    if (ue_list == NULL) {
        printf("Failed to allocate memory for UE list\n");
        return;
    }

    // Populate the list with random data
