```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define a struct for the linked list nodes
struct nas_message {
    int ue_id;
    int message_id;
    char *s1ap_message;
    bool is_initial_context_setup;
    struct nas_message *next;
};

// Define a custom memory pool for allocating and deallocating nodes
struct memory_pool {
    size_t size;
    size_t capacity;
    void **buffer;
};

// Function to create and populate a linked list of LTE NAS messages
int create_nas_messages(int ue_id, int num_messages) {
    // Check if the input UE ID is valid
    if (ue_id < 1 || ue_id > 1000) {
        printf("Invalid UE ID: %d\n", ue_id);
        return -1;
    }

    // Initialize a memory pool for allocating and deallocating nodes
    struct memory_pool *pool = (struct memory_pool *)malloc(sizeof(struct memory_pool));
    if (!pool) {
        printf("Failed to initialize memory pool\n");
        return -1;
    }
    pool->size = 0;
    pool->capacity = num_messages * sizeof(struct nas_message);
    pool->buffer = (void **)malloc(pool->capacity);
    if (!pool->buffer) {
        printf("Failed to allocate memory for the linked list\n");
        free(pool);
        return -1;
    }

    // Create and populate a linked list of LTE NAS messages
    struct nas_message *head = NULL, *cur = NULL;
    for (int i = 0; i < num_messages; i++) {
        // Generate a random UE ID
        int ue_id = rand() % 1000 + 1;

        // Allocate memory for the current node
        struct nas_message *node = (struct nas_message *)malloc(sizeof(struct nas_message));
        if (!node) {
            printf("Failed to allocate memory for NAS message\n");
            free_nas_messages(head);
            return -1;
        }

        // Initialize the current node
        node->ue_id = ue_id;
        node->message_id = rand() % 1000 + 1;
        node->s1ap_message = (char *)malloc(sizeof(char) * 50);
        if (!node->s1ap_message) {
            printf("Failed to allocate memory for S1AP message\n");
            free(node);
            continue;
        }
        node->is_initial_context_setup = rand() % 2 == 0 ? true : false;
        node->next = NULL;

        // Add the current node to the linked list
        if (head == NULL) {
            head = cur = node;
        } else {
            cur->next = node;
            cur = node;
        }
    }

    // Free the memory pool
    free(pool);
    return 0;
}

// Function to free a linked list of LTE NAS messages
void free_nas_messages(struct nas_message *head) {
    struct nas_message *cur = head, *next = NULL;
    while (cur != NULL) {
        next = cur->next;
        free(cur->s1ap_message);
        free(cur);
        cur = next;
