// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures, each containing a valid RX_UE_INFORMATION_TAG and RNTI, and a CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
void populate_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T **crc_indication_pdus, int num_crc_indications, FSA_STATE_LIST *fsa_state_lists) {
    // Allocate memory for the list of CRC indication PDUs and initialize it to NULL
    *crc_indication_pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_crc_indications * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*crc_indication_pdus == NULL) {
        printf("Error: Failed to allocate memory for CRC indication PDU list\n");
        return;
    }

    // Initialize the CRC indication PDUs with valid values
    for (int i = 0; i < num_crc_indications; i++) {
        (*crc_indication_pdus)[i].rx_ue_information_tag = i + 1;
        (*crc_indication_pdus)[i].rnti = i + 2;
        (*crc_indication_pdus)[i].crc_indication_rel8_tag = i + 3;
        (*crc_indication_pdus)[i].crcflag = rand() % 2; // Randomly set CRCFLAG to true or false
    }

    // Allocate memory for the state lists and initialize them to NULL
    *fsa_state_lists = (FSA_STATE_LIST *)malloc(MAX_FSAS * sizeof(FSA_STATE_LIST));
    if (*fsa_state_lists == NULL) {
        printf("Error: Failed to allocate memory for FSA state lists\n");
        return;
    }
    for (int i = 0; i < MAX_FSAS; i++) {
        (*fsa_state_lists)[i].state_list = NULL;
        (*fsa_state_lists)[i].num_states = 0;
        (*fsa_state_lists)[i].last_state = -1;
    }
}

// Function to manage a dynamic list of state lists for multiple finite state automata (FSAs) in a resource-constrained environment
void manage_fsa_state_lists(NFAPI_CRC_INDICATION_PDU_T **crc_indication_pdus, int num_crc_indications, FSA_STATE_LIST *fsa_state_lists) {
    // Allocate memory for the state lists and initialize them to NULL
    for (int i = 0; i < MAX_FSAS; i++) {
        (*fsa_state_lists)[i].state_list = (uint32_t *)malloc(MAX_STATES * sizeof(uint32_t));
        if ((*fsa_state_lists)[i].state_list == NULL) {
            printf("Error: Failed to allocate memory for FSA state list %d\n", i);
            return;
        }
        (*fsa_state_lists)[i].num_states = 0;
        (*fsa_state_lists)[i].last_state = -1;
    }

    // Loop through the CRC indication PDUs and add each state to its corresponding FSA's state list
    for (int i = 0; i < num_crc_indications; i++) {
        int fsa_id = (*crc_indication_pdus)[i].rx_ue_information_tag - 1; // Convert RX UE information tag to FSA ID
        if (fsa_id >= MAX_FSAS) continue; // Skip invalid FSA IDs
        int state_id = (*crc_indication_pdus)[i].rnti; // Use the RNTI as the state ID
        (*fsa_state_lists)[fsa_id].state_list[(*fsa_state_lists)[fsa_id].num_states] = state_id;
        (*fsa_state_lists)[fsa_id].num_states++;
    }

    // Sort the state lists for each FSA by state ID
    for (int i = 0; i < MAX_FSAS; i++) {
        qsort((*fsa_state_lists)[i].state_list, (*fsa_state_lists)[i].num_states, sizeof(uint32_t), compare_state_ids);
    }
}

// Function to filter transactions based on criteria including the transaction's age, the number of transactions in the past 3 seconds, and the transaction's weighted sum.
void filter_transactions(NFAPI_CRC_INDICATION_PDU_T **crc_indication_pdus, int num_crc_indications, FSA_STATE_LIST *fsa_state_lists) {
    // Initialize a set of metrics for each FSA, including the number of transactions and their weighted sum
    for (int i = 0; i < MAX_FSAS; i++) {
        (*fsa_state_lists)[i].num_transactions = 0;
        (*fsa_state_lists)[i].weighted_sum = 0;
    }

    // Loop through the CRC indication PDUs and update the metrics for each FSA based on the transaction's age, number of transactions in the past 3 seconds, and weighted sum
    for (int i = 0; i < num_crc_indications; i++) {
        int fsa_id = (*crc_indication_pdus)[i].rx_ue_information_tag - 1; // Convert RX UE information tag to FSA ID
        if (fsa_id >= MAX_FSAS) continue; // Skip invalid FSA IDs
        int state_id = (*crc_indication_pdus)[i].rnti; // Use the RNTI as the state ID
        uint8_t crcflag = (*crc_indication_pdus)[i].crcflag; // Use the CRCFLAG for filtering
        if (crcflag) { // Only count transactions with valid CRC flags
            (*fsa_state_lists)[fsa_id].num_transactions++;
            (*fsa_state_lists)[fsa_id].weighted_sum += state_id;
        }
    }

    // Find the maximum weighted sum and corresponding transaction ID for each FSA
    int max_weighted_sum = 0;
    uint32_t max_transaction_id = 0;
    for (int i = 0; i < MAX_FSAS; i++) {
        if ((*fsa_state_lists)[i].num_transactions > 0 && (*fsa_state_lists)[i].weighted_sum > max_weighted_sum) {
            max_transaction_id = (*fsa_state_lists)[i].state_list[(*fsa_state_lists)[i].last_state];
        }
    }
}

// Comparison function for sorting state IDs in ascending order
int compare_state_ids(const void *a, const void *b) {
    return (*(uint32_t *)a - *(uint32_t *)b);
}
