class PasswordUpdateService {
    private $dao;
    private $commonPasswordList;

    public function __construct($dao, $commonPasswordList) {
        $this->dao = $dao;
        $this->commonPasswordList = $commonPasswordList;
    }

    public function updateUserPassword(int $userId, string $oldPassword, string $newPassword) {
        if (!$this->validateOldPassword($oldPassword)) {
            throw new \Exception("Invalid old password");
        }

        if (!$this->validateNewPassword($newPassword)) {
            throw new \Exception("Invalid new password");
        }

        $result = $this->dao->updateUserPassword($userId, $oldPassword, $newPassword);

        if ($result === false) {
            throw new \Exception("Failed to update user password");
        }

        return true;
    }

    private function validateOldPassword(string $password): bool {
        // Ensure that the old password is not a subset of the new password
        if (strpos($newPassword, $oldPassword) !== false) {
            return false;
        }

        return true;
    }

    private function validateNewPassword(string $password): bool {
        // Validate that the new password is not in the common password list
        if (in_array($password, $this->commonPasswordList)) {
            return false;
        }

        return true;
    }

    private function rateLimit(int $userId): bool {
        // Implement rate limiting to prevent brute-force attacks
        $consecutiveFailures = 0;

        while ($consecutiveFailures < 5) {
            if (!$this->dao->checkRateLimit($userId)) {
                $consecutiveFailures++;
            } else {
                break;
            }
        }

        return $consecutiveFailures >= 5;
    }
}
