// Define the structure for the MAC PDUs
struct mac_pdu {
    struct mac_header header;
    size_t sdu_count;
    struct sdu **sdus;
};

// Define the structure for the SDUs
struct sdu {
    uint8_t *data;
    size_t size;
};

// Function to create and populate a list of MAC PDUs
int create_mac_pdu_list(size_t max_count, struct mac_pdu **mac_pdus) {
    // Check if the input parameters are valid
    if (max_count > 1000 || max_count == 0) {
        return -1;
    }

    // Allocate memory for the list of MAC PDUs
    *mac_pdus = malloc(sizeof(struct mac_pdu) * max_count);
    if (*mac_pdus == NULL) {
        return -2;
    }

    // Initialize the list of MAC PDUs
    for (size_t i = 0; i < max_count; i++) {
        (*mac_pdus)[i].header.valid = false;
        (*mac_pdus)[i].sdu_count = 0;
        (*mac_pdus)[i].sdus = NULL;
    }

    // Allocate memory for the SDUs and populate the list of MAC PDUs
    for (size_t i = 0; i < max_count; i++) {
        size_t sdu_count = rand() % 10 + 1;
        (*mac_pdus)[i].sdu_count = sdu_count;
        (*mac_pdus)[i].sdus = malloc(sizeof(struct sdu) * sdu_count);
        if ((*mac_pdus)[i].sdus == NULL) {
            return -2;
        }

        for (size_t j = 0; j < sdu_count; j++) {
            size_t data_size = rand() % 1500 + 1;
            (*mac_pdus)[i].sdus[j].data = malloc(sizeof(uint8_t) * data_size);
            if ((*mac_pdus)[i].sdus[j].data == NULL) {
                return -2;
            }

            memset((*mac_pdus)[i].sdus[j].data, 0, sizeof(uint8_t) * data_size);
        }
    }

    // Validate the SDU sizes and handle any errors
    for (size_t i = 0; i < max_count; i++) {
        for (size_t j = 0; j < (*mac_pdus)[i].sdu_count; j++) {
            if ((*mac_pdus)[i].sdus[j].size < 1 || (*mac_pdus)[i].sdus[j].size > 1500) {
                return -2;
            }
        }
    }

    // Return success
    return 0;
}

// Function to destroy the list of MAC PDUs
void destroy_mac_pdu_list(struct mac_pdu *mac_pdus, size_t count) {
    for (size_t i = 0; i < count; i++) {
        free((*mac_pdus)[i].sdus);
    }
    free(mac_pdus);
}
