  for (int i = 0; i < octree->capacity; i++) {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.rx_ue_information_tag = i;
    pdu.rnti = ueInfo[i];
    pdu.crc_indication_rel8_tag = rand() % 2 == 0 ? true : false;
    octree->list.push_back(pdu);
  }

  return 0;
}
