```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <netdb.h>
#include <arpa/inet.h>

// DNS resolution function
int dns_resolution(const char *hostname, u_char **ip_address) {
    struct addrinfo hints;
    struct addrinfo *result, *rp;
    int status;

    // Set up the hints for the getaddrinfo function
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_INET;   // IPv4
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_V4MAPPED | AI_ADDRCONFIG;

    // Get the IP address for the given hostname
    status = getaddrinfo(hostname, NULL, &hints, &result);
    if (status != 0) {
        fprintf(stderr, "getaddrinfo failed: %s\n", gai_strerror(status));
        return -1;
    }

    // Loop through the results and find the first valid IPv4 address
    for (rp = result; rp != NULL; rp = rp->ai_next) {
        void *addr;
        int addrlen;

        if (rp->ai_family == AF_INET) {
            addr = &((struct sockaddr_in *)rp->ai_addr)->sin_addr;
            addrlen = sizeof(struct in_addr);
        } else {
            continue;
        }

        // Return the IP address as a u_char array
        *ip_address = malloc(addrlen);
        memcpy(*ip_address, addr, addrlen);

        freeaddrinfo(result);
        return 0;
    }

    freeaddrinfo(result);
    fprintf(stderr, "No IPv4 addresses found for hostname\n");
    return -1;
}
```

