// Asynchronous reduction method for an array of numbers using callbacks
function reduceAsync(arr, initialValue, callback) {
    // Initialize the final reduced value to the initial value
    let finalReducedValue = initialValue;

    // Loop through the array asynchronously and perform the reduction operation
    arr.forEach(async (element, index) => {
        // Perform the reduction operation on each element using the callback function
        const reducedValue = await callback(finalReducedValue, element);

        // Set the final reduced value to the return value of the callback function
        finalReducedValue = reducedValue;
    });

    // Return the final reduced value
    return finalReducedValue;
}
```

