// Define the structure for storing RX UE information
typedef struct {
    uint16_t rnti;
    uint8_t crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list node for storing the RX UE information
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct node *next;
} node;

// Function to create and populate a list of RX UE information
int create_rx_ue_list(uint16_t num_ues) {
    int ret = 0; // Initialize return value
    uint16_t i, j; // Loop counters
    NFAPI_CRC_INDICATION_PDU_T *rx_pdu; // Pointer to RX UE information PDU
    node *head = NULL; // Head of the linked list

    // Validate the number of UEs
    if (num_ues > 1000) {
        printf("Number of UEs exceeds maximum limit of 1000\n");
        ret = -1;
        goto cleanup;
    }

    // Allocate memory for the linked list node
    head = (node *) malloc(sizeof(node));
    if (!head) {
        printf("Failed to allocate memory for linked list node\n");
        ret = -1;
        goto cleanup;
    }

    // Initialize the linked list node and its data
    head->next = NULL;
    rx_pdu = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!rx_pdu) {
        printf("Failed to allocate memory for RX UE information PDU\n");
        ret = -1;
        goto cleanup;
    }
    head->data = rx_pdu;

    // Populate the linked list with random RX UE information
    for (i = 0; i < num_ues; i++) {
        // Generate a random RNTI value between 1 and 65535 inclusive
        uint16_t rnti = rand() % 65536 + 1;

        // Validate the RNTI value
        if (rnti < 1 || rnti > 65535) {
            printf("Invalid RNTI value: %u\n", rnti);
            ret = -2;
            goto cleanup;
        }

        // Generate a random CRC_INDICATION_REL8_TAG value between 0 and 15 inclusive
        uint8_t crc_indication_rel8 = rand() % 16;

        // Set the RX UE information in the linked list node
        head->data->rnti = rnti;
        head->data->crc_indication_rel8 = crc_indication_rel8;

        // Add the linked list node to the end of the linked list
        while (head->next) {
            head = head->next;
        }
        head->next = (node *) malloc(sizeof(node));
        if (!head->next) {
            printf("Failed to allocate memory for linked list node\n");
            ret = -1;
            goto cleanup;
        }
        head = head->next;
    }

cleanup:
    // Clean up the linked list and its nodes if an error occurred
    if (ret < 0) {
        while (head != NULL) {
            node *temp = head;
            head = head->next;
            free(temp);
        }
    }
    return ret;
}
