    char *rrc_state; // Radio resource configuration state (e.g., "connected")
    void **downlink_buffers; // Set of downlink data buffers
} lte_ue_context;

// Global list of LTE UE contexts
lte_ue_context *ue_list = NULL;

// Function to create and populate a new LTE UE context
int create_ue_context(int ue_id, char *rrc_state) {
    // Allocate memory for the new UE context
    lte_ue_context *new_ue = (lte_ue_context *) malloc(sizeof(lte_ue_context));
    if (!new_ue) {
        printf("Error: unable to allocate memory for new UE\n");
        return -1;
    }

    // Initialize the UE context with the provided values
    new_ue->ue_id = ue_id;
    new_ue->rrc_state = strdup(rrc_state);
    new_ue->downlink_buffers = NULL;

    // Add the new UE to the list of UE contexts
    pthread_mutex_lock(&mutex);
    ue_list = realloc(ue_list, (sizeof(lte_ue_context) * (num_ues + 1)));
    if (!ue_list) {
        printf("Error: unable to allocate memory for new UE list\n");
        free(new_ue);
        return -1;
    }
    ue_list[num_ues++] = new_ue;
    pthread_mutex_unlock(&mutex);

    return 0;
}

// Function to update the RRC state of a UE context
int update_rrc_state(int ue_id, char *new_state) {
    // Find the UE context with the provided ID
    lte_ue_context *ue = find_ue_by_id(ue_id);
    if (!ue) {
        printf("Error: unable to find UE with ID %d\n", ue_id);
        return -1;
    }

    // Update the RRC state of the found UE context
    free(ue->rrc_state);
    ue->rrc_state = strdup(new_state);

    return 0;
}

// Function to add a new downlink buffer to an existing UE context
int add_downlink_buffer(int ue_id, void *buffer) {
    // Find the UE context with the provided ID
    lte_ue_context *ue = find_ue_by_id(ue_id);
    if (!ue) {
        printf("Error: unable to find UE with ID %d\n", ue_id);
        return -1;
    }

    // Allocate memory for the new downlink buffer
    void **new_buffer = (void **) malloc(sizeof(void *));
    if (!new_buffer) {
        printf("Error: unable to allocate memory for new downlink buffer\n");
        return -1;
    }

    // Add the new downlink buffer to the existing UE context
    ue->downlink_buffers = realloc(ue->downlink_buffers, (sizeof(void *) * (num_buffers + 1)));
    if (!ue->downlink_buffers) {
        printf("Error: unable to allocate memory for new downlink buffer\n");
        free(new_buffer);
        return -1;
    }
    ue->downlink_buffers[num_buffers++] = new_buffer;

    return 0;
}

// Function to release a downlink buffer from an existing UE context
int release_downlink_buffer(int ue_id, void *buffer) {
    // Find the UE context with the provided ID
    lte_ue_context *ue = find_ue_by_id(ue_id);
    if (!ue) {
        printf("Error: unable to find UE with ID %d\n", ue_id);
        return -1;
    }

    // Find the downlink buffer in the UE context
    for (int i = 0; i < num_buffers; i++) {
        if (ue->downlink_buffers[i] == buffer) {
            break;
        }
    }

    // If the buffer was found, remove it from the list of downlink buffers
    if (i < num_buffers) {
        free(ue->downlink_buffers[i]);
        ue->downlink_buffers[i] = NULL;
        return 0;
    } else {
        printf("Error: unable to find downlink buffer in UE context\n");
        return -1;
    }
}
