// Define a struct to store information about a RX UE information element
typedef struct {
    NFAPI_RX_UE_INFORMATION_TAG rx_ue_information;
    uint32_t rnti;
} rx_ue_information_element_t;

// Define a struct to store information about a CRC indication element
typedef struct {
    NFAPI_CRC_INDICATION_REL8_TAG crc_indication_rel8;
    uint32_t rnti;
} crc_indication_element_t;

// Define a linked list to store the RX UE information elements
typedef struct {
    rx_ue_information_element_t *head;
    rx_ue_information_element_t *tail;
    size_t size;
} rx_ue_information_list_t;

// Define a linked list to store the CRC indication elements
typedef struct {
    crc_indication_element_t *head;
    crc_indication_element_t *tail;
    size_t size;
} crc_indication_list_t;

// Define a semaphore to protect the list from concurrent access
sem_t list_lock;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int create_and_populate_crc_indication_list(rx_ue_information_list_t *rx_ue_info_list, crc_indication_list_t *crc_indication_list) {
    // Iterate through the list of RX UE information elements and populate the CRC indication list
    for (rx_ue_information_element_t *element = rx_ue_info_list->head; element != NULL; element = element->next) {
        // Create a new CRC indication element
        crc_indication_element_t *new_element = malloc(sizeof(crc_indication_element_t));
        if (new_element == NULL) {
            return -1;
        }

        // Set the RNTI and CRCFLAG fields of the CRC indication element
        new_element->rnti = element->rnti;
        new_element->crc_indication_rel8.CRCFlag = rand() % 2;

        // Add the CRC indication element to the list
        pthread_mutex_lock(&list_lock);
        if (crc_indication_list->head == NULL) {
            crc_indication_list->head = new_element;
            crc_indication_list->tail = new_element;
        } else {
            crc_indication_list->tail->next = new_element;
            crc_indication_list->tail = new_element;
        }
        pthread_mutex_unlock(&list_lock);
    }

    return 0;
}

// Function to retrieve an element from the list based on RNTI
rx_ue_information_element_t *get_rx_ue_info(crc_indication_list_t *crc_indication_list, uint32_t rnti) {
    // Iterate through the CRC indication list and search for an element with a matching RNTI
    for (crc_indication_element_t *element = crc_indication_list->head; element != NULL; element = element->next) {
        if (element->rnti == rnti) {
            return &element->rx_ue_information;
        }
    }

    // If no matching element is found, return NULL
    return NULL;
}
