// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_nfapi_crc_indication_pdu_list(size_t num_structures, const char *password, size_t seed) {
    // Initialize an AES-256-CBC cipher with the given password using OpenSSL
    EVP_CIPHER_CTX *cipher = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(cipher, EVP_aes_256_cbc(), NULL, password, NULL) != 1) {
        printf("Error initializing AES cipher\n");
        return;
    }

    // Set the IV length to 16 bytes and the key length to 32 bytes
    EVP_CIPHER_CTX_set_iv_length(cipher, 16);
    EVP_CIPHER_CTX_set_key_length(cipher, 32);

    // Initialize a theme cache for the mobile application
    struct {
        uint8_t *bitmap;
        size_t bitmap_size;
        size_t num_recycled;
    } theme_cache[num_structures];

    // Loop through each structure in the list and populate it with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (size_t i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Generate a random RX_UE_INFORMATION_TAG
        uint8_t rx_ue_information_tag;
        do {
            RAND_bytes((unsigned char *)&rx_ue_information_tag, 1);
        } while (rx_ue_information_tag == 0);

        // Generate a random RNTI
        uint16_t rnti;
        do {
            RAND_bytes((unsigned char *)&rnti, 2);
        } while (rnti == 0);

        // Derive an encryption key from the password using SHA-256
        uint8_t encryption_key[32];
        SHA256(password, strlen(password), encryption_key);

        // Generate a random CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        uint8_t crc_indication_rel8_tag;
        do {
            RAND_bytes((unsigned char *)&crc_indication_rel8_tag, 1);
        } while (crc_indication_rel8_tag == 0);

        // Populate the structure with the generated values
        pdu->RX_UE_INFORMATION_TAG = rx_ue_information_tag;
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG = crc_indication_rel8_tag;

        // Initialize the cipher with the derived key and IV
        EVP_EncryptInit_ex(cipher, NULL, NULL, encryption_key, NULL);

        // Recycle a theme bitmap from the cache if necessary
        size_t bitmap_index = (i % theme_cache[0].num_recycled) - 1;
        if (bitmap_index >= 0 && theme_cache[0].bitmap[bitmap_index] != NULL) {
            pdu->theme_bitmap = theme_cache[0].bitmap[bitmap_index];
            theme_cache[0].num_recycled--;
        } else {
            // Parse a PNG file from the cache root directory and store it in the theme cache if necessary
            char filepath[256];
            sprintf(filepath, "themes/theme%zu.png", seed);
            FILE *file = fopen(filepath, "rb");
            if (file != NULL) {
                pdu->theme_bitmap = malloc(sizeof(char) * 1024); // assume maximum size of 1024 bytes per PNG file
                fread(pdu->theme_bitmap, sizeof(char), 1024, file);
                fclose(file);
            } else {
                pdu->theme_bitmap = NULL;
            }
        }

        // Add the structure to the list
        NFAPI_CRC_INDICATION_PDU_T *pdu_list = realloc(NULL, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (i + 1));
        pdu_list[i] = *pdu;
    }

    // Clean up and disable the cipher and theme caching when they are no longer needed
    EVP_CIPHER_CTX_free(cipher);
}

// Function to clean up and disable the cipher and theme caching when they are no longer needed
void cleanup_nfapi_crc_indication_pdu_list() {
    // Disable the cipher and theme caching by setting their pointers to NULL
    EVP_CIPHER_CTX *cipher = EVP_CIPHER_CTX_new();
    struct {
        uint8_t *bitmap;
        size_t bitmap_size;
        size_t num_recycled;
    } theme_cache[1];

    // Loop through each structure in the list and recycle its theme bitmap if necessary
    for (size_t i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(pdu_list[i]);

        // Recycle the theme bitmap from the cache if necessary
        size_t bitmap_index = (i % theme_cache[0].num_recycled) - 1;
        if (bitmap_index >= 0 && theme_cache[0].bitmap[bitmap_index] != NULL) {
            theme_cache[0].bitmap[bitmap_index] = pdu->theme_bitmap;
            theme_cache[0].num_recycled++;
        } else {
            // Free the theme bitmap if it was allocated dynamically
            free(pdu->theme_bitmap);
        }
    }

    // Free the memory allocated for the list of structures
    free(pdu_list);
}
