// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list data structure
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    int capacity;
    int size;
    sem_t lock;
} NFAPI_CRC_LIST_T;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_LIST_T *create_nfapi_crc_list(int capacity) {
    // Allocate memory for the list data structure
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T *)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) {
        return NULL;
    }

    // Initialize the list with a specified capacity
    list->capacity = capacity;
    list->size = 0;
    list->list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    if (!list->list) {
        free(list);
        return NULL;
    }

    // Initialize the lock for thread safety
    sem_init(&list->lock, 0, 1);

    return list;
}

// Function to add an element to the end of the list
void nfapi_crc_list_add(NFAPI_CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    // Acquire the lock to prevent concurrent access
    sem_wait(&list->lock);

    // Check if the list needs to be resized
    if (list->size == list->capacity) {
        // Resize the list by 50%
        int new_capacity = list->capacity * 3 / 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
        if (!new_list) {
            free(list->list);
            list->capacity = 0;
            list->size = 0;
            sem_destroy(&list->lock);
            return;
        }
        list->list = new_list;
        list->capacity = new_capacity;
    }

    // Add the element to the end of the list
    NFAPI_CRC_INDICATION_PDU_T *element = &list->list[list->size];
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->size++;

    // Release the lock
    sem_post(&list->lock);
}

// Function to remove an element from the front of the list
void nfapi_crc_list_remove(NFAPI_CRC_LIST_T *list) {
    // Acquire the lock to prevent concurrent access
    sem_wait(&list->lock);

    // Check if the list is empty
    if (list->size == 0) {
        // Release the lock and return
        sem_post(&list->lock);
        return;
    }

    // Remove the element from the front of the list
    NFAPI_CRC_INDICATION_PDU_T *element = &list->list[0];
    for (int i = 1; i < list->size; i++) {
        element[i - 1] = element[i];
    }
    list->size--;

    // Release the lock
    sem_post(&list->lock);
}

// Function to flush the list to an external data source (e.g., a file or database)
void nfapi_crc_list_flush(NFAPI_CRC_LIST_T *list, void *data_source) {
    // Acquire the lock to prevent concurrent access
    sem_wait(&list->lock);

    // Check if the list is empty
    if (list->size == 0) {
        // Release the lock and return
        sem_post(&list->lock);
        return;
    }

    // Flush the list to the external data source
    for (int i = 0; i < list->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = &list->list[i];
        // Write the element to the external data source
        write_to_data_source(data_source, element);
    }

    // Clear the list
    list->size = 0;

    // Release the lock
    sem_post(&list->lock);
}

// Function to destroy the list and release its resources
void nfapi_crc_list_destroy(NFAPI_CRC_LIST_T *list) {
    // Acquire the lock to prevent concurrent access
    sem_wait(&list->lock);

    // Release the memory allocated for the list
    free(list->list);
    list->capacity = 0;
    list->size = 0;

    // Destroy the lock
    sem_destroy(&list->lock);

    // Release the lock and return
    sem_post(&list->lock);
}
