// Structure to hold a PDU element in the list
typedef struct {
    uint32_t rnti; // RNTI value for this PDU
    void *pdu; // Pointer to the PDU data
} pdu_element_t;

// List of PDU elements, with a maximum capacity of 1024 elements
static pdu_element_t pdu_list[1024];

// Number of elements in the list
static size_t num_pdu_elements = 0;

// Semaphore to protect access to the list
static sem_t *sem = NULL;

// Initialize the list and semaphore for use
void pdu_list_init(void) {
    // Initialize the list with all elements set to NULL
    memset(pdu_list, 0, sizeof(pdu_list));
    num_pdu_elements = 0;

    // Create a semaphore for protecting access to the list
    sem = sem_open("pdu_sem", O_CREAT | O_EXCL, 0644, 1);
}

// Add a new PDU element to the list
void pdu_list_add(uint32_t rnti, void *pdu) {
    // Acquire the semaphore to protect access to the list
    if (sem_wait(sem)) {
        perror("Error waiting for semaphore");
        return;
    }

    // Check if there is space in the list for a new element
    if (num_pdu_elements >= 1024) {
        printf("Maximum capacity of PDU list reached\n");
        goto done;
    }

    // Add the new element to the list
    pdu_element_t *new_element = &(pdu_list[num_pdu_elements++]);
    new_element->rnti = rnti;
    new_element->pdu = pdu;

done:
    // Release the semaphore and return
    if (sem_post(sem)) {
        perror("Error posting semaphore");
    }
}

// Remove a PDU element from the list
void pdu_list_remove(uint32_t rnti) {
    // Acquire the semaphore to protect access to the list
    if (sem_wait(sem)) {
        perror("Error waiting for semaphore");
        return;
    }

    // Find the element with the specified RNTI value in the list
    size_t i = 0;
    while (i < num_pdu_elements) {
        if (pdu_list[i].rnti == rnti) {
            break;
        }
        i++;
    }

    // Check if the element was found in the list
    if (i >= num_pdu_elements) {
        printf("PDU with RNTI value %u not found\n", rnti);
        goto done;
    }

    // Remove the element from the list by shifting all subsequent elements back one position
    for (size_t j = i + 1; j < num_pdu_elements; j++) {
        pdu_list[j - 1] = pdu_list[j];
    }
    num_pdu_elements--;

done:
    // Release the semaphore and return
    if (sem_post(sem)) {
        perror("Error posting semaphore");
    }
}

