// Structure to represent an LTE UE Context
struct lte_ue_context {
    int ue_id;
    struct rrc_connection_info *rrc_info;
    struct radio_bearer_context *rb_contexts;
};

// Function to create and populate a list of LTE UE Context structures
struct lte_ue_context *create_lte_ue_contexts(int num_ues) {
    // Allocate memory for the list of LTE UE Context structures
    struct lte_ue_context *ue_contexts = malloc(num_ues * sizeof(struct lte_ue_context));
    if (!ue_contexts) {
        fprintf(stderr, "Failed to allocate memory for LTE UE Context list\n");
        return NULL;
    }

    // Initialize the list of LTE UE Context structures
    for (int i = 0; i < num_ues; i++) {
        ue_contexts[i].ue_id = -1;
        ue_contexts[i].rrc_info = NULL;
        ue_contexts[i].rb_contexts = NULL;
    }

    // Populate the list of LTE UE Context structures with valid data
    for (int i = 0; i < num_ues; i++) {
        // Acquire a lock to ensure thread-safe access to the list
        pthread_mutex_lock(&ue_contexts_lock);

        // Check if the UE ID is already present in the list
        for (int j = 0; j < num_ues; j++) {
            if (ue_contexts[j].ue_id == i) {
                fprintf(stderr, "Duplicate UE ID %d detected\n", i);
                pthread_mutex_unlock(&ue_contexts_lock);
                return NULL;
            }
        }

        // Allocate memory for the RRC Connection Information structure
        ue_contexts[i].rrc_info = malloc(sizeof(struct rrc_connection_info));
        if (!ue_contexts[i].rrc_info) {
            fprintf(stderr, "Failed to allocate memory for RRC Connection Information\n");
            pthread_mutex_unlock(&ue_contexts_lock);
            return NULL;
        }

        // Initialize the RRC Connection Information structure
        ue_contexts[i].rrc_info->cell_id = 0;
        ue_contexts[i].rrc_info->plmn_id = 0;
        ue_contexts[i].rrc_info->rsrq = 0.0;
        ue_contexts[i].rrc_info->rsrp = 0.0;
        ue_contexts[i].rrc_info->rssi = 0.0;
        ue_contexts[i].rrc_info->sinr = 0.0;

        // Allocate memory for the List of Radio Bearer Contexts structure
        ue_contexts[i].rb_contexts = malloc(sizeof(struct radio_bearer_context));
        if (!ue_contexts[i].rb_contexts) {
            fprintf(stderr, "Failed to allocate memory for List of Radio Bearer Contexts\n");
            pthread_mutex_unlock(&ue_contexts_lock);
            return NULL;
        }

        // Initialize the List of Radio Bearer Contexts structure
        ue_contexts[i].rb_contexts->num_bearers = 0;
        ue_contexts[i].rb_contexts->bearer_ids = malloc(sizeof(int) * ue_contexts[i].rb_contexts->num_bearers);
        if (!ue_contexts[i].rb_contexts->bearer_ids) {
            fprintf(stderr, "Failed to allocate memory for Bearer IDs\n");
            pthread_mutex_unlock(&ue_contexts_lock);
            return NULL;
        }

        // Fill in the List of Radio Bearer Contexts structure with valid data
        ue_contexts[i].rb_contexts->num_bearers = 3;
        for (int j = 0; j < ue_contexts[i].rb_contexts->num_bearers; j++) {
            ue_contexts[i].rb_contexts->bearer_ids[j] = j + 1;
        }

        // Set the UE ID and RRC Connection Information in the LTE UE Context structure
        ue_contexts[i].ue_id = i;
        ue_contexts[i].rrc_info->cell_id = i + 1;
        ue_contexts[i].rrc_info->plmn_id = i + 1;
        ue_contexts[i].rrc_info->rsrq = (double) (i + 1) / 10.0;
        ue_contexts[i].rrc_info->rsrp = (double) (i + 1) / 10.0;
        ue_contexts[i].rrc_info->rssi = (double) (i + 1) / 10.0;
        ue_contexts[i].rrc_info->sinr = (double) (i + 1) / 10.0;

        // Release the lock to allow other threads to access the list
        pthread_mutex_unlock(&ue_contexts_lock);
    }

    return ue_contexts;
}

// Function to update a LTE UE Context structure with new RRC Connection Information and Radio Bearer Contexts
int update_lte_ue_context(struct lte_ue_context *ue_context, struct rrc_connection_info *rrc_info, struct radio_bearer_context *rb_contexts) {
    // Acquire a lock to ensure thread-safe access to the LTE UE Context structure
    pthread_mutex_lock(&ue_context->lock);

    // Update the RRC Connection Information in the LTE UE Context structure
    ue_context->rrc_info = rrc_info;
    ue_context->rb_contexts = rb_contexts;

    // Release the lock to allow other threads to access the LTE UE Context structure
    pthread_mutex_unlock(&ue_context->lock);
}

// Function to delete a LTE UE Context structure from the list
void delete_lte_ue_context(struct lte_ue_context *ue_context) {
    // Acquire a lock to ensure thread-safe access to the list of LTE UE Context structures
    pthread_mutex_lock(&ue_contexts_lock);

    // Find the index of the LTE UE Context structure in the list
    int i;
    for (i = 0; i < num_ues; i++) {
        if (ue_contexts[i].ue_id == ue_context->ue_id) {
            break;
        }
    }

    // Check if the LTE UE Context structure was found in the list
    if (i >= num_ues) {
        fprintf(stderr, "LTE UE Context structure with UE ID %d not found\n", ue_context->ue_id);
        pthread_mutex_unlock(&ue_contexts_lock);
        return;
    }

    // Delete the LTE UE Context structure from the list
    for (int j = i + 1; j < num_ues; j++) {
        ue_contexts[j - 1] = ue_contexts[j];
    }
    num_ues--;

    // Release the lock to allow other threads to access the list of LTE UE Context structures
    pthread_mutex_unlock(&ue_contexts_lock);
}
