void* enableAes256cbcCipher(char* password) {
    // Set the IV length to 16 bytes
    int iv_len = 16;

    // Set the key length to 32 bytes
    int key_len = 32;

    // Derive the encryption key from the password using a secure but efficient hashing algorithm (e.g., SHA-256)
    uint8_t* encryption_key = (uint8_t*)malloc(sizeof(uint8_t) * key_len);
    if (!encryption_key) {
        printf("Failed to allocate memory for encryption key\n");
        return NULL;
    }

    // Generate the encryption key from the password using SHA-256
    SHA256(password, strlen(password), encryption_key);

    // Initialize an AES-256-CBC cipher with the derived encryption key
