// Recursive traversal function in JavaScript to traverse a DOM tree and return a list of elements that match a given selector, using a provided function to test the element's class or ID.
function getElementsBySelector(selector, callback) {
    var elementList = [];

    // Helper function to traverse the DOM tree recursively
    function traverseDOMTree(node) {
        if (node == null) {
            return;
        }

        // Test the current node against the given selector and add it to the list if it matches
        var classID = node.className + "|" + node.id;
        if (selector === classID || selector === "*") {
            elementList.push(node);
        }

        // Recursively traverse the current node's children
        for (var i = 0; i < node.childNodes.length; i++) {
            traverseDOMTree(node.childNodes[i]);
        }
    }

    // Call the recursive traversal function on the document element
    traverseDOMTree(document.documentElement);

    return elementList;
}

// Example usage: getElementsBySelector("*", function(element) { console.log(element.tagName); }); // Returns all elements in the page, printing their tag names

// Optimized version of getElementsBySelector() that uses a single function to test the element's class or ID against the selector and avoids repeatedly calling external functions for each element.
function optimizedGetElementsBySelector(selector, callback) {
    var elementList = [];

    // Helper function to traverse the DOM tree recursively and test elements against the given selector
    function traverseDOMTree(node) {
        if (node == null) {
            return;
        }

        // Test the current node against the given selector and add it to the list if it matches
        var classID = node.className + "|" + node.id;
        if ((selector === "*") || (classID === selector)) {
            elementList.push(node);
        }

        // Recursively traverse the current node's children
        for (var i = 0; i < node.childNodes.length; i++) {
            traverseDOMTree(node.childNodes[i]);
        }
    }

    // Call the recursive traversal function on the document element
    traverseDOMTree(document.documentElement);

    return elementList;
}

// Example usage: optimizedGetElementsBySelector("*", function(element) { console.log(element.tagName); }); // Returns all elements in the page, printing their tag names

// Thread-safe version of create_nfapi_crc_indication_pdu_list() that ensures that the function is called concurrently from multiple threads without causing excessive memory usage or performance issues.
NFAPI_CRC_INDICATION_PDU_T *create_thread_safe_nfapi_crc_indication_pdu_list(int num_elements) {
    // Allocate a lock for the function to ensure that only one thread can access it at a time.
    pthread_mutex_t *lock = malloc(sizeof(pthread_mutex_t));
    if (lock == NULL) {
        return NULL;
    }

    // Initialize the lock and set it as recursive to allow nested calls from multiple threads without causing deadlocks.
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(lock, &attr);
    pthread_mutexattr_destroy(&attr);

    // Call the function that creates and populates the list of NFAPI_CRC_INDICATION_PDU_T structures with the lock held.
    pthread_mutex_lock(lock);
    NFAPI_CRC_INDICATION_PDU_T *list = create_nfapi_crc_indication_pdu_list(num_elements);
    pthread_mutex_unlock(lock);

    // Free the lock and return the list.
    free(lock);
    return list;
}

