    }
}

// Function to create and populate the NFAPI_CRC_INDICATION_PDU_T structure list
void initAndPopulateNFAPICrcIndicationPduList(struct NFAPI_CRC_INDICATION_PDU_T *nfapiCrcIndicationPduList, int numUEs) {
    // Initialize the RX_UE_INFORMATION_TAG for each structure
    for (int i = 0; i < numUEs; i++) {
        nfapiCrcIndicationPduList[i].RX_UE_INFORMATION_TAG = i + 1;
    }

