        nfapiCrcIndicationPduList[i].RNTI = rand() % 10000 + 1;
        nfapiCrcIndicationPduList[i].CRCFLAG = (rand() % 2 == 0);
    }
}

// Function to randomly select a subset of UE contexts based on the given probability threshold and maximum number of concurrent users
void randomSelectUEContexts(struct UEContext *ueContextList, int numUEs, float probabilityThreshold, int maxConcurrentUsers) {
    // Create a temporary list to store the selected UE contexts
    struct UEContext *selectedUeContextList = malloc(maxConcurrentUsers * sizeof(struct UEContext));
    memset(selectedUeContextList, 0, maxConcurrentUsers * sizeof(struct UEContext));

    // Iterate through the UE context list and select a random subset of contexts based on the given probability threshold
    int selectedUECount = 0;
    for (int i = 0; i < numUEs && selectedUECount < maxConcurrentUsers; i++) {
        float randomValue = ((float)rand() / (float)RAND_MAX); // Generate a random value between [0, 1]
        if (randomValue <= probabilityThreshold) {
            // Add the current UE context to the selected list
            memcpy(&selectedUeContextList[selectedUECount], &ueContextList[i], sizeof(struct UEContext));
            selectedUECount++;
        }
    }

    // Update the selected UE context list size and return it
    free(ueContextList);
    ueContextList = selectedUeContextList;
}

// Function to handle dynamic data updates from external sources, integrate user information into the list, and update the selection of UE contexts based on the given probability threshold
void updateUEContextList(struct UEContext *ueContextList, int numUEs, float probabilityThreshold, int maxConcurrentUsers) {
    // Update the UE context list with new user information from external sources
    for (int i = 0; i < numUEs; i++) {
        // Check if the current UE has valid user information and update it in the list accordingly
        if (ueContextList[i].UEIdentifier != 0 && ueContextList[i].RNTI != 0) {
            memcpy(&ueContextList[i], &ueContextList[i], sizeof(struct UEContext));
        } else {
            // If the current UE does not have valid user information, set its CQI to a negative value to indicate that it should be removed from the list
            ueContextList[i].CQI = -1;
        }
    }

    // Remove all invalid or inactive UE contexts from the list
    for (int i = 0; i < numUEs; i++) {
        if (ueContextList[i].CQI < 0) {
            memset(&ueContextList[i], 0, sizeof(struct UEContext));
        }
    }

    // Randomly select a subset of UE contexts based on the given probability threshold and maximum number of concurrent users
    randomSelectUEContexts(ueContextList, numUEs, probabilityThreshold, maxConcurrentUsers);
}

