// Structure to represent a LTE MAC PDU
struct mac_pdu {
    int lcid;
    char *payload;
};

// Function to generate a randomized payload size between 100 and 1000 bytes
int generate_random_payload_size() {
    return (rand() % 900) + 100;
}

// Function to create and populate a list of LTE MAC PDUs
struct mac_pdu *create_mac_pdus(int num_pdus, char *json_config_file) {
    struct mac_pdu *mac_pdus = NULL;
    json_object *config = NULL;
    json_object *payload_config = NULL;
    int i;

    // Read initial configuration data from JSON file
    config = json_object_from_file(json_config_file);
    if (config == NULL) {
        fprintf(stderr, "Failed to read JSON configuration file\n");
        return NULL;
    }

    // Get the payload configuration data from the JSON object
    payload_config = json_object_get_object(config, "payload_sizes");
    if (payload_config == NULL) {
        fprintf(stderr, "Failed to get payload sizes from JSON configuration\n");
        return NULL;
    }

    // Allocate memory for the list of MAC PDUs
    mac_pdus = malloc(sizeof(struct mac_pdu) * num_pdus);
    if (mac_pdus == NULL) {
        fprintf(stderr, "Failed to allocate memory for MAC PDUS\n");
        return NULL;
    }

    // Loop through the payload configuration data and generate randomized payloads
    for (i = 0; i < num_pdus; i++) {
        int payload_size = generate_random_payload_size();
        char *payload = malloc(payload_size);
        if (payload == NULL) {
            fprintf(stderr, "Failed to allocate memory for MAC PDU payload\n");
            return NULL;
        }
        memset(payload, 'x', payload_size);
        mac_pdus[i].lcid = json_object_get_int(payload_config, "lcids") + i;
        mac_pdus[i].payload = payload;
    }

    // Free the JSON object and return the list of MAC PDUs
    json_object_put(config);
    return mac_pdus;
}
