NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int num_ues, int crc_flag) {
    // Validate input parameters
    if (num_ues < 0 || crc_flag < 0 || crc_flag > 3) {
        return NULL;
    }

    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*) malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        return NULL;
    }

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < num_ues; i++) {
        pdu_list[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG(i + 1);
        pdu_list[i].rnti = RNTI(i + 1);
        pdu_list[i].crc_indication_rel8_tag.crfla = crc_flag;
    }

    // Log the creation of each NFAPI_CRC_INDICATION_PDU_T structure
    for (int i = 0; i < num_ues; i++) {
        printf("Created CRC indication PDU %d with RX UE information tag %d and RNTI %d\n", i + 1, pdu_list[i].rx_ue_information_tag, pdu_list[i].rnti);
