    return pdu_list;
}

// Define the function to handle concurrent access from multiple threads safely
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_threadsafe(int num_ues, int crc_flag) {
    // Allocate memory for a mutex to protect the function
    pthread_mutex_t* mutex = (pthread_mutex_t*) malloc(sizeof(pthread_mutex_t));
    if (!mutex) {
        return NULL;
    }

    // Initialize the mutex
    int ret = pthread_mutex_init(mutex, NULL);
    if (ret != 0) {
        free(mutex);
        return NULL;
    }

    // Lock the mutex before calling the create_crc_indication_pdu function
    ret = pthread_mutex_lock(mutex);
    if (ret != 0) {
        pthread_mutex_destroy(mutex);
        free(mutex);
        return NULL;
    }

    // Call the create_crc_indication_pdu function with the mutex locked
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = create_crc_indication_pdu(num_ues, crc_flag);

    // Unlock the mutex and free it
    ret = pthread_mutex_unlock(mutex);
    if (ret != 0) {
        pthread_mutex_destroy(mutex);
        free(mutex);
        return NULL;
    }
    pthread_mutex_destroy(mutex);
    free(mutex);

    return pdu_list;
}

