// Define structure for LTE PHY UE measurements
typedef struct {
    int UE_ID;
    int CELL_ID;
    MEASUREMENT_TAG measurement_tags[MAX_MEASUREMENTS];
} LTE_PHY_UE_MEASUREMENTS_T;

// Define structure for measurement tags
typedef struct {
    float signal_strength;
    int quality_indicator;
} MEASUREMENT_TAG;

// Function to create and populate list of LTE PHY UE measurements
LTE_PHY_UE_MEASUREMENTS_T* create_ue_measurements(const char* config_file, int max_measurements) {
    // Load configuration file into JSON object
    json_object* config = json_object_from_file(config_file);
    if (!config) {
        printf("Error loading configuration file\n");
        return NULL;
    }

    // Validate configuration data
    if (json_object_get_int(config, "max_measurements") > max_measurements) {
        printf("Invalid maximum number of measurements per UE in configuration file\n");
        json_object_put(config);
        return NULL;
    }

    // Allocate memory for LTE PHY UE measurements list
    int num_ues = json_object_array_length(config);
    LTE_PHY_UE_MEASUREMENTS_T* ue_measurements = (LTE_PHY_UE_MEASUREMENTS_T*)malloc(num_ues * sizeof(LTE_PHY_UE_MEASUREMENTS_T));
    if (!ue_measurements) {
        printf("Error allocating memory for LTE PHY UE measurements\n");
        json_object_put(config);
        return NULL;
    }

    // Populate list of LTE PHY UE measurements
    int i, j;
    for (i = 0; i < num_ues; i++) {
        json_object* ue_obj = json_object_array_get_idx(config, i);
        if (!ue_obj) {
            printf("Error retrieving UE %d from configuration file\n", i);
            continue;
        }

        // Retrieve UE ID and cell ID from JSON object
        int ue_id = json_object_get_int(ue_obj, "UE_ID");
        int cell_id = json_object_get_int(ue_obj, "CELL_ID");

        // Initialize measurement tags for current UE
        MEASUREMENT_TAG* measurement_tags = (MEASUREMENT_TAG*)malloc(max_measurements * sizeof(MEASUREMENT_TAG));
        if (!measurement_tags) {
            printf("Error allocating memory for measurement tags for UE %d\n", ue_id);
            continue;
        }

        // Populate measurement tags with random values
        int num_measurements = json_object_array_length(ue_obj);
        if (num_measurements > max_measurements) {
            printf("Invalid number of measurements for UE %d in configuration file\n", ue_id);
            continue;
        }

        for (j = 0; j < num_measurements; j++) {
            json_object* measurement_obj = json_object_array_get_idx(ue_obj, j);
            if (!measurement_obj) {
                printf("Error retrieving measurement %d from configuration file for UE %d\n", j, ue_id);
                continue;
            }

            // Retrieve signal strength and quality indicator from JSON object
            float signal_strength = json_object_get_float(measurement_obj, "signal_strength");
            int quality_indicator = json_object_get_int(measurement_obj, "quality_indicator");

            // Store measurement tag in list for current UE
            measurement_tags[j].signal_strength = signal_strength;
            measurement_tags[j].quality_indicator = quality_indicator;
        }

        // Initialize LTE PHY UE measurements structure for current UE
        ue_measurements[i].UE_ID = ue_id;
        ue_measurements[i].CELL_ID = cell_id;
        ue_measurements[i].num_measurement_tags = num_measurements;
        memcpy(ue_measurements[i].measurement_tags, measurement_tags, num_measurements * sizeof(MEASUREMENT_TAG));
    }

    // Clean up JSON object and return list of LTE PHY UE measurements
    json_object_put(config);
    return ue_measurements;
}
