        (*list)[i].crc_indication_rel8.crcFlag = (i % 2 == 0) ? 1 : 0; // set CRCFLAG to 1 for every second structure
    }

    // validate unique RX_UE_INFORMATION_TAG and RNTI values
    bool duplicate = false;
    for (int i = 0; i < max_list_size - 1; i++) {
        if ((*list)[i].rx_ue_information_tag == (*list)[i + 1].rx_ue_information_tag ||
            (*list)[i].rnti == (*list)[i + 1].rnti) {
            duplicate = true;
            break;
        }
    }

    // handle duplicates gracefully
    if (duplicate) {
        for (int i = 0; i < max_list_size - 1; i++) {
            if ((*list)[i].rx_ue_information_tag == (*list)[i + 1].rx_ue_information_tag ||
                (*list)[i].rnti == (*list)[i + 1].rnti) {
                // mark duplicate values as invalid
                (*list)[i].rx_ue_information_tag = -1;
                (*list)[i].rnti = -1;
            }
        }
    }

    return 0;
}

