#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_CRC_INDICATIONS 100000 // maximum number of CRC indications to handle
#define MAX_RX_UE_INFO_TAGS 500 // maximum number of RX UE information tags to handle

typedef struct {
    uint8_t tag;
    uint32_t rnti;
    uint16_t crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// thread-safe list structure for storing CRC indications
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* items[MAX_CRC_INDICATIONS];
} NFAPI_CRC_INDICATION_LIST_T;

// mutex for protecting concurrent access to the list
pthread_mutex_t crc_indication_list_mutex = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_LIST_T* create_crc_indication_list() {
    NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (list == NULL) {
        printf("Error: failed to allocate memory for CRC indication list\n");
        return NULL;
    }
    list->size = 0;
    list->capacity = MAX_CRC_INDICATIONS;
    list->items[MAX_CRC_INDICATIONS] = calloc(sizeof(NFAPI_CRC_INDICATION_PDU_T), MAX_CRC_INDICATIONS);
    if (list->items == NULL) {
        printf("Error: failed to allocate memory for CRC indication items\n");
        free(list);
        return NULL;
    }
    return list;
}

void destroy_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (list == NULL) {
        return;
    }
    free(list->items);
    free(list);
}

int populate_crc_indication_list(NFAPI_CRC_INDICATION_LIST_T* list, int num_rx_ue_info_tags) {
    // ensure that the list has enough capacity to hold all RX UE information tags
    if (list->capacity < num_rx_ue_info_tags) {
        printf("Error: CRC indication list capacity insufficient for %d RX UE information tags\n", num_rx_ue_info_tags);
        return -1;
    }
    // populate the list with random CRC indications
    for (int i = 0; i < num_rx_ue_info_tags; i++) {
        NFAPI_CRC_INDICATION_PDU_T* item = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (item == NULL) {
            printf("Error: failed to allocate memory for CRC indication item\n");
            destroy_crc_indication_list(list);
            return -1;
        }
        // set a random RX UE information tag and RNTI
        int rx_ue_info_tag = rand() % MAX_RX_UE_INFO_TAGS + 1;
        item->tag = rx_ue_info_tag;
        item->rnti = rand() % MAX_RNTI + 1;
        // set a random CRC indication REL8 tag with a CRCFLAG of 1 for every second structure in the list
        if (i % 2 == 0) {
            item->crc_indication_rel8 = rand() % MAX_CRC_INDICATION_REL8 + 1;
        } else {
            item->crc_indication_rel8 = rand() % MAX_CRC_INDICATION_REL8 + 1;
            item->crc_indication_rel8 |= (1 << CRCFLAG);
        }
        // add the item to the list
        pthread_mutex_lock(&crc_indication_list_mutex);
        if (list->size >= MAX_CRC_INDICATIONS) {
            printf("Error: CRC indication list overflow\n");
            pthread_mutex_unlock(&crc_indication_list_mutex);
            free(item);
            return -1;
        }
        list->items[list->size++] = item;
        pthread_mutex_unlock(&crc_indication_list_mutex);
    }
    return 0;
}

int validate_crc_indications(NFAPI_CRC_INDICATION_LIST_T* list) {
    // validate that each RX UE information tag and RNTI are unique within the list
    for (int i = 0; i < list->size - 1; i++) {
        NFAPI_CRC_INDICATION_PDU_T* item = list->items[i];
        for (int j = i + 1; j < list->size; j++) {
            NFAPI_CRC_INDICATION_PDU_T* other_item = list->items[j];
            if (item->tag == other_item->tag && item->rnti == other_item->rnti) {
                printf("Error: duplicate RX UE information tag %d and RNTI %u found in CRC indication list\n", item->tag, item->rnti);
                return -1;
            }
        }
    }
    return 0;
}

// integrate with an external data source to populate RX UE information tags based on real-time data feeds
int populate_rx_ue_info_tags(NFAPI_CRC_INDICATION_LIST_T* list, int num_rx_ue_info_tags) {
    // read the next num_rx_ue_info_tags RX UE information tags from the external data source
    int ret = integrate_with_data_source(num_rx_ue_info_tags);
    if (ret < 0) {
        printf("Error: failed to retrieve %d RX UE information tags from data source\n", num_rx_ue_info_tags);
        return -1;
    }
    // populate the CRC indication list with the retrieved RX UE information tags
    ret = populate_crc_indication_list(list, num_rx_ue_info_tags);
    if (ret < 0) {
        printf("Error: failed to populate CRC indication list with %d RX UE information tags\n", num_rx_ue_info_tags);
        return -1;
    }
    return 0;
}

// support different external data sources with varying update frequencies
int integrate_with_data_source(int num_rx_ue_info_tags) {
    // handle intermittent connectivity issues by retrying failed operations
    while (true) {
        int ret = read_rx_ue_info_tags(num_rx_ue_info_tags);
        if (ret == -1) {
            printf("Warning: failed to retrieve RX UE information tags from data source, retrying in 5 seconds\n");
