        }
    }
}

// read the next num_rx_ue_info_tags RX UE information tags from the external data source
int read_rx_ue_info_tags(int num_rx_ue_info_tags) {
    // handle duplicate tags occasionally by skipping duplicates or marking them as invalid
    int ret = read_rx_ue_info_tags_from_data_source(num_rx_ue_info_tags);
    if (ret < 0) {
