        return -1;
    }
    // validate that each RX UE information tag is unique within the list
    ret = validate_crc_indications(list);
    if (ret < 0) {
        printf("Error: failed to validate CRC indication list with %d RX UE information tags\n", num_rx_ue_info_tags);
        return -1;
    }
    return 0;
}

// read the next num_rx_ue_info_tags RX UE information tags from the external data source and populate the CRC indication list
int read_rx_ue_info_tags_from_data_source(int num_rx_ue_info_tags) {
    // handle duplicate tags occasionally by skipping duplicates or marking them as invalid
    for (int i = 0; i < num_rx_ue_info_tags; i++) {
        int rx_ue_info_tag = read_next_rx_ue_info_tag_from_data_source();
        if (rx_ue_info_tag == -1) {
            printf("Error: failed to retrieve RX UE information tag %d from data source\n", i);
            return -1;
        }
        // validate that each RX UE information tag is unique within the list
        for (int j = 0; j < i; j++) {
            if (rx_ue_info_tag == read_next_rx_ue_info_tag_from_data_source()) {
                printf("Warning: duplicate RX UE information tag %d found in data source, skipping\n", rx_ue_info_tag);
                i++;
            }
        }
    }
    return 0;
}

// read the next RX UE information tag from the external data source and validate it is unique within the list
int read_next_rx_ue_info_tag_from_data_source() {
    // handle duplicate tags occasionally by skipping duplicates or marking them as invalid
    int rx_ue_info_tag = rand() % MAX_RX_UE_INFO_TAGS + 1;
    for (int i = 0; i < list->size; i++) {
        if (rx_ue_info_tag == list->items[i]->tag) {
            printf("Warning: duplicate RX UE information tag %d found in data source, skipping\n", rx_ue_info_tag);
            return -1;
        }
    }
    return rx_ue_info_tag;
}
