// Define the maximum number of CRC indications that can be stored in the list
#define MAX_CRC_INDICATIONS 1024

// Define the maximum number of threads that can concurrently access the list
#define MAX_THREADS 32

// Structure to represent a CRC indication
typedef struct {
    uint64_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// List to store the CRC indications
static NFAPI_CRC_INDICATION_PDU_T* crc_indications = NULL;

// Variable to track the total number of CRC indications generated by the function
static uint64_t num_crc_indications = 0;

// Mutex for protecting concurrent access to the list from multiple threads
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to create and populate a new CRC indication structure
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication(uint64_t rx_ue_information_tag, uint16_t rnti) {
    // Allocate memory for the new structure
    NFAPI_CRC_INDICATION_PDU_T* crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indication == NULL) {
        return NULL;
    }

    // Set the RX_UE_INFORMATION_TAG and RNTI values
    crc_indication->rx_ue_information_tag = rx_ue_information_tag;
    crc_indication->rnti = rnti;

    // Generate a random CRCFLAG value for the CRC indication
    crc_indication->crc_indication_rel8_tag = rand() % 256;

    return crc_indication;
}

// Function to add a new CRC indication to the list
bool add_crc_indication(uint64_t rx_ue_information_tag, uint16_t rnti) {
    // Lock the mutex to protect concurrent access to the list from multiple threads
    pthread_mutex_lock(&mutex);

    // Check if the list has reached its maximum size and needs to be resized
    if (crc_indications == NULL || num_crc_indications >= MAX_CRC_INDICATIONS) {
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(crc_indications, (MAX_CRC_INDICATIONS + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            // Release the mutex and return false on failure to resize the list
            pthread_mutex_unlock(&mutex);
            return false;
        }
        crc_indications = new_list;
    }

    // Create a new CRC indication structure and add it to the list
    NFAPI_CRC_INDICATION_PDU_T* crc_indication = create_crc_indication(rx_ue_information_tag, rnti);
    if (crc_indication == NULL) {
        // Release the mutex and return false on failure to create a new CRC indication structure
        pthread_mutex_unlock(&mutex);
        return false;
    }
    crc_indications[num_crc_indications++] = *crc_indication;

    // Release the mutex and return true on success
    pthread_mutex_unlock(&mutex);
    return true;
}

// Function to validate that the RX_UE_INFORMATION_TAG and RNTI values are unique within the list
bool validate_crc_indication(uint64_t rx_ue_information_tag, uint16_t rnti) {
    // Lock the mutex to protect concurrent access to the list from multiple threads
    pthread_mutex_lock(&mutex);

    // Check if the RX_UE_INFORMATION_TAG and RNTI values are already present in the list
    for (int i = 0; i < num_crc_indications; i++) {
        if (crc_indications[i].rx_ue_information_tag == rx_ue_information_tag && crc_indications[i].rnti == rnti) {
            // Release the mutex and return false if a duplicate CRC indication is found
            pthread_mutex_unlock(&mutex);
            return false;
        }
    }

    // Release the mutex and return true if no duplicates are found
    pthread_mutex_unlock(&mutex);
    return true;
}

// Function to handle rate limiting for adding new CRC indications to prevent abuse or excessive load on the system
bool add_crc_indication_rate_limited(uint64_t rx_ue_information_tag, uint16_t rnti) {
    // Lock the mutex to protect concurrent access to the list from multiple threads
    pthread_mutex_lock(&mutex);

    // Check if rate limiting is enabled and the number of CRC indications generated exceeds the rate limit
    if (enable_rate_limiting && num_crc_indications >= rate_limit) {
        // Release the mutex and return false if rate limiting is enabled and the number of CRC indications exceeds the rate limit
        pthread_mutex_unlock(&mutex);
        return false;
    }

    // Create a new CRC indication structure and add it to the list
    NFAPI_CRC_INDICATION_PDU_T* crc_indication = create_crc_indication(rx_ue_information_tag, rnti);
    if (crc_indication == NULL) {
        // Release the mutex and return false on failure to create a new CRC indication structure
        pthread_mutex_unlock(&mutex);
        return false;
    }
    crc_indications[num_crc_indications++] = *crc_indication;

    // Release the mutex and return true on success
    pthread_mutex_unlock(&mutex);
    return true;
}

// Function to handle external database persistence for CRC indications data
bool persist_crc_indications(void) {
    // Lock the mutex to protect concurrent access to the list from multiple threads
    pthread_mutex_lock(&mutex);

    // Iterate over the CRC indications list and persist each structure in the external database
    for (int i = 0; i < num_crc_indications; i++) {
        NFAPI_CRC_INDICATION_PDU_T* crc_indication = &crc_indications[i];
        if (!persist_crc_indication(crc_indication)) {
            // Release the mutex and return false on failure to persist a CRC indication structure in the external database
            pthread_mutex_unlock(&mutex);
            return false;
        }
    }

    // Release the mutex and return true on success
    pthread_mutex_unlock(&mutex);
    return true;
}
