// Define a structure to represent a TCP segment
struct tcp_segment {
    uint32_t seq_num;
    size_t payload_size;
    char* payload;
};

// Generate a random integer between min and max, inclusive
int generate_random_number(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Create and populate a list of TCP segments
struct tcp_segment* create_tcp_segments(size_t num_segments) {
    // Allocate memory for the list of segments
    struct tcp_segment* segments = malloc(num_segments * sizeof(struct tcp_segment));
    if (segments == NULL) {
        fprintf(stderr, "Failed to allocate memory for TCP segments\n");
        return NULL;
    }

    // Initialize the sequence number and payload size for each segment
    size_t i;
    for (i = 0; i < num_segments; ++i) {
        segments[i].seq_num = generate_random_number(1, 65535);
        segments[i].payload_size = generate_random_number(100, 1000);

        // Allocate memory for the payload
        segments[i].payload = malloc(segments[i].payload_size * sizeof(char));
        if (segments[i].payload == NULL) {
            fprintf(stderr, "Failed to allocate memory for TCP segment payload\n");
            return NULL;
        }
    }

    // Generate random payload data for each segment
    for (i = 0; i < num_segments; ++i) {
        int j;
        for (j = 0; j < segments[i].payload_size; ++j) {
            segments[i].payload[j] = generate_random_number(0, 255);
        }
    }

    return segments;
}

// Free the memory allocated for a list of TCP segments
void free_tcp_segments(struct tcp_segment* segments) {
    if (segments == NULL) {
        return;
    }

    size_t i;
    for (i = 0; i < num_segments; ++i) {
        if (segments[i].payload != NULL) {
            free(segments[i].payload);
        }
    }

    free(segments);
}
