    nfapi_crc_indication_pdu_t* temp = realloc(pdu_list, n * sizeof(nfapi_crc_indication_pdu_t));
    if (!temp) {
        // If the reallocation fails, free the memory allocated for the original list of NFAPI_CRC_INDICATION_PDU_T structures and return NULL
        free_memory(pdu_list);
        return NULL;
    }
    pdu_list = temp;
