lte_ue_context *create_ue_contexts(int num_uces, int num_cells) {
    // Dynamically allocate memory for the list of UE contexts
    lte_ue_context *ue_contexts = malloc(num_uces * sizeof(lte_ue_context));
    if (ue_contexts == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for UE contexts\n");
        return NULL;
    }

    // Populate the list of UE contexts with random signal strength values
    for (int i = 0; i < num_uces; i++) {
        ue_contexts[i].ue_id = i + 1;
        ue_contexts[i].cell_id = rand() % num_cells + 1;
        ue_contexts[i].signal_strength = rand() / (float)RAND_MAX * 50 - 25;
    }

    return ue_contexts;
}

// Function to free the memory allocated for the list of LTE UE context structures
void free_ue_contexts(lte_ue_context **ue_contexts) {
    // Check if the input pointer is null or not
    if (ue_contexts != NULL && *ue_contexts != NULL) {
        // Free the memory allocated for the list of UE contexts
        free(*ue_contexts);
        *ue_contexts = NULL;
    }
}
