['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <limits.h>

// Define the structure to hold UE context information
typedef struct {
    int ue_id; // Unique identifier for each UE
    int cell_id; // Cell ID where the UE is attached
    double signal_strength; // Signal strength of the UE
} ue_context_t;

// Define a list to store all UE contexts
typedef struct {
    int count; // Number of elements in the list
    ue_context_t* contexts; // Array of UE context structures
} ue_context_list_t;

// Function to create and populate a new list of UE contexts
ue_context_list_t* create_ue_context_list() {
    ue_context_list_t* list = malloc(sizeof(ue_context_list_t));
    if (list == NULL) {
        // Handle memory allocation failure gracefully
        printf("Error: Unable to allocate memory for UE context list\n");
        return NULL;
    }

    // Initialize the count and contexts pointers
    list->count = 0;
    list->contexts = NULL;

    return list;
}

// Function to add a new UE context to the list
int add_ue_context(ue_context_list_t* list, int ue_id, int cell_id) {
    // Check if the list is empty
    if (list->count == 0) {
        // Allocate memory for the first context structure
        list->contexts = malloc(sizeof(ue_context_t));
        if (list->contexts == NULL) {
            // Handle memory allocation failure gracefully
            printf("Error: Unable to allocate memory for UE context %d\n", ue_id);
            return -1;
        }
    } else {
        // Reallocate memory for the next context structure
        list->contexts = realloc(list->contexts, (list->count + 1) * sizeof(ue_context_t));
        if (list->contexts == NULL) {
            // Handle memory allocation failure gracefully
            printf("Error: Unable to allocate memory for UE context %d\n", ue_id);
            return -1;
        }
    }

    // Set the new context values and increment the count
    list->contexts[list->count].ue_id = ue_id;
    list->contexts[list->count].cell_id = cell_id;
    list->contexts[list->count].signal_strength = generate_random_signal_strength();
    list->count++;

    return 0;
}

// Function to remove a UE context from the list based on its ID
int remove_ue_context(ue_context_list_t* list, int ue_id) {
    // Find the index of the context with the specified ID
    int i = find_ue_context_index(list, ue_id);
    if (i == -1) {
        return -1;
    }

    // Shift all subsequent contexts to fill the gap left by the removed one
    for (int j = i + 1; j < list->count; j++) {
        list->contexts[j - 1] = list->contexts[j];
    }

    // Decrement the count and reallocate memory if necessary
    list->count--;
    if (list->count == 0) {
        free(list->contexts);
        list->contexts = NULL;
    } else {
        list->contexts = realloc(list->contexts, list->count * sizeof(ue_context_t));
    }

    return 0;
}

// Function to retrieve a UE context from the list based on its ID
int get_ue_context(ue_context_list_t* list, int ue_id) {
    // Find the index of the context with the specified ID
    int i = find_ue_context_index(list, ue_id);
    if (i == -1) {
        return NULL;
    }

    return &list->contexts[i];
}

// Function to periodically prune the list of inactive UE contexts
int prune_ue_contexts(ue_context_list_t* list) {
    // Iterate through all contexts and remove those that have not been updated for more than 10 minutes
    time_t current_time = time(NULL);
    int count = list->count;
    for (int i = 0; i < count; i++) {
        if ((current_time - list->contexts[i].update_time) > (10 * 60)) {
            remove_ue_context(list, list->contexts[i].ue_id);
            count--;
        }
    }

    return 0;
}

// Function to generate a random signal strength value for the UE context
double generate_random_signal_strength() {
    // Generate a random number between -120 and -50 dBm
    double range = -120.0 + (double)rand() / RAND_MAX * (-50.0 + -120.0);
    return range;
}

// Function to find the index of a UE context in the list based on its ID
int find_ue_context_index(ue_context_list_t* list, int ue_id) {
    for (int i = 0; i < list->count; i++) {
        if (list->contexts[i].ue_id == ue_id) {
            return i;
        }
    }

    return -1;
}
