} NFAPI_CRC_INDICATION_STRUCTURE;

// Function to generate a random number within the given range
int generateRandomNumber(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_STRUCTURE *createCrcIndicationList(int numStructures) {
    // Allocate memory for the list
    NFAPI_CRC_INDICATION_STRUCTURE *list = (NFAPI_CRC_INDICATION_STRUCTURE *)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_STRUCTURE));

    // Initialize the list and its elements
    for (int i = 0; i < numStructures; i++) {
        // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structure
        list[i].pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Set the RX_UE_INFORMATION_TAG field to a valid value
        list[i].rx_tag = (RX_UE_INFORMATION_TAG *)malloc(sizeof(RX_UE_INFORMATION_TAG));
        list[i].rx_tag->ue_information_type = RX_UE_INFORMATION_TYPE_CRC;
        list[i].rx_tag->crc_indication_rel8.crc_flag = 0; // Initialize the CRCFLAG to 0 for all structures

        // Set the RNTI field to a valid value
        int rnti = generateRandomNumber(0, 65535);
        list[i].rx_tag->ue_information.rnti = rnti;

        // Set the CRCFLAG to 1 for at least 5% of the structures
        if (generateRandomNumber(0, 10) <= 5) {
            list[i].rx_tag->crc_indication_rel8.crc_flag = 1;
        }
    }

    // Return the populated list
    return list;
}

// Function to validate the RNTI values and handle invalid ones gracefully
int validateRnti(RX_UE_INFORMATION_TAG *rx_tag) {
    if (rx_tag->ue_information.rnti < 0 || rx_tag->ue_information.rnti > 65535) {
        // Log an error message and return a failure code
        printf("Invalid RNTI value: %d\n", rx_tag->ue_information.rnti);
        return -1;
    }

    // Return success
    return 0;
}

// Function to handle potential delays or failures in external data sources
NFAPI_CRC_INDICATION_STRUCTURE *handleExternalData(NFAPI_CRC_INDICATION_STRUCTURE *list, int numStructures) {
    // Initialize the number of valid structures to 0
    int validStructures = 0;

    // Iterate over each structure in the list
    for (int i = 0; i < numStructures; i++) {
        // Check if the RNTI value is valid
        if (validateRnti(list[i].rx_tag) == -1) {
            // If not, log an error message and continue with the next structure
            printf("Error validating RNTI value for structure %d\n", i);
            continue;
        }

        // Increment the number of valid structures if the RNTI is valid
        validStructures++;
    }

    // Return a new list with only the valid structures
    NFAPI_CRC_INDICATION_STRUCTURE *validList = (NFAPI_CRC_INDICATION_STRUCTURE *)malloc(validStructures * sizeof(NFAPI_CRC_INDICATION_STRUCTURE));
    int j = 0; // Index for the valid list
    for (int i = 0; i < numStructures; i++) {
        if (validateRnti(list[i].rx_tag) == -1) continue;
        validList[j++] = list[i];
    }

    // Free the original list
    free(list);

    return validList;
}

// Function to handle thread-safety and memory management for the external data source
NFAPI_CRC_INDICATION_STRUCTURE *fetchExternalData() {
    NFAPI_CRC_INDICATION_STRUCTURE *list = NULL; // Initialize the list to NULL
    int numStructures = 0; // Initialize the number of structures to 0

    // Fetch external data from the source, if available
    if (fetchExternalDataFromSource(&list, &numStructures) == -1) {
        printf("Error fetching external data\n");
        return NULL;
    }

    // If no external data is available, allocate a new list and populate it with default values
    if (list == NULL) {
        list = createCrcIndicationList(1000);
        numStructures = 1000;
    }

    return handleExternalData(list, numStructures);
}
