// Define the function to update a resource using the HTTP PUT method
function put($resource, $data) {
    // Set the request URL and headers
    $url = "https://example.com/api/$resource";
    $headers = array(
        'Content-Type: application/json',
        'Authorization: Bearer '. $config['API_TOKEN']
    );

    // Send the PUT request and get the response
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    curl_setopt($ch, CURLOPT_CUSTOMREQUEST, 'PUT');
    curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($data));
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    $response = curl_exec($ch);
    if ($response === false) {
        return 'PUT request failed with error: '. curl_error($ch);
    }
    curl_close($ch);

    // Return the updated resource
    return json_decode($response, true);
}

// Define the function to delete a resource using the HTTP DELETE method
function delete($resource) {
    // Set the request URL and headers
    $url = "https://example.com/api/$resource";
    $headers = array(
        'Content-Type: application/json',
        'Authorization: Bearer '. $config['API_TOKEN']
    );

    // Send the DELETE request and get the response
    $ch = curl_init();
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_HTTPHEADER, $headers);
    curl_setopt($ch, CURLOPT_CUSTOMREQUEST, 'DELETE');
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    $response = curl_exec($ch);
    if ($response === false) {
        return 'DELETE request failed with error: '. curl_error($ch);
    }
    curl_close($ch);

    // Return the updated resource with default values
    return json_decode($response, true);
}
