typedef struct LTEPHYControlPDU {
    int phich;
    int pdsch_ri;
    bool crc;
    struct LTEPHYControlPDU *next;
} LTEPHYControlPDU;

LTEPHYControlPDU* createAndPopulateList(int numStructures) {
    // Dynamic memory allocation for the list of structures
    LTEPHYControlPDU **list = malloc(numStructures * sizeof(LTEPHYControlPDU));
    if (list == NULL) {
        fprintf(stderr, "Failed to allocate memory: %s\n", strerror(errno));
        return NULL;
    }

    // Initialize the list of structures
    for (int i = 0; i < numStructures; i++) {
        LTEPHYControlPDU *pdu = malloc(sizeof(LTEPHYControlPDU));
        if (pdu == NULL) {
            fprintf(stderr, "Failed to allocate memory: %s\n", strerror(errno));
            return NULL;
        }

        // Initialize the PHICH configuration and PDSCH resource indicator randomly
        pdu->phich = rand() % 10;
        pdu->pdsch_ri = rand() % 8;

        // Set the CRC indication randomly with a flag set to true
        if (rand() % 2 == 0) {
            pdu->crc = true;
        } else {
            pdu->crc = false;
        }

        // Link the structures in a chain
        list[i] = pdu;
        if (i > 0) {
            list[i - 1]->next = pdu;
        }
    }

    return list[numStructures - 1];
}

void freeList(LTEPHYControlPDU *head) {
    LTEPHYControlPDU *current = head;
    while (current != NULL) {
        LTEPHYControlPDU *next = current->next;
        free(current);
        current = next;
    }
}
