    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(list->mutex));
    // Check if the list is full and needs to be resized
    if (list->num_entries == list->max_num_entries) {
        size_t new_size = list->max_num_entries * 2;
        nfapi_crc_indication_pdu_t *new_entries = realloc(list->entries, new_size * sizeof(nfapi_crc_indication_pdu_t));
        if (new_entries == NULL) {
