void remove_entry_from_crc_indication_list(nfapi_crc_indication_list_t *list, size_t index) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&(list->mutex));
    if (index >= list->num_entries || list->num_entries == 0) {
        pthread_mutex_unlock(&(list->mutex));
        return;
    }
    // Shift the entries in the list to fill the gap left by the removed entry
    for (size_t i = index; i < list->num_entries - 1; ++i) {
        list->entries[i] = list->entries[i + 1];
