#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include "nfapi.h"

// Custom logging mechanism
void log(const char *message) {
    printf("%s\n", message);
}

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    NFAPI_CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} nfapi_rx_ue_info_t;

// Dynamic resizing list of nfapi_rx_ue_info_t structs
typedef struct {
    size_t capacity;
    size_t count;
    nfapi_rx_ue_info_t *elements;
} nfapi_rx_ue_list_t;

// Initialize an empty list with a specified initial capacity
nfapi_rx_ue_list_t* initialize_list(size_t initial_capacity) {
    assert(initial_capacity > 0);
    nfapi_rx_ue_list_t *list = malloc(sizeof(nfapi_rx_ue_list_t));
    list->capacity = initial_capacity;
    list->count = 0;
    list->elements = calloc(initial_capacity, sizeof(nfapi_rx_ue_info_t));
    return list;
}

// Add a new element to the end of the list and return its index
int add_element(nfapi_rx_ue_list_t *list, uint16_t rx_ue_information_tag, uint32_t rnti) {
    assert(list != NULL);
    // Check if the list is full and needs to be resized
    if (list->count == list->capacity) {
        list->capacity *= 2;
        list->elements = realloc(list->elements, list->capacity * sizeof(nfapi_rx_ue_info_t));
    }
    // Create and populate the new element
    nfapi_rx_ue_info_t *element = &list->elements[list->count];
    element->pdu.rx_ue_information.rx_ue_information_tag = rx_ue_information_tag;
    element->pdu.rx_ue_information.rnti = rnti;
    // Randomly set CRCFLAG
    element->crc_indication_rel8_tag.crcflag = rand() % 2;
    list->count++;
    return list->count - 1;
}

// Remove an element from the list by its index and update the count
void remove_element(nfapi_rx_ue_list_t *list, int index) {
    assert(list != NULL);
    if (index >= 0 && index < list->count) {
        // Shift all elements after the removed element to the left
        for (int i = index + 1; i < list->count; i++) {
            list->elements[i - 1] = list->elements[i];
        }
        // Decrease the count by 1
        list->count--;
    }
}

// Free all memory used by the list
void free_list(nfapi_rx_ue_list_t *list) {
    assert(list != NULL);
    if (list->elements != NULL) {
        free(list->elements);
    }
    free(list);
}
```
To use this code, you would first create an empty list with a specified initial capacity using the `initialize_list` function. Then, for each received RX_UE_INFORMATION_TAG from the radio interface, you would add a new element to the list using the `add_element` function. If the list is full and needs to be resized, it will automatically resize itself to double its current capacity. You can also remove elements from the list by their index using the `remove_element` function. Finally, when you are done with the list, you would free all memory used by it using the `free_list` function.
```c
int main() {
    nfapi_rx_ue_list_t *list = initialize_list(10);

    // Add some elements to the list
    add_element(list, 12345, 1000);
    add_element(list, 12346, 2000);
    add_element(list, 12347, 3000);

    // Remove an element from the list
    remove_element(list, 1);

    // Free all memory used by the list
    free_list(list);

    return 0;
}
