        list[i]->rx_tag.RX_UE_INFORMATION_TAG = 0x00;
        list[i]->rnti.RNTI = 0x00;
        list[i]->crc_tag.CRC_INDICATION_REL8_TAG = 0x00;
    }

    // Set the capacity of the list
    list->capacity = capacity;

    return list;
}

