<?php
function userAccountManagement($_REQUEST) {
    // Validate input data
    $validation = validateData($_REQUEST);
    if ($validation !== true) {
        return json_encode(['message' => 'error', 'errors' => $validation]);
    }

    // Save data to database
    $saveResult = saveData($_REQUEST);
    if (!$saveResult) {
        return json_encode(['message' => 'error', 'errors' => ['Failed to save user account']]);
    }

    // Retrieve user data
    $userData = getUserData($_REQUEST['id']);
    if (!$userData) {
        return json_encode(['message' => 'error', 'errors' => ['Failed to retrieve user data']]);
    }

    // Return JSON response
    return json_encode([
        'message' => 'success',
        'data' => $userData,
    ]);
}

function validateData($data) {
    // Check if required fields are present
    if (!isset($data['name']) || !isset($data['email']) || !isset($data['password'])) {
        return ['Missing required fields'];
    }

    // Validate email address uniqueness
    $email = $data['email'];
    if (checkEmailUniqueness($email)) {
        return ['Email address is already in use'];
    }

    // Return true if no errors
    return true;
}

function saveData($data) {
    // Build query to insert or update user account
    $query = "INSERT INTO users (name, email, password) VALUES (:name, :email, :password)";
    if (isset($data['id'])) {
        $query = "UPDATE users SET name=:name, email=:email, password=:password WHERE id=:id";
    }

    // Prepare query and bind params
    $stmt = $pdo->prepare($query);
    $stmt->bindParam(':name', $data['name']);
    $stmt->bindParam(':email', $data['email']);
    $stmt->bindParam(':password', $data['password']);
    if (isset($data['id'])) {
        $stmt->bindParam(':id', $data['id']);
    }

    // Execute query and return result
    try {
        $result = $stmt->execute();
    } catch (PDOException $e) {
        // Handle error and return false
    }
    return $result;
}

function getUserData($id) {
    // Build query to retrieve user account by ID
    $query = "SELECT * FROM users WHERE id=:id";

    // Prepare query and bind params
    $stmt = $pdo->prepare($query);
    $stmt->bindParam(':id', $id);

    // Execute query and return result
    try {
        $result = $stmt->execute();
    } catch (PDOException $e) {
        // Handle error and return false
    }
    return $result;
}

function checkEmailUniqueness($email) {
    // Build query to retrieve user account by email address
    $query = "SELECT COUNT(*) AS count FROM users WHERE email=:email";

    // Prepare query and bind params
    $stmt = $pdo->prepare($query);
    $stmt->bindParam(':email', $email);

    // Execute query and return result
    try {
        $result = $stmt->execute();
        if ($result) {
            $row = $stmt->fetch(PDO::FETCH_ASSOC);
            return $row['count'] > 0;
        } else {
            // Handle error and return false
        }
    } catch (PDOException $e) {
        // Handle error and return false
    }
    return false;
}
?>

