char* generateCRC(char* input, size_t limit) {
    // Check if the input string exceeds the size limit
    if (strlen(input) > limit) {
        return NULL;
    }

    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pduList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * limit);

    // Populate the list with random values for RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG
    for (int i = 0; i < limit; i++) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 65535;
        pduList[i].RNTI = rand() % 4294967295;
        pduList[i].CRCFLAG = rand() % 128;
    }

    // Calculate the MD5 hash of the input string
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
    MD5(input, strlen(input), md5Hash);

    // Concatenate the MD5 hash with a slash and return the resulting string
    char* result = malloc(sizeof(char) * (MD5_DIGEST_LENGTH + 1));
    memcpy(result, md5Hash, MD5_DIGEST_LENGTH);
    result[MD5_DIGEST_LENGTH] = '/';
    return result;
}
