// Define a struct to represent a UE context
typedef struct {
    char mac_ce[6]; // MAC-CE tag (6 characters)
    unsigned int rnti; // RNTI value
} ue_context_t;

// Define a list data structure to store the UE contexts
typedef struct {
    ue_context_t *data;
    size_t capacity;
    size_t count;
} ue_context_list_t;

// Function to create and populate a list of UE context structures
void populate_ue_context_list(ue_context_list_t *list, int num_ue) {
    // Allocate memory for the list data structure
    list->data = (ue_context_t *) malloc(sizeof(ue_context_t) * num_ue);
    list->capacity = num_ue;
    list->count = 0;

    // Populate the list with random MAC-CE tags and RNTI values
    for (int i = 0; i < num_ue; i++) {
        ue_context_t *ue = &list->data[i];

        // Generate a random MAC-CE tag
        char mac_ce[6] = "MAC-CE";
        for (int j = 0; j < 5; j++) {
            mac_ce[j] = 'A' + rand() % 26;
        }

        // Generate a random RNTI value
        ue->rnti = rand() % 1000000;

        // Store the MAC-CE tag and RNTI value in the list
        strcpy(ue->mac_ce, mac_ce);
        list->count++;
    }
}

// Function to insert a new UE context into the list
void insert_ue_context(ue_context_list_t *list, char *mac_ce, unsigned int rnti) {
    // Check if the list is full
    if (list->count == list->capacity) {
        // If the list is full, double its capacity and reallocate memory
        ue_context_t *new_data = (ue_context_t *) realloc(list->data, 2 * list->capacity);
        if (!new_data) {
            fprintf(stderr, "Failed to allocate memory for UE contexts\n");
            return;
        }
        list->data = new_data;
        list->capacity *= 2;
    }

    // Insert the new UE context into the list
    ue_context_t *ue = &list->data[list->count++];
    strcpy(ue->mac_ce, mac_ce);
    ue->rnti = rnti;
}

// Function to delete a UE context from the list
void delete_ue_context(ue_context_list_t *list, char *mac_ce) {
    // Find the index of the UE context with the given MAC-CE tag
    int i = 0;
    for (i = 0; i < list->count; i++) {
        if (strcmp(list->data[i].mac_ce, mac_ce) == 0) {
            break;
        }
    }

    // If the UE context was found, delete it from the list
    if (i < list->count) {
        memmove(&list->data[i], &list->data[i + 1], (list->count - i - 1) * sizeof(ue_context_t));
        list->count--;
    }
}
