#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure to store the UE_Identity and RRC_Configuration
typedef struct LTE_RRC_CONN_RECFG_CMP_T {
    int UE_Identity;
    char RRC_Configuration[64];
    bool Mobility_Failure_Indicator;
} LTE_RRC_CONN_RECFG_CMP_T;

// Define the linked list structure to store the populated list of UE_Identities and RRC_Configurations
typedef struct LTE_RRC_CONN_RECFG_LIST {
    LTE_RRC_CONN_RECFG_CMP_T* head;
    LTE_RRC_CONN_RECFG_CMP_T* tail;
} LTE_RRC_CONN_RECFG_LIST;

// Function to create and populate the list of UE_Identities and RRC_Configurations
LTE_RRC_CONN_RECFG_LIST* populate_list(int N) {
    // Check if the input parameter is within acceptable ranges
    if (N < 0 || N > 100000) {
        printf("Error: Invalid value for N. Must be between 0 and 100000.\n");
        return NULL;
    }

    // Initialize the linked list structure
    LTE_RRC_CONN_RECFG_LIST* list = malloc(sizeof(LTE_RRC_CONN_RECFG_LIST));
    if (!list) {
        printf("Error: Unable to allocate memory for the linked list.\n");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;

    // Loop through each UE_Identity and RRC_Configuration pair, and create a new structure
    for (int i = 0; i < N; ++i) {
        LTE_RRC_CONN_RECFG_CMP_T* entry = malloc(sizeof(LTE_RRC_CONN_RECFG_CMP_T));
        if (!entry) {
            printf("Error: Unable to allocate memory for the linked list entry.\n");
            return NULL;
        }
        entry->UE_Identity = i + 1;
        sprintf(entry->RRC_Configuration, "RRC_Configuration_%d", i);
        entry->Mobility_Failure_Indicator = (rand() % 2) == 0;

        // Add the new structure to the linked list
        if (!list->head) {
            list->head = entry;
            list->tail = entry;
        } else {
            list->tail->next = entry;
            list->tail = entry;
        }
    }

    // Periodically check for and free any unused memory in the list
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_create(&mutex, NULL, periodic_check, (void*)list);

    // Provide an option to save the populated list to a file for later use or restoration
    if (save_to_file) {
        FILE* file = fopen("LTE_RRC_CONN_RECFG_LIST.txt", "w");
        fprintf(file, "%d\n", N);
        for (LTE_RRC_CONN_RECFG_CMP_T* entry = list->head; entry != NULL; entry = entry->next) {
            fprintf(file, "%d %s %s\n", entry->UE_Identity, entry->RRC_Configuration, entry->Mobility_Failure_Indicator ? "true" : "false");
        }
        fclose(file);
    }

    // Return the populated linked list structure
    return list;
}

// Thread function to periodically check for and free any unused memory in the list
void* periodic_check(void* arg) {
    LTE_RRC_CONN_RECFG_LIST* list = (LTE_RRC_CONN_RECFG_LIST*)arg;
    while (1) {
        // Check if any entry in the list is unused, and free it if so
        pthread_mutex_lock(&mutex);
        for (LTE_RRC_CONN_RECFG_CMP_T* entry = list->head; entry != NULL; entry = entry->next) {
            if (!entry->used) {
                free(entry);
                break;
            }
        }
        pthread_mutex_unlock(&mutex);

        // Sleep for a short period before checking again
        sleep(10);
    }
}
