#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>

// Structures and definitions
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    bool CRCFLAG;
} CRC_INDICATION_REL8_TAG;

// Global variables
int MAX_LIST_SIZE = 1024;
pthread_mutex_t list_lock;
semaphore_t data_ready;
NFAPI_CRC_INDICATION_PDU_T *list = NULL;
int list_size = 0;
bool is_data_available = false;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void createAndPopulateList(int num_elements) {
    // Check if the input parameter is valid
    if (num_elements < 0 || num_elements > MAX_LIST_SIZE) {
        printf("Invalid number of elements: %d\n", num_elements);
        return;
    }

    // Initialize the list and its size
    if (list == NULL) {
        list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
    } else {
        // Reallocate memory for the list if necessary
        if (num_elements > list_size) {
            list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
        }
    }
    list_size = num_elements;

    // Populate the list with random data
    for (int i = 0; i < num_elements; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = &list[i];
        element->RX_UE_INFORMATION_TAG = rand() % MAX_LIST_SIZE;
        element->RNTI = rand() % MAX_LIST_SIZE;
        CRC_INDICATION_REL8_TAG crc_indication;
        crc_indication.CRCFLAG = rand() % 2;
    }

    // Set the flag to indicate that data is available
    is_data_available = true;
}

// Function to fetch data from an external source and populate the list
void fetchDataAndPopulateList(int timeout) {
    // Acquire the lock to prevent race conditions with other threads
    pthread_mutex_lock(&list_lock);

    // Fetch data from the external source
    if (is_data_available) {
        printf("Data is already available\n");
        goto release_lock;
    } else {
        printf("Fetching data...\n");
    }

    // Wait for a specified timeout for data to become available
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout;
    semaphore_wait(&data_ready, &ts);

    // If the wait timed out, print an error message and release the lock
    if (semaphore_get_value(&data_ready) != 0) {
        printf("Data fetching timed out\n");
        goto release_lock;
    }

    // Populate the list with data from the external source
    createAndPopulateList(list_size);

release_lock:
    // Release the lock and return
    pthread_mutex_unlock(&list_lock);
}

// Function to retrieve the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *getList() {
    // Return a pointer to the list
    return list;
}

// Main function
int main() {
    // Initialize the data ready semaphore and set its value to 0
    semaphore_init(&data_ready, 0);

    // Create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures with random data
    createAndPopulateList(5);

    // Fetch data from an external source and populate the list
    fetchDataAndPopulateList(10);

    // Retrieve the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *list = getList();

    // Print the contents of the list
    for (int i = 0; i < list_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = &list[i];
        printf("RX_UE_INFORMATION_TAG: %d\n", element->RX_UE_INFORMATION_TAG);
        printf("RNTI: %d\n", element->RNTI);
        CRC_INDICATION_REL8_TAG crc_indication = element->crc_indication;
        printf("CRCFLAG: %s\n", crc_indication.CRCFLAG ? "true" : "false");
    }

    // Clean up
    free(list);
    semaphore_destroy(&data_ready);
    pthread_mutex_destroy(&list_lock);

    return 0;
}']

