    if (max_entries < 1 || max_entries > 500) {
        printf("Error: Invalid value for 'max_entries'");
        return NULL;
    }

    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* crc_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_entries);
    if (!crc_list) {
        printf("Error: Failed to allocate memory for the CRC list");
        return NULL;
    }

    // Initialize each entry in the list with a unique RX_UE_INFORMATION_TAG and RNTI
    int i;
    for (i = 0; i < max_entries; ++i) {
        crc_list[i].RX_UE_INFORMATION_TAG = i + 1;
        crc_list[i].RNTI = (i % 250) + 1;
    }

    // Set the CRCFLAG randomly for each entry in the list
    srand(time(NULL));
    for (i = 0; i < max_entries; ++i) {
        crc_list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
