#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

// Thread-safe data structure for storing UE contexts
typedef struct {
    int valid; // 0 if the UE is not valid, 1 otherwise
    char *ue_id; // unique identifier for the UE
    char *ip_addr; // IP address of the UE
    pthread_mutex_t lock; // mutex to protect the UE context
    struct {
        int state; // current session state (ESTABLISHED or TERMINATED)
        long timestamp; // timestamp for last state transition
    } sessions[]; // array of session states
} ue_context_t;

// Function to create and populate a list of UE contexts
ue_context_t *create_ue_contexts(int num_ues) {
    int i;
    ue_context_t *contexts = (ue_context_t *)malloc(num_ues * sizeof(ue_context_t));
    for (i = 0; i < num_ues; i++) {
        contexts[i].valid = 1;
        contexts[i].ue_id = malloc(sizeof(char) * 20); // unique identifier for the UE
        sprintf(contexts[i].ue_id, "UE-%d", i);
        contexts[i].ip_addr = malloc(sizeof(char) * 16); // IP address of the UE
        sprintf(contexts[i].ip_addr, "%d.%d.%d.%d", i / 256, (i % 256) / 16, (i % 16) / 4, i % 4);
        contexts[i].lock = PTHREAD_MUTEX_INITIALIZER; // initialize mutex
        contexts[i].sessions[0].state = ESTABLISHED; // set initial state to ESTABLISHED
        contexts[i].sessions[0].timestamp = time(NULL); // set initial timestamp
    }
    return contexts;
}

// Function to handle NMS interactions with UE contexts
void nms_interaction(ue_context_t *context) {
    pthread_mutex_lock(&context->lock); // acquire mutex lock
    if (context->valid == 1) { // only process valid UE contexts
        // perform NMS interaction with the UE context
        printf("NMS interaction with UE %s, IP address %s\n", context->ue_id, context->ip_addr);
    }
    pthread_mutex_unlock(&context->lock); // release mutex lock
}

// Function to update the session state of a UE context
void update_session_state(ue_context_t *context, int session_idx, int new_state) {
    pthread_mutex_lock(&context->lock); // acquire mutex lock
    if (new_state == ESTABLISHED || new_state == TERMINATED) {
        context->sessions[session_idx].state = new_state; // update session state
        context->sessions[session_idx].timestamp = time(NULL); // update timestamp for state transition
    } else {
        printf("Invalid session state specified. Ignoring.\n");
    }
    pthread_mutex_unlock(&context->lock); // release mutex lock
}

// Function to destroy a UE context and free associated resources
void destroy_ue_context(ue_context_t *context) {
    if (context != NULL) {
        int i;
        for (i = 0; i < 10; i++) { // loop through all session states
            pthread_mutex_lock(&context->lock); // acquire mutex lock
            context->sessions[i].state = TERMINATED; // set state to TERMINATED
            context->sessions[i].timestamp = time(NULL); // update timestamp for state transition
            pthread_mutex_unlock(&context->lock); // release mutex lock
        }
        free(context->ue_id); // free memory allocated for UE ID
        free(context->ip_addr); // free memory allocated for IP address
        free(context); // free memory allocated for the UE context
    }
}

// Function to handle concurrent access from multiple threads without causing data corruption or race conditions
void *thread_worker(void *arg) {
    ue_context_t *context = (ue_context_t *)arg;
    pthread_mutex_lock(&context->lock); // acquire mutex lock
    if (context->valid == 1) { // only process valid UE contexts
        printf("Thread %lu: Processing UE %s, IP address %s\n", pthread_self(), context->ue_id, context->ip_addr);
        nms_interaction(context); // perform NMS interaction with the UE context
    }
    pthread_mutex_unlock(&context->lock); // release mutex lock
    return NULL;
}

// Main function to demonstrate usage of the create_ue_contexts() and update_session_state() functions
int main(void) {
    int i, num_ues = 10;
    ue_context_t *contexts = create_ue_contexts(num_ues); // create list of UE contexts
    for (i = 0; i < num_ues; i++) {
        pthread_t thread; // thread identifier
        int rc = pthread_create(&thread, NULL, &thread_worker, (void *)&contexts[i]); // create new thread to process UE context
        if (rc) {
            printf("Error creating thread: %d\n", rc);
        } else {
            pthread_join(thread, NULL); // wait for thread to complete
        }
    }
    destroy_ue_contexts(&contexts[0]); // free memory allocated for UE contexts
    return 0;
}']

