            }
        }

        lte_phy_pdus[i].mac_pdus = mac_pdus;
    }

    return lte_phy_pdus;
}

// Function for destroying LTE PHY layer PDUS and their MAC PDUS
void destroy_lte_phy_pdus(struct lte_phy_pdu *lte_phy_pdus) {
