// Define the list structure for storing the CRC_INDICATION_PDU_T structures
typedef struct {
  NFAPI_CRC_INDICATION_PDU_T** pdu_list; // Pointer to an array of pointers to NFAPI_CRC_INDICATION_PDU_T structures
  uint32_t count; // Number of elements in the list
  uint32_t capacity; // Maximum number of elements that can be stored in the list
  pthread_mutex_t mutex; // Mutex for thread-safe access to the list
} CRC_INDICATION_LIST;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
int32_t create_crc_indication_list(uint16_t num_pdus, uint16_t num_rntis, CRC_INDICATION_LIST* list) {
  // Initialize the list structure and allocate memory for the array of pointers to NFAPI_CRC_INDICATION_PDU_T structures
  if (list == NULL) {
    return -1;
  }
  list->pdu_list = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
  if (list->pdu_list == NULL) {
    free(list);
    return -2;
  }
  memset(list->pdu_list, 0, num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
  list->count = 0;
  list->capacity = num_pdus;
  pthread_mutex_init(&list->mutex, NULL);

  // Populate the list with random RNTIs and CRCFLAG values
  for (uint16_t i = 0; i < num_pdus; i++) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
      free(list->pdu_list);
      list->pdu_list = NULL;
      list->count = 0;
      list->capacity = 0;
      pthread_mutex_destroy(&list->mutex);
      return -3;
    }
    memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    uint16_t rx_ue_information_tag = rand() % num_rntis; // Generate a random RX_UE_INFORMATION_TAG value
    pdu->rx_ue_information_tag = rx_ue_information_tag;
    for (uint8_t j = 0; j < 4; j++) { // Set the CRCFLAG value randomly
      uint32_t crcflag = rand() % 256;
      pdu->crc_indication_rel8_tag[j] = crcflag;
    }
    list->pdu_list[i] = pdu;
  }

  return 0;
}

// Function to validate the integrity of a CRCFLAG value before adding it to the list
bool is_valid_crcflag(uint32_t crcflag) {
  // Implement your own validation logic here
