  return true; // Return true if the CRCFLAG value is valid, false otherwise
}

// Function to add an element to the list of CRC_INDICATION_PDUs
int32_t add_crc_indication(CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
  if (list == NULL || pdu == NULL) {
    return -1;
  }

  // Lock the mutex to prevent concurrent access to the list
  pthread_mutex_lock(&list->mutex);

  // Check if there is enough space in the list to store the new element
  if (list->count >= list->capacity) {
    // Reallocate memory for the array of pointers to NFAPI_CRC_INDICATION_PDU_T structures if necessary
    if (list->capacity < 2 * num_pdus) {
      list->pdu_list = realloc(list->pdu_list, 2 * num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
      if (list->pdu_list == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -2;
      }
      list->capacity = 2 * num_pdus;
    }
  }

  // Add the new element to the list and update the count
  list->pdu_list[list->count++] = pdu;

  // Unlock the mutex to allow other threads to access the list
  pthread_mutex_unlock(&list->mutex);

  return 0;
}

// Function to remove an element from the list of CRC_INDICATION_PDUs
int32_t remove_crc_indication(CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
  if (list == NULL || pdu == NULL) {
    return -1;
  }

  // Lock the mutex to prevent concurrent access to the list
  pthread_mutex_lock(&list->mutex);

  // Search for the element in the list and remove it if found
  for (uint32_t i = 0; i < list->count; i++) {
    if (list->pdu_list[i] == pdu) {
      // Shift all elements after the removed element to fill the gap
      for (uint32_t j = i; j < list->count - 1; j++) {
        list->pdu_list[j] = list->pdu_list[j + 1];
      }
      // Decrement the count and free the memory allocated to the removed element
      list->count--;
      free(pdu);
      break;
    }
  }

  // Unlock the mutex to allow other threads to access the list
  pthread_mutex_unlock(&list->mutex);

  return 0;
}

// Function to release all memory allocated for the list of CRC_INDICATION_PDUs
void destroy_crc_indication_list(CRC_INDICATION_LIST* list) {
  if (list == NULL) {
    return;
  }

  // Lock the mutex to prevent concurrent access to the list
  pthread_mutex_lock(&list->mutex);

  // Free all memory allocated for the array of pointers to NFAPI_CRC_INDICATION_PDU_T structures and set the count to zero
  free(list->pdu_list);
  list->pdu_list = NULL;
  list->count = 0;

  // Unlock the mutex to allow other threads to access the list
  pthread_mutex_unlock(&list->mutex);
}
