['```
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG;
    RNTI;
    CRC_INDICATION_REL8_TAG crc_ind;
};

struct CrcIndicationList {
    struct NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
};

static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
static size_t total_crc_indications = 0;

struct CrcIndicationList *createCrcIndicationList(size_t count) {
    struct CrcIndicationList *list = (struct CrcIndicationList *)malloc(sizeof(struct CrcIndicationList));
    if (!list) {
        return NULL;
    }
    list->list = (struct NFAPI_CRC_INDICATION_PDU_T *)malloc(count * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!list->list) {
        free(list);
        return NULL;
    }
    list->count = count;
    return list;
}

void addCrcIndicationToList(struct CrcIndicationList *list, struct NFAPI_CRC_INDICATION_PDU_T crc_ind) {
    pthread_mutex_lock(&list_lock);
    if (list->count < list->count + 1) {
        size_t new_size = list->count * 2;
        struct NFAPI_CRC_INDICATION_PDU_T *new_list = (struct NFAPI_CRC_INDICATION_PDU_T *)realloc(list->list, new_size * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list_lock);
            return;
        }
        list->list = new_list;
        list->count = new_size;
    }
    list->list[list->count++] = crc_ind;
    pthread_mutex_unlock(&list_lock);
}

void freeCrcIndicationList(struct CrcIndicationList *list) {
    if (list) {
        free(list->list);
        free(list);
    }
}

struct NFAPI_CRC_INDICATION_PDU_T createCrcIndicationPdu(RX_UE_INFORMATION_TAG, RNTI) {
    struct NFAPI_CRC_INDICATION_PDU_T crc_ind;
    crc_ind.rx_ue_information = rx_ue_info;
    crc_ind.rnti = rnti;
    crc_ind.crc_indication_rel8.crflag = (int)rand() % 2;
    return crc_ind;
}

void incrementTotalCrcIndications(size_t count) {
    pthread_mutex_lock(&list_lock);
    total_crc_indications += count;
    pthread_mutex_unlock(&list_lock);
}

size_t getTotalCrcIndications() {
    size_t result;
    pthread_mutex_lock(&list_lock);
    result = total_crc_indications;
    pthread_mutex_unlock(&list_lock);
    return result;
}
