// Structure to hold the RX_UE_INFORMATION_TAG and RNTI values
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *ptr;
} CrcIndicationPduListNode;

// Linked list to store the CRC indication PDUs
static CrcIndicationPduListNode *crcIndicationPduList = NULL;

// Mutex for synchronizing access to the linked list
static pthread_mutex_t crcIndicationPduListMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to create and populate a CRC indication PDU structure
NFAPI_CRC_INDICATION_PDU_T *createAndPopulateCrcIndicationPdu(void) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;

    // Allocate memory for the PDU structure
    pdu = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        printf("Failed to allocate memory for CRC indication PDU\n");
        return NULL;
    }

    // Fill in the RX_UE_INFORMATION_TAG and RNTI values
    pdu->rx_ue_information.rnti = getRntiFromExternalDataFeed();
    if (pdu->rx_ue_information.rnti == -1) {
        printf("Failed to retrieve RNTI value from external data feed\n");
        free(pdu);
        return NULL;
    }
    pdu->crc_indication_rel8.crcflag = getRandomCrcFlag();

    // Add the PDU to the linked list
    CrcIndicationPduListNode *newNode = (CrcIndicationPduListNode *) malloc(sizeof(CrcIndicationPduListNode));
    if (!newNode) {
        printf("Failed to allocate memory for new node in linked list\n");
        free(pdu);
        return NULL;
    }
    newNode->ptr = pdu;

    // Lock the mutex before modifying the linked list
    pthread_mutex_lock(&crcIndicationPduListMutex);
    if (!crcIndicationPduList) {
        crcIndicationPduList = newNode;
    } else {
        CrcIndicationPduListNode *currNode = crcIndicationPduList;
        while (currNode->next) {
            currNode = currNode->next;
        }
        currNode->next = newNode;
    }
    pthread_mutex_unlock(&crcIndicationPduListMutex);

    return pdu;
}

// Function to get a random CRC flag value
int getRandomCrcFlag(void) {
    // Generate a random number between 0 and 1
    int random = rand() % 2;
    if (random == 0) {
        return NFAPI_CRC_FLAG_NO;
    } else {
        return NFAPI_CRC_FLAG_YES;
    }
}

// Function to get the RNTI value from an external data feed
int getRntiFromExternalDataFeed(void) {
    // Simulate retrieving RNTI value from external data feed
    int rnti = rand() % 100;
    if (rnti == -1) {
        return -1;
    } else {
        return rnti;
    }
}

