#include <json-c/json.h>

// Define the structure for LTE UE Contexts
typedef struct {
    int ue_id;
    char mac[6];
    json_object *radio_config;
} lte_ue_context_t;

// Define a list data structure to store LTE UE Contexts
typedef struct {
    int size;
    lte_ue_context_t **data;
} lte_ue_context_list_t;

// Function to create and populate a list of LTE UE Context structures
lte_ue_context_list_t *create_and_populate_ue_contexts(const char *json_file) {
    // Load the JSON file into memory
    json_object *root = json_object_from_file(json_file);
    if (root == NULL) {
        printf("Error loading JSON file\n");
        return NULL;
    }

    // Get the number of UE contexts from the JSON file
    int num_ue_contexts = json_object_array_length(root);

    // Create a new list to store the LTE UE Context structures
    lte_ue_context_list_t *list = malloc(sizeof(lte_ue_context_list_t));
    if (list == NULL) {
        printf("Error allocating memory for UE context list\n");
        return NULL;
    }
    list->size = num_ue_contexts;
    list->data = malloc(sizeof(lte_ue_context_t*) * num_ue_contexts);
    if (list->data == NULL) {
        printf("Error allocating memory for UE context data\n");
        free(list);
        return NULL;
    }

    // Populate the list with LTE UE Context structures
    for (int i = 0; i < num_ue_contexts; i++) {
        json_object *obj = json_object_array_get_idx(root, i);
        if (obj == NULL) {
            printf("Error getting JSON object at index %d\n", i);
            free(list->data);
            free(list);
            return NULL;
        }

        // Allocate memory for the LTE UE Context structure
        lte_ue_context_t *ue_context = malloc(sizeof(lte_ue_context_t));
        if (ue_context == NULL) {
            printf("Error allocating memory for UE context\n");
            free(list->data);
            free(list);
            return NULL;
        }

        // Get the UE ID and MAC address from the JSON object
        json_object *ue_id = json_object_get_string(json_object_object_get(obj, "UEID"));
        if (ue_id == NULL) {
            printf("Error getting UEID from JSON object\n");
            free(ue_context);
            continue;
        }
        ue_context->ue_id = atoi(json_object_get_string(ue_id));
        json_object *mac = json_object_get_string(json_object_object_get(obj, "MAC"));
        if (mac == NULL) {
            printf("Error getting MAC from JSON object\n");
            free(ue_context);
            continue;
        }
        strcpy(ue_context->mac, json_object_get_string(mac));

        // Get the radio resource configurations from the JSON object
        json_object *radio_config = json_object_object_get(obj, "RadioConfig");
        if (radio_config == NULL) {
            printf("Error getting RadioConfig from JSON object\n");
            free(ue_context);
            continue;
        }
        ue_context->radio_config = json_object_deep_copy(radio_config);

        // Add the LTE UE Context structure to the list
        list->data[i] = ue_context;
    }

    return list;
}

// Function to insert a new LTE UE Context into the list
void insert_ue_context(lte_ue_context_list_t *list, int ue_id, const char *mac) {
    // Allocate memory for the new LTE UE Context structure
    lte_ue_context_t *ue_context = malloc(sizeof(lte_ue_context_t));
    if (ue_context == NULL) {
        printf("Error allocating memory for UE context\n");
        return;
    }

    // Set the UE ID and MAC address for the new LTE UE Context structure
    ue_context->ue_id = ue_id;
    strcpy(ue_context->mac, mac);

    // Insert the new LTE UE Context structure into the list
    list->data[list->size++] = ue_context;
}

// Function to delete a LTE UE Context from the list by UE ID
void delete_ue_context(lte_ue_context_list_t *list, int ue_id) {
    // Find the index of the LTE UE Context structure with the specified UE ID
    int i;
    for (i = 0; i < list->size; i++) {
        if (list->data[i]->ue_id == ue_id) {
            break;
        }
    }

    // If the LTE UE Context structure was found, remove it from the list
    if (i < list->size) {
        free(list->data[i]);
        memmove(&list->data[i], &list->data[i + 1], sizeof(lte_ue_context_t*) * (list->size - i));
        list->size--;
    }
}

// Function to update the radio resource configurations for a LTE UE Context in the list by UE ID
void update_radio_config(lte_ue_context_list_t *list, int ue_id, json_object *radio_config) {
    // Find the index of the LTE UE Context structure with the specified UE ID
    int i;
    for (i = 0; i < list->size; i++) {
        if (list->data[i]->ue_id == ue_id) {
            break;
        }
    }

    // If the LTE UE Context structure was found, update its radio resource configurations
    if (i < list->size) {
        json_object_put(list->data[i]->radio_config);
        list->data[i]->radio_config = json_object_deep_copy(radio_config);
    }
}

