int populate_crc_indications_list(NFAPI_CRC_INDICATION_PDU_T **crc_list, uint32_t max_structs) {
    // Check input parameters
    if (crc_list == NULL || max_structs > 1000) {
        return -1;
    }

    // Allocate memory for the list of structures
    *crc_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * max_structs);
    if (*crc_list == NULL) {
        return -2;
    }

    // Populate the list of structures
    for (uint32_t i = 0; i < max_structs; i++) {
        NFAPI_CRC_INDICATION_PDU_T *current_pdu = &(*crc_list)[i];
        current_pdu->rx_ue_information.rnti = (uint16_t)rand(); // Use random RNTI value
        current_pdu->rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        current_pdu->crc_indication_rel8.crcflag = (uint8_t)rand() % 2; // Use random CRCFLAG value
        current_pdu->crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
    }

    return 0;
}

// Checks if the RNTI values in the list are unique within each batch
bool check_rnti_uniqueness(NFAPI_CRC_INDICATION_PDU_T *crc_list, uint32_t max_structs) {
    // Initialize a set to store the RNTI values
    std::set<uint16_t> rnti_set;

    // Iterate over the list of structures and check if each RNTI value is unique in the set
    for (uint32_t i = 0; i < max_structs; i++) {
        NFAPI_CRC_INDICATION_PDU_T *current_pdu = &crc_list[i];
        if (!rnti_set.insert(current_pdu->rx_ue_information.rnti).second) {
            // If the RNTI value already exists in the set, return false
            return false;
        }
    }

    // If all RNTI values are unique, return true
    return true;
}

// Prints an error message to the console if memory allocation fails during structure population
void print_memory_allocation_error() {
    printf("Error: Memory allocation failed during structure population.\n");
}

