void maintain_current_network_topology(NFAPI_CRC_INDICATION_PDU_T *crc_indication_list, int num_nodes) {
    // Remove any nodes that are no longer connected from the list of structures
    for (int i = 0; i < crc_indication_list->num_entries; i++) {
        if (!node_is_connected(latest_node_info, num_nodes)) {
            // Remove the node from the list of structures
            remove_entry(&crc_indication_list[i]);
        }
