// Function to read a list of integers from standard input and find the largest value
int *readInputAndFindLargestValue(int num_inputs) {
  int *inputs = (int *)malloc(num_inputs * sizeof(int));
  if (!inputs) {
    // Handle allocation failure gracefully
    printf("Error: Failed to allocate memory for input array\n");
    return NULL;
  }

  // Read the list of integers from standard input
  for (int i = 0; i < num_inputs; i++) {
    scanf("%d", &inputs[i]);
  }

  // Find the largest value in the array
  int largest_value = inputs[0];
  for (int i = 1; i < num_inputs; i++) {
    if (inputs[i] > largest_value) {
      largest_value = inputs[i];
    }
  }

  return largest_value;
}

// Main function to validate input and create a list of LTEPHY.receive_cfg_t structures
