    list->data = NULL;

    // Iterate over the DL-TCH data source and create a new UE context structure for each entry
    while (1) {
        int ue_id, cell_id;
        char dl_tch[1024];
        time_t timestamp = time(NULL); // Get current timestamp

        // Read the next entry from the DL-TCH data source (assuming it's a file)
        if (fscanf(dl_tch_source, "%d %d %1024[^\n]", &ue_id, &cell_id, dl_tch) != 3) {
            break; // End of file reached
        }

