#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structure to represent a LTE UE context
typedef struct {
  int ue_id;
  int cell_id;
  char *dl_tch_data;
  time_t last_updated;
} lte_ue_context;

// Function to create and populate a list of LTE UE contexts
void create_and_populate_lte_ue_contexts(int num_uces, int *ue_ids, int *cell_ids, char **dl_tch_data) {
  // Initialize the list of UE contexts
  lte_ue_context **ue_contexts = malloc(sizeof(lte_ue_context *) * num_uces);
  for (int i = 0; i < num_uces; i++) {
    ue_contexts[i] = malloc(sizeof(lte_ue_context));
    ue_contexts[i]->ue_id = ue_ids[i];
    ue_contexts[i]->cell_id = cell_ids[i];
    ue_contexts[i]->dl_tch_data = dl_tch_data[i];
    ue_contexts[i]->last_updated = time(NULL);
  }

  // Add a periodic cleanup mechanism to remove outdated UE contexts
  struct timespec timer;
  timer.tv_sec = 10; // 10 seconds
  timer.tv_nsec = 0;
  pthread_t thread;
  if (pthread_create(&thread, NULL, &cleanup_ue_contexts, ue_contexts) != 0) {
    perror("Error creating thread for cleanup");
  }

  // Dynamic resizing of the list based on the number of UE contexts received from external sources
  size_t num_uces_ext = num_uces;
  while (num_uces_ext > 0) {
    int uce_id = ue_ids[--num_uces_ext];
    lte_ue_context *uce = NULL;
    for (int i = 0; i < num_uces; i++) {
      if (ue_contexts[i]->ue_id == uce_id) {
        uce = ue_contexts[i];
        break;
      }
    }
    if (uce != NULL) {
      free(uce->dl_tch_data);
      free(uce);
      ue_contexts[num_uces - 1] = NULL;
    } else {
      uce = malloc(sizeof(lte_ue_context));
      uce->ue_id = uce_id;
      uce->cell_id = cell_ids[uce_id];
      uce->dl_tch_data = dl_tch_data[uce_id];
      ue_contexts[num_uces] = uce;
    }
  }
}

// Function to cleanup outdated UE contexts periodically
void *cleanup_ue_contexts(void *args) {
  lte_ue_context **ue_contexts = args;
  while (1) {
    sleep(timer);
    for (int i = 0; i < num_uces; i++) {
      if (ue_contexts[i]->last_updated + timer.tv_sec <= time(NULL)) {
        free(ue_contexts[i]->dl_tch_data);
        free(ue_contexts[i]);
        ue_contexts[i] = NULL;
      }
    }
  }
}
