#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <errno.h>
#include "nfapi_crc_indication.h"

/* Thread-safe data structure to store the list of NFAPI_CRC_INDICATION_PDU_T */
typedef struct {
  pthread_mutex_t mutex; /* Mutex for thread-safety */
  int size; /* Size of the list */
  int capacity; /* Capacity of the list */
  NFAPI_CRC_INDICATION_PDU_T *list; /* List of NFAPI_CRC_INDICATION_PDU_T structures */
} CrcIndicationList;

/* Create and initialize a new CrcIndicationList */
static inline void create_crc_indication_list(CrcIndicationList *list) {
  list->size = 0;
  list->capacity = INITIAL_CAPACITY;
  list->list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * INITIAL_CAPACITY);
}

/* Add a new NFAPI_CRC_INDICATION_PDU_T to the list, ensuring it is sorted and unique */
static inline int add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu, CrcIndicationList *list) {
  pthread_mutex_lock(&list->mutex);
  /* Validate that the RX_UE_INFORMATION_TAG is unique within the list */
  for (int i = 0; i < list->size; i++) {
    if (pdu->rx_ue_information.rnti == list->list[i].rx_ue_information.rnti) {
      pthread_mutex_unlock(&list->mutex);
      return -EINVAL; /* Error: duplicate RX_UE_INFORMATION_TAG found */
    }
  }
  /* Add the new NFAPI_CRC_INDICATION_PDU_T to the list */
  if (list->size < list->capacity) {
    list->list[list->size] = *pdu;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return 0; /* Success: added new NFAPI_CRC_INDICATION_PDU_T to the list */
  } else {
    pthread_mutex_unlock(&list->mutex);
    return -ENOMEM; /* Error: no more space in the list */
  }
}

/* Sort the list of NFAPI_CRC_INDICATION_PDU_T structures based on the RNTI values in ascending order */
static inline void sort_crc_indication_list(CrcIndicationList *list) {
  qsort(list->list, list->size, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_pdu);
}

/* Compare two NFAPI_CRC_INDICATION_PDU_T structures based on their RNTI values */
static inline int compare_pdu(const void *a, const void *b) {
  const NFAPI_CRC_INDICATION_PDU_T *pa = a;
  const NFAPI_CRC_INDICATION_PDU_T *pb = b;
  if (pa->rx_ue_information.rnti > pb->rx_ue_information.rnti) {
    return 1; /* Greater: RNTI of a is greater than the RNTI of b */
  } else if (pa->rx_ue_information.rnti < pb->rx_ue_information.rnti) {
    return -1; /* Less: RNTI of a is less than the RNTI of b */
  } else {
    return 0; /* Equal: RNTI values are equal */
  }
}

/* Free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures */
static inline void free_crc_indication_list(CrcIndicationList *list) {
  free(list->list);
  pthread_mutex_destroy(&list->mutex);
}
```
To handle the thread-safety of the list, a mutex is used to synchronize access to the list. The `add_crc_indication` function acquires the lock on the mutex before checking for duplicate RX_UE_INFORMATION_TAG and adding the new PDU to the list.

To handle the case where PDUs are provided out of order or contain duplicate RNTI values, the `sort_crc_indication_list` function is used to sort the list based on the RNTI values in ascending order. The `compare_pdu` function is used as the comparison function for the `qsort` function.

To handle memory allocation and deallocation of the list, a dynamic array is used with the `INITIAL_CAPACITY` set to 1024. As more PDUs are added to the list, the capacity of the list is doubled whenever it reaches 50% full. This avoids excessive memory usage and reduces the need for frequent reallocations.

To log any errors or warnings during execution, the `errno` function can be used to set the error code and the `perror` function can be used to print a string describing the error. The `free_crc_indication_list` function is called when the list is no longer needed to free the memory allocated for it.']

