// Define the structure to represent an LTE UE context
typedef struct {
    int ue_id;
    int cell_id;
    char *dl_tch;
    time_t last_update;
    int ref_count;
} lte_ue_context_t;

// Define the list data structure to store the LTE UE contexts
typedef struct {
    size_t capacity;
    size_t size;
    lte_ue_context_t **data;
    pthread_mutex_t *lock;
} lte_ue_context_list_t;

// Function to initialize the list with a given capacity
void lte_ue_context_list_init(lte_ue_context_list_t *list, size_t capacity) {
    // Allocate memory for the data structure and its lock
    list->capacity = capacity;
    list->size = 0;
    list->data = malloc(sizeof(lte_ue_context_t*) * capacity);
    list->lock = (pthread_mutex_t*)malloc(sizeof(pthread_mutex_t));
    // Initialize the lock and set its type to PTHREAD_MUTEX_RECURSIVE, which allows
    // recursive locking of the mutex. This is necessary for thread safety in concurrent access.
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(list->lock, &attr);
}

// Function to add a new LTE UE context to the list
void lte_ue_context_list_add(lte_ue_context_list_t *list, int ue_id, int cell_id) {
    // Acquire the lock for exclusive access to the list
    pthread_mutex_lock(list->lock);
    // Check if the capacity of the list has been exceeded and resize it if necessary
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->data = realloc(list->data, sizeof(lte_ue_context_t*) * list->capacity);
    }
    // Generate a random sequence of bytes representing the payload for the new DL-TCH data
    char *dl_tch = generate_random_sequence(1024);
    // Create a new LTE UE context with the given UE ID and cell ID, as well as the generated DL-TCH data
    lte_ue_context_t *new_ctx = malloc(sizeof(lte_ue_context_t));
    new_ctx->ue_id = ue_id;
    new_ctx->cell_id = cell_id;
    new_ctx->dl_tch = dl_tch;
    new_ctx->last_update = time(NULL);
    new_ctx->ref_count = 0;
    // Add the new LTE UE context to the list and increment its reference count
    list->data[list->size++] = new_ctx;
    pthread_mutex_unlock(list->lock);
}

// Function to update an existing LTE UE context in the list with the given DL-TCH data
void lte_ue_context_list_update(lte_ue_context_list_t *list, int ue_id, char *dl_tch) {
    // Acquire the lock for exclusive access to the list
    pthread_mutex_lock(list->lock);
    // Search for the LTE UE context with the given UE ID in the list
    lte_ue_context_t *ctx = NULL;
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->data[i]->ue_id == ue_id) {
            ctx = list->data[i];
            break;
        }
    }
    // Update the DL-TCH data in the LTE UE context if it was found
    if (ctx != NULL) {
        free(ctx->dl_tch);
        ctx->dl_tch = dl_tch;
        ctx->last_update = time(NULL);
        pthread_mutex_unlock(list->lock);
    } else {
        // If the LTE UE context was not found, add a new one with the given DL-TCH data
        lte_ue_context_list_add(list, ue_id, dl_tch);
        pthread_mutex_unlock(list->lock);
    }
}

// Function to query the list for a specific LTE UE context based on its UE ID
lte_ue_context_t* lte_ue_context_list_query(lte_ue_context_list_t *list, int ue_id) {
    // Acquire the lock for exclusive access to the list
    pthread_mutex_lock(list->lock);
    // Search for the LTE UE context with the given UE ID in the list
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->data[i]->ue_id == ue_id) {
            break;
        }
    }
    // Return the found LTE UE context or NULL if it was not found
    pthread_mutex_unlock(list->lock);
    return i < list->size ? list->data[i] : NULL;
}

// Function to query the list for a specific LTE UE context based on its cell ID
lte_ue_context_t* lte_ue_context_list_query_cell(lte_ue_context_list_t *list, int cell_id) {
    // Acquire the lock for exclusive access to the list
    pthread_mutex_lock(list->lock);
    // Search for the LTE UE context with the given cell ID in the list
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->data[i]->cell_id == cell_id) {
            break;
        }
    }
    // Return the found LTE UE context or NULL if it was not found
    pthread_mutex_unlock(list->lock);
    return i < list->size ? list->data[i] : NULL;
}

// Function to remove a specific LTE UE context from the list based on its UE ID
void lte_ue_context_list_remove(lte_ue_context_list_t *list, int ue_id) {
    // Acquire the lock for exclusive access to the list
    pthread_mutex_lock(list->lock);
    // Search for the LTE UE context with the given UE ID in the list
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->data[i]->ue_id == ue_id) {
            break;
        }
    }
    // If the LTE UE context was found, remove it from the list and decrement its reference count
    if (i < list->size) {
        free(list->data[i]->dl_tch);
        list->ref_count--;
        memmove(list->data + i, list->data + i + 1, sizeof(lte_ue_context_t*) * (list->size - i));
        list->size--;
    }
    pthread_mutex_unlock(list->lock);
}

// Function to remove a specific LTE UE context from the list based on its cell ID
void lte_ue_context_list_remove_cell(lte_ue_context_list_t *list, int cell_id) {
    // Acquire the lock for exclusive access to the list
    pthread_mutex_lock(list->lock);
    // Search for the LTE UE context with the given cell ID in the list
    size_t i;
    for (i = 0; i < list->size; i++) {
        if (list->data[i]->cell_id == cell_id) {
            break;
        }
    }
    // If the LTE UE context was found, remove it from the list and decrement its reference count
    if (i < list->size) {
        free(list->data[i]->dl_tch);
        list->ref_count--;
        memmove(list->data + i, list->data + i + 1, sizeof(lte_ue_context_t*) * (list->size - i));
        list->size--;
    }
    pthread_mutex_unlock(list->lock);
}

// Function to periodically clean up unused LTE UE contexts in the list based on their last update timestamp
void lte_ue_context_list_cleanup() {
    // Acquire the lock for exclusive access to the list
    pthread_mutex_lock(list->lock);
    // Search for the unused LTE UE contexts with stale last update timestamps and remove them from the list
    size_t i;
    time_t now = time(NULL);
    for (i = 0; i < list->size; i++) {
        if (list->data[i]->last_update + CLEANUP_PERIOD <= now) {
            free(list->data[i]->dl_tch);
            list->ref_count--;
            memmove(list->data + i, list->data + i + 1, sizeof(lte_ue_context_t*) * (list->size - i));
            list->size--;
        }
    }
    pthread_mutex_unlock(list->lock);
}
