struct ccch_pdu {
    uint16_t ue_id;
    struct ccch_channel_configurations *configurations;
};

struct ccch_channel_configurations {
    int32_t max_ccch_message_size;
    int32_t min_ccch_message_size;
    int32_t max_num_active_ue;
};

void load_json_data(const char *filename) {
    json_object *root = NULL, *config = NULL;
    json_object_foreach(root, key, val) {
        if (strcmp(key, "ccch") == 0) {
            config = json_object_get_object(val);
            break;
        }
    }
    if (!config) {
        fprintf(stderr, "Error: unable to find ccch configuration in JSON data\n");
        return;
    }

    int32_t max_ccch_message_size = json_object_get_int(json_object_get_object(config, "max-ccch-message-size"));
    int32_t min_ccch_message_size = json_object_get_int(json_object_get_object(config, "min-ccch-message-size"));
    int32_t max_num_active_ue = json_object_get_int(json_object_get_object(config, "max-num-active-ue"));
}

void create_and_populate_ccch_pdu_list() {
    // allocate memory for the list of CCCH PDUs
    struct ccch_pdu *ccch_pdus = malloc(sizeof(struct ccch_pdu) * max_num_active_ue);
    if (!ccch_pdus) {
        fprintf(stderr, "Error: unable to allocate memory for CCCH PDU list\n");
        return;
    }

    // initialize each element in the list with a valid UE ID and set of channel configurations
    for (int i = 0; i < max_num_active_ue; i++) {
        ccch_pdus[i].ue_id = i + 1;
        ccch_pdus[i].configurations = malloc(sizeof(struct ccch_channel_configurations));
        if (!ccch_pdus[i].configurations) {
            fprintf(stderr, "Error: unable to allocate memory for CCCH channel configurations\n");
            return;
        }
        ccch_pdus[i].configurations->max_ccch_message_size = max_ccch_message_size;
        ccch_pdus[i].configurations->min_ccch_message_size = min_ccch_message_size;
    }
}

void populate_ccch_pdu_list(struct ccch_pdu *ccch_pdus, int num_active_ue) {
    // iterate over the list of CCCH PDUs and set their channel configurations accordingly
    for (int i = 0; i < num_active_ue; i++) {
        struct ccch_channel_configurations *config = malloc(sizeof(struct ccch_channel_configurations));
        if (!config) {
            fprintf(stderr, "Error: unable to allocate memory for CCCH channel configurations\n");
            return;
        }
        config->max_ccch_message_size = max_ccch_message_size;
        config->min_ccch_message_size = min_ccch_message_size;
        ccch_pdus[i].configurations = config;
    }
}

void free_ccch_pdu_list(struct ccch_pdu *ccch_pdus, int num_active_ue) {
    // iterate over the list of CCCH PDUs and free their channel configurations
    for (int i = 0; i < num_active_ue; i++) {
        free(ccch_pdus[i].configurations);
        ccch_pdus[i].configurations = NULL;
    }

    // free the memory allocated for the list of CCCH PDUs
    free(ccch_pdus);
}
