    }
    list[i].CRC_Indication = (rand() % 2) ? true : false; // Randomly set CRC flag
  }

  return list;
}

// Function to read packet data from an external file or stream
void read_packet_data(FILE* file, L2_InformationElement* list, int num_elements) {
  if (!file || !list) {
    fprintf(stderr, "Invalid input!\n");
    return;
  }

  // Read packet data from the file or stream and populate the list
  for (int i = 0; i < num_elements; i++) {
    int UE_ID, MAC_PDU[10];
    bool CRC_Indication;
    fscanf(file, "%d %*s %*s %d", &UE_ID, &MAC_PDU, &CRC_Indication);
    list[i].UE_ID = UE_ID;
    for (int j = 0; j < 10; j++) {
      list[i].MAC_PDU[j] = MAC_PDU[j];
    }
    list[i].CRC_Indication = CRC_Indication;
  }
}
