L2_InformationElement* createList(size_t numElements, size_t maxUE_ID) {
    // Validate input
    if (numElements > 0 && maxUE_ID > 0) {
        // Allocate memory for the list and initialize it to NULL
        L2_InformationElement* list = calloc(numElements, sizeof(L2_InformationElement));
        if (list == NULL) {
            printf("Error: Memory allocation failed\n");
            return NULL;
        }

        // Loop through each element and populate it with random data
        for (size_t i = 0; i < numElements; i++) {
            list[i].UE_ID = rand() % maxUE_ID;
            list[i].MAC_PDU = malloc(512); // arbitrary size
            if (list[i].MAC_PDU == NULL) {
                printf("Error: Memory allocation failed\n");
                freeList(list, i);
                return NULL;
            }
            list[i].CRC_Indication = rand() % 2 ? true : false;
        }

        // Sort the list based on UE_ID in ascending order
        qsort(list, numElements, sizeof(L2_InformationElement), compareUE_ID);

        return list;
    } else {
        printf("Error: Invalid input\n");
        return NULL;
    }
}

// Function to search for an L2_InformationElement by UE_ID and return its index if found
size_t findByUE_ID(L2_InformationElement* list, size_t numElements, uint32_t UE_ID) {
    // Loop through each element in the list until the UE_ID is found or the end of the list is reached
    for (size_t i = 0; i < numElements; i++) {
        if (list[i].UE_ID == UE_ID) {
            return i;
        }
    }

    // If the UE_ID was not found, return -1
    return -1;
}

// Function to free memory allocated for the list of L2_InformationElement structures
void freeList(L2_InformationElement* list, size_t numElements) {
    // Loop through each element in the list and free its memory
    for (size_t i = 0; i < numElements; i++) {
        if (list[i].MAC_PDU != NULL) {
            free(list[i].MAC_PDU);
        }
    }

    // Free the list memory itself
    free(list);
}

// Comparison function for sorting the list based on UE_ID in ascending order
int compareUE_ID(const void* a, const void* b) {
    L2_InformationElement* ia = (L2_InformationElement*)a;
    L2_InformationElement* ib = (L2_InformationElement*)b;
    return ia->UE_ID - ib->UE_ID;
}
