#include <boost/thread.hpp>
#include <iostream>
#include <chrono>
#include <vector>
#include <string>

using namespace boost::asio;
using namespace std::literals::chrono_literals;

class ConfigManager {
public:
    virtual ~ConfigManager() = default;
    virtual const std::vector<std::string>& GetServerList() = 0;
};

class MonitoringClient {
public:
    explicit MonitoringClient(io_context& ioContext, const ConfigManager& config)
        : m_ioContext(ioContext), m_config(config) {}

    void Start() {
        for (const auto& server : m_config.GetServerList()) {
            boost::asio::ip::tcp::resolver resolver(m_ioContext);
            boost::asio::connect(m_socket, resolver.resolve(server));
        }
    }

    void Stop() {
        m_ioContext.stop();
    }

    void Run() {
        while (true) {
            const auto startTime = std::chrono::steady_clock::now();
            boost::asio::write(m_socket, boost::asio::buffer("GET / HTTP/1.1\r\nHost: localhost:8080\r\nConnection: close\r\nAccept-Encoding: gzip\r\n\r\n"));
            std::cout << "Request sent to " << m_socket.remote_endpoint() << std::endl;
            boost::asio::read(m_socket, response);
            const auto endTime = std::chrono::steady_clock::now();
            const auto latency = std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count();
            m_latencies.push_back(latency);
            std::cout << "Response received from " << m_socket.remote_endpoint() << ", latency: " << latency << "ms" << std::endl;
        }
    }

private:
    io_context& m_ioContext;
    const ConfigManager& m_config;
    boost::asio::ip::tcp::socket m_socket;
    boost::asio::streambuf response;
    std::vector<int> m_latencies;
};

class MonitoringClientFactory {
public:
    explicit MonitoringClientFactory(const ConfigManager& config) : m_config(config) {}

    std::unique_ptr<MonitoringClient> Create() {
        io_context ioContext;
        return std::make_unique<MonitoringClient>(ioContext, m_config);
    }

private:
    const ConfigManager& m_config;
};

int main() {
    auto config = new ConfigManager();
    config->GetServerList().push_back("http://server1.com");
    config->GetServerList().push_back("http://server2.com");
    MonitoringClientFactory factory(config);

    auto client = factory.Create();
    client->Start();

    std::thread clientThread([client] { client->Run(); });

    while (true) {
        // Track and print out metrics such as the number of successful health checks, proxy sessions established, internal errors, retries performed, and latency statistics.
        // Consider implementing a logging mechanism to record detailed operational data for later analysis.
        std::cout << "Metrics: ";
        std::cout << "Successful health checks: " << client->m_latencies.size() << ", ";
        std::cout << "Proxy sessions established: " << client->m_latencies.size() << ", ";
        std::cout << "Internal errors: 0, ";
        std::cout << "Retries performed: 0, ";
        std::cout << "Latency statistics (ms): ";
        for (const auto& latency : client->m_latencies) {
            std::cout << latency << ", ";
        }
        std::cout << std::endl;
    }
}
```
