State** generate_state_list(int num_states, int* states, FSA* fsa) {
    // Allocate memory for the state list and initialize it to NULL
    State** state_list = malloc(num_states * sizeof(State*));
    if (state_list == NULL) {
        return NULL;
    }

    // Initialize each state in the list to a new instance of the State struct
    for (int i = 0; i < num_states; i++) {
        state_list[i] = malloc(sizeof(State));
        if (state_list[i] == NULL) {
            return NULL;
        }
        state_list[i]->id = states[i];
        state_list[i]->name = NULL;
    }

    // Loop through each state in the FSA and create a new instance of the State struct for it
    for (int i = 0; i < fsa->num_states; i++) {
        int current_state = fsa->states[i];
        state_list[current_state] = malloc(sizeof(State));
        if (state_list[current_state] == NULL) {
            return NULL;
        }
        state_list[current_state]->id = current_state;
        state_list[current_state]->name = NULL;
    }

    // Loop through each transition in the FSA and add it to the corresponding state in the list
    for (int i = 0; i < fsa->num_transitions; i++) {
        int current_transition = fsa->transitions[i];
        int from_state = current_transition / fsa->alphabet_size;
        int to_state = current_transition % fsa->alphabet_size;
        state_list[from_state]->next = state_list[to_state];
    }

    // Update the 'next' pointer of the last state in the list to point to the newly created state list
    if (last_state != NULL) {
        last_state->next = state_list;
    }

    return state_list;
}
