// Structure for storing the encryption parameters and cipher context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
    int keylen;
    unsigned char *key;
} EncryptionParams;

// Function for selecting the appropriate encryption algorithm based on the input string
EVP_CIPHER* selectCipher(const char *name) {
    if (strcasecmp("aes-128", name) == 0 || strcasecmp("AES-128", name) == 0) {
        return EVP_aes_128_ecb();
    } else if (strcasecmp("aes-256", name) == 0 || strcasecmp("AES-256", name) == 0) {
        return EVP_aes_256_ecb();
    } else if (strcasecmp("chacha20", name) == 0 || strcasecmp("CHACHA20", name) == 0) {
        return EVP_chacha20();
    } else {
        return NULL;
    }
}

// Function for generating the encryption parameters based on the input string
EncryptionParams* generateEncryptionParams(const char *name, const unsigned char *key, int keylen) {
    EncryptionParams *params = (EncryptionParams*) malloc(sizeof(EncryptionParams));
    params->cipher = selectCipher(name);
    if (params->cipher == NULL) {
        return NULL;
    }
    params->keylen = keylen;
    params->key = (unsigned char*) malloc(keylen);
    memcpy(params->key, key, keylen);
    return params;
}

// Function for encrypting the data using the selected cipher
void encryptData(EncryptionParams *params, const unsigned char *data, int datalen) {
    EVP_CIPHER_CTX *ctx = NULL;
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return;
    }
    if (!EVP_EncryptInit_ex(ctx, params->cipher, NULL, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    if (!EVP_CIPHER_CTX_set_padding(ctx, 0)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    if (!EVP_EncryptInit_ex(ctx, NULL, NULL, params->key, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    if (!EVP_EncryptUpdate(ctx, (unsigned char*) data, datalen)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    if (!EVP_EncryptFinal_ex(ctx, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    EVP_CIPHER_CTX_free(ctx);
}

// Function for decrypting the data using the selected cipher
void decryptData(EncryptionParams *params, const unsigned char *data, int datalen) {
    EVP_CIPHER_CTX *ctx = NULL;
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        return;
    }
    if (!EVP_DecryptInit_ex(ctx, params->cipher, NULL, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    if (!EVP_CIPHER_CTX_set_padding(ctx, 0)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    if (!EVP_DecryptInit_ex(ctx, NULL, NULL, params->key, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    if (!EVP_DecryptUpdate(ctx, (unsigned char*) data, datalen)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    if (!EVP_DecryptFinal_ex(ctx, NULL, NULL)) {
        EVP_CIPHER_CTX_free(ctx);
        return;
    }
    EVP_CIPHER_CTX_free(ctx);
}

// Function for handling errors and logging to a specified log file
void handleError(const char *file, int line, const char *func, const char *message) {
    FILE *log = fopen("encryption.log", "a+");
    if (log == NULL) {
        return;
    }
    fprintf(log, "%s:%d %s(): %s\n", file, line, func, message);
    fclose(log);
}

// Main function for encrypting and decrypting data using the selected cipher
void main() {
    // Load the encryption key from an external key management service (KMS)
    unsigned char *key = NULL;
    int keylen = 0;
    if (!loadKey(&key, &keylen)) {
        handleError(__FILE__, __LINE__, __FUNCTION__, "Failed to load encryption key");
        return;
    }

    // Encrypt the data using the selected cipher
    const unsigned char *data = (unsigned char*) "Hello World!";
    int datalen = strlen((const char*) data);
    EncryptionParams *params = generateEncryptionParams("aes-256", key, keylen);
    encryptData(params, data, datalen);

    // Decrypt the encrypted data using the selected cipher
    decryptData(params, data, datalen);

    // Free the encryption parameters and key memory
    free(key);
    free(params);
}
