// Synchronization mechanism for concurrent access
static pthread_mutex_t crcIndicationMutex = PTHREAD_MUTEX_INITIALIZER;

int createCrcIndicationStructures(int numStructures) {
    // Initialize custom memory pool if not already initialized
    if (crcIndicationPool == NULL) {
        crcIndicationPool = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numStructures);
        if (crcIndicationPool == NULL) {
            return -1;
        }
        crcIndicationPoolSize = numStructures;
        crcIndicationPoolIndex = 0;
    }

    // Lock mutex to ensure thread safety while populating structures
    pthread_mutex_lock(&crcIndicationMutex);

    int i, j;
    for (i = 0; i < numStructures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *crcIndication = &crcIndicationPool[i];

