    }

    // Unlock mutex and return the number of successfully created structures
    pthread_mutex_unlock(&crcIndicationMutex);
    return i;
}

int destroyCrcIndicationStructures(int numStructures) {
    // Lock mutex to ensure thread safety while freeing memory
    pthread_mutex_lock(&crcIndicationMutex);

    if (numStructures < 0 || crcIndicationPoolIndex - numStructures < 0) {
        return -1;
    }

    // Free custom memory pool
    free(crcIndicationPool);
    crcIndicationPool = NULL;
    crcIndicationPoolSize = 0;
    crcIndicationPoolIndex = 0;

    // Unlock mutex and return
    pthread_mutex_unlock(&crcIndicationMutex);
    return 0;
}

// Utility function to generate a random number within the given range
int generateRandomNumber(int min, int max) {
