```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    uint32_t rx_ue_information_tag;
    uint32_t rnti;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint32_t ue_id;
    char mac_address[18]; // Format: XX:XX:XX:XX:XX:XX
    int num_bearers;
    struct {
        uint16_t bearer_id;
        int is_active;
    } *bearers;
    struct {
        time_t start_time;
        int interval;
    } timer;
} LTE_UE_CONTEXT_T;

void populate_ue_contexts_and_crc_indications(NFAPI_CRC_INDICATION_PDU_T **crc_indications, LTE_UE_CONTEXT_T **ue_contexts, size_t num_ues) {
    // Allocate memory for the list of CRC indication PDUs and UE contexts
    *crc_indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_ues);
    *ue_contexts = (LTE_UE_CONTEXT_T *)malloc(sizeof(LTE_UE_CONTEXT_T) * num_ues);

    // Initialize the list of CRC indication PDUs and UE contexts with random data
    for (size_t i = 0; i < num_ues; i++) {
        (*crc_indications)[i].rx_ue_information_tag = rand();
        (*crc_indications)[i].rnti = rand();
        (*crc_indications)[i].crc_flag = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        (*ue_contexts)[i].ue_id = i + 1;
        strcpy((*ue_contexts)[i].mac_address, "XX:XX:XX:XX:XX:XX"); // Format: XX:XX:XX:XX:XX:XX
        (*ue_contexts)[i].num_bearers = rand() % 10; // Randomly set number of bearers to 0-9

        // Initialize timers for each UE context
        (*ue_contexts)[i].timer.start_time = time(NULL);
        (*ue_contexts)[i].timer.interval = rand() % 1000; // Randomly set retransmission interval to 0-999

        for (int j = 0; j < (*ue_contexts)[i].num_bearers; j++) {
            (*ue_contexts)[i].bearers[j].bearer_id = rand() % 1000; // Randomly set bearer ID to 0-999
            (*ue_contexts)[i].bearers[j].is_active = rand() % 2; // Randomly set active status to 0 or 1
        }
    }
}
```
