    context->rnti = rnti;
    context->signal_strength = 0.0;

    // Return a pointer to the newly created LTE UE Context structure
    return context;
}

// Define a function to add an LTE UE Context to the linked list
void add_lte_ue_context(node_t *list, lte_ue_context_t *context) {
    // Check if the linked list is empty
    if (!list) {
        // If the linked list is empty, create a new node and point it to the context
        list = (node_t *)malloc(sizeof(node_t));
        list->data = context;
        list->next = NULL;
    } else {
        // Otherwise, add the context to the end of the linked list
        node_t *current = list;
        while (current->next) {
            current = current->next;
        }
        current->next = (node_t *)malloc(sizeof(node_t));
        current->next->data = context;
        current->next->next = NULL;
    }
}

// Define a function to remove an LTE UE Context from the linked list
