        while (current->next && current->next->data->signal_strength < list->data->signal_strength) {
            current = current->next;
        }
        remove_lte_ue_context(list, current->data->ue_id);
    }
}

// Define a function to count the number of LTE UE Contexts in the linked list
int count_lte_ue_contexts(node_t *list) {
    int count = 0;
    node_t *current = list;
    while (current) {
