        node_t *current = list;
        while (current->next && current->data->ue_id != ue_id) {
            current = current->next;
        }
        if (current->data->ue_id == ue_id) {
            // If the UE ID is found, add a new measurement report to the context
            lte_ue_context_t *context = current->data;
            context->signal_strength += signal_strength;
        } else {
            // Otherwise, create a new LTE UE Context structure and add it to the linked list
            lte_ue_context_t *context = create_lte_ue_context(ue_id, 0);
            if (context) {
                context->signal_strength += signal_strength;
                add_lte_ue_context(list, context);
            } else {
                // If memory allocation fails, log an error message and do nothing
                fprintf(stderr, "Failed to allocate memory for LTE UE Context\n");
            }
        }
    }
}

// Define a function to remove all LTE UE Contexts from the linked list
void clear_lte_ue_contexts(node_t *list) {
    // Check if the linked list is empty
    if (!list) {
        // If the linked list is empty, do nothing
        return;
    } else {
        // Otherwise, remove all LTE UE Contexts from the linked list and free their memory
        node_t *current = list;
        while (current->next) {
