#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>
#include <pthread.h>

// Define the structure for UE context
struct ue_context {
    int ue_id;
    unsigned short rnti;
    struct measurement_report *reports;
};

// Define a list data structure to store UE contexts
typedef struct ue_list {
    struct ue_context **ue_contexts;
    size_t count;
} ue_list_t;

// Function to create and populate a list of UE contexts
int populate_ue_list(ue_list_t *list, const int num_ues) {
    assert(list != NULL);

    // Dynamically allocate memory for the list of UE contexts
    struct ue_context **ue_contexts = malloc(sizeof(struct ue_context *) * num_ues);
    if (ue_contexts == NULL) {
        return -1;
    }

    // Initialize the list with empty UE contexts
    for (int i = 0; i < num_ues; ++i) {
        ue_contexts[i] = malloc(sizeof(struct ue_context));
        if (ue_contexts[i] == NULL) {
            return -1;
        }
    }

    // Populate the list with random UE IDs, RNTIs, and measurement reports
    for (int i = 0; i < num_ues; ++i) {
        ue_contexts[i]->ue_id = rand();
        ue_contexts[i]->rnti = rand() % 10000;
        struct measurement_report *reports = malloc(sizeof(struct measurement_report));
        if (reports == NULL) {
            return -1;
        }
        for (int j = 0; j < 10; ++j) {
            reports->signal_strengths[j] = rand() % 100;
        }
        ue_contexts[i]->reports = reports;
    }

    // Set the count of UE contexts in the list to the number of UEs
    list->count = num_ues;

    // Return the pointer to the first element in the list
    return ue_contexts[0];
}

// Function to add a new UE context to the list
int add_ue_to_list(ue_list_t *list, int ue_id) {
    assert(list != NULL);

    // Dynamically allocate memory for the new UE context
    struct ue_context *ue_context = malloc(sizeof(struct ue_context));
    if (ue_context == NULL) {
        return -1;
    }

    // Set the UE ID and RNTI of the new UE context to random values
    ue_context->ue_id = rand();
    ue_context->rnti = rand() % 10000;

    // Dynamically allocate memory for the measurement reports
    struct measurement_report *reports = malloc(sizeof(struct measurement_report));
    if (reports == NULL) {
        return -1;
    }

    // Initialize the signal strengths in the new UE context's measurement reports
    for (int i = 0; i < 10; ++i) {
        reports->signal_strengths[i] = rand() % 100;
    }

    // Set the pointer to the new UE context in the list
    ue_context->reports = reports;
    list->ue_contexts[list->count++] = ue_context;

    return 0;
}

// Function to remove a UE context from the list
int remove_ue_from_list(ue_list_t *list, int ue_id) {
    assert(list != NULL);

    // Find the index of the UE context with the given UE ID in the list
    size_t i = 0;
    while (i < list->count && list->ue_contexts[i]->ue_id != ue_id) {
        ++i;
    }

    // If the UE context is not found, return an error
    if (i == list->count) {
        return -1;
    }

    // Remove the UE context from the list by overwriting it with the last element
    struct ue_context *ue_context = list->ue_contexts[i];
    list->ue_contexts[i] = list->ue_contexts[list->count - 1];

    // Free the memory of the removed UE context and its measurement reports
    free(ue_context);
    free(ue_context->reports);

    // Decrement the count of UE contexts in the list
    --list->count;

    return 0;
}

// Function to fetch updated measurement reports from a remote server
void *fetch_remote_reports(void *args) {
    assert(args != NULL);

    // Cast the arguments to the correct data types
    ue_list_t *list = (ue_list_t *) args;
    int num_ues = list->count;

    // Fetch updated measurement reports from the remote server asynchronously
    for (int i = 0; i < num_ues; ++i) {
        struct ue_context *ue_context = list->ue_contexts[i];
        char url[1024];
        sprintf(url, "http://remote-server/measurement_reports?ue_id=%d", ue_context->ue_id);
        http_get(url, ue_context->reports);
    }

    return NULL;
}

// Function to manage the list of UE contexts efficiently
void manage_list(ue_list_t *list) {
    assert(list != NULL);

    // Dynamically allocate memory for a new thread pool
    pthread_t threads[10];

    // Initialize each thread in the pool with a function to fetch updated measurement reports from a remote server
    for (int i = 0; i < 10; ++i) {
        pthread_create(&threads[i], NULL, fetch_remote_reports, list);
    }

    // Join each thread in the pool with the main processing thread
    for (int i = 0; i < 10; ++i) {
        pthread_join(threads[i], NULL);
    }
}
