nfapi_crc_indication_pdu_t* create_crc_indication_list(int n) {
    // Dynamically allocate memory for the list
    nfapi_crc_indication_pdu_t* list = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t) * n);
    if (!list) {
        // Handle memory allocation failure
        return NULL;
    }

    // Initialize the list with random RX_UE_INFORMATION_TAG and RNTI values
    for (int i = 0; i < n; i++) {
        list[i].rx_ue_information_tag = rand() % 1024;
        list[i].rnti = ((long long)rand()) << 32 | rand();
    }

    // Set the CRC flag for each element to a random value
    for (int i = 0; i < n; i++) {
        list[i].crc_indication_repl8.crflag = arc4random_uniform(2);
    }

    return list;
}

// Function to handle dynamic memory allocation and deallocation for the list
void free_crc_indication_list(nfapi_crc_indication_pdu_t* list) {
    if (list) {
        // Free the memory allocated for the list
        free(list);
    }
}

// Function to handle unique RNTIs by using a hash table
void populate_rnti_hash_table(nfapi_crc_indication_pdu_t* list, int n) {
    // Create a hash table for storing the RNTI values
    typedef struct {
        long long rnti;
        bool exists;
    } rnti_hash_table_t;
    rnti_hash_table_t* rnti_hash = (rnti_hash_table_t*)malloc(sizeof(rnti_hash_table_t) * n);
    if (!rnti_hash) {
        // Handle memory allocation failure
        return;
    }

    // Initialize the hash table with random RNTI values
    for (int i = 0; i < n; i++) {
        rnti_hash[i].rnti = list[i].rnti;
        rnti_hash[i].exists = true;
    }

    // Loop through the hash table to check for duplicate RNTIs and retry if necessary
    for (int i = 0; i < n; i++) {
        while (rnti_hash[i].exists) {
            list[i].rnti = ((long long)rand()) << 32 | rand();
            rnti_hash[i].exists = false;
        }
    }

    // Free the memory allocated for the hash table
    free(rnti_hash);
}
