// Define the function to create and parameterize an SQL command using the provided values and return an IDataReader for the result set
void executeSqlCommand(sqlite3 *db, char *sql, int N, int *array) {
    // Prepare the SQL command
    sqlite3_stmt *stmt = NULL;
    int rc = sqlite3_prepare_v2(db, sql, -1, &stmt, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error preparing SQL statement: %s\n", sqlite3_errmsg(db));
        return;
    }

    // Bind the values to the SQL command
    for (int i = 0; i < N; i++) {
        sqlite3_bind_int(stmt, i + 1, array[i]);
    }

    // Execute the SQL command and retrieve the result set as an IDataReader
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_ROW) {
        fprintf(stderr, "Error executing SQL statement: %s\n", sqlite3_errmsg(db));
        return;
    }
}

int main() {
