    sqlite3 *db = NULL;
    char *sql = "CREATE TABLE IF NOT EXISTS mytable (id INTEGER PRIMARY KEY, value INTEGER)";
    int rc = sqlite3_open("mydatabase.db", &db);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error opening database: %s\n", sqlite3_errmsg(db));
        return -1;
    }
    rc = sqlite3_exec(db, sql, NULL, NULL, NULL);
    if (rc != SQLITE_OK) {
        fprintf(stderr, "Error creating table: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Populate the list of NFAPI_CRC_INDICATION_PDU_T structures with random data
