['Here is an example implementation of the `initializeCellularUeInfo` function:
```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    uint32_t ue_id;
    uint16_t rnti;
    bool crc_flag;
} CellularUeInfo_PDU_T;

typedef struct {
    CellularUeInfo_PDU_T* ue_info_list;
    size_t capacity;
    size_t count;
} UeInfoList;

UeInfoList* initializeCellularUeInfo(size_t num_ue_ids, uint32_t* ue_ids, uint16_t* rntis) {
    // Validate input parameters
    if (num_ue_ids <= 0 || !ue_ids || !rntis) {
        return NULL;
    }

    // Allocate memory for the list and its contents
    UeInfoList* list = malloc(sizeof(UeInfoList));
    if (!list) {
        fprintf(stderr, "Error: failed to allocate memory for UeInfoList\n");
        return NULL;
    }
    list->ue_info_list = malloc(num_ue_ids * sizeof(CellularUeInfo_PDU_T));
    if (!list->ue_info_list) {
        fprintf(stderr, "Error: failed to allocate memory for CellularUeInfo_PDU_T list\n");
        free(list);
        return NULL;
    }
    list->capacity = num_ue_ids;
    list->count = 0;

    // Populate the list with UE IDs and RNTIs
    for (size_t i = 0; i < num_ue_ids; i++) {
        CellularUeInfo_PDU_T* ue_info = &list->ue_info_list[i];
        ue_info->ue_id = ue_ids[i];
        ue_info->rnti = rntis[i];
        ue_info->crc_flag = (rand() % 2) == 0; // Randomly set CRC flag to true or false
    }

    return list;
}

void freeCellularUeInfo(UeInfoList* list) {
    if (!list) {
        return;
    }
    free(list->ue_info_list);
    free(list);
}
```
