    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to allocate memory for and initialize arrays
void allocate_and_initialize_arrays(int numRecords, int *offsetArr, int *keyArr, record_t **recordArr, NFAPI_CRC_INDICATION_PDU_T **nfapiCrcIndicationPduArr) {
    // Allocate memory for the offset array
    offsetArr = (int *)malloc(numRecords * sizeof(int));
    if (!offsetArr) {
        perror("Failed to allocate memory for offset array");
        exit(EXIT_FAILURE);
    }

    // Initialize the offset array with random values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        offsetArr[i] = rand() % 100;
    }

    // Allocate memory for the key array
    keyArr = (int *)malloc(numRecords * sizeof(int));
    if (!keyArr) {
        perror("Failed to allocate memory for key array");
        exit(EXIT_FAILURE);
    }

    // Initialize the key array with random values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        keyArr[i] = rand() % 100;
    }

    // Allocate memory for the record array
    recordArr = (record_t **)malloc(numRecords * sizeof(record_t));
    if (!recordArr) {
        perror("Failed to allocate memory for record array");
        exit(EXIT_FAILURE);
    }

    // Initialize the record array with random values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        recordArr[i] = malloc(sizeof(record_t));
        if (!recordArr[i]) {
            perror("Failed to allocate memory for a single record");
            exit(EXIT_FAILURE);
        }
        recordArr[i]->key = rand() % 100;
    }

    // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T array
    nfapiCrcIndicationPduArr = (NFAPI_CRC_INDICATION_PDU_T **)malloc(numRecords * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfapiCrcIndicationPduArr) {
        perror("Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T array");
        exit(EXIT_FAILURE);
    }

    // Initialize the NFAPI_CRC_INDICATION_PDU_T array with random values
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        nfapiCrcIndicationPduArr[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!nfapiCrcIndicationPduArr[i]) {
            perror("Failed to allocate memory for a single NFAPI_CRC_INDICATION_PDU_T");
            exit(EXIT_FAILURE);
        }
        nfapiCrcIndicationPduArr[i]->rxUeInformationTag = rand() % 100;
        nfapiCrcIndicationPduArr[i]->rnti = rand() % 100;
        nfapiCrcIndicationPduArr[i]->crcIndicationRel8Tag.crCFlag = rand() % 2;
    }
}

// Define the function to execute the background command
void execute_background_command(int numRecords, int *offsetArr, int *keyArr, record_t **recordArr, NFAPI_CRC_INDICATION_PDU_T **nfapiCrcIndicationPduArr) {
    // Fork a child process to execute the background command
    pid_t pid = fork();
    if (pid < 0) {
        perror("Failed to fork a child process");
        exit(EXIT_FAILURE);
    } else if (pid == 0) {
        // Child process: Execute the background command
        printf("Child process executing...\n");

        // Use the data from the arrays in the background command
        for (int i = 0; i < numRecords; i++) {
            // Use the offset array to calculate some value
            int calculatedValue = offsetArr[i] * keyArr[i];

            // Use the record array to store some data
            recordArr[i]->key = calculatedValue;

            // Use the NFAPI_CRC_INDICATION_PDU_T array to store some data
            nfapiCrcIndicationPduArr[i]->rxUeInformationTag = calculatedValue;
        }

        // Wait for the background command to finish
        wait(NULL);
    } else {
        // Parent process: Monitor the execution of the background command
        printf("Parent process monitoring...\n");
    }
}

int main() {
    int numRecords = 10; // Number of records to process

    // Allocate memory for and initialize the arrays
    int *offsetArr, *keyArr;
    record_t **recordArr;
    NFAPI_CRC_INDICATION_PDU_T **nfapiCrcIndicationPduArr;
    allocate_and_initialize_arrays(numRecords, offsetArr, keyArr, recordArr, nfapiCrcIndicationPduArr);

    // Execute the background command
    execute_background_command(numRecords, offsetArr, keyArr, recordArr, nfapiCrcIndicationPduArr);

    return 0;
}
