                break;
            }
        }
    }

    return 0;
}

int get_list_size(NFAPI_CRC_INDICATION_PDU_T *list) {
    int size = 0;
    while (list != NULL && list->rnti != 0x0000) {
        size++;
        list = list->next;
    }
    return size;
}

NFAPI_CRC_INDICATION_PDU_T *get_nth_entry(NFAPI_CRC_INDICATION_PDU_T *list, int n) {
    if (n < 0 || list == NULL) {
        return NULL; // Invalid input
    }
    while (list != NULL && n > 0) {
        list = list->next;
        n--;
    }
    return list;
}

int add_entry(NFAPI_CRC_INDICATION_PDU_T *list, NFAPI_CRC_INDICATION_PDU_T entry) {
    // Ensure that the new entry has a unique RNTI
    if (get_list_size(list) >= 500 || get_nth_entry(list, get_list_size(list) - 1)->rnti == entry.rnti) {
        return -2; // List size exceeded or new entry has a duplicate RNTI
    }

    // Add the new entry to the end of the list
    NFAPI_CRC_INDICATION_PDU_T *new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_entry == NULL) {
        return -1; // Memory allocation failed
    }
    memcpy(new_entry, &entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_entry->next = NULL;

    NFAPI_CRC_INDICATION_PDU_T *last_entry = get_nth_entry(list, get_list_size(list) - 1);
    if (last_entry == NULL) {
        return -3; // List is empty or new entry has a duplicate RNTI
    }
    last_entry->next = new_entry;

    return 0;
}

int remove_entry(NFAPI_CRC_INDICATION_PDU_T *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (list == NULL || entry == NULL) {
        return -1; // Invalid input
    }

    // Remove the specified entry from the list
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;
    while (list != NULL && list->next != entry) {
        prev = list;
        list = list->next;
    }
    if (list == NULL) {
        return -2; // Entry not found in the list
    }
    if (prev == NULL) {
        list = list->next;
    } else {
        prev->next = list->next;
    }

    free(entry);

    return 0;
}

