    *pdu_list = (LTE_PHY_RX_PDU_T *)malloc(num_pdus * sizeof(LTE_PHY_RX_PDU_T));
    if (*pdu_list == NULL) {
        printf("Error: Failed to allocate memory for PDU list\n");
        return -1;
    }

    // Populate the list with random data
    srand(seed);
    for (int i = 0; i < num_pdus; i++) {
        LTE_PHY_RX_PDU_T *pdu = &(*pdu_list)[i];
        pdu->channel.carrier_to_noise_ratio = rand() % 100;
        pdu->payload.crc_status = (rand() % 2 == 0) ? true : false;
        pdu->sync.lock_status = (rand() % 2 == 0) ? true : false;
    }

    // Clean up the list on error or return
    if (*pdu_list == NULL) {
        free(*pdu_list);
        *pdu_list = NULL;
    }

    return num_pdus;
}

// Function to clean up memory for the PDU list
void free_pdu_list(LTE_PHY_RX_PDU_T **pdu_list) {
    if (*pdu_list != NULL) {
        free(*pdu_list);
        *pdu_list = NULL;
    }
}

// Function to print the PDU list
void print_pdu_list(LTE_PHY_RX_PDU_T **pdu_list, int num_pdus) {
    printf("PDU List:\n");
    for (int i = 0; i < num_pdus; i++) {
        LTE_PHY_RX_PDU_T *pdu = &(*pdu_list)[i];
        printf("\tChannel: %d\n", pdu->channel.carrier_to_noise_ratio);
        printf("\tPayload: %s\n", (pdu->payload.crc_status) ? "Valid" : "Invalid");
        printf("\tSync: %s\n", (pdu->sync.lock_status) ? "Locked" : "Unlocked");
    }
}

// Main function to test the PDU list generation and printing functionality
int main() {
    LTE_PHY_RX_PDU_T *pdu_list = NULL;
    int num_pdus = 10;
    unsigned long seed = 42;

    // Generate the PDU list with random data and print it
    generate_pdu_list(&pdu_list, num_pdus, seed);
    print_pdu_list(&pdu_list, num_pdus);

    // Clean up memory for the PDU list
    free_pdu_list(&pdu_list);

    return 0;
}']

