// Define the maximum number of structures in the list
#define NFAPI_CRC_INDICATION_PDU_LIST_MAX_SIZE 100000

// Define a function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_create_crc_indication_pdu_list(size_t n, unsigned char rx_ue_information_tag) {
    // Check if the list is already initialized
    if (nfapi_crc_indication_pdu_list != NULL) {
        // Free any existing memory allocated for the list
        free(nfapi_crc_indication_pdu_list);
    }

    // Allocate memory for the list
    nfapi_crc_indication_pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (nfapi_crc_indication_pdu_list == NULL) {
        // Log an error message if memory allocation failed
        printf("Error: Failed to allocate memory for NFAPI CRC indication PDU list\n");
        return;
    }

    // Initialize the list size
    nfapi_crc_indication_pdu_list_size = 0;

    // Generate random CRCFLAG values using the custom random number generator function
    unsigned int crcflag = generate_random_crflag();

    // Populate the list with the specified number of structures
    for (size_t i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &nfapi_crc_indication_pdu_list[i];
        pdu->rx_ue_information_tag = rx_ue_information_tag;
        pdu->rnti = i + 1; // Assign a unique RNTI value for each structure
        pdu->crc_indication_rel8_tag = (unsigned short)((crcflag >> i) & 0xffff); // Generate a random CRCFLAG value for each structure
    }
}

// Define a function to add a new structure to the list of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_add_crc_indication_pdu(unsigned char rx_ue_information_tag, unsigned short rnti, unsigned short crc_indication_rel8_tag) {
    // Check if the list is already initialized
    if (nfapi_crc_indication_pdu_list == NULL) {
        nfapi_create_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_LIST_MAX_SIZE, rx_ue_information_tag);
    }

    // Check if the list is full
    if (nfapi_crc_indication_pdu_list_size == NFAPI_CRC_INDICATION_PDU_LIST_MAX_SIZE) {
        return;
    }

    // Add a new structure to the list
    nfapi_crc_indication_pdu_list[nfapi_crc_indication_pdu_list_size].rx_ue_information_tag = rx_ue_information_tag;
    nfapi_crc_indication_pdu_list[nfapi_crc_indication_pdu_list_size].rnti = rnti;
    nfapi_crc_indication_pdu_list[nfapi_crc_indication_pdu_list_size].crc_indication_rel8_tag = crc_indication_rel8_tag;

    // Increment the list size
    nfapi_crc_indication_pdu_list_size++;
}

// Define a function to retrieve a structure from the list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *nfapi_get_crc_indication_pdu(unsigned short rnti) {
    // Check if the list is initialized and not empty
    if (nfapi_crc_indication_pdu_list == NULL || nfapi_crc_indication_pdu_list_size == 0) {
        return NULL;
    }

    // Search for the specified RNTI value in the list
    for (size_t i = 0; i < nfapi_crc_indication_pdu_list_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &nfapi_crc_indication_pdu_list[i];
        if (pdu->rnti == rnti) {
