        }

        // Update the RX_UE_INFORMATION_TAG values in the list of structures with the new batch of UE information
        for (int j = 0; j < batch_size && i * batch_size + j < num_entries; j++) {
            pdu_list[i * batch_size + j].rx_ue_information_tag = rx_ue_information_tag_batch[j];
