#define MAX_BITS_IN_BYTE 8

// Struct to represent an LTE PHY layer packet
struct lte_phy_packet {
    uint16_t ue_id;
    uint16_t cell_id;
    int32_t num_symbols;
    char* symbols; // Dynamically allocated memory for the symbol data
};

// Function to generate a list of LTE PHY layer packets with random bit values
void generate_lte_phy_packets(uint16_t num_packets, uint32_t num_symbols, char* predefined_pattern) {
    // Declare variables for the generated packets and the current packet index
    struct lte_phy_packet* packets = NULL;
    int32_t curr_packet = 0;

    // Dynamically allocate memory for the generated packets
    packets = (struct lte_phy_packet*) malloc(num_packets * sizeof(struct lte_phy_packet));

    // Initialize the UE IDs and cell IDs for each packet from an external source
    for (int32_t i = 0; i < num_packets; i++) {
        packets[i].ue_id = get_next_ue_id();
        packets[i].cell_id = get_next_cell_id();
        packets[i].num_symbols = num_symbols;
    }

    // Generate random bit values for each symbol in the packet
    for (int32_t i = 0; i < num_packets; i++) {
        // Allocate memory for the symbols data based on the number of symbols per packet
        packets[i].symbols = (char*) malloc(num_symbols * sizeof(char));

        for (int32_t j = 0; j < num_symbols; j++) {
            // Generate a random bit value between 0 and 1
            int8_t random_bit = rand() % 2;

            // Write the random bit to the corresponding symbol in the packet
            packets[i].symbols[j] = (char) random_bit;
        }
    }

    // Verify the integrity of each generated packet against a predefined pattern
    for (int32_t i = 0; i < num_packets; i++) {
        char* curr_symbols = packets[i].symbols;
        int32_t symbol_index = 0;

        // Iterate through each symbol in the packet and compare it to the predefined pattern
        while (symbol_index < num_symbols) {
            if (curr_symbols[symbol_index] != predefined_pattern[symbol_index]) {
                // If a mismatch is found, deallocate memory for the current packet and break out of the loop
                free(packets[i].symbols);
                packets[i].symbols = NULL;
                break;
            }

            symbol_index++;
        }
    }

    // Deallocate memory for any packets that failed the integrity check
    for (int32_t i = 0; i < num_packets; i++) {
        if (packets[i].symbols == NULL) {
            free(packets[i].symbols);
            packets[i] = NULL;
        }
    }
}
