#include <vector>
#include <algorithm>
#include <cstring>
#include <dirent.h>
#include <sys/stat.h>
#include <errno.h>

using namespace std;

void convertJPEGtoPDF(char* inputDir, char* outputDir) {
    // Dynamic adjustment of compression level based on file size
    int compressionLevel = 10;
    struct stat st;
    if (stat(inputDir, &st) == -1) {
        perror("stat");
        return;
    }
    off_t inputFileSize = st.st_size;
    if (inputFileSize > 1024*1024) { // 1 MB
        compressionLevel = 7;
    } else if (inputFileSize > 512*1024) { // 512 KB
        compressionLevel = 5;
    }

    // Batch processing with limited number of concurrent conversions
    vector<string> inputFiles;
    DIR *d;
    struct dirent *dir;
    d = opendir(inputDir);
    if (d) {
        while ((dir = readdir(d)) != NULL) {
            if (strcmp(dir->d_name, ".") != 0 && strcmp(dir->d_name, "..") != 0) {
                inputFiles.push_back(inputDir + "/" + dir->d_name);
            }
        }
    }
    closedir(d);
    int numConversions = min((int)inputFiles.size(), 4); // limit number of concurrent conversions to 4
    vector<pid_t> conversionPids;
    for (int i=0; i<numConversions; i++) {
        pid_t pid = fork();
        if (pid == 0) { // child process
            char* inputFile = inputFiles[i].c_str();
            char* outputFile = outputDir + "/" + basename(inputFile);
            string command = "convert -compress jpeg_" + to_string(compressionLevel) + " " + inputFile + " " + outputFile;
            system(command.c_str());
        } else if (pid > 0) { // parent process
            conversionPids.push_back(pid);
        }
    }
    for (int i=0; i<conversionPids.size(); i++) {
        pid_t pid = waitpid(conversionPids[i], NULL, 0);
    }

    // Logging and error handling
    ofstream logFile("log.txt", ios::out | ios::app);
    for (int i=0; i<inputFiles.size(); i++) {
        char* inputFile = inputFiles[i].c_str();
        char* outputFile = outputDir + "/" + basename(inputFile);
        ifstream outputFileStream(outputFile, ios::in | ios::binary);
        if (outputFileStream.good()) {
            logFile << "Successfully converted " << inputFile << " to " << outputFile << endl;
        } else {
            logFile << "Error converting " << inputFile << " to " << outputFile << ": " << strerror(errno) << endl;
        }
    }
}
