// Define the structure for holding the RX UE information
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    uint8_t crcFlag;
} rx_ue_info_t;

// Define a list of rx_ue_info_t structures
typedef struct {
    size_t num_elements;
    size_t max_size;
    rx_ue_info_t* elements;
} rx_ue_info_list_t;

// Initialize the list of rx_ue_info_t structures with a given number of elements
void initialize_rx_ue_info_list(rx_ue_info_list_t* list, size_t num_elements) {
    // Check for null pointers and invalid input parameters
    if (list == NULL || num_elements == 0) {
        return;
    }

    // Allocate memory for the list elements
    list->num_elements = num_elements;
    list->max_size = num_elements * sizeof(rx_ue_info_t);
    list->elements = (rx_ue_info_t*) malloc(list->max_size);

    // Initialize the CRC flag for each element to a random value
    for (size_t i = 0; i < num_elements; ++i) {
        list->elements[i].crcFlag = rand() % 256;
    }
}

// Add an element to the list of rx_ue_info_t structures
void add_rx_ue_info(rx_ue_info_list_t* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Check for null pointers and invalid input parameters
    if (list == NULL || pdu.rx_ue_information_tag == NULL) {
        return;
    }

    // Increase the number of elements in the list by 1
    ++list->num_elements;

    // Allocate memory for the new element
    rx_ue_info_t* new_element = (rx_ue_info_t*) malloc(sizeof(rx_ue_info_t));
    if (new_element == NULL) {
        return;
    }

    // Initialize the CRC flag for the new element to a random value
    new_element->crcFlag = rand() % 256;

    // Copy the RX UE information from the input parameter to the new element
    memcpy(&new_element->pdu, pdu.rx_ue_information_tag, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add the new element to the list
    list->elements = (rx_ue_info_t*) realloc(list->elements, list->num_elements * sizeof(rx_ue_info_t));
    if (list->elements == NULL) {
        return;
    }
    list->elements[list->num_elements - 1] = *new_element;
}

// Free the memory used by the list of rx_ue_info_t structures
void free_rx_ue_info_list(rx_ue_info_list_t* list) {
    // Check for null pointers and invalid input parameters
    if (list == NULL || list->elements == NULL) {
        return;
    }

    // Free the memory used by each element in the list
    for (size_t i = 0; i < list->num_elements; ++i) {
        free(list->elements[i].rx_ue_information_tag);
    }

    // Free the memory used by the list itself
    free(list->elements);
}

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_and_populate_rx_ue_info_list(size_t num_elements) {
    // Initialize the list of rx_ue_info_t structures with the given number of elements
    rx_ue_info_list_t* list = (rx_ue_info_list_t*) malloc(sizeof(rx_ue_info_list_t));
    if (list == NULL) {
        return;
    }
    initialize_rx_ue_info_list(list, num_elements);

    // Add elements to the list until it reaches its maximum size
    while (list->num_elements < list->max_size) {
        add_rx_ue_info(list, NFAPI_CRC_INDICATION_PDU_T());
    }
}

// Function to get a random CRC flag value for the given RX UE information tag and RNTI
uint8_t get_random_crc_flag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Check for null pointers and invalid input parameters
    if (pdu == NULL || pdu->rx_ue_information_tag == NULL) {
        return 0;
    }

    // Initialize the CRC flag to a random value
    uint8_t crcFlag = rand() % 256;

    // Return the CRC flag value
    return crcFlag;
}
