    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// List to store thread-safe NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    pthread_mutex_t lock; // Mutex for synchronizing access to list
    size_t count; // Number of elements in the list
    NFAPI_CRC_INDICATION_PDU_T* data; // Array of NFAPI_CRC_INDICATION_PDU_T structures
} NFAPI_CRC_INDICATION_LIST_T;

// Function to create and populate a thread-safe list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_create(size_t size) {
    // Allocate memory for the list and its elements
    NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!list) {
        return NULL;
    }
    list->data = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }
    // Initialize the mutex and set the count to 0
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure to the list
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T* list, uint16_t rx_ue_information_tag, uint16_t rnti, uint8_t crc_indication_rel8_tag, bool crcflag) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->lock);
    // Increment the count and allocate memory for a new element
    list->count++;
    NFAPI_CRC_INDICATION_PDU_T* new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_element) {
        // If allocation fails, decrement the count and unlock the mutex
        list->count--;
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_element->rx_ue_information_tag = rx_ue_information_tag;
    new_element->rnti = rnti;
    new_element->crc_indication_rel8_tag = crc_indication_rel8_tag;
    new_element->crcflag = crcflag;
    // Append the new element to the end of the list
    list->data[list->count - 1] = new_element;
    pthread_mutex_unlock(&list->lock);
}

// Function to filter the list based on specific criteria (e.g., RNTI value or CRCFLAG status)
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_filter(NFAPI_CRC_INDICATION_LIST_T* list, uint16_t rnti, bool crcflag) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* new_data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->count);
    if (!new_data) {
        // If allocation fails, unlock the mutex and return NULL
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    int new_index = 0;
    for (int i = 0; i < list->count; i++) {
        if ((rnti == 0 || list->data[i]->rnti == rnti) && (crcflag == -1 || list->data[i]->crcflag == crcflag)) {
            new_data[new_index++] = *list->data[i];
        }
    }
    // Allocate memory for the filtered list and its elements
    NFAPI_CRC_INDICATION_LIST_T* filtered_list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!filtered_list) {
        free(new_data);
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }
    filtered_list->data = new_data;
    filtered_list->count = new_index;
    pthread_mutex_unlock(&list->lock);
    return filtered_list;
}

// Function to serialize the list into a JSON format file
void nfapi_crc_indication_list_serialize(NFAPI_CRC_INDICATION_LIST_T* list, const char* filename) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->lock);
    FILE* fp = fopen(filename, "w");
    if (!fp) {
        perror("fopen");
        return;
    }
    for (int i = 0; i < list->count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* element = &list->data[i];
        fprintf(fp, "{\"rx_ue_information_tag\": %d, \"rnti\": %d, \"crc_indication_rel8_tag\": %d, \"crcflag\": %s}\n",
            element->rx_ue_information_tag, element->rnti, element->crc_indication_rel8_tag, (element->crcflag ? "true" : "false"));
    }
    fclose(fp);
    pthread_mutex_unlock(&list->lock);
}

// Function to deserialize the list from a JSON format file into an existing structure
NFAPI_CRC_INDICATION_LIST_T* nfapi_crc_indication_list_deserialize(const char* filename, NFAPI_CRC_INDICATION_LIST_T* list) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&list->lock);
    FILE* fp = fopen(filename, "r");
    if (!fp) {
        perror("fopen");
        return NULL;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Parse the JSON data and validate its structure
        json_value* root = json_parse_string(line);
        if (!root) {
            fprintf(stderr, "Invalid JSON: %s\n", line);
            continue;
        }
        json_object* object = json_value_get_object(root);
        if (!object) {
            fprintf(stderr, "Invalid JSON object: %s\n", line);
            json_value_free(root);
            continue;
        }
        // Validate the RX_UE_INFORMATION_TAG and RNTI values
        int rx_ue_information_tag = json_object_get_number(object, "rx_ue_information_tag");
        if (rx_ue_information_tag <= 0) {
            fprintf(stderr, "Invalid RX_UE_INFORMATION_TAG value: %s\n", line);
            json_value_free(root);
            continue;
        }
        int rnti = json_object_get_number(object, "rnti");
        if (rnti <= 0) {
            fprintf(stderr, "Invalid RNTI value: %s\n", line);
            json_value_free(root);
            continue;
        }
        // Validate the CRCFLAG status
        int crcflag = json_object_get_boolean(object, "crcflag");
        if (crcflag < 0) {
            fprintf(stderr, "Invalid CRCFLAG value: %s\n", line);
            json_value_free(root);
            continue;
        }
        // Add the deserialized element to the list
        nfapi_crc_indication_list_add(list, rx_ue_information_tag, rnti, crcflag ? 1 : 0, true);
        json_value_free(root);
    }
    fclose(fp);
    pthread_mutex_unlock(&list->lock);
}
