void select_attack(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Calculate the attack selection probability based on the character's current state and in-game events
    float attack_selection_probability = 0.5;

    // If the character is currently healthy, increase the probability of selecting an attack
    if (pdu->health > 10) {
        attack_selection_probability += 0.2;
    }

    // If the character has enough energy to perform a special attack, increase the probability of selecting it
    if (pdu->energy > 50) {
        attack_selection_probability += 0.3;
    }

    // If there are enemy units in close proximity, increase the probability of selecting an attack that involves them
    if (pdu->num_enemies > 0) {
        attack_selection_probability += 0.2;
    }

    // Select an attack based on the calculated probability and set its cooldown period accordingly
    if (rand() < attack_selection_probability * RAND_MAX) {
        pdu->attack = 1;
        pdu->cooldown = rand() % 10 + 5;
    } else {
