void create_and_populate_nfapi_crc_indication_pdu(struct rnti_list* rnti_list, int num_rntis) {
    // Dynamically allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    struct nfapi_crc_indication_pdu** pdu_list = malloc(sizeof(struct nfapi_crc_indication_pdu*) * num_rntis);
    if (pdu_list == NULL) {
        // Handle memory allocation failure gracefully
        printf("Error: Failed to allocate memory for PDU list\n");
        return;
    }

    int i = 0;
    while (i < num_rntis) {
        struct rnti_list* rnti = &(rnti_list[i]);

        // Dynamically allocate memory for each PDU structure
        struct nfapi_crc_indication_pdu* pdu = malloc(sizeof(struct nfapi_crc_indication_pdu));
        if (pdu == NULL) {
            // Handle memory allocation failure gracefully
            printf("Error: Failed to allocate memory for PDU %d\n", i);
            return;
        }

        pdu->RX_UE_INFORMATION_TAG = rnti->RX_UE_INFORMATION_TAG;
        pdu->RNTI = rnti->rntis[0];
        pdu->CRCFLAG = (pdu->RNTI & 1) ? 1 : 0;

        // Add the PDU to the list
        pdu_list[i++] = pdu;
    }

    // Dynamically resize the list if necessary
    if (num_rntis > i) {
        struct nfapi_crc_indication_pdu** temp_list = realloc(pdu_list, sizeof(struct nfapi_crc_indication_pdu*) * num_rntis);
        if (temp_list == NULL) {
            // Handle memory allocation failure gracefully
            printf("Error: Failed to resize PDU list\n");
            return;
        }
        pdu_list = temp_list;
    }

    // Free the allocated memory when we're done with it
    for (int i = 0; i < num_rntis; ++i) {
        free(pdu_list[i]);
    }
    free(pdu_list);
}
