static int populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T **pdu_list, uint32_t max_size, uint16_t *rnti_list, uint32_t num_rntis) {
  // Check input parameters for validity and initialize output variables
  CHECK_NULL(pdu_list);
  assert(max_size > 0);
  assert(num_rntis > 0);
  *pdu_list = NULL;

  // Acquire the mutex to synchronize access to the RNTI cache
  pthread_mutex_lock(&mutex);

  // Update the RNTI cache if necessary
  if (cache_enabled && num_rntis > rnti_cache_size) {
    populate_rnti_cache(rnti_list, num_rntis);
    rnti_cache_size = num_rntis;
  }

  // Allocate memory for the output list and initialize each structure
  *pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_rntis * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  for (uint32_t i = 0; i < num_rntis; i++) {
    (*pdu_list)[i].RX_UE_INFORMATION_TAG = 0x1871; // Dummy value
    (*pdu_list)[i].RNTI = rnti_list[i];
    (*pdu_list)[i].CRCFLAG = (rnti_list[i] % 2) ? 1 : 0; // Set CRCFLAG based on the parity of RNTI
  }

  // Release the mutex and return
  pthread_mutex_unlock(&mutex);
  return num_rntis;
}

// Function to release memory allocated for a list of NFAPI_CRC_INDICATION_PDU_T structures
static void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T *pdu_list, uint32_t num_rntis) {
  // Check input parameters for validity
  CHECK_NULL(pdu_list);
  assert(num_rntis > 0);

  // Release the mutex to synchronize access to the RNTI cache
  pthread_mutex_lock(&mutex);

  // Free memory allocated for the output list and clear the cache if necessary
  free(pdu_list);
  if (cache_enabled && num_rntis > rnti_cache_size) {
    free(rnti_cache);
    rnti_cache = NULL;
    rnti_cache_size = 0;
  }

  // Release the mutex and return
  pthread_mutex_unlock(&mutex);
}
