        return NULL;
    }

    // Populate the CRC indication structure with the received RX UE information tag and RNTI
    pdu->rxUeInformationTag = rxUeInformationTag;
    pdu->rnti = rnti;

    // Generate a random value for the CRCFlag
    srand(time(NULL));
    unsigned int crcFlag = rand() % 2;

    // Set the CRCFlag in the CRC indication structure
    pdu->crcIndicationReL8.crCFlag = crcFlag;

    // Log the creation of the CRC indication structure for debugging purposes
    printf("Created CRC indication structure with RX UE information tag %d and RNTI %u\n", rxUeInformationTag, rnti);

    return pdu;
}

// Function to add a CRC indication structure to the list of structures
void addCrcIndication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Lock the mutex for thread safety when accessing the list
    pthread_mutex_lock(&crcIndicationsLock);

    // Allocate memory for a new structure in the list
    NFAPI_CRC_INDICATION_DATA_T *newData = (NFAPI_CRC_INDICATION_DATA_T *)malloc(sizeof(NFAPI_CRC_INDICATION_DATA_T));
    if (!newData) {
        fprintf(stderr, "Error: Failed to allocate memory for CRC indication data structure\n");
        pthread_mutex_unlock(&crcIndicationsLock);
        return;
    }

    // Populate the new structure with the received PDU
    newData->pdu = pdu;
    newData->crcFlag = pdu->crcIndicationReL8.crCFlag;

    // Add the new structure to the end of the list
    crcIndications = (NFAPI_CRC_INDICATION_DATA_T *)realloc(crcIndications, sizeof(NFAPI_CRC_INDICATION_DATA_T) * (numCrcIndications + 1));
    if (!crcIndications) {
        fprintf(stderr, "Error: Failed to reallocate memory for CRC indication list\n");
        free(newData);
        pthread_mutex_unlock(&crcIndicationsLock);
        return;
    }
    crcIndications[numCrcIndications++] = newData;

    // Unlock the mutex and return
    pthread_mutex_unlock(&crcIndicationsLock);
}

// Function to remove a CRC indication structure from the list of structures
void removeCrcIndication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Lock the mutex for thread safety when accessing the list
    pthread_mutex_lock(&crcIndicationsLock);

    // Find the index of the structure in the list that matches the received PDU
    int i;
    for (i = 0; i < numCrcIndications; ++i) {
        if (crcIndications[i]->pdu == pdu) {
            break;
        }
    }

    // If the structure was not found, unlock the mutex and return
    if (i == numCrcIndications) {
        fprintf(stderr, "Error: CRC indication structure not found\n");
        pthread_mutex_unlock(&crcIndicationsLock);
        return;
    }

    // Remove the structure from the list by shifting all structures after it to the left
    --numCrcIndications;
    for (int j = i + 1; j < numCrcIndications; ++j) {
        crcIndications[j - 1] = crcIndications[j];
    }

    // Free the memory for the removed structure and unlock the mutex
    free(crcIndications[numCrcIndications]);
    pthread_mutex_unlock(&crcIndicationsLock);
}

// Function to validate RX UE information tags against predefined whitelists or blacklists
void validateRxUeInformationTag(NFAPI_RX_UE_INFORMATION_TAG_T rxUeInformationTag) {
    // If a whitelist is defined, check if the received tag is in it
    if (whitelist && !isInWhitelist(rxUeInformationTag)) {
        fprintf(stderr, "Error: RX UE information tag %d is not in the whitelist\n", rxUeInformationTag);
        return;
    }

    // If a blacklist is defined, check if the received tag is in it
    if (blacklist && isInBlacklist(rxUeInformationTag)) {
        fprintf(stderr, "Error: RX UE information tag %d is in the blacklist\n", rxUeInformationTag);
        return;
    }
}

// Function to validate RNTIs against predefined whitelists or blacklists
void validateRnti(uint32_t rnti) {
    // If a whitelist is defined, check if the received RNTI is in it
    if (whitelist && !isInWhitelist(rnti)) {
        fprintf(stderr, "Error: RNTI %u is not in the whitelist\n", rnti);
        return;
