// CRC flag generation function
uint32_t generateCrcFlag() {
    uint32_t crcFlag = 0;
    // Generate a random number between 0 and 1
    double randomNumber = (double)rand() / RAND_MAX;
    if (randomNumber < 0.5) {
        crcFlag = 1;
    }
    return crcFlag;
}

// CRC flag validation function
bool validateCrcFlag(uint32_t crcFlag) {
    // Validate the generated CRCFLAG
    if (crcFlag == 0 || crcFlag == 1) {
        return true;
    } else {
        return false;
    }
}

// List initialization function
void listInit(LIST_T *list) {
    list->data = NULL;
    list->capacity = 0;
    list->length = 0;
}

// List insertion function
int listInsert(LIST_T *list, RX_UE_INFORMATION_TAG rxUETag, uint32_t crcIndicationTag) {
    // Create a new NFAPI_CRC_INDICATION_PDU_T structure
    NFAPI_CRC_INDICATION_PDU_T *newElement = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newElement == NULL) {
        return -1;
    }
    newElement->rxUETag = rxUETag;
    newElement->crcIndicationTag = crcIndicationTag;
    newElement->crcFlag = generateCrcFlag();

    // Check if the list needs to be resized
    if (list->capacity == 0) {
        list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (list->data == NULL) {
            free(newElement);
            return -1;
        }
        list->capacity = 1;
    } else if (list->length >= list->capacity) {
        list->data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T *) * list->capacity * 2);
        if (list->data == NULL) {
            free(newElement);
            return -1;
        }
        list->capacity *= 2;
    }

    // Add the new element to the list
    list->data[list->length] = newElement;
    list->length++;

    return 0;
}

// List deletion function
int listDelete(LIST_T *list, RX_UE_INFORMATION_TAG rxUETag) {
