    // Check if the element was found
    if (i >= list->length) {
        return -1;
    }

    // Delete the element from the list
    NFAPI_CRC_INDICATION_PDU_T *elementToDelete = list->data[i];
    list->length--;
    for (size_t j = i; j < list->length; j++) {
        list->data[j] = list->data[j + 1];
    }

    free(elementToDelete);

    return 0;
}

