        cache[i].rxUETag = element->rxUETag;
        cache[i].crcIndicationTag = element->crcIndicationTag;
        cache[i].crcFlag = element->crcFlag;
    }
}

// CRC flag validation function with caching
bool validateCrcFlagWithCache(uint32_t crcFlag) {
    // Validate the generated CRCFLAG using the cached values
    for (size_t i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].rxUETag == NULL || cache[i].crcIndicationTag == NULL) {
            break;
        } else if (cache[i].crcFlag == crcFlag) {
            return true;
        }
    }
    // If no cached value was found, validate the CRCFLAG using the original function
    return validateCrcFlag(crcFlag);
}

// List batch insertion function
int listBatchInsert(LIST_T *list, RX_UE_INFORMATION_TAG rxUETag, uint32_t crcIndicationTag) {
    // Create a new NFAPI_CRC_INDICATION_PDU_T structure for each element in the batch
    size_t numElements = 0;
    while (numElements < list->length && list->data[numElements]->rxUETag != rxUETag) {
        numElements++;
    }
    if (numElements >= list->length) {
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T *newElements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * numElements);
    if (newElements == NULL) {
        return -1;
    }

    // Insert the new elements into the list
    for (size_t i = 0; i < numElements; i++) {
        NFAPI_CRC_INDICATION_PDU_T *element = list->data[i];
        newElements[i].rxUETag = element->rxUETag;
        newElements[i].crcIndicationTag = element->crcIndicationTag;
