    // Insert the new elements into the list in a thread-safe manner
    semaphore_wait(&listMutex);
    for (size_t i = 0; i < numElements; i++) {
        NFAPI_CRC_INDICATION_PDU_T *newElement = &newElements[i];
        if (listInsert(list, newElement->rxUETag, newElement->crcIndicationTag) != 0) {
            free(newElements);
            semaphore_post(&listMutex);
            return -1;
        }
    }
    semaphore_post(&listMutex);

    // Free the memory allocated for the new elements
    free(newElements);

    return 0;
}

// List quota system function
void listQuotaSystem(LIST_T *list) {
    // Check if the list is over the maximum capacity
    if (list->length > MAX_CAPACITY) {
        // Remove elements from the list until it reaches the maximum capacity
        while (list->length > MAX_CAPACITY) {
            NFAPI_CRC_INDICATION_PDU_T *elementToDelete = list->data[0];
            list->length--;
            for (size_t i = 0; i < list->length; i++) {
                list->data[i] = list->data[i + 1];
            }
            free(elementToDelete);
        }
    }
}

// List implementation function
void *listImplementation(void *args) {
    // Get the thread arguments
    LIST_T *list = (LIST_T *) args;

    // Initialize the list structure
    listInit(list);

    // Set up the caching mechanism
    cache = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * CACHE_SIZE);

    // Set up the thread key for logging events
    pthread_key_create(&threadKey, NULL);

    while (true) {
        // Check if there are any new elements to insert
        semaphore_wait(&listMutex);
        if (list->length < list->capacity) {
            // Insert the new elements into the list in a thread-safe manner
            for (size_t i = 0; i < numElements; i++) {
                NFAPI_CRC_INDICATION_PDU_T *newElement = &newElements[i];
                if (listInsert(list, newElement->rxUETag, newElement->crcIndicationTag) != 0) {
                    free(newElements);
                    semaphore_post(&listMutex);
                    return -1;
                }
            }
        } else {
            // Remove elements from the list until it reaches the maximum capacity
            while (list->length > MAX_CAPACITY) {
                NFAPI_CRC_INDICATION_PDU_T *elementToDelete = list->data[0];
                list->length--;
                for (size_t i = 0; i < list->length; i++) {
                    list->data[i] = list->data[i + 1];
                }
                free(elementToDelete);
            }
        }
        semaphore_post(&listMutex);

        // Check if there are any cached CRCFLAG values to validate
        semaphore_wait(&cacheMutex);
        for (size_t i = 0; i < CACHE_SIZE; i++) {
            if (cache[i].rxUETag != NULL && cache[i].crcIndicationTag != NULL) {
                bool validCrcFlag = validateCrcFlagWithCache(cache[i].crcFlag);
                if (!validCrcFlag) {
                    // Log the event
                    pthread_setspecific(threadKey, "Invalid CRCFLAG value detected");
                }
            }
        }
        semaphore_post(&cacheMutex);

        // Check if there are any elements to delete or filter
        semaphore_wait(&listMutex);
        for (size_t i = 0; i < list->length; i++) {
            NFAPI_CRC_INDICATION_PDU_T *element = list->data[i];
            if (element->rxUETag == NULL || element->crcIndicationTag == NULL) {
                break;
            } else if (!validateCrcFlag(element->crcFlag)) {
                // Delete the element from the list
                NFAPI_CRC_INDICATION_PDU_T *elementToDelete = list->data[i];
                list->length--;
                for (size_t j = 0; j < list->length - i; j++) {
                    list->data[j] = list->data[j + 1];
                }
                free(elementToDelete);
            }
        }
        semaphore_post(&listMutex);

        // Check if there are any elements to query
        semaphore_wait(&listMutex);
        for (size_t i = 0; i < list->length; i++) {
            NFAPI_CRC_INDICATION_PDU_T *element = list->data[i];
            if (element->rxUETag == NULL || element->crcIndicationTag == NULL) {
                break;
            } else if (queryElement(element) != 0) {
                // Log the event
                pthread_setspecific(threadKey, "Query error detected");
            }
        }
        semaphore_post(&listMutex);
    }
}

// Main function
int main() {
    // Set up the list structure and its mutexes
    LIST_T *list = malloc(sizeof(LIST_T));
    semaphore_create(&listMutex, 1);
    semaphore_create(&cacheMutex, 1);

    // Start the list implementation thread
    pthread_t thread;
    pthread_create(&thread, NULL, listImplementation, (void *) list);

    // Wait for the list implementation thread to finish
    pthread_join(thread, NULL);

    // Clean up the list structure and its mutexes
    free(list);
    semaphore_destroy(&listMutex);
    semaphore_destroy(&cacheMutex);

    return 0;
}
