// Structure to hold LTE UE context information
typedef struct {
    int ue_id;                  // Unique UE identifier
    char mac_address[18];       // MAC address of the UE
    list_t *pdusessions;        // List of PDU sessions associated with the UE
} ue_context_t;

// Structure to hold information about a PDU session
typedef struct {
    int pdusession_id;          // Unique PDU session identifier
    char snssai[10];           // SNSSAI (Single-NSSAI) associated with the PDU session
} pdusession_t;

// Function to create and populate a list of LTE UE contexts
int populate_ue_contexts(list_t **ue_contexts, int num_ues) {
    // Allocate memory for the list of UE contexts
    *ue_contexts = malloc(sizeof(list_t) * num_ues);
    if (*ue_contexts == NULL) {
        printf("Error: Out of memory\n");
        return -1;
    }

    // Initialize the list of UE contexts
    for (int i = 0; i < num_ues; i++) {
        (*ue_contexts)[i].ue_id = -1;
        (*ue_contexts)[i].mac_address[0] = '\0';
        (*ue_contexts)[i].pdusessions = NULL;
    }

    // Retrieve UE information from an external database or API
    for (int i = 0; i < num_ues; i++) {
        char *ue_info = retrieve_ue_info(i);
        if (ue_info == NULL) {
            continue;
        }

        // Parse the UE information to extract the UE ID and MAC address
        int ue_id = -1, mac_address[6] = {0};
        sscanf(ue_info, "%d:%x%x%x%x%x%x", &ue_id, &mac_address[0], &mac_address[1], &mac_address[2], &mac_address[3], &mac_address[4], &mac_address[5]);
        if (ue_id == -1) {
            printf("Error: Invalid UE ID\n");
            continue;
        }

        // Add the UE context to the list of UE contexts
        ue_context_t *ue_context = &(*ue_contexts)[i];
        ue_context->ue_id = ue_id;
        memcpy(ue_context->mac_address, mac_address, 6);
        free(ue_info);
    }

    return num_ues;
}

// Function to create and populate a list of PDU sessions
int populate_pdusessions(list_t **pdusessions, int num_sessions) {
    // Allocate memory for the list of PDU sessions
    *pdusessions = malloc(sizeof(list_t) * num_sessions);
    if (*pdusessions == NULL) {
        printf("Error: Out of memory\n");
        return -1;
    }

    // Initialize the list of PDU sessions
    for (int i = 0; i < num_sessions; i++) {
        (*pdusessions)[i].pdusession_id = -1;
        (*pdusessions)[i].snssai[0] = '\0';
    }

    // Retrieve PDU session information from an external database or API
    for (int i = 0; i < num_sessions; i++) {
        char *session_info = retrieve_session_info(i);
        if (session_info == NULL) {
            continue;
        }

        // Parse the PDU session information to extract the PDU session ID and SNSSAI
        int pdusession_id = -1, snssai[2] = {0};
        sscanf(session_info, "%d:%x%x", &pdusession_id, &snssai[0], &snssai[1]);
        if (pdusession_id == -1) {
            printf("Error: Invalid PDU session ID\n");
            continue;
        }

        // Add the PDU session to the list of PDU sessions
        pdusession_t *session = &(*pdusessions)[i];
        session->pdusession_id = pdusession_id;
        memcpy(session->snssai, snssai, 2);
        free(session_info);
    }

    return num_sessions;
}

// Function to add a PDU session to an LTE UE context
int add_pdusession(ue_context_t *ue_context, pdusession_t *session) {
    // Check for NULL pointers
    if (ue_context == NULL || session == NULL) {
        printf("Error: Invalid pointer\n");
        return -1;
    }

    // Allocate memory for the list of PDU sessions
    int num_sessions = ue_context->pdusessions == NULL ? 0 : ue_context->pdusessions->count;
    if (num_sessions > 0) {
        ue_context->pdusessions = realloc(ue_context->pdusessions, sizeof(list_t) * (num_sessions + 1));
        if (ue_context->pdusessions == NULL) {
            printf("Error: Out of memory\n");
            return -1;
        }
    } else {
        ue_context->pdusessions = malloc(sizeof(list_t));
        if (ue_context->pdusessions == NULL) {
            printf("Error: Out of memory\n");
            return -1;
        }
        ue_context->pdusessions->count = 0;
    }

    // Add the PDU session to the list of PDU sessions associated with the UE
    ue_context->pdusessions->count++;
    pdusession_t *new_session = &(ue_context->pdusessions->items[num_sessions]);
    new_session->pdusession_id = session->pdusession_id;
    memcpy(new_session->snssai, session->snssai, 2);

    return 0;
}

// Function to remove a PDU session from an LTE UE context
int remove_pdusession(ue_context_t *ue_context, int pdusession_id) {
    // Check for NULL pointers
    if (ue_context == NULL || ue_context->pdusessions == NULL) {
        printf("Error: Invalid pointer\n");
        return -1;
    }

    // Find the index of the PDU session in the list of PDU sessions associated with the UE
    int idx = -1;
    for (int i = 0; i < ue_context->pdusessions->count; i++) {
        if (ue_context->pdusessions->items[i].pdusession_id == pdusession_id) {
            idx = i;
            break;
        }
    }

    // If the PDU session is not found, return an error
    if (idx == -1) {
        printf("Error: PDU session ID %d not found\n", pdusession_id);
        return -1;
    }

    // Remove the PDU session from the list of PDU sessions associated with the UE
    ue_context->pdusessions->count--;
    memmove(&(ue_context->pdusessions->items[idx]), &(ue_context->pdusessions->items[idx+1]), (ue_context->pdusessions->count - idx) * sizeof(pdusession_t));

    return 0;
}
