// Function to create and populate a list of LTE UE Context structures
void create_ue_contexts(int num_uces, int max_measurements_per_uce) {
    // Initialize the list of LTE UE Context structures
    LTEUEContext* ue_contexts = malloc(sizeof(LTEUEContext) * num_uces);
    if (ue_contexts == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

