        MeasurementReport* measurements = malloc(sizeof(MeasurementReport) * max_measurements_per_uce);
        if (measurements == NULL) {
            printf("Error: Memory allocation failed\n");
            return;
        }

        // Generate random signal strengths and timestamps for each measurement report
        for (int j = 0; j < max_measurements_per_uce; j++) {
            measurements[j].signal_strength = rand() % 100;
            measurements[j].timestamp = time(NULL);
        }

        // Add the LTE UE Context structure to the list
        ue_contexts[i] = (LTEUEContext) { id, rnti, max_measurements_per_uce, measurements };
    }
}

// Function to update the measurement reports for a given UE
void update_measurements(int uce_id, int max_measurements_per_uce) {
    // Check if the UE context exists in the list
    LTEUEContext* ue_context = find_ue_context(uce_id);
    if (ue_context == NULL) {
        printf("Error: No such UE context\n");
        return;
    }

    // Generate new measurement reports for the UE
    MeasurementReport* measurements = malloc(sizeof(MeasurementReport) * max_measurements_per_uce);
    if (measurements == NULL) {
        printf("Error: Memory allocation failed\n");
        return;
    }

    // Update the measurement reports for the UE
    for (int i = 0; i < max_measurements_per_uce; i++) {
        measurements[i].signal_strength = rand() % 100;
        measurements[i].timestamp = time(NULL);
    }

    // Add the new measurement reports to the existing ones
    int num_new_measurements = max_measurements_per_uce - ue_context->num_measurements;
    for (int i = 0; i < num_new_measurements; i++) {
        ue_context->measurements[i] = measurements[i];
    }

    // Free the memory allocated for the new measurement reports
    free(measurements);
}

// Function to synchronize the LTE UE Context structures with external data source updates
void sync_ue_contexts() {
    // Check if there are any pending updates from the external data source
    if (external_data_source.has_pending_updates()) {
        // Retrieve the pending updates from the external data source
        int* pending_updates = external_data_source.get_pending_updates();
        for (int i = 0; i < num_uces; i++) {
            // Check if the UE context exists in the list and has pending updates
            LTEUEContext* ue_context = find_ue_context(i);
            if (ue_context != NULL && pending_updates[i] > 0) {
                // Update the measurement reports for the UE
                update_measurements(i, pending_updates[i]);
            }
        }
    }
}
