        nfapi_crc_indication_pdu_t *tail;
    } list;
} nfapi_crc_list_t;

// Define the global variable for the linked list
static nfapi_crc_list_t crc_list = { NULL, { 0 }, { 0, NULL, NULL } };

void nfapi_create_crc_indication(uint32_t rx_ue_information_tag, uint16_t rnti) {
    // Validate the input parameters for range and type correctness
