        return;
    }

    // Check if the maximum number of structures has been reached per second
    struct timespec timestamp;
    clock_gettime(CLOCK_REALTIME, &timestamp);
    double delta = (double)(timestamp.tv_sec - crc_list.timestamp.tv_sec) + (double)(timestamp.tv_nsec - crc_list.timestamp.tv_nsec) / 1000000000;
    if (delta < 1.0 && crc_list.count >= MAX_STRUCTURES_PER_SEC) {
        return;
    }

    // Create a new structure for the CRC indication data
    nfapi_crc_indication_pdu_t *new_data = (nfapi_crc_indication_pdu_t *)malloc(sizeof(nfapi_crc_indication_pdu_t));
    if (!new_data) {
