    new_data->rx_ue_information_tag = rx_ue_information_tag;
    new_data->rnti = rnti;
    new_data->crcflag = (uint8_t)rand() % 2; // randomly set the CRCFLAG value

    // Add the structure to the linked list
    if (!crc_list.head) {
        crc_list.head = new_data;
    } else {
        crc_list.tail->next = new_data;
    }
    crc_list.tail = new_data;
    crc_list.count++;

