void nfapi_get_crc_indications(uint32_t *rx_ue_information_tags, uint16_t *rntis, uint8_t *crcflags, size_t count) {
    // Check if the input parameters are valid
    if (!rx_ue_information_tags || !rntis || !crcflags || count == 0) {
        return;
    }

    // Iterate through the linked list and populate the output arrays
    size_t index = 0;
    nfapi_crc_indication_pdu_t *current = crc_list.head;
    while (index < count && current) {
        rx_ue_information_tags[index] = current->rx_ue_information_tag;
        rntis[index] = current->rnti;
        crcflags[index] = current->crcflag;
        index++;
        current = current->next;
    }
}

void nfapi_delete_all_crc_indications() {
    // Delete all structures in the linked list
    while (crc_list.head) {
        nfapi_crc_indication_pdu_t *to_delete = crc_list.head;
        crc_list.head = crc_list.head->next;
        free(to_delete);
    }
    crc_list.count = 0;
}
