import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.logging.Level;
import java.util.logging.Logger;
import javax.xml.crypto.dsig.spec.HMACParameterSpec;
import org.apache.http.HttpEntity;
import org.apache.http.HttpStatus;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.json.JSONArray;
import org.json.JSONObject;

public class CommandExecutor {
    private static final Logger LOGGER = Logger.getLogger(CommandExecutor.class.getName());
    private static final int MAX_RETRIES = 3;
    private static final long RETRY_DELAY = 10_000L; // 10 seconds

    private CloseableHttpClient httpClient;
    private ThreadPoolExecutor executor;
    private String dataSourceUrl;

    public CommandExecutor(String dataSourceUrl) {
        this.dataSourceUrl = dataSourceUrl;
        this.httpClient = HttpClients.createDefault();
        this.executor = (ThreadPoolExecutor) Executors.newFixedThreadPool(10);
    }

    public void executeCommands() throws IOException, InterruptedException {
        List<Command> commands = retrieveCommands();
        for (Command command : commands) {
            executor.execute(() -> {
                try {
                    executeCommand(command);
                } catch (IOException e) {
                    LOGGER.log(Level.WARNING, "Failed to execute command", e);
                }
            });
        }
    }

    private void executeCommand(Command command) throws IOException, InterruptedException {
        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
            try {
                executeCommandOnce(command);
                return;
            } catch (IOException e) {
                if (e.getMessage().contains("file exists")) {
                    LOGGER.log(Level.INFO, "File already exists, skipping deletion");
                    break; // No need to retry file existence checks
                } else if (retryCount < MAX_RETRIES) {
                    LOGGER.log(Level.WARNING, "Command failed with exception", e);
                    Thread.sleep(RETRY_DELAY); // Wait before retrying
                } else {
                    throw e; // Give up and propagate the error
                }
            }
        }
    }

    private void executeCommandOnce(Command command) throws IOException {
        ProcessBuilder pb = new ProcessBuilder(command.getArgs());
        pb.redirectErrorStream(true);
        Process process = pb.start();

        // Capture output and error streams
        InputStream is = process.getInputStream();
        BufferedReader reader = new BufferedReader(new InputStreamReader(is));
        String line;
        while ((line = reader.readLine()) != null) {
            LOGGER.log(Level.INFO, "Command output: " + line);
        }

        // Delete file if it exists and is not being used by another process
        File file = new File(command.getFilePath());
        if (file.exists() && file.delete()) {
            LOGGER.log(Level.INFO, "Deleted file: " + command.getFilePath());
        } else {
            LOGGER.log(Level.WARNING, "Failed to delete file: " + command.getFilePath());
        }
    }

    private List<Command> retrieveCommands() throws IOException {
        // Retrieve commands from data source using REST API
        CloseableHttpResponse response = httpClient.execute(new HttpGet(dataSourceUrl));
        int statusCode = response.getStatusLine().getStatusCode();
        if (statusCode == HttpStatus.SC_OK) {
            HttpEntity entity = response.getEntity();
            String jsonString = EntityUtils.toString(entity);
            JSONArray commandsJson = new JSONObject(jsonString).getJSONArray("commands");
            List<Command> commands = new ArrayList<>();
            for (int i = 0; i < commandsJson.length(); i++) {
                JSONObject commandJson = commandsJson.getJSONObject(i);
                String filePath = commandJson.getString("filePath");
                String[] args = commandJson.getString("args").split(" ");
                Command command = new Command(filePath, args);
                commands.add(command);
            }
            return commands;
        } else {
            throw new IOException("Failed to retrieve commands from data source with status code: " + statusCode);
        }
    }
}
