void populateLteUeContextList(LteUeContextList *list) {
    // Read data from external data source (e.g., a database or a file)
    char *data = getExternalData();

    // Extract UE IDs and measurement reports from the data
    int numUeIds = extractNumUeIds(data);
    UEContext *ueContexts[numUeIds];
    for (int i = 0; i < numUeIds; ++i) {
        UEContext *ueContext = malloc(sizeof(UEContext));
        ueContext->ueId = extractUeId(data, i);
        strncpy(ueContext->measurementReport, extractMeasurementReport(data, i), MAX_LENGTH_MEASUREMENT_REPORT);
        ueContexts[i] = ueContext;
    }

    // Extract serving cell IDs and SQIs from the data
    int numServingCells = extractNumServingCells(data);
    ServingCell *servingCells[numServingCells];
    for (int i = 0; i < numServingCells; ++i) {
        ServingCell *servingCell = malloc(sizeof(ServingCell));
        servingCell->servingCellId = extractServingCellId(data, i);
        servingCell->sqi = extractSqi(data, i);
        servingCells[i] = servingCell;
    }

    // Populate the LTE UE context list with the extracted data
    for (int i = 0; i < numUeIds; ++i) {
        ueContexts[i]->servingCells[i] = malloc(sizeof(ServingCell));
        memcpy(ueContexts[i]->servingCells[i], servingCells[i], sizeof(ServingCell));
    }

    // Clean up dynamic memory allocation
    for (int i = 0; i < numUeIds; ++i) {
        free(ueContexts[i]);
    }
    for (int i = 0; i < numServingCells; ++i) {
        free(servingCells[i]);
    }
}

