// Define error codes and messages
#define ERROR_CONFIGURATION_EMPTY 100
#define ERROR_CONNECTION_NOT_INITIALIZED 200
#define ERROR_CALLBACK_FUNCTION_NULL 300
#define ERROR_SIGNAL_INTERRUPTION 400

// Define structure for configuration and connection object
struct Configuration {
    char* path;
    void* connection;
    void (*callback)(void);
};

int startOperation(struct Configuration* config) {
    // Check if configuration is empty or NULL
    if (config->path == NULL || strlen(config->path) == 0) {
        return ERROR_CONFIGURATION_EMPTY;
    }

    // Verify that connection object has been properly initialized and has a non-empty title
    if (config->connection == NULL || strlen((char*)config->connection) == 0) {
        return ERROR_CONNECTION_NOT_INITIALIZED;
    }

    // Confirm that callback function is not NULL
    if (config->callback == NULL) {
        return ERROR_CALLBACK_FUNCTION_NULL;
    }

    // Initialize and start timer to track duration of operation
    clock_t start = clock();
    int ret = config->callback(config->connection);
    clock_t end = clock();
    double duration = (double)(end - start) / CLOCKS_PER_SEC;

    // Log start time and log another message when timer completes
    printf("Start time: %f\n", start);
    printf("Duration of operation: %f seconds\n", duration);

    // Handle signal interrupts during the operation and ensure that resources are properly cleaned up in case of an interruption
    struct sigaction sa = {.sa_handler = &handleSignalInterrupt, .sa_flags = 0};
    sigaction(SIGINT, &sa, NULL);

    // If an error occurs during the operation, log detailed information including error code and message
    if (ret != 0) {
        printf("Error occurred during operation: %d\n", ret);
        return ret;
    }

    return 0;
}

// Define function to handle signal interrupts during the operation
void handleSignalInterrupt(int sig) {
    // Clean up resources and exit gracefully
    printf("Interrupted by signal %d\n", sig);
    exit(1);
}
