/*
 * LTE UE Context List Management
 */
#include <stdlib.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_UE_CONTEXTS 100000

typedef struct {
    uint32_t ue_id;
    uint16_t rnti;
    uint32_t pdcp_sn;
} lte_ue_context_t;

typedef struct {
    lte_ue_context_t *list;
    size_t num_elems;
    size_t max_size;
} lte_ue_context_list_t;

/*
 * Function to create and populate a list of LTE UE Contexts.
 */
lte_ue_context_list_t* lte_create_ue_context_list(void) {
    lte_ue_context_list_t *list = (lte_ue_context_list_t*) malloc(sizeof(lte_ue_context_list_t));
    if (!list) return NULL;
    list->list = (lte_ue_context_t*) malloc(sizeof(lte_ue_context_t)*MAX_UE_CONTEXTS);
    if (!list->list) {
        free(list);
        return NULL;
    }
    list->num_elems = 0;
    list->max_size = MAX_UE_CONTEXTS;
    return list;
}

/*
 * Function to add a new LTE UE Context to the list.
 */
bool lte_add_ue_context(lte_ue_context_list_t *list, uint32_t ue_id, uint16_t rnti) {
    if (!list || list->num_elems >= list->max_size) return false;
    lte_ue_context_t new_ctx = {ue_id, rnti, 0};
    list->list[list->num_elems] = new_ctx;
    list->num_elems++;
    return true;
}

/*
 * Function to remove an LTE UE Context from the list.
 */
bool lte_remove_ue_context(lte_ue_context_list_t *list, uint32_t ue_id) {
    if (!list || list->num_elems == 0) return false;
    for (size_t i = 0; i < list->num_elems; i++) {
        if (list->list[i].ue_id == ue_id) {
            // Move the last element to the current position and reduce the number of elements by one.
            list->list[i] = list->list[list->num_elems-1];
            list->num_elems--;
            return true;
        }
    }
    return false;
}

/*
 * Function to get the total number of LTE UE Contexts in use.
 */
size_t lte_get_ue_context_count(lte_ue_context_list_t *list) {
    if (!list) return 0;
    return list->num_elems;
}

/*
 * Function to iterate over all LTE UE Contexts in the list.
 */
void lte_iterate_ue_contexts(lte_ue_context_list_t *list, void (*callback)(lte_ue_context_t*)) {
    if (!list || !callback) return;
    for (size_t i = 0; i < list->num_elems; i++) {
        callback(&(list->list[i]));
    }
}

/*
 * Function to serialize the LTE UE Context list for persistence or transmission.
 */
void lte_serialize_ue_contexts(lte_ue_context_list_t *list, char **buffer) {
    if (!list || !buffer) return;
    size_t total_size = 0;
    for (size_t i = 0; i < list->num_elems; i++) {
        // Each context is represented by a fixed-length string with the format: "UE ID,RNTI,PDCP SN\n"
        total_size += strlen(list->list[i].ue_id) + strlen(list->list[i].rnti) + 12; // 12 for ",RNTI,PDCP SN\n"
    }
    *buffer = (char*) malloc(total_size);
    if (!*buffer) return;
    size_t current_pos = 0;
    for (size_t i = 0; i < list->num_elems; i++) {
        // Construct the string representation of the context.
        char *ctx_str = malloc(12); // 12 for ",RNTI,PDCP SN\n"
        sprintf(ctx_str, "%d,%d,%d\n", list->list[i].ue_id, list->list[i].rnti, list->list[i].pdcp_sn);
        // Copy the string representation of the context to the buffer.
        memcpy(*buffer + current_pos, ctx_str, strlen(ctx_str));
        current_pos += strlen(ctx_str);
        free(ctx_str);
    }
}

/*
 * Function to deserialize the LTE UE Context list from a buffer.
 */
void lte_deserialize_ue_contexts(lte_ue_context_list_t *list, char *buffer) {
    if (!list || !buffer) return;
    size_t current_pos = 0;
    while (current_pos < strlen(buffer)) {
        // Parse the next context from the buffer.
        uint32_t ue_id = atoi(buffer + current_pos);
        current_pos += strcspn(buffer + current_pos, ",") + 1;
        uint16_t rnti = atoi(buffer + current_pos);
        current_pos += strcspn(buffer + current_pos, ",") + 1;
        uint32_t pdcp_sn = atoi(buffer + current_pos);
        // Add the context to the list.
        lte_add_ue_context(list, ue_id, rnti);
    }
}

/*
 * Thread-safe mechanism for adding and removing LTE UE Contexts from the list.
 */
void lte_add_remove_ue_context_thread_safe(lte_ue_context_list_t *list, uint32_t ue_id) {
    sem_wait(&list->sem);
    bool success = lte_add_ue_context(list, ue_id, 0);
    sem_post(&list->sem);
    if (!success) printf("Failed to add UE Context with ID %d\n", ue_id);
}

/*
 * Thread-safe mechanism for getting the total number of LTE UE Contexts in use.
 */
size_t lte_get_ue_context_count_thread_safe(lte_ue_context_list_t *list) {
    sem_wait(&list->sem);
    size_t num_elems = list->num_elems;
    sem_post(&list->sem);
    return num_elems;
}

/*
 * Thread-safe mechanism for iterating over all LTE UE Contexts in the list.
 */
void lte_iterate_ue_contexts_thread_safe(lte_ue_context_list_t *list, void (*callback)(lte_ue_context_t*)) {
    sem_wait(&list->sem);
    for (size_t i = 0; i < list->num_elems; i++) {
        callback(&(list->list[i]));
    }
    sem_post(&list->sem);
}

/*
 * Function to handle concurrent access to the database and ensure data consistency.
 */
void lte_persist_ue_contexts(lte_ue_context_list_t *list) {
    // Serialize the list of UE Contexts for persistence.
    char *buffer = NULL;
    lte_serialize_ue_contexts(list, &buffer);
    if (!buffer) return;
    // Save the serialized data to the database.
    int status = save_to_database(buffer);
    free(buffer);
    if (status != 0) printf("Failed to persist UE Contexts\n");
}

/*
 * Function to handle concurrent access to the database and ensure data consistency.
 */
void lte_load_ue_contexts(lte_ue_context_list_t *list) {
    // Load serialized data from the database.
    char *buffer = load_from_database();
    if (!buffer) return;
    // Deserialize the serialized data and populate the list of UE Contexts.
    lte_deserialize_ue_contexts(list, buffer);
    free(buffer);
}

/*
 * Function to handle concurrent access to the database and ensure data consistency.
 */
void lte_remove_ue_contexts(lte_ue_context_list_t *list) {
    // Remove all UE Contexts from the list.
    for (size_t i = 0; i < list->num_elems; i++) {
        lte_remove_ue_context(list, list->list[i].ue_id);
    }
}

/*
 * Function to handle concurrent access to the database and ensure data consistency.
 */
void lte_update_pdcp_sn(lte_ue_context_t *ctx) {
    // Update the PDCP SN of the UE Context.
    ctx->pdcp_sn = generate_pdcp_sn();
}

/*
 * Function to handle concurrent access to the database and ensure data consistency.
 */
void lte_commit_ue_context(lte_ue_context_t *ctx) {
    // Persist the updated UE Context in the database.
    persist_to_database(ctx);
}

/*
 * Function to handle concurrent access to the database and ensure data consistency.
 */
void lte_rollback_ue_context(lte_ue_context_t *ctx) {
    // Roll back the updated UE Context in the database.
    rollback_to_database(ctx);
}']

