    struct LTE_UE_Context *context_list = malloc(sizeof(struct LTE_UE_Context) * num_elements);

    // Fill in the list with random values for UE ID, RNTI, and DL PDCP SN
    for (int i = 0; i < num_elements; i++) {
        struct LTE_UE_Context context = {
