// Custom memory pool for allocating NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_T *structures;
} memory_pool_t;

void init_memory_pool(memory_pool_t *pool, size_t capacity) {
    pool->capacity = capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pool->structures = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
}

void destroy_memory_pool(memory_pool_t *pool) {
    free(pool->structures);
    pthread_mutex_destroy(&pool->lock);
}

int allocate_structure(memory_pool_t *pool, NFAPI_CRC_INDICATION_PDU_T **out_structure) {
    if (pool->count == pool->capacity) {
        return -1;
    }

    pthread_mutex_lock(&pool->lock);

    size_t index = pool->count++;
    *out_structure = &pool->structures[index];
    (*out_structure)->rx_ue_information.tag = RX_UE_INFORMATION_TAG;
    (*out_structure)->crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
    (*out_structure)->crc_indication_rel8.crcFlag = (index % 2 == 0) ? 1 : 0;

    pthread_mutex_unlock(&pool->lock);
    return 0;
}

int populate_structure(NFAPI_CRC_INDICATION_PDU_T *structure, uint16_t rnti) {
