    // Generate a random CRC and add it to the list
    srand(time(NULL));
    uint16_t crc = rand() % 10000;
    structure->crc_indication_rel8.numCrcs++;
    structure->crc_indication_rel8.crcList[structure->crc_indication_rel8.numCrcs - 1].rnti = rnti;
    structure->crc_indication_rel8.crcList[structure->crc_indication_rel8.numCrcs - 1].crc = crc;

    return 0;
}

int create_and_populate_list(memory_pool_t *pool, size_t num_structures, NFAPI_CRC_INDICATION_PDU_T **out_list) {
    if (num_structures > pool->capacity || num_structures <= 0) {
        return -1;
    }

    // Allocate structures in the memory pool
    NFAPI_CRC_INDICATION_PDU_T **structures = (NFAPI_CRC_INDICATION_PDU_T **)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T *) * num_structures);
    for (int i = 0; i < num_structures; i++) {
        if (allocate_structure(pool, &structures[i]) != 0) {
            return -1;
        }
    }

    // Populate the structures with random RNTIs and CRCs
    for (int i = 0; i < num_structures; i++) {
        uint16_t rnti = rand() % 65536;
        if (populate_structure(structures[i], rnti) != 0) {
            return -1;
        }
    }

    // Return the populated list of structures
    *out_list = structures;
    return num_structures;
