    if (*list == NULL) {
        // Handle memory allocation error
    }

    // Populate the list with random RX_UE_INFORMATION_TAG and RNTI values, as well as a randomly set CRCFLAG
    for (int i = 0; i < numRequests; i++) {
        (*list)[i].RX_UE_INFORMATION_TAG = rand() % MAX_RXTIME_VALUE;
        (*list)[i].RNTI = rand() % MAX_RNTI_VALUE;
        (*list)[i].CRCFLAG = rand() % 2 == 0;
    }

    // Validate that the RNTI values are within the valid range for 5G NR
    for (int i = 0; i < numRequests; i++) {
        if ((*list)[i].RNTI < MIN_RNTI_VALUE || (*list)[i].RNTI > MAX_RNTI_VALUE) {
            // Handle out-of-range RNTI values
        }
    }
}

void freeList(NFAPI_CRC_INDICATION_PDU_T **list) {
    // Free the memory allocated for the list on the heap
    free(*list);
    *list = NULL;
}
```
