// Define the structure to hold the MAC PDU data
typedef struct {
    unsigned int mac_ce; // MAC Control Element (MAC-CE)
    unsigned int ue_idx; // UE index
} mac_pdu_t;

// Function to create and populate a list of LTE MAC PDU structures
mac_pdu_list_t* populate_mac_pdus(unsigned char* data, size_t len) {
    // Allocate memory for the list of MAC PDUs
    mac_pdu_list_t* pdu_list = (mac_pdu_list_t*) malloc(sizeof(mac_pdu_list_t));
    if (!pdu_list) {
        printf("Error: Failed to allocate memory for the MAC PDU list\n");
        return NULL;
    }

    // Initialize the list with a fixed size of 100 elements
    pdu_list->size = 100;
    pdu_list->count = 0;
    pdu_list->pdus = (mac_pdu_t*) malloc(sizeof(mac_pdu_t) * pdu_list->size);
