    pthread_mutex_lock(&mutex);

    // Populate the list using the populate_crc_indication_list function
    int ret = populate_crc_indication_list(list, n);

    // Check if the RNTIs in the list fall within the dynamic range
    for (struct NFAPI_CRC_INDICATION_LIST *cur = list; cur != NULL; cur = cur->next) {
