['// C code for the create_and_populate_pdu_list function to create a list of LTE_PDU_T structures with random UE_IDs and MAC_MESSAGE_TYPES
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int ue_id;
    LTE_MAC_PDU_T mac_pdu;
} LTE_PDU_T;

typedef struct {
    int context_id;
    int ue_id;
} LTE_UE_CONTEXT_T;

typedef struct {
    int message_type;
} LTE_MAC_PDU_T;

int create_and_populate_pdu_list(int num_pdus, LTE_PDU_T **pdu_list) {
    *pdu_list = (LTE_PDU_T *)malloc(num_pdus * sizeof(LTE_PDU_T));
    if (*pdu_list == NULL) {
        return -1; // Memory allocation failed
    }

    pthread_mutex_t id_mutex = PTHREAD_MUTEX_INITIALIZER;
    int used_ids[1000] = {0}; // Assuming max 1000 unique UE_IDs

    srand(time(NULL));
    for (int i = 0; i < num_pdus; i++) {
        pthread_mutex_lock(&id_mutex);
        int found_unique_id = 0;
        while (!found_unique_id) {
            int new_id = rand() % 1000 + 1;
            if (!used_ids[new_id - 1]) {
                used_ids[new_id - 1] = 1;
                found_unique_id = 1;
            }
        }
        pthread_mutex_unlock(&id_mutex);

        (*pdu_list)[i].ue_id = new_id;

        // Set a random MAC_MESSAGE_TYPE for the current PDU
        int message_type = rand() % 3 + 1;
        (*pdu_list)[i].mac_pdu.message_type = message_type;
    }

    return num_pdus; // Return the number of PDUs created
}
```
This code uses a mutex to ensure thread safety in the `used_ids` array, which tracks the unique UE_IDs used so far. It also uses the `rand()` function to generate random UE_IDs within the range of 1-1000 (assuming a maximum of 1000 unique UE_IDs). The `srand()` function is used to seed the random number generator with the current time, so that the UE_IDs are generated randomly and not predictably.

The code also uses dynamic memory allocation to create the list of PDUs using `malloc()`. If the memory allocation fails, the function returns `-1` indicating an error.

Finally, the function populates each PDU with a random MAC_MESSAGE_TYPE, and returns the number of PDUs created (which is the same as the input parameter `num_pdus`).']

