// C function to initialize and populate a list of CellularUeInfo_PDU_T structures
int initializeUeList(CellularUeInfo_PDU_T **ueList, int numEntries, bool crcFlag, void *metadata) {
    // Check if input parameters are valid
    if (numEntries <= 0 || numEntries > 100) {
        return -1;
    }

    // Allocate memory for the list of UE structures
    ueList = (CellularUeInfo_PDU_T **)malloc(sizeof(CellularUeInfo_PDU_T *) * numEntries);
    if (!ueList) {
        return -2;
    }

    // Initialize the list of UE structures
    for (int i = 0; i < numEntries; i++) {
        ueList[i] = (CellularUeInfo_PDU_T *)malloc(sizeof(CellularUeInfo_PDU_T));
        if (!ueList[i]) {
            return -3;
        }

        // Set the UE ID and RNTI for each structure
        ueList[i]->ueId = i + 1;
        ueList[i]->rnti = i + 100;

        // Set the CRC flag for each structure
        ueList[i]->crcIndication = crcFlag ? 1 : 0;

        // Set user-defined metadata for each structure (if provided)
        if (metadata) {
            memcpy(ueList[i]->metadata, metadata, sizeof(CellularUeInfo_PDU_T));
        } else {
            ueList[i]->metadata = NULL;
        }
    }

    // Handle dynamic memory allocation and freeing to prevent memory leaks
    atexit(freeList);

    return 0;
}

