// 函数实现
void init_list(list_t *list) {
    list->capacity = 10; // 初始化容量为 10
    list->size = 0; // 初始化大小为 0
    list->mutex = PTHREAD_MUTEX_INITIALIZER; // 初始化互斥锁
    list->list = malloc(sizeof(LTE_PHY_RX_indicator_t) * list->capacity); // 分配内存
}

bool add_ue(list_t *list, int ue_id) {
    pthread_mutex_lock(&list->mutex);
    if (list->size == list->capacity) {
        list->capacity *= 2; // 扩大容量
        list->list = realloc(list->list, sizeof(LTE_PHY_RX_indicator_t) * list->capacity); // 重新分配内存
    }
    LTE_PHY_RX_indicator_t *new_entry = &list->list[list->size];
    new_entry->ue_id = ue_id;
    new_entry->dmrs_idx = 0; // 默认 DMRS 索引为 0
    new_entry->crc_flag = false; // 默认 CRC 标志为 false
    list->size++;
    pthread_mutex_unlock(&list->mutex);
    return true;
}

bool remove_ue(list_t *list, int ue_id) {
    bool found = false;
    for (int i = 0; i < list->size; i++) {
        if (list->list[i].ue_id == ue_id) {
            found = true;
            break;
        }
    }
    if (!found) {
        return false; // 如果没有找到对应的 UE，返回 false
    }
    list->size--; // 更新列表大小
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (i == list->size - 1) {
            break;
        }
        list->list[i].ue_id = list->list[i + 1].ue_id;
        list->list[i].dmrs_idx = list->list[i + 1].dmrs_idx;
        list->list[i].crc_flag = list->list[i + 1].crc_flag;
    }
    pthread_mutex_unlock(&list->mutex);
    return true;
}

void update_dmrs_idx(list_t *list, int ue_id, int dmrs_idx) {
    for (int i = 0; i < list->size; i++) {
        if (list->list[i].ue_id == ue_id) {
            list->list[i].dmrs_idx = dmrs_idx;
            break;
        }
    }
}

void update_crc_flag(list_t *list, int ue_id, bool crc_flag) {
    for (int i = 0; i < list->size; i++) {
        if (list->list[i].ue_id == ue_id) {
            list->list[i].crc_flag = crc_flag;
            break;
        }
    }
}

void free_list(list_t *list) {
    pthread_mutex_lock(&list->mutex);
    if (list->list != NULL) {
        free(list->list);
    }
    list->size = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->mutex);
}
