    pthread_mutex_init(&list->mutex, NULL);
}

void destroy_list(LIST *list) {
    for (int i = 0; i < MAX_UE_COUNT; i++) {
        if (list->ue_info[i] != NULL) {
            free(list->ue_info[i]);
        }
    }
    pthread_mutex_destroy(&list->mutex);
}

void insert_pdu(LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_UE_COUNT) {
        printf("List is full\n");
        pthread_mutex_unlock(&list->mutex);
        return;
    }
    UE_INFO *ue = malloc(sizeof(UE_INFO));
    ue->rnti = pdu->rnti;
    ue->crc_flag = pdu->crc_indication_rel8_tag;
    list->ue_info[list->count++] = ue;
    pthread_mutex_unlock(&list->mutex);
}

void delete_pdu(LIST *list, uint64_t rnti) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->ue_info[i]->rnti == rnti) {
            free(list->ue_info[i]);
            list->ue_info[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void get_pdu(LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->ue_info[i]->rnti == pdu->rnti) {
            pdu->crc_indication_rel8_tag = list->ue_info[i]->crc_flag;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    LIST *list = malloc(sizeof(LIST));
    create_list(list);

    NFAPI_CRC_INDICATION_PDU_T pdu;
    int32_t rnti = 1001;
    pdu.rx_ue_information_tag = 1;
    pdu.rnti = rnti;
    pdu.crc_indication_rel8_tag = 1;
    insert_pdu(list, &pdu);

    NFAPI_CRC_INDICATION_PDU_T pdu2;
    pdu2.rx_ue_information_tag = 1;
    pdu2.rnti = rnti;
    pdu2.crc_indication_rel8_tag = 0;
    insert_pdu(list, &pdu2);

    get_pdu(list, &pdu);
    printf("CRC flag for UE with RNTI %d is: %d\n", rnti, pdu.crc_indication_rel8_tag);

    delete_pdu(list, rnti);

    free(list);
    return 0;
}
```
The above code defines a `LIST` structure that contains a list of `UE_INFO` structures, each representing an UE and containing the RNTI and CRC flag information. The `create_list`, `destroy_list`, `insert_pdu`, `delete_pdu`, and `get_pdu` functions are implemented to manage the list efficiently.

The `main` function creates a `LIST` instance, inserts two `NFAPI_CRC_INDICATION_PDU_T` structures into the list using the `insert_pdu` function, retrieves the CRC flag for a specific UE using the `get_pdu` function, and then deletes that UE from the list using the `delete_pdu` function.

Note that this code uses a linked list to store the list of UEs, which allows for efficient insertions and deletions of UEs. However, this approach can be slower than using a fixed-size array with realloc, as it requires dynamic memory allocation and deallocation. Additionally, this implementation is not thread-safe, as the `LIST` structure itself is not protected by a mutex. To make it thread-safe, you can use a mutex to protect access to the list from multiple threads.

