// Structure to represent an LTE PHY layer configuration
struct lte_phy_config {
    int pci;                     // Physical Cell ID
    char *band;                  // Band
    float frequency_band;        // Frequency band
    int antenna_ports;           // Antenna ports
    int reference_signal_power;  // Reference signal power
