// Define a function to log error messages using snprintf and va_start/va_end
void log_error(char* format, ...) {
  // Get the current time as a string
  time_t rawtime;
  struct tm * timeinfo;
  char buffer[80];
  time(&rawtime);
  timeinfo = localtime(&rawtime);
  strftime(buffer, 80, "%Y-%m-%d %H:%M:%S", timeinfo);

  // Allocate memory for the error message
  char* err_msg = (char*)malloc(sizeof(char) * 256);
  if (!err_msg) {
    fprintf(stderr, "Failed to allocate memory for error message\n");
    return;
  }

  // Format the error message using snprintf and va_start/va_end
  va_list args;
  va_start(args, format);
  vsnprintf(err_msg, 256, format, args);
  va_end(args);

  // Log the error message to stderr
  fprintf(stderr, "[%s] %s\n", buffer, err_msg);

  // Free the memory allocated for the error message
  free(err_msg);
}
