import actix_web::{get, post, web};
use tokio::sync::Mutex;
use serde::{Deserialize, Serialize};
use log::info;

#[derive(Serialize, Deserialize)]
struct ServerConfig {
    host: String,
    port: u16,
    protocol: String,
}

#[get("/servers")]
async fn list_servers() -> web::HttpResponse {
    let servers = get_servers();
    let response = serde_json::to_string(&servers).unwrap();
    web::HttpResponse::Ok().body(response)
}

#[post("/servers")]
async fn add_server(config: web::Json<ServerConfig>) -> web::HttpResponse {
    let config = config.into_inner();
    info!("Adding new server: {:?}", config);
    add_server_config(&config);
    web::HttpResponse::Ok().body("Server added successfully")
}

#[get("/health")]
async fn health_check() -> web::HttpResponse {
    let servers = get_servers();
    for server in servers {
        if !server.is_alive() {
            return web::HttpResponse::ServiceUnavailable().body("Server is not alive");
        }
    }
    web::HttpResponse::Ok().body("All servers are alive")
}

fn get_servers() -> Vec<ServerConfig> {
    let mut servers = vec![];
    // Fetch server configurations from an external API or database.
    for config in fetch_server_configs() {
        if is_valid_config(&config) {
            servers.push(config);
        } else {
            info!("Invalid configuration: {:?}", config);
        }
    }
    servers
}

fn add_server_config(config: &ServerConfig) {
    // Add the new server configuration to the external system or database.
    let response = add_server(&config).unwrap();
    if !response.is_success() {
        info!("Failed to add server configuration: {:?}", config);
    } else {
        info!("Successfully added server configuration: {:?}", config);
    }
}

fn fetch_server_configs() -> Vec<ServerConfig> {
    // Fetch all server configurations from the external system or database.
    vec![
        ServerConfig { host: "localhost".to_string(), port: 8080, protocol: "http".to_string() },
        ServerConfig { host: "example.com".to_string(), port: 443, protocol: "https".to_string() },
    ]
}

fn is_valid_config(config: &ServerConfig) -> bool {
    // Validate the server configuration before adding it to the list of servers.
    config.host.len() > 0 && config.port > 0 && ["http", "https"].contains(&config.protocol.as_str())
}

fn main() {
    let mutex = Mutex::new(get_servers());
    let server = actix_web::HttpServer::new(move || {
        actix_web::App::new()
            .service(list_servers)
            .service(add_server)
            .service(health_check)
    })
    .bind("localhost:8080")?
    .run();
}']

