// Define a structure to store LTE UE context information
typedef struct {
    int ue_id;
    MeasurementReport report;
    ReportingConfig config;
} LTEUEContext;

// Define a function to create and populate a list of LTE UE Context structures
LTEUEContext* create_ue_contexts(int num_ue, int measurement_interval) {
    // Allocate memory for the list of UE contexts
    LTEUEContext *ue_contexts = malloc(sizeof(LTEUEContext) * num_ue);
    if (!ue_contexts) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Set the measurement interval for all UE contexts
    for (int i = 0; i < num_ue; i++) {
        ue_contexts[i].config.measurement_interval = measurement_interval;
    }

    // Populate the list of UE contexts with random data
    srand(time(NULL));
    for (int i = 0; i < num_ue; i++) {
        ue_contexts[i].ue_id = rand() % 1000;
        // Generate a random measurement report and store it in the UE context
        MeasurementReport *report = generate_measurement_report();
        memcpy(&ue_contexts[i].report, report, sizeof(MeasurementReport));
    }

    return ue_contexts;
}

// Define a function to generate a random measurement report
MeasurementReport* generate_measurement_report() {
    MeasurementReport *report = malloc(sizeof(MeasurementReport));
    if (!report) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Fill the report with random data
    for (int i = 0; i < 10; i++) {
        report->rssi[i] = rand() % 20 - 10;
        report->rsrp[i] = rand() % 140 - 70;
    }

    return report;
}

// Define a function to deallocate the memory allocated for the list of UE contexts
void free_ue_contexts(LTEUEContext *ue_contexts) {
    if (!ue_contexts) {
        return;
    }

    for (int i = 0; i < num_ue; i++) {
        MeasurementReport *report = &ue_contexts[i].report;
        free(report);
    }

    free(ue_contexts);
}
