int init_records(long* offsets, int* keys, struct record** records, int max_records) {
    // Initialize the arrays for offsets and keys
    if ((offsets = (long*)malloc(max_records * sizeof(long))) == NULL ||
            (keys = (int*)malloc(max_records * sizeof(int))) == NULL ||
            (records = (struct record**)malloc(max_records * sizeof(struct record*))) == NULL) {
        // Handle memory allocation failure gracefully
        printf("Error: Memory allocation failed\n");
        return -1;
    }

    // Initialize the array of records
    for (int i = 0; i < max_records; i++) {
        if ((records[i] = (struct record*)malloc(sizeof(struct record))) == NULL) {
            printf("Error: Memory allocation failed\n");
            return -1;
        }
    }

    // Initialize the count of initialized records
    int num_records = 0;

    // Set the value of each record's int field to a random value within a given range
    srand(time(NULL));
    for (int i = 0; i < max_records; i++) {
        records[i]->value = rand() % 100 + 1;
        offsets[i] = i * sizeof(struct record);
        keys[i] = i;
        num_records++;
    }

    return num_records;
}
