}

// Define a function to remove an element from the list
void removeElement(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Acquire the mutex
    pthread_mutex_lock(&crc_ind_mutex);

    // Check if the list is empty
    if (crc_ind_list == NULL || crc_ind_list->timestamp <= 0) {
        // Release the mutex and return
        pthread_mutex_unlock(&crc_ind_mutex);
        return;
    }

    // Find the element to remove
    NFAPITCRCIndicationPDU *element = crc_ind_list;
    while (element != NULL) {
        if (element->pdu.rx_ue_information_tag == pdu.rx_ue_information_tag &&
            element->pdu.rnti == pdu.rnti) {
            // Remove the element from the list
            memmove(element, element + 1, (MAX_ELEMENTS - (element - crc_ind_list)) * ELEMENT_SIZE);
            break;
        }

        element = element->next;
    }

    // Release the mutex
    pthread_mutex_unlock(&crc_ind_mutex);
}

// Define a function to prune old entries from the list
void pruneList() {
    // Acquire the mutex
    pthread_mutex_lock(&crc_ind_mutex);

    // Check if the list is empty
    if (crc_ind_list == NULL || crc_ind_list->timestamp <= 0) {
        // Release the mutex and return
        pthread_mutex_unlock(&crc_ind_mutex);
        return;
    }

    // Get the current timestamp
    time_t now = time(NULL);

    // Find the oldest entry in the list
    NFAPITCRCIndicationPDU *oldest = crc_ind_list;
    while (oldest != NULL) {
        if (now - oldest->timestamp > 500) {
            break;
        }

        oldest = oldest->next;
    }

    // If there are no old entries, release the mutex and return
    if (oldest == NULL) {
        pthread_mutex_unlock(&crc_ind_mutex);
        return;
    }

    // Remove the oldest entry from the list
    memmove(oldest, oldest + 1, (MAX_ELEMENTS - (oldest - crc_ind_list)) * ELEMENT_SIZE);

    // Release the mutex
    pthread_mutex_unlock(&crc_ind_mutex);
}

// Define a function to update the list based on external updates
void updateList(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Acquire the mutex
    pthread_mutex_lock(&crc_ind_mutex);

    // Check if the list is full
    if (crc_ind_list == NULL || crc_ind_list->timestamp <= 0) {
        // Allocate memory for the list
        crc_ind_list = malloc(LIST_SIZE);

        // Initialize the list
        memset(crc_ind_list, 0, LIST_SIZE);
