    pthread_mutex_init(&crc_ind_mutex, NULL);
    pthread_cond_init(&crc_ind_prune_cv, NULL);

    // Create a signal handler for the prune condition variable
    sigset(SIGUSR1, &crc_ind_prune_cv);

    // Set up the periodic pruning of the list
    struct sigevent sev;
    memset(&sev, 0, sizeof(struct sigevent));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGUSR1;

    // Create a timer for the periodic pruning of the list
    timer_create(CLOCK_REALTIME, &sev, NULL);

    while (true) {
