        if (ueCtx == NULL) {
            printf("Memory allocation failed for LTE UE context\n");
            pthread_mutex_unlock(&mutex);
            continue;
        }
        (*list)->size++;
        (*list)[(*list)->size - 1] = ueCtx;
        ueCtx->ueid = rand() % 1000000 + 1; // Random UEID between 1 and 1000000
        for (int j = 0; j < 10; j++) {
            ueCtx->reportData[j] = (float)rand() / RAND_MAX; // Random report data between 0 and 1
