        ueCtx->qosIndication = getRandomQosIndication(); // Random QoS indication value

        // Release lock on the mutex
        pthread_mutex_unlock(&mutex);

        // Wait for a signal to continue
        pthread_cond_wait(&cond, &mutex);
    }
}

