    srand(time(NULL));

    for (int i = 0; i < list_size; i++) {
        // Allocate memory for the structure
        LTE_MAC_PDU *pdu = malloc(sizeof(LTE_MAC_PDU));
        if (!pdu) {
            return -1;
        }

        // Populate structure with valid MAC IE tag and QoS value
        pdu->tag = i % 5;
        pdu->qos = rand() % 10;

        // Add the structure to the list
        if (i == 0) {
            list[i] = *pdu;
        } else {
            LTE_MAC_PDU *prev = &list[i - 1];
            prev->next = pdu;
        }
    }

    return 0;
}

int main() {
    LTE_MAC_PDU list[MAX_LIST_SIZE];
    int list_size = populate_list(list, MAX_LIST_SIZE);
