#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_UE_CONTEXTS 1000
#define MAX_MRs_PER_UE 10
#define MAX_SIGNAL_STRENGTH 40
#define UPDATE_INTERVAL 5 // seconds

typedef struct {
    int ue_id;
    unsigned short rnti;
    int mr[MAX_MRs_PER_UE];
} LTE_UE_Context;

LTE_UE_Context* create_ue_context(int id) {
    // Allocate memory for the UE context
    LTE_UE_Context* ctx = malloc(sizeof(LTE_UE_Context));
    if (!ctx) {
        return NULL;
    }

    // Initialize the UE ID and RNTI
    ctx->ue_id = id;
    ctx->rnti = (unsigned short)(rand() % 65536);

    // Initialize the MRs with random signal strengths
    for (int i = 0; i < MAX_MRs_PER_UE; i++) {
        ctx->mr[i] = (rand() % (MAX_SIGNAL_STRENGTH + 1));
    }

    return ctx;
}

void update_mrs(LTE_UE_Context* ctx) {
    // Update the signal strengths of MRs based on a provided time interval
    for (int i = 0; i < MAX_MRs_PER_UE; i++) {
        ctx->mr[i] = (rand() % (MAX_SIGNAL_STRENGTH + 1));
    }
}

void add_ue_context(LTE_UE_Context* ctx) {
    // Add the UE context to the list of UE contexts
    if (ctx->ue_id >= MAX_UE_CONTEXTS || ctx->rnti == 0) {
        return;
    }

    // Check if the number of MRs exceeds the maximum limit
    int mr_count = 0;
    for (int i = 0; i < MAX_MRs_PER_UE; i++) {
        if (ctx->mr[i] != 0) {
            mr_count++;
        }
    }
    if (mr_count > MAX_MRs_PER_UE) {
        return;
    }

    // Add the UE context to the list
    ctx->next = NULL;
    if (ue_contexts == NULL) {
        ue_contexts = ctx;
    } else {
        LTE_UE_Context* tmp = ue_contexts;
        while (tmp->next != NULL) {
            tmp = tmp->next;
        }
        tmp->next = ctx;
    }
}

void delete_ue_context(int id) {
    // Delete the UE context from the list of UE contexts
    if (id >= MAX_UE_CONTEXTS || ue_contexts == NULL) {
        return;
    }

    LTE_UE_Context* tmp = ue_contexts;
    LTE_UE_Context* prev = NULL;
    while (tmp != NULL && tmp->ue_id != id) {
        prev = tmp;
        tmp = tmp->next;
    }
    if (tmp == NULL) {
        return;
    }
    if (prev == NULL) {
        ue_contexts = tmp->next;
    } else {
        prev->next = tmp->next;
    }
}

int main() {
    srand(time(NULL));
    LTE_UE_Context* ctx;
    for (int i = 0; i < MAX_UE_CONTEXTS; i++) {
        ctx = create_ue_context(i);
        if (ctx != NULL) {
            add_ue_context(ctx);
        }
    }

    while (1) {
        // Update the signal strengths of MRs periodically based on a provided time interval
        for (LTE_UE_Context* tmp = ue_contexts; tmp != NULL; tmp = tmp->next) {
            update_mrs(tmp);
        }

        // Handle dynamic changes in the number of UE contexts and MRs due to network traffic fluctuations
        int mr_count = 0;
        for (LTE_UE_Context* tmp = ue_contexts; tmp != NULL; tmp = tmp->next) {
            for (int i = 0; i < MAX_MRs_PER_UE; i++) {
                if (tmp->mr[i] != 0) {
                    mr_count++;
                }
            }
        }
        if (mr_count > MAX_MRs_PER_UE * MAX_UE_CONTEXTS) {
            // Handle memory leaks or crashes caused by excessive MRs
        }
    }

    return 0;
}
