    int value;
} Record;

/* Define a function to allocate and initialize memory for arrays and records */
int initMemory(size_t longOffsetCount, size_t intKeyCount, size_t recordCount) {
    /* Validate input parameters */
    if (longOffsetCount == 0 || intKeyCount == 0 || recordCount == 0) {
        return -1; /* Return an error code if any of the input parameters are invalid */
    }

    /* Allocate memory for the arrays and records */
    long *longOffsets = malloc(sizeof(long) * longOffsetCount);
    int *intKeys = malloc(sizeof(int) * intKeyCount);
    Record *records = malloc(sizeof(Record) * recordCount);

    /* Check for memory allocation failures */
    if (longOffsets == NULL || intKeys == NULL || records == NULL) {
        free(longOffsets);
        free(intKeys);
        free(records);
        return -2; /* Return an error code if any of the memory allocations failed */
    }

    /* Initialize the arrays and records */
    for (size_t i = 0; i < longOffsetCount; i++) {
        longOffsets[i] = rand() % (RANDOM_MAX - RANDOM_MIN + 1) + RANDOM_MIN;
    }

    for (size_t i = 0; i < intKeyCount; i++) {
        intKeys[i] = rand() % (RANDOM_MAX - RANDOM_MIN + 1) + RANDOM_MIN;
    }

    for (size_t i = 0; i < recordCount; i++) {
        records[i].value = rand() % (RANDOM_MAX - RANDOM_MIN + 1) + RANDOM_MIN;
    }

    /* Set the total memory usage */
    size_t totalMemoryUsage = sizeof(long *) * longOffsetCount + sizeof(int *) * intKeyCount + sizeof(Record *) * recordCount;

    /* Check if the total memory usage exceeds the limit */
    if (totalMemoryUsage > MEMORY_LIMIT) {
        free(longOffsets);
        free(intKeys);
        free(records);
        return -3; /* Return an error code if the total memory usage exceeds the limit */
    }

    return 0; /* Return success if all operations were successful */
}

/* Define a function to clean up any allocated memory */
void cleanupMemory() {
    free(longOffsets);
    free(intKeys);
    free(records);
}
