void init_phy_layer_configuration_list(struct phy_layer_configuration **config_list, size_t *config_count) {
    // Validate input parameters
    if (!config_list || !config_count) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Initialize list and count
    *config_list = NULL;
    *config_count = 0;

    // Read external data sources for configuration parameters
    uint32_t cell_id = read_external_data("CELL_ID");
    uint32_t bandwidth = read_external_data("BANDWIDTH");
    uint32_t subcarrier_spacing = read_external_data("SUBCARRIER_SPACING");

    // Validate configuration parameters
    if (!IS_VALID(cell_id, 0, 65535) || !IS_VALID(bandwidth, 1, 42) || !IS_VALID(subcarrier_spacing, 15, 30)) {
        printf("Error: Invalid configuration parameters\n");
        return;
    }

    // Allocate memory for the list of structures and initialize each structure
    *config_list = malloc(*config_count * sizeof(struct phy_layer_configuration));
    if (!*config_list) {
        printf("Error: Memory allocation failed\n");
        return;
    }
    for (size_t i = 0; i < *config_count; i++) {
        (*config_list)[i].cell_id = cell_id;
        (*config_list)[i].bandwidth = bandwidth;
        (*config_list)[i].subcarrier_spacing = subcarrier_spacing;
        (*config_list)[i].cqi = get_random_cqi();
    }
}

// Function to dynamically resize the list of LTE PHY Layer Configuration structures
void resize_phy_layer_configuration_list(struct phy_layer_configuration **config_list, size_t *config_count) {
    // Validate input parameters
    if (!config_list || !config_count) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Check if the list needs to be resized
    if (*config_count == 0) {
        // Initialize list and count
        *config_list = NULL;
        *config_count = 0;
        return;
    } else if (*config_count < *config_count / 2) {
        // Reallocate memory for the list of structures
        *config_list = realloc(*config_list, (*config_count / 2) * sizeof(struct phy_layer_configuration));
        if (!*config_list) {
            printf("Error: Memory allocation failed\n");
            return;
        }
        *config_count /= 2;
    }
}

// Function to validate external data sources for configuration parameters
uint32_t read_external_data(const char *key) {
    // Read data from external source and validate it
    uint32_t value = read_data(key);
    if (!IS_VALID(value, 0, 65535)) {
        printf("Error: Invalid configuration parameter for %s\n", key);
        return 0;
    }
    return value;
}

// Function to get a random Channel Quality Indicator (CQI)
uint8_t get_random_cqi() {
    // Generate a random number between 1 and 25
    uint8_t cqi = rand() % 25 + 1;
    return cqi;
}

// Function to update the list of LTE PHY Layer Configuration structures with new configurations
void update_phy_layer_configuration_list(struct phy_layer_configuration **config_list, size_t *config_count) {
    // Validate input parameters
    if (!config_list || !config_count) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Check if the list needs to be resized
    if (*config_count == 0) {
        // Initialize list and count
        *config_list = NULL;
        *config_count = 0;
        return;
    } else if (*config_count < *config_count * 2) {
        // Reallocate memory for the list of structures
        *config_list = realloc(*config_list, (*config_count * 2) * sizeof(struct phy_layer_configuration));
        if (!*config_list) {
            printf("Error: Memory allocation failed\n");
            return;
        }
        *config_count *= 2;
    }

    // Update the list of structures with new configurations
    for (size_t i = 0; i < *config_count; i++) {
        (*config_list)[i].cell_id += rand() % 5 + 1;
        (*config_list)[i].bandwidth += rand() % 2 + 1;
        (*config_list)[i].subcarrier_spacing += rand() % 10 + 1;
        (*config_list)[i].cqi = get_random_cqi();
    }
}

// Function to deallocate memory for the list of LTE PHY Layer Configuration structures
void free_phy_layer_configuration_list(struct phy_layer_configuration **config_list) {
    // Validate input parameters
    if (!config_list) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    // Deallocate memory for the list of structures
    free(*config_list);
}

// Function to handle memory allocation failures
void memory_allocation_failed(size_t *config_count) {
    printf("Error: Memory allocation failed\n");
    // Update the count variable to reflect the current state of the list
    *config_count = 0;
}

// Function to handle external data source failures or invalid input
void data_source_failed(const char *key) {
    printf("Error: Invalid configuration parameter for %s\n", key);
}
