// Function to sort the list of NFAPI_CRC_INDICATION_PDU_T structures based on RNTI values in ascending order
void sort_nfapi_crc_indication_pdu(struct nfapi_crc_indication_pdu **list, uint16_t num_elements) {
    // Implement a bubble sort algorithm to sort the list based on RNTI values in ascending order
    for (uint16_t i = 0; i < num_elements - 1; i++) {
        bool swap = false;

        for (uint16_t j = 0; j < num_elements - i - 1; j++) {
            if ((*list)[j].rnti > (*list)[j + 1].rnti) {
                struct nfapi_crc_indication_pdu tmp = (*list)[j];
                (*list)[j] = (*list)[j + 1];
                (*list)[j + 1] = tmp;
                swap = true;
            }
        }

        if (!swap) {
            break;
        }
    }
