// Define the structure for storing UE information
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list data structure for storing UE information
typedef struct {
    int capacity; // total number of elements in the list
    int size; // current number of elements in the list
    NFAPI_CRC_INDICATION_PDU_T* elements; // array of elements in the list
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function for initializing the list
NFAPI_CRC_INDICATION_LIST_T* initializeNfaList(int capacity) {
    if (capacity <= 0 || capacity > 100) {
        // Invalid input parameter, return NULL
        return NULL;
    }

    NFAPI_CRC_INDICATION_LIST_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (list == NULL) {
        // Memory allocation failed, return NULL
        return NULL;
    }

    list->capacity = capacity;
    list->size = 0;
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    if (list->elements == NULL) {
        // Memory allocation failed, return NULL
        free(list);
        return NULL;
    }

    return list;
}

// Define the function for adding a new UE entry to the list
int addNfaEntry(NFAPI_CRC_INDICATION_LIST_T* list, uint16_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    if (list == NULL || RX_UE_INFORMATION_TAG <= 0 || RNTI <= 0) {
        // Invalid input parameter, return error code
        return -1;
    }

    if (list->size >= list->capacity) {
        // List is full, return error code
        return -2;
    }

    int index = 0;
    while (index < list->size && list->elements[index].RX_UE_INFORMATION_TAG != RX_UE_INFORMATION_TAG) {
        index++;
    }
    if (index == list->size) {
        // UE with given RX_UE_INFORMATION_TAG not found in the list, return error code
        return -3;
    }

    int rntiIndex = 0;
    while (rntiIndex < list->size && list->elements[rntiIndex].RNTI != RNTI) {
        rntiIndex++;
    }
    if (rntiIndex == list->size) {
        // UE with given RNTI not found in the list, return error code
        return -4;
    }

    NFAPI_CRC_INDICATION_PDU_T* entry = &list->elements[index];
    entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    entry->RNTI = RNTI;
    entry->CRC_INDICATION_REL8_TAG = (uint8_t) rand(); // Randomly set CRCFLAG

    return 0;
}

// Define the function for freeing memory used by the list
void destroyNfaList(NFAPI_CRC_INDICATION_LIST_T* list) {
    if (list == NULL) {
        // Invalid input parameter, do nothing
        return;
    }

    free(list->elements);
    free(list);
}
