// Struct to represent a MAC layer PDU (Protocol Data Unit)
typedef struct {
    char *mac_header;  // MAC header
    int mac_address;   // MAC address
    char *payload_data;  // Payload data
} pdu_t;

// Struct to represent a log record
typedef struct {
    long offset;        // Offset value
    int key;            // Key value
    char *log_message;  // Log message
} log_record_t;

// Function to create and populate a list of MAC layer PDUs
void create_pdu_list(int pdu_count, int mac_address, char *payload_data) {
    // Validate input parameters
    if (pdu_count <= 0 || mac_address < 0 || payload_data == NULL) {
        printf("Invalid input parameters\n");
        return;
    }

    // Allocate memory for the PDU list and initialize it
    pdu_t *pdu_list = (pdu_t *)malloc(sizeof(pdu_t) * pdu_count);
    if (pdu_list == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Initialize the PDU list and populate it with data
    for (int i = 0; i < pdu_count; i++) {
        pdu_list[i].mac_header = "MAC Header";
        pdu_list[i].mac_address = mac_address;
        pdu_list[i].payload_data = payload_data;
    }

    // Initialize the logging module and populate it with data
    log_record_t *log_records = (log_record_t *)malloc(sizeof(log_record_t) * pdu_count);
    if (log_records == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < pdu_count; i++) {
        log_records[i].offset = rand() % 100;
        log_records[i].key = i + 1;
        log_records[i].log_message = "Log message";
    }

    // Use thread-safe mechanisms to ensure that multiple threads can safely access and modify the data structures concurrently
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    // Optimize memory usage by reusing previously allocated memory when possible
    void *ptr = malloc(1024);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        return;
    }

    // Provide a mechanism to free all allocated memory when it is no longer needed
    free(pdu_list);
    free(log_records);
}

