    // Calculate the new number of elements in the list based on the current count and the number of new elements to add
    size_t newCount = list->count + numElements;
    if (newCount < list->count) {
        printf("Error: Integer overflow occurred while calculating the new number of elements in the list\n");
        return false;
    }
    // Allocate memory for the new elements in the list and copy the existing elements to the new allocation
    NFAPI_CRC_INDICATION_PDU_T* newElements = malloc(newCount * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newElements == NULL) {
