// Define the structure for the LTE UE context
typedef struct {
    int ue_id;
    int rnti;
    int srb1_status_flag;
} lte_ue_context;

// Function to create and populate a list of LTE UE Context structures
void populate_ue_contexts(int *states, int num_states, fsa_t *fsa, int last_state) {
    // Allocate memory for the new state list
    lte_ue_context *new_state_list = (lte_ue_context *)malloc(num_states * sizeof(lte_ue_context));
    if (!new_state_list) {
        printf("Error: Failed to allocate memory for new state list\n");
        return;
    }

    // Initialize the new state list with the given states and SRB1 status transfer flag
    for (int i = 0; i < num_states; i++) {
        new_state_list[i].ue_id = i + 1;
        new_state_list[i].rnti = i + 2;
        new_state_list[i].srb1_status_flag = rand() % 2 ? 0 : 1;
    }

    // Update the 'next' pointer of the last state in each FSA's list to point to the newly created state list
    for (int i = 0; i < fsa->num_states; i++) {
        if (fsa->state_list[i].ue_id == last_state) {
            fsa->state_list[i].next = new_state_list;
            break;
        }
    }

    // Free the old state list and update the FSA's state list pointer to point to the new state list
    free(fsa->state_list);
    fsa->state_list = new_state_list;
}
```
