    new_node->crc_indication_rel8_tag = crc_indication_rel8_tag;
    new_node->crcflag = crcflag;

    // Check if the position is valid and adjust accordingly
    if (position > list->size) {
        position = list->size;
    }

    // Insert the new node at the specified position
    NFAPI_CRC_INDICATION_PDU_T *node = list->head;
    for (size_t i = 0; i < position - 1; i++) {
        node = node->next;
    }
    new_node->next = node->next;
    node->next = new_node;
    list->size++;

    // Reuse existing structures if possible
    if (list->size > 1000) {
        NFAPI_CRC_INDICATION_PDU_T *old_node = list->tail;
        list->tail = old_node->next;
        free(old_node);
        list->size--;
    }

    return true;
}

// Function to delete an element from the linked list by RNTI
bool delete_crc_indication(NFAPI_CRC_INDICATION_LIST_T *list, uint16_t rnti) {
