    while (node) {
        if (node->rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T *prev_node = node->next;
            free(node);
            node = prev_node;
            list->size--;
            break;
        } else {
            node = node->next;
        }
    }

    // If the deleted node was the tail, update the tail pointer
    if (list->tail == node) {
        list->tail = node->next;
