// Function to create and populate a new LTE_UERadioLinkStatus structure
LTE_UERadioLinkStatus* create_status(uint64_t UE_ID, uint32_t LCG_ID) {
    // Allocate memory for the structure
    LTE_UERadioLinkStatus *status = malloc(sizeof(LTE_UERadioLinkStatus));
    if (status == NULL) {
        return NULL;
    }

    // Initialize the structure with the given UE_ID and LCG_ID
    status->UE_ID = UE_ID;
    status->LCG_ID = LCG_ID;

    // Generate a random RRC_Connection_Reestablishment_Count value
    status->status_info.RRC_Connection_Reestablishment_Count = rand() % 100;

    // Increment the UL_SINR value by 10 dB
    status->status_info.UL_SINR += 10;

    return status;
}

// Function to add a new LTE_UERadioLinkStatus structure to the list
void add_status(LTE_UERadioLinkStatus *status) {
    // Acquire the semaphore for synchronizing access to the list
    sem_wait(&status_list_sem);

    // Check if the list is empty, and allocate memory for it if necessary
    if (status_list == NULL) {
        status_list = malloc(sizeof(LTE_UERadioLinkStatus));
        if (status_list == NULL) {
            sem_post(&status_list_sem);
            return;
        }
    }

    // Check if the list is full, and allocate more memory if necessary
    if (status_list->next == NULL) {
        status_list->next = malloc(sizeof(LTE_UERadioLinkStatus));
        if (status_list->next == NULL) {
            sem_post(&status_list_sem);
            return;
        }
    }

    // Add the new structure to the list
    status_list->next->prev = status_list;
    status_list->next = status;
    status->prev = status_list;

    sem_post(&status_list_sem);
}

// Function to remove a LTE_UERadioLinkStatus structure from the list
void remove_status(LTE_UERadioLinkStatus *status) {
    // Acquire the semaphore for synchronizing access to the list
    sem_wait(&status_list_sem);

    // Check if the given structure is the first in the list, and adjust the pointers accordingly
    if (status == status_list) {
        status->prev->next = NULL;
        status_list = status->next;
    } else {
        status->prev->next = status->next;
        status->next->prev = status->prev;
    }

    sem_post(&status_list_sem);
}

