    // Create a new array to store the PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        // Handle the memory allocation failure gracefully
        perror("Failed to allocate memory for PDU list");
        return NULL;
    }

    // Initialize each PDU in the list
    for (int i = 0; i < n; i++) {
        pdu_list[i].rx_ue_information_tag = 0;
        pdu_list[i].rnti = 0;
        pdu_list[i].crc_indication_rel8_tag = 0;
    }

    // Set the CRCFLAG randomly for each PDU
    for (int i = 0; i < n; i++) {
        pdu_list[i].crc_indication_rel8_tag = rand() & 1;
    }

    // Return the list of PDUs
    return pdu_list;
}
