```csharp
using System;
using System.Collections.Generic;
using System.Threading;

// Define the LogRecord structure
public struct LogRecord {
    public long Timestamp { get; set; }
    public string Message { get; set; }
}

// Define the LoggingModule class
public class LoggingModule {
    // Define a static instance of the LoggingModule
    private static readonly LoggingModule _instance = new LoggingModule();

    // Define a dictionary to store the log records
    private Dictionary<int, List<LogRecord>> _logRecords;

    // Define an object to synchronize access to the log records
    private readonly object _syncObject = new object();

    // Define a constructor to initialize the log records dictionary
    public LoggingModule() {
        _logRecords = new Dictionary<int, List<LogRecord>>();
    }

    // Define a method to add a log record to the dictionary
    public void AddLogRecord(long timestamp, string message) {
        lock (_syncObject) {
            // Check if the key for the current timestamp exists in the dictionary
            if (!_logRecords.ContainsKey(timestamp)) {
                // If not, create a new list of log records for the current timestamp
                _logRecords[timestamp] = new List<LogRecord>();
            }

            // Add the new log record to the list of log records for the current timestamp
            _logRecords[timestamp].Add(new LogRecord { Timestamp = timestamp, Message = message });
        }
    }

    // Define a method to retrieve all log records for a given timestamp
    public List<LogRecord> GetLogRecords(long timestamp) {
        lock (_syncObject) {
            if (!_logRecords.ContainsKey(timestamp)) {
                return null;
            }

            return _logRecords[timestamp];
        }
    }

    // Define a method to clear all log records in the dictionary
    public void ClearLogRecords() {
        lock (_syncObject) {
            _logRecords.Clear();
        }
    }
}
```
