// Define the ExternalDataFetcher class
public class ExternalDataFetcher {
    // Define a static instance of the ExternalDataFetcher
    private static readonly ExternalDataFetcher _instance = new ExternalDataFetcher();

    // Define a dictionary to store external data sources
    private Dictionary<int, string> _dataSources;

    // Define an object to synchronize access to the data sources
    private readonly object _syncObject = new object();

    // Define a constructor to initialize the data sources dictionary
    public ExternalDataFetcher() {
        _dataSources = new Dictionary<int, string>();
    }

    // Define a method to add an external data source to the dictionary
    public void AddExternalDataSource(int key, string url) {
        lock (_syncObject) {
            // Check if the key already exists in the dictionary
            if (!_dataSources.ContainsKey(key)) {
                // If not, add a new data source with the specified URL
                _dataSources[key] = url;
            } else {
                // Otherwise, update the existing data source with the new URL
                _dataSources[key] = url;
            }
        }
    }

    // Define a method to retrieve data from an external data source
    public string FetchData(int key) {
        lock (_syncObject) {
            if (!_dataSources.ContainsKey(key)) {
                return null;
            }

            // Fetch the data from the specified URL using an HTTP GET request
            var httpClient = new HttpClient();
            var response = await httpClient.GetAsync(_dataSources[key]);
            if (response.IsSuccessStatusCode) {
                return await response.Content.ReadAsStringAsync();
            } else {
                return null;
            }
        }
    }
}
