#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>
#include <stdbool.h>

// Define the structure to hold the CRC information
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T crc_ind;
} nfapi_crc_indication_pdu_t;

// Define a cache for storing the RX_UE_INFORMATION_TAG values
#define CACHE_SIZE 10000
static struct {
    int next_index;
    nfapi_crc_indication_pdu_t *cache[CACHE_SIZE];
} cache = { 0, NULL };

// Define a mutex for thread safety
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to generate a random CRCFLAG value
uint8_t rand_crcflag() {
    return (uint8_t)(rand() % 256);
}

// Function to create and populate an NFAPI_CRC_INDICATION_PDU_T structure
nfapi_crc_indication_pdu_t* nfapi_create_crc_ind(NFAPI_RX_UE_INFORMATION_TAG rx_ue_information_tag, NFAPI_RNTI rnti) {
    nfapi_crc_indication_pdu_t *crc_ind = malloc(sizeof(nfapi_crc_indication_pdu_t));
    memset(crc_ind, 0, sizeof(nfapi_crc_indication_pdu_t));
    crc_ind->rx_ue_information.rx_ue_information_tag = rx_ue_information_tag;
    crc_ind->rnti = rnti;
    crc_ind->crc_indication_rel8.crcflag = rand_crcflag();
    return crc_ind;
}

// Function to add a CRC indication PDU to the cache
void nfapi_add_crc_ind(nfapi_crc_indication_pdu_t *crc_ind) {
    pthread_mutex_lock(&mutex);
    if (cache.next_index == CACHE_SIZE) {
        // Cache is full, resize it by 10%
        cache.cache = realloc(cache.cache, sizeof(nfapi_crc_indication_pdu_t*) * (CACHE_SIZE + (CACHE_SIZE / 10)));
    }
    cache.cache[cache.next_index++] = crc_ind;
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a CRC indication PDU from the cache
nfapi_crc_indication_pdu_t* nfapi_get_crc_ind(NFAPI_RX_UE_INFORMATION_TAG rx_ue_information_tag, NFAPI_RNTI rnti) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < cache.next_index; i++) {
        nfapi_crc_indication_pdu_t *crc_ind = cache.cache[i];
        if (crc_ind->rx_ue_information.rx_ue_information_tag == rx_ue_information_tag && crc_ind->rnti == rnti) {
            // Move the retrieved PDU to the end of the cache
            memmove(&cache.cache[i], &cache.cache[i + 1], sizeof(nfapi_crc_indication_pdu_t*) * (cache.next_index - i));
            memset(&cache.cache[cache.next_index - 1], 0, sizeof(nfapi_crc_indication_pdu_t*));
            cache.next_index--;
            pthread_mutex_unlock(&mutex);
            return crc_ind;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

// Function to retrieve a CRC indication PDU from the external data source
nfapi_crc_indication_pdu_t* nfapi_get_crc_ind_from_external(NFAPI_RX_UE_INFORMATION_TAG rx_ue_information_tag, NFAPI_RNTI rnti) {
