#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int cell_id;
    int ue_id;
    int rx_power;
    float sinr;
    int cqi;
} LTE_PHY_MEASUREMENTS;

void populate_measurements_list(LTE_PHY_MEASUREMENTS **list, char *config_file) {
    // Read configuration file and get number of measurements
    FILE *fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return;
    }
    int num_measurements = 0;
    while (fscanf(fp, "%*[^\n]\n", config_file) != EOF) {
        num_measurements++;
    }
    fclose(fp);

    // Allocate memory for the measurements list and populate it with random values within ranges
    *list = (LTE_PHY_MEASUREMENTS *)malloc(sizeof(LTE_PHY_MEASUREMENTS) * num_measurements);
    if (*list == NULL) {
        perror("Error allocating memory for measurements list");
        return;
    }

    // Initialize variables to store random value ranges
    int rx_power_min = 0;
    int rx_power_max = 0;
    float sinr_min = 0.0f;
    float sinr_max = 0.0f;
    int cqi_min = 0;
    int cqi_max = 0;

    // Read configuration file and set value ranges for each measurement parameter
    fp = fopen(config_file, "r");
    if (fp == NULL) {
        perror("Error opening configuration file");
        return;
    }
    while (fscanf(fp, "%*[^\n]\n", config_file) != EOF) {
        int rx_power = 0;
        float sinr = 0.0f;
        int cqi = 0;

        // Read and store value ranges for each measurement parameter
        if (fscanf(fp, "rx_power_min: %d\n", &rx_power_min) != EOF) {
            rx_power_max = rx_power_min + 10;
        }
        if (fscanf(fp, "rx_power_max: %d\n", &rx_power_max) != EOF) {
            sinr_min = (float)(rx_power_min - 10);
        }
        if (fscanf(fp, "sinr_min: %.2f\n", &sinr_min) != EOF) {
            sinr_max = (float)(rx_power_max + 10);
        }
        if (fscanf(fp, "sinr_max: %.2f\n", &sinr_max) != EOF) {
            cqi_min = rx_power_min - 5;
        }
        if (fscanf(fp, "cqi_min: %d\n", &cqi_min) != EOF) {
            cqi_max = rx_power_max + 5;
        }

        // Populate list with random values within ranges for each measurement parameter
        for (int i = 0; i < num_measurements; i++) {
            (*list)[i].cell_id = rand() % 1000 + 1;
            (*list)[i].ue_id = rand() % 1000 + 1;
            (*list)[i].rx_power = rand() % (rx_power_max - rx_power_min + 1) + rx_power_min;
            (*list)[i].sinr = ((float)rand() / RAND_MAX) * (sinr_max - sinr_min) + sinr_min;
            (*list)[i].cqi = rand() % (cqi_max - cqi_min + 1) + cqi_min;
        }

        // Close configuration file
        fclose(fp);
    }
}

int main() {
    char config_file[] = "config.txt";
    LTE_PHY_MEASUREMENTS *measurements = NULL;

    populate_measurements_list(&measurements, config_file);

    if (measurements != NULL) {
        for (int i = 0; i < sizeof(measurements) / sizeof(LTE_PHY_MEASUREMENTS); i++) {
            printf("Cell ID: %d, UE ID: %d, RX Power: %d dBm, SINR: %.2f dB, CQI: %d\n",
                   measurements[i].cell_id, measurements[i].ue_id,
                   measurements[i].rx_power, measurements[i].sinr,
                   measurements[i].cqi);
        }
        free(measurements);
    } else {
        printf("Memory allocation failed.\n");
    }

    return 0;
}']

