void initializeDataRecords(int numRecords, long *offsets, int *keys, float *values,
                           data_record **records) {
    // Allocate memory for the arrays of offsets, keys, and values
    *offsets = (long *)malloc(numRecords * sizeof(long));
    *keys = (int *)malloc(numRecords * sizeof(int));
    *values = (float *)malloc(numRecords * sizeof(float));

    // Initialize the arrays with random values
    srand((unsigned)time(NULL));
    for (int i = 0; i < numRecords; i++) {
        (*offsets)[i] = rand() % 1000;
        (*keys)[i] = rand() % 1000;
        (*values)[i] = (float)(rand() % 100) / 10.0f;
    }

    // Allocate memory for the records and initialize them with random values
    *records = (data_record *)malloc(numRecords * sizeof(data_record));
    for (int i = 0; i < numRecords; i++) {
        (*records)[i].intValue = rand() % 1000;
        (*records)[i].floatValue = (float)(rand() % 100) / 10.0f;
        (*records)[i].strValue = "Random string";
    }
}

void freeDataRecords(data_record **records) {
    // Free the memory allocated for the arrays of offsets, keys, and values
    if (*records != NULL) {
        free(*offsets);
        free(*keys);
        free(*values);
        *offsets = NULL;
        *keys = NULL;
        *values = NULL;
    }

    // Free the memory allocated for the records
    if (*records != NULL) {
        free(*records);
        *records = NULL;
    }
}
