#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to read a list of integers from standard input, store them in an array, and find the largest integer
int readIntList(int *arr, int size) {
  // Check if the array is null
  if (arr == NULL) {
    return -1;
  }

  // Read the list of integers from standard input
  for (int i = 0; i < size; i++) {
    scanf("%d", &arr[i]);
  }

  // Find the largest integer in the array
  int max = arr[0];
  for (int i = 1; i < size; i++) {
    if (max < arr[i]) {
      max = arr[i];
    }
  }

  return max;
}
