  }

  // Loop over the elements of the list and check for stale or unavailable data
  for (int i = 0; i < list->size; i++) {
    NFAPI_CRC_INDICATION_PDU_T *element = &list->elements[i];

    // Check if the RX_UE_INFORMATION_TAG is stale or unavailable
    if (element->RX_UE_INFORMATION_TAG < 1 || element->RX_UE_INFORMATION_TAG > 100) {
      // Remove the current element from the list and reallocate memory for the remaining elements
      NFAPI_CRC_INDICATION_PDU_T *newElements = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->size - 1));
      if (newElements == NULL) {
        return -2;
      }

      // Update the elements of the list and decrement the size by 1
      list->elements = newElements;
      list->size--;
    }
  }

  return 0;
}
