Here is an example implementation of a C function that creates and populates a list of NFAPI_CRC_INDICATION_PDU_T structures, each containing a valid RX_UE_INFORMATION_TAG and RNTI, and a CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG:
```c
#include <stdlib.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>
#include <errno.h>
#include "nfapi_types.h"

// Structure to represent a single CRC indication PDU
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// List to store all CRC indication PDUs
static NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu_list = NULL;

// Lock to protect the list from concurrent access
static pthread_mutex_t crc_indication_pdu_list_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create and populate a single CRC indication PDU structure
NFAPI_CRC_INDICATION_PDU_T *create_crc_indication_pdu(uint16_t rx_ue_information_tag, uint32_t rnti) {
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_indication_pdu == NULL) {
        fprintf(stderr, "Error: Out of memory!\n");
        return NULL;
    }

    crc_indication_pdu->rx_ue_information_tag = rx_ue_information_tag;
    crc_indication_pdu->rnti = rnti;
    crc_indication_pdu->crc_indication_rel8_tag = rand() % 256;
    crc_indication_pdu->crcflag = true;

    return crc_indication_pdu;
}

// Function to add a new CRC indication PDU to the list
void add_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&crc_indication_pdu_list_lock);

    // Create a new node in the list for the CRC indication PDU
    NFAPI_CRC_INDICATION_PDU_T *new_node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        fprintf(stderr, "Error: Out of memory!\n");
        pthread_mutex_unlock(&crc_indication_pdu_list_lock);
        return;
    }

    // Copy the CRC indication PDU into the new node
    memcpy(new_node, crc_indication_pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add the new node to the end of the list
    if (crc_indication_pdu_list == NULL) {
        crc_indication_pdu_list = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current_node = crc_indication_pdu_list;
        while (current_node->next != NULL) {
            current_node = current_node->next;
        }
        current_node->next = new_node;
    }

    // Unlock the list and return
    pthread_mutex_unlock(&crc_indication_pdu_list_lock);
}

// Function to remove a CRC indication PDU from the list by RX_UE_INFORMATION_TAG and RNTI
void remove_crc_indication_pdu(uint16_t rx_ue_information_tag, uint32_t rnti) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&crc_indication_pdu_list_lock);

    // Search for the node with the specified RX_UE_INFORMATION_TAG and RNTI in the list
    NFAPI_CRC_INDICATION_PDU_T *current_node = crc_indication_pdu_list;
    while (current_node != NULL) {
        if (current_node->rx_ue_information_tag == rx_ue_information_tag && current_node->rnti == rnti) {
            // Remove the node from the list by updating the pointers
            NFAPI_CRC_INDICATION_PDU_T *previous_node = NULL;
            while (current_node != NULL) {
                if (current_node->next != NULL && current_node->next->rx_ue_information_tag == rx_ue_information_tag && current_node->next->rnti == rnti) {
                    previous_node->next = current_node->next;
                } else {
                    previous_node = current_node;
                }
                current_node = current_node->next;
            }

            // Free the memory for the removed node
            free(previous_node);

            // Unlock the list and return
            pthread_mutex_unlock(&crc_indication_pdu_list_lock);
            return;
        }
    }

    // If the specified RX_UE_INFORMATION_TAG and RNTI was not found in the list, print an error message and unlock the list
    fprintf(stderr, "Error: Could not find CRC indication PDU with RX_UE_INFORMATION_TAG %d and RNTI %u\n", rx_ue_information_tag, rnti);
    pthread_mutex_unlock(&crc_indication_pdu_list_lock);
}
