void populate_call_session_list(VOIP_CALL_SESSION_LIST_T* list, size_t num_sessions) {
    // Initialize the list of call sessions
    list->sessions = (VOIP_CALL_SESSION_T**)malloc(num_sessions * sizeof(VOIP_CALL_SESSION_T*));
    if (!list->sessions) {
        fprintf(stderr, "Error: Failed to allocate memory for call session list\n");
        exit(1);
    }
    list->capacity = num_sessions;
    list->count = 0;

    // Populate the list of call sessions with random data
    for (size_t i = 0; i < num_sessions; ++i) {
        VOIP_CALL_SESSION_T* session = malloc(sizeof(VOIP_CALL_SESSION_T));
        if (!session) {
            fprintf(stderr, "Error: Failed to allocate memory for call session\n");
            exit(1);
        }
        list->sessions[i] = session;

        // Generate a random call ID and caller/callee IDs
        session->call_id = rand() % 100000;
        session->caller_id = rand() % 100000;
        session->callee_id = rand() % 100000;

        // Generate random media packets with randomly generated sequence numbers and sizes
        size_t num_packets = rand() % 100 + 1;
        session->packets = (struct media_packet*)malloc(num_packets * sizeof(struct media_packet));
        if (!session->packets) {
            fprintf(stderr, "Error: Failed to allocate memory for media packets\n");
            exit(1);
        }
        for (size_t j = 0; j < num_packets; ++j) {
            struct media_packet* packet = &session->packets[j];
            packet->seq_num = rand() % 65536;
            packet->size = rand() % 1000 + 1;
        }
    }
}
