#define MAX_NUM_ELEMENTS 1000
#define MIN_RNTI 1
#define MAX_RNTI 65535

typedef struct {
    uint32_t ue_id;
    uint16_t rnti;
    bool crc_indication;
} CellularUeInfo_PDU_T;

// Structure to store the list of UE information and its associated RNTIs
typedef struct {
    CellularUeInfo_PDU_T *list;
    uint32_t num_elements;
    uint16_t min_rnti;
    uint16_t max_rnti;
} UE_List_T;

// Structure to store the mapping of UE IDs to their corresponding RNTIs and number of times they have been added to the list
typedef struct {
    uint32_t ue_id;
    uint16_t rnti;
    uint32_t num_additions;
} UE_ID_Mapping_T;

// Array to store the mappings of UE IDs to their corresponding RNTIs and number of times they have been added to the list
UE_ID_Mapping_T ue_id_mappings[MAX_NUM_ELEMENTS];

int initialize_and_populate_list(uint32_t num_elements, uint16_t min_rnti, uint16_t max_rnti) {
    if (num_elements > MAX_NUM_ELEMENTS || min_rnti < MIN_RNTI || max_rnti > MAX_RNTI) {
        return -1; // Error: Number of elements or RNTI range is invalid
    }

    UE_List_T *list = (UE_List_T *)malloc(sizeof(UE_List_T));
    if (!list) {
        return -2; // Error: Memory allocation failed
    }

    list->num_elements = num_elements;
    list->min_rnti = min_rnti;
    list->max_rnti = max_rnti;

    for (uint32_t i = 0; i < num_elements; i++) {
        CellularUeInfo_PDU_T *ue_info = (CellularUeInfo_PDU_T *)malloc(sizeof(CellularUeInfo_PDU_T));
        if (!ue_info) {
            free(list);
            return -3; // Error: Memory allocation failed
        }

        ue_info->ue_id = i + 1;
        ue_info->rnti = (uint16_t)(min_rnti + (rand() % (max_rnti - min_rnti)));
        ue_info->crc_indication = ((rand() & 0x01) == 1);

        list->list[i] = *ue_info;

        UE_ID_Mapping_T mapping = {.ue_id = ue_info->ue_id, .rnti = ue_info->rnti, .num_additions = 1};
        for (uint32_t j = 0; j < i; j++) {
            if (list->list[j].ue_id == mapping.ue_id) {
                return -4; // Error: Duplicate UE IDs are not allowed
            }
        }

        ue_id_mappings[i] = mapping;
    }

    return 0; // Success: List initialized and populated successfully
}
```
