void populate_ue_contexts(UE_Context *ue_contexts, int num_ues) {
  // Initialize the UE context structures with default values
  for (int i = 0; i < num_ues; i++) {
    ue_contexts[i].ue_id = i + 1;
    for (int j = 0; j < 10; j++) {
      ue_contexts[i].grants[j].subcarrier_spacing = 15;
      ue_contexts[i].grants[j].transmission_power = 20;
    }
  }

  // Fetch initial UE context configurations from an external data source
  FILE *file = fopen("ue_config.txt", "r");
  if (file == NULL) {
    printf("Error: unable to open ue_config.txt\n");
    return;
  }

  char line[1024];
  while (fgets(line, sizeof(line), file)) {
    // Parse the incoming data and validate its structure
    int ue_id = atoi(strtok(line, " "));
    if (ue_id < 1 || ue_id > num_ues) {
      printf("Error: invalid UE ID %d\n", ue_id);
      continue;
    }

    // Update the corresponding UE context structure with the incoming data
    for (int j = 0; j < 10; j++) {
      int subcarrier_spacing = atoi(strtok(NULL, " "));
      if (subcarrier_spacing < 5 || subcarrier_spacing > 20) {
        printf("Error: invalid subcarrier spacing %d\n", subcarrier_spacing);
        continue;
      }

      int transmission_power = atoi(strtok(NULL, " "));
      if (transmission_power < 10 || transmission_power > 30) {
        printf("Error: invalid transmission power %d\n", transmission_power);
        continue;
      }

      ue_contexts[ue_id - 1].grants[j].subcarrier_spacing = subcarrier_spacing;
      ue_contexts[ue_id - 1].grants[j].transmission_power = transmission_power;
    }
  }

  // Handle cases where the external data source is not available or returns incomplete configurations
  for (int i = 0; i < num_ues; i++) {
    if (ue_contexts[i].grants[0].subcarrier_spacing == 15 && ue_contexts[i].grants[0].transmission_power == 20) {
      // Use default values for the UE context structure
      continue;
    }

    // Adjust downlink grants based on available radio resources
    int num_available_resources = calculate_num_available_resources(ue_contexts[i].grants, 10);
    if (num_available_resources < 5) {
      for (int j = 0; j < num_available_resources; j++) {
        ue_contexts[i].grants[j].subcarrier_spacing = 20;
        ue_contexts[i].grants[j].transmission_power = 30;
      }
    } else {
      for (int j = 0; j < num_available_resources / 2; j++) {
        ue_contexts[i].grants[j].subcarrier_spacing = 10;
        ue_contexts[i].grants[j].transmission_power = 25;
      }
    }
  }

  // Implement a caching mechanism to reduce the frequency of disk access for frequently accessed data structures
  int num_cached_ues = calculate_num_cached_ues(ue_contexts, num_ues);
  for (int i = 0; i < num_cached_ues; i++) {
    // Add the cached UE context structure to a cache map
    ue_contexts[i].cache_hit = true;
  }
}
