#define MAX_ELEMENTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU {
    uint16_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t num_elements = 0;
static bool is_resizing = false;
static NFAPI_CRC_INDICATION_PDU_T *list = NULL;

void add_element(uint16_t rx_ue_information_tag, uint16_t rnti) {
    pthread_mutex_lock(&mutex);
    if (num_elements == MAX_ELEMENTS || is_resizing) {
        // resize list if necessary
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_elements + 1));
        if (!new_list) {
            pthread_mutex_unlock(&mutex);
            // handle memory allocation failure
            return;
        }
        list = new_list;
        is_resizing = true;
    }

    // generate CRCFLAG randomly
    uint8_t crcflag = rand() % 2;

    // populate new element
    NFAPI_CRC_INDICATION_PDU_T *element = &list[num_elements++];
    element->rx_ue_information_tag = rx_ue_information_tag;
    element->rnti = rnti;
    element->crc_indication_rel8_tag = crcflag;

    // integrate with external data source if necessary
    // ...

    pthread_mutex_unlock(&mutex);
}

void resize_list() {
    pthread_mutex_lock(&mutex);
    is_resizing = true;
    size_t new_size = num_elements * 2;
    NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_size);
    if (!new_list) {
        pthread_mutex_unlock(&mutex);
        // handle memory allocation failure
        return;
    }
    list = new_list;
    pthread_mutex_unlock(&mutex);
}

void remove_element(size_t index) {
    pthread_mutex_lock(&mutex);
    if (index >= num_elements) {
        // handle invalid index
        pthread_mutex_unlock(&mutex);
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T *element = &list[index];
    memmove(element, element + 1, (num_elements - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    num_elements--;
    pthread_mutex_unlock(&mutex);
}

void clear_list() {
    pthread_mutex_lock(&mutex);
    free(list);
    list = NULL;
    num_elements = 0;
    is_resizing = false;
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T *get_element(size_t index) {
    pthread_mutex_lock(&mutex);
    if (index >= num_elements) {
        // handle invalid index
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T *element = &list[index];
    pthread_mutex_unlock(&mutex);
    return element;
}
