  if (num_pdus < 0 || num_pdus > 1000) {
    fprintf(stderr, "Invalid number of PDUs: %d\n", num_pdus);
    return NULL;
  }

  // Allocate memory for the list of PDUs
  nfapi_crci_pdu_t *pdus = malloc(num_pdus * sizeof(nfapi_crci_pdu_t));
  if (pdus == NULL) {
    fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
    return NULL;
  }

  // Read RNTI values from the data source and populate the PDUs
  FILE *fp = fopen(data_source, "r");
  if (fp == NULL) {
