// Function to read strings from file and initialize arrays
Item *read_strings(const char *filename, size_t *n_items) {
    // Open the file and check for errors
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return NULL;
    }

    // Get the number of items in the file
    *n_items = 0;
    while (!feof(fp)) {
        char line[256];
        if (fgets(line, sizeof(line), fp) != NULL) {
            (*n_items)++;
        }
    }
    rewind(fp);

    // Allocate memory for the arrays
    Item *items = malloc(*n_items * sizeof(Item));
    if (items == NULL) {
        perror("Error allocating memory");
        fclose(fp);
        return NULL;
    }

    // Read strings from file and initialize struct items
    size_t i = 0;
    while (!feof(fp)) {
        char line[256];
        if (fgets(line, sizeof(line), fp) != NULL) {
            // Initialize string field of item
            Item *item = &items[i];
            item->string = malloc((strlen(line) + 1) * sizeof(char));
            strcpy(item->string, line);

            // Initialize integer field of item with random value within range
            srand(time(NULL));
            int min_value = 0;
            int max_value = 100;
            item->value = rand() % (max_value - min_value + 1) + min_value;

            i++;
        }
    }

    // Close the file and return the array of items
    fclose(fp);
    return items;
}
