#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include "measurement_list.h"
#include "logging.h"

typedef struct measurement {
    uint32_t ue_id;
    uint16_t cell_id;
    float rsrp;
    float rsrq;
    float sinr;
} measurement_t;

struct measurement_list {
    size_t capacity;
    size_t count;
    measurement_t* measurements;
};

void create_measurement_list(size_t initial_capacity) {
    struct measurement_list* list = malloc(sizeof(struct measurement_list));
    if (!list) {
        log_error("Failed to allocate memory for measurement list");
        return NULL;
    }
    list->count = 0;
    list->capacity = initial_capacity;
    list->measurements = malloc(sizeof(measurement_t) * initial_capacity);
    if (!list->measurements) {
        log_error("Failed to allocate memory for measurement entries");
        free(list);
        return NULL;
    }
    return list;
}

void destroy_measurement_list(struct measurement_list* list) {
    free(list->measurements);
    free(list);
}

bool add_measurement(struct measurement_list* list, uint32_t ue_id, uint16_t cell_id, float rsrp, float rsrq, float sinr) {
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        measurement_t* new_measurements = realloc(list->measurements, sizeof(measurement_t) * new_capacity);
        if (!new_measurements) {
            log_error("Failed to resize measurement list");
            return false;
        }
        list->capacity = new_capacity;
        list->measurements = new_measurements;
    }
    list->measurements[list->count].ue_id = ue_id;
    list->measurements[list->count].cell_id = cell_id;
    list->measurements[list->count].rsrp = rsrp;
    list->measurements[list->count].rsrq = rsrq;
    list->measurements[list->count].sinr = sinr;
    ++list->count;
    return true;
}

bool remove_measurement(struct measurement_list* list, uint32_t ue_id) {
    for (size_t i = 0; i < list->count; ++i) {
        if (list->measurements[i].ue_id == ue_id) {
            --list->count;
            memmove(&list->measurements[i], &list->measurements[i + 1], sizeof(measurement_t) * (list->count - i));
            return true;
        }
    }
    log_error("Failed to remove measurement: UE ID not found");
    return false;
}

void clear_measurements(struct measurement_list* list) {
    list->count = 0;
}

struct measurement_list* get_measurement_list() {
    return create_measurement_list(1000);
}

void free_measurement_list(struct measurement_list* list) {
    destroy_measurement_list(list);
}
```
This implementation defines a `measurement_t` struct to store the PHY layer measurements, and a `struct measurement_list` to store a list of these measurements. The functions for creating, modifying, and querying the list are defined as follows:

* `create_measurement_list()` creates an empty list with the specified initial capacity. If memory allocation fails, it logs an error message and returns NULL.
* `destroy_measurement_list()` frees all memory associated with the list.
* `add_measurement()` adds a new measurement to the list if there is enough space. If not, it resizes the list by doubling its capacity and copies the old measurements to the new array. If memory reallocation fails, it logs an error message and returns false.
* `remove_measurement()` removes the first occurrence of a measurement with the specified UE ID. If no such measurement is found, it logs an error message and returns false.
* `clear_measurements()` sets the count of measurements to 0.
* `get_measurement_list()` creates an empty list with initial capacity 1000.
* `free_measurement_list()` frees all memory associated with the list.

These functions are designed to be used in a real-time application, where performance and efficiency are critical. They handle memory allocation and resizing dynamically to accommodate varying numbers of measurements without significant performance impact. Additionally, they provide mechanisms for logging any errors or warnings during the measurement process. The code is optimized for minimizing fragmentation and reducing memory usage by using `realloc()` instead of `malloc()` to resize the list.']

