// Function to create and populate a list of CRC_INDICATION_PDU_T structures
void createCrcIndicationList(int numPdus, int maxRnti, uint8_t *crcflag) {
    // Allocate memory for the list
    CRC_INDICATION_PDU_T **list = (CRC_INDICATION_PDU_T **)malloc(numPdus * sizeof(CRC_INDICATION_PDU_T *));
    if (!list) {
        // Handle memory allocation failure
    }

    // Initialize the list with default values
    for (int i = 0; i < numPdus; i++) {
        CRC_INDICATION_PDU_T *pdu = (CRC_INDICATION_PDU_T *)malloc(sizeof(CRC_INDICATION_PDU_T));
        if (!pdu) {
            // Handle memory allocation failure
        }
        pdu->rnti = 0;
        pdu->crcflag = crcflag[i];
        list[i] = pdu;
    }

    // Populate the list with random RNTIs and CRCFLAGS
    for (int i = 0; i < numPdus; i++) {
        int retryCount = 0;
        while (retryCount < maxRnti) {
            uint32_t rnti = rand() % maxRnti + 1;
            if (!isUniqueRnti(rnti, list, i)) {
                continue;
            } else {
                list[i]->rnti = rnti;
                break;
            }
        }
    }

    // Sort the list by RNTI values
    qsort(list, numPdus, sizeof(CRC_INDICATION_PDU_T *), compareRnti);
}

// Helper function to check if a given RNTI is unique within the list
bool isUniqueRnti(uint32_t rnti, CRC_INDICATION_PDU_T **list, int index) {
    for (int i = 0; i < index; i++) {
        if (list[i]->rnti == rnti) {
            return false;
        }
    }
    return true;
}

// Helper function to compare two RNTIs and sort the list accordingly
int compareRnti(const void *a, const void *b) {
    CRC_INDICATION_PDU_T **ia = (CRC_INDICATION_PDU_T **)a;
    CRC_INDICATION_PDU_T **ib = (CRC_INDICATION_PDU_T **)b;
    return (*ia)->rnti - (*ib)->rnti;
}
