['// Safe Code Example:
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

struct nas_message {
    char *imsi;
    int message_type;
    char *payload;
};

void safe_add_message(struct nas_message **list, int size) {
    struct nas_message *new_msg = malloc(sizeof(struct nas_message));
    new_msg->imsi = "12345678901234567"; // Assume this is fetched from an external source
    new_msg->message_type = 1;
    new_msg->payload = NULL;

    // Check if the IMSI already exists in the list
    int i;
    for (i = 0; i < size; i++) {
        if (strcmp(new_msg->imsi, list[i]->imsi) == 0) {
            free(new_msg);
            return;
        }
    }

    // If the IMSI is unique, add it to the list and sort it
    list[size++] = new_msg;
    qsort(list, size, sizeof(struct nas_message), compare_imsis);
}

int compare_imsis(const void *a, const void *b) {
    return strcmp(((struct nas_message *)a)->imsi, ((struct nas_message *)b)->imsi);
}
```
