// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
struct NFAPI_CRC_INDICATION_PDU_LIST* create_NFAPI_CRC_INDICATION_PDU_list(int N) {
    // Check if the input value for N is valid
    if (N < 1 || N > 1000) {
        fprintf(stderr, "Error: Invalid input value for N. Must be between 1 and 1000.\n");
        return NULL;
    }

    // Allocate memory for the list of structures
    struct NFAPI_CRC_INDICATION_PDU_LIST *list = (struct NFAPI_CRC_INDICATION_PDU_LIST*)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_LIST));
    if (list == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for the list of structures.\n");
        return NULL;
    }

    // Initialize the size of the list
    list->size = 0;

    // Create a mutex to protect the access to the list and the external data source
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Loop through each element in the input range
    for (int i = 0; i < N; i++) {
        // Acquire the mutex to protect the access to the list and the external data source
        pthread_mutex_lock(&mutex);

        // Allocate memory for a new structure in the list
        struct NFAPI_CRC_INDICATION_PDU_T *pdu = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for a new structure in the list.\n");
            // Release the mutex and return NULL
            pthread_mutex_unlock(&mutex);
            free(list);
            return NULL;
        }

        // Initialize the fields of the new structure
        pdu->RX_UE_INFORMATION_TAG = 0;
        pdu->RNTI = 0;
        pdu->CRC_INDICATION_REL8_TAG = 0;

        // Acquire the external data source and populate the fields of the new structure
        bool success = acquire_external_data(pdu);
        if (!success) {
            fprintf(stderr, "Error: Failed to acquire external data.\n");
            // Release the mutex and return NULL
            pthread_mutex_unlock(&mutex);
            free(list);
            free(pdu);
            return NULL;
        }

        // Validate the consistency between the UE information fetched from the external source and the CRC indications
        success = validate_consistency(pdu);
        if (!success) {
            fprintf(stderr, "Error: Consistency between UE information and CRC indications is not valid.\n");
            // Release the mutex and return NULL
            pthread_mutex_unlock(&mutex);
            free(list);
            free(pdu);
            return NULL;
        }

        // Add the new structure to the list
        list->list = (struct NFAPI_CRC_INDICATION_PDU_T*)realloc(list->list, sizeof(struct NFAPI_CRC_INDICATION_PDU_T) * (list->size + 1));
        if (list->list == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for the new structure in the list.\n");
            // Release the mutex and return NULL
            pthread_mutex_unlock(&mutex);
            free(list);
            free(pdu);
            return NULL;
        }
        list->list[list->size] = *pdu;
        list->size++;

        // Release the mutex and continue with the next element in the input range
        pthread_mutex_unlock(&mutex);
    }

    // Free the mutex
    pthread_mutex_destroy(&mutex);

    return list;
}

// Function to acquire external data from a fictional source
