// Function to release the memory allocated for a list of NFAPI_CRC_INDICATION_PDU_T structures
void release_NFAPI_CRC_INDICATION_PDU_list(struct NFAPI_CRC_INDICATION_PDU_LIST *list) {
    // Check if the input value is valid
    if (list == NULL) {
        fprintf(stderr, "Error: Invalid input value for list.\n");
