      if (element->RNTI > maxRNTI) {
        // Return an error code if the operation fails due to invalid RNTI values
        return NULL;
      }
    }
  }

  return list;
}

// Function to efficiently manage memory and avoid excessive allocations and deallocations under high load conditions
NFAPI_CRC_INDICATION_PDU_LIST_T *manageMemory(NFAPI_CRC_INDICATION_PDU_LIST_T *list, size_t numElements) {
  // Check if the list capacity exceeds the number of elements and resize the list accordingly
  if (list->capacity > numElements) {
    // Reduce the capacity of the list to match the number of elements
    list->capacity = numElements;
    list->elements = realloc(list->elements, list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  }

  return list;
}

// Function to design modular code that can easily adapt to changes in UE information tagging formats or additional data fields
NFAPI_CRC_INDICATION_PDU_LIST_T *adaptToChanges(NFAPI_CRC_INDICATION_PDU_LIST_T *list, uint16_t maxRNTI) {
  // Check if the list needs to be adapted to changes in UE information tagging formats or additional data fields
  if (list->size > 0 && (list->elements[0].RX_UE_INFORMATION_TAG != rand() % 65535 + 1 || list->elements[0].RNTI != rand() % maxRNTI + 1)) {
    // Adapt the list to changes in UE information tagging formats or additional data fields by re-populating the list with random values
    for (size_t i = 0; i < list->capacity; i++) {
