// RandomValueGenerator class for generating random float and integer values within a specified range
class RandomValueGenerator {
private:
  int minimum, maximum;

public:
  RandomValueGenerator(int min, int max) : minimum(min), maximum(max) {}

  // Get a randomly generated integer value within the specified range
  int get_random_integer() { return minimum + (rand() % (maximum - minimum + 1)); }

  // Get a randomly generated float value within the specified range
  float get_random_float() { return minimum + ((float)rand() / RAND_MAX) * (maximum - minimum); }

  // Override the ToString method to display the range of values
