} NFAPI_CRC_INDICATION_PDU_T;

// Define the list data structure for the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* data;
} NFAPI_CRC_INDICATION_LIST;

// Initialize the list with a given capacity
void nfapi_crc_indication_list_init(NFAPI_CRC_INDICATION_LIST* list, int capacity) {
    list->size = 0;
    list->capacity = capacity;
    list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
}

// Add a new structure to the list
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST* list, uint8_t rx_ue_information_tag, uint16_t rnti, uint32_t crcflag) {
    if (list->size == list->capacity) {
        // Reallocate the memory for the list if it's full
        list->capacity *= 2;
        list->data = realloc(list->data, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    }
    NFAPI_CRC_INDICATION_PDU_T* new_item = &(list->data[list->size++]);
    new_item->rx_ue_information_tag = rx_ue_information_tag;
    new_item->rnti = rnti;
    new_item->crcflag = crcflag;
}

// Populate the list with a given number of structures
void nfapi_crc_indication_list_populate(NFAPI_CRC_INDICATION_LIST* list, int count) {
    for (int i = 0; i < count; i++) {
        uint8_t rx_ue_information_tag = rand() % 256;
        uint16_t rnti = rand() % 65536;
        uint32_t crcflag = rand() % 4294967295;
        nfapi_crc_indication_list_add(list, rx_ue_information_tag, rnti, crcflag);
    }
}

// Free the memory for the list
void nfapi_crc_indication_list_free(NFAPI_CRC_INDICATION_LIST* list) {
    free(list->data);
}

int main() {
    // Initialize the list with a capacity of 1024
    NFAPI_CRC_INDICATION_LIST list;
    nfapi_crc_indication_list_init(&list, 1024);

    // Populate the list with 1000 structures
    nfapi_crc_indication_list_populate(&list, 1000);

    // Print out the contents of the list
    for (int i = 0; i < list.size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* item = &(list.data[i]);
