#include <pthread.h>
#include "NFAPI_CRC_INDICATION_PDU_T.h" // Custom data structure for storing CRC indication information

// Define a linked list node for the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct NFAPI_CRC_INDICATION_PDU_LIST {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct NFAPI_CRC_INDICATION_PDU_LIST *next;
} NFAPI_CRC_INDICATION_PDU_LIST;

// Define a linked list for storing the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct NFAPI_CRC_INDICATION_PDU_LIST_HEADER {
    NFAPI_CRC_INDICATION_PDU_LIST *head;
} NFAPI_CRC_INDICATION_PDU_LIST_HEADER;

// Define a hash map for storing the number of times each RNTI appears in the list
typedef struct RNTI_COUNTER {
