    unsigned int count;
} RNTI_COUNTER;

// Define a linked list node for the RNTI counters
typedef struct RNTI_COUNTER_LIST {
    RNTI_COUNTER *data;
    struct RNTI_COUNTER_LIST *next;
} RNTI_COUNTER_LIST;

