typedef struct RNTI_COUNTER_LIST_HEADER {
    RNTI_COUNTER_LIST *head;
} RNTI_COUNTER_LIST_HEADER;

// Define the function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_LIST_HEADER* createAndPopulateNfapiList(unsigned int M) {
