    NFAPI_CRC_INDICATION_PDU_LIST_HEADER *list = NULL;

    // Allocate memory for the list header
    list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST_HEADER));
    if (list == NULL) {
        printf("Error: Memory allocation failed\n");
        return NULL;
    }

    // Initialize the linked list header
    list->head = NULL;

    // Create a hash map for storing the RNTI counters
    RNTI_COUNTER_LIST_HEADER *rntiCounters = malloc(sizeof(RNTI_COUNTER_LIST_HEADER));
