        free(list);
        return NULL;
    }

    // Initialize the hash map for storing the RNTI counters
    rntiCounters->head = NULL;

    // Create a mutex for synchronizing access to the list and the hash map
    pthread_mutex_t *mutex = malloc(sizeof(pthread_mutex_t));
    if (mutex == NULL) {
        printf("Error: Memory allocation failed\n");
        free(list);
        free(rntiCounters);
        return NULL;
    }

    // Initialize the mutex for synchronizing access to the list and the hash map
    pthread_mutex_init(mutex, NULL);

    // Create a thread-safe version of the linked list for storing the NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_LIST *threadSafeList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_LIST));
    if (threadSafeList == NULL) {
        printf("Error: Memory allocation failed\n");
        free(list);
        free(rntiCounters);
        pthread_mutex_destroy(mutex);
        free(mutex);
        return NULL;
    }

    // Initialize the thread-safe version of the linked list for storing the NFAPI_CRC_INDICATION_PDU_T structures
    threadSafeList->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (threadSafeList->data == NULL) {
        printf("Error: Memory allocation failed\n");
        free(list);
        free(rntiCounters);
        pthread_mutex_destroy(mutex);
        free(mutex);
        return NULL;
    }

    // Initialize the thread-safe version of the linked list for storing the NFAPI_CRC_INDICATION_PDU_T structures
    threadSafeList->next = NULL;

    // Create a thread-safe version of the hash map for storing the RNTI counters
    RNTI_COUNTER_LIST *threadSafeRntiCounters = malloc(sizeof(RNTI_COUNTER_LIST));
    if (threadSafeRntiCounters == NULL) {
