            printf("Error: Memory allocation failed\n");
            break;
        }

        // Set the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG for the new NFAPI_CRC_INDICATION_PDU_T structure data
        newListNode->data->RX_UE_INFORMATION_TAG = rand() % 10 + 1; // Randomly set the RX_UE_INFORMATION_TAG
        newListNode->data->RNTI = rand() % 10000 + 1; // Randomly set the RNTI
        newListNode->data->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2 ? 1 : 0; // Randomly set the CRCFLAG

        // Lock the mutex for synchronizing access to the list and the hash map
        pthread_mutex_lock(mutex);

        // Add the new NFAPI_CRC_INDICATION_PDU_T structure data to the thread-safe linked list for storing the NFAPI_CRC_INDICATION_PDU_T structures
        threadSafeList->next = newListNode;
        threadSafeList = threadSafeList->next;

        // Update the hash map for storing the RNTI counters
        RNTI_COUNTER *rntiCounter = malloc(sizeof(RNTI_COUNTER));
        if (rntiCounter == NULL) {
            printf("Error: Memory allocation failed\n");
            break;
        }

        rntiCounter->rnti = newListNode->data->RNTI;
        rntiCounter->count = 1;

        // Add the RNTI counter to the thread-safe hash map for storing the RNTI counters
        threadSafeRntiCounters->next = malloc(sizeof(RNTI_COUNTER_LIST));
        if (threadSafeRntiCounters->next == NULL) {
            printf("Error: Memory allocation failed\n");
            break;
        }

        threadSafeRntiCounters = threadSafeRntiCounters->next;
        threadSafeRntiCounters->data = rntiCounter;
        threadSafeRntiCounters->next = NULL;

        // Unlock the mutex for synchronizing access to the list and the hash map
        pthread_mutex_unlock(mutex);
    }

    // Clean up memory for the linked lists and hash maps
    if (list == NULL) {
        free(list);
    } else {
        NFAPI_CRC_INDICATION_PDU_LIST *temp = list->head;
        while (temp != NULL) {
            NFAPI_CRC_INDICATION_PDU_LIST *next = temp->next;
            free(temp);
            temp = next;
        }
    }

    if (rntiCounters == NULL) {
        free(rntiCounters);
    } else {
        RNTI_COUNTER_LIST *temp = rntiCounters->head;
        while (temp != NULL) {
            RNTI_COUNTER_LIST *next = temp->next;
            free(temp);
            temp = next;
        }
    }

    // Clean up memory for the mutex
    pthread_mutex_destroy(mutex);
    free(mutex);

    return list;
}
