pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Data structure: linked list for efficient insertion and deletion
struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
