    struct NFAPI_CRC_INDICATION_PDU_T *next;
};

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void populate_crc_indication_list(int num_elements) {
    // Allocate memory for the list
    struct NFAPI_CRC_INDICATION_PDU_T *head = NULL;
    struct NFAPI_CRC_INDICATION_PDU_T *tail = NULL;

    // Iterate over the external data source to generate CRC indications
    for (int i = 0; i < num_elements; i++) {
        // Allocate memory for the current element
        struct NFAPI_CRC_INDICATION_PDU_T *current = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (current == NULL) {
            printf("Memory allocation failed\n");
            return;
        }

        // Initialize the current element with valid RX_UE_INFORMATION_TAG and RNTI
        current->RX_UE_INFORMATION_TAG = i + 1000;
        current->RNTI = i + 2000;
        current->CRC_INDICATION_REL8_TAG = rand() % 2 == 0 ? true : false;
        current->CRCFLAG = false; // Default value for CRCFLAG is false

        // Insert the current element into the list
        if (head == NULL) {
            head = tail = current;
        } else {
            tail->next = current;
            tail = current;
        }
    }

    // Lock the mutex to ensure thread safety during updates
    pthread_mutex_lock(&mutex);

    // Update the global list with the populated elements
    struct NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        // Check for invalid CRC indications and handle errors appropriately
        if (current->RX_UE_INFORMATION_TAG < 0 || current->RNTI < 0) {
            printf("Invalid CRC indication: RX_UE_INFORMATION_TAG = %d, RNTI = %d\n", current->RX_UE_INFORMATION_TAG, current->RNTI);
            free(current); // Free the memory for the invalid element
        } else {
            current->CRCFLAG = rand() % 2 == 0 ? true : false; // Randomly set CRCFLAG to true or false
        }
        current = current->next;
    }

    // Unlock the mutex and return the list
    pthread_mutex_unlock(&mutex);
}

// Function to handle periodic updates from an external data source
void update_crc_indication_list(int num_elements) {
    // Lock the mutex to ensure thread safety during updates
    pthread_mutex_lock(&mutex);

    // Update the global list with the new elements
    populate_crc_indication_list(num_elements);

    // Unlock the mutex and return the updated list
    pthread_mutex_unlock(&mutex);
}
```
