// Define the maximum number of valid structures that can be created
#define MAX_VALID_STRUCTURES 100000

// Define the size limit for input strings
#define SIZE_LIMIT 4096

// Define the mutex variable to ensure thread-safe access to the count of valid structures
pthread_mutex_t count_mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
void createAndPopulateNfaciCrcIndicationList(char* inputString, unsigned int maxSize) {
    // Check if the input string is within the size limit
    if (maxSize > SIZE_LIMIT) {
        return NULL;
    }

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* nfaciCrcIndicationList = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_VALID_STRUCTURES);
    int count = 0;

    // Loop through the input string and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < maxSize; i++) {
        // Generate a random RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        nfaciCrcIndicationList[count].rx_ue_information_tag = rand() % 10;
        nfaciCrcIndicationList[count].rnti = rand() % 10000;
        nfaciCrcIndicationList[count].crc_indication_rel8_tag = rand() % 256;
        nfaciCrcIndicationList[count].crcflag = rand() % 2;

        // Validate the consistency between the RNTI and RX_UE_INFORMATION_TAG
        if (nfaciCrcIndicationList[count].rnti == nfaciCrcIndicationList[count].rx_ue_information_tag) {
            count++;
        }
    }

    // Ensure that the total number of valid structures created does not exceed the maximum limit
    pthread_mutex_lock(&count_mutex);
    if (count > MAX_VALID_STRUCTURES) {
        free(nfaciCrcIndicationList);
        return NULL;
    }
    count_mutex.unlock();

    // Return the MD5 hash of the input string using standard library functions
    unsigned char* md5 = (unsigned char*) malloc(sizeof(unsigned char) * 16);
    memset(md5, 0, 16);
    MD5_CTX ctx;
    MD5Init(&ctx);
    MD5Update(&ctx, inputString, maxSize);
    MD5Final(md5, &ctx);

    return md5;
}
