// Define the data structures for the arrays and lists
typedef struct {
    long offset;
    int key;
} record;

typedef struct {
    RX_UE_INFORMATION_TAG rxUETag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndicationTag;
