    SupportedRRCVersions versions;
    LTE_RRC_Feature_Set features;
} LTE_RRC_Capability_Info;

// Define the function to dynamically allocate memory for and initialize the arrays and lists
void populateList(int N, int rangeLow, int rangeHigh) {
    // Allocate memory for the offset array
    long *offsetArray = (long *)malloc(N * sizeof(long));
    if (!offsetArray) {
        printf("Error: Failed to allocate memory for offset array\n");
        return;
    }
    // Initialize the offset array with random values within the given range
    for (int i = 0; i < N; i++) {
        offsetArray[i] = rand() % (rangeHigh - rangeLow) + rangeLow;
    }

    // Allocate memory for the key array
    int *keyArray = (int *)malloc(N * sizeof(int));
    if (!keyArray) {
        printf("Error: Failed to allocate memory for key array\n");
        free(offsetArray);
        return;
    }
    // Initialize the key array with random values within the given range
    for (int i = 0; i < N; i++) {
        keyArray[i] = rand() % (rangeHigh - rangeLow) + rangeLow;
    }

    // Allocate memory for the record structures
    record *records = (record *)malloc(N * sizeof(record));
    if (!records) {
        printf("Error: Failed to allocate memory for record structures\n");
        free(offsetArray);
        free(keyArray);
        return;
    }
    // Initialize the records with random values within the given range
    for (int i = 0; i < N; i++) {
        records[i].offset = offsetArray[i];
        records[i].key = keyArray[i];
    }

    // Allocate memory for the list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *crcIndicationList = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcIndicationList) {
        printf("Error: Failed to allocate memory for CRC indication list\n");
        free(offsetArray);
        free(keyArray);
        free(records);
        return;
    }
    // Initialize the CRCFLAG field of each structure with a random value within the given range
    for (int i = 0; i < N; i++) {
        crcIndicationList[i].crcFlag = rand() % 2;
    }

    // Allocate memory for the list of LTE_RRC_Capability_Info structures
    LTE_RRC_Capability_Info *capabilityInfos = (LTE_RRC_Capability_Info *)malloc(N * sizeof(LTE_RRC_Capability_Info));
    if (!capabilityInfos) {
        printf("Error: Failed to allocate memory for capability info list\n");
        free(offsetArray);
        free(keyArray);
        free(records);
        free(crcIndicationList);
        return;
    }
    // Initialize the UE_Identity field of each structure with a random value within the given range
    for (int i = 0; i < N; i++) {
        capabilityInfos[i].identity = rand() % 10000;
    }

    // Allocate memory for the list of LTE_RRC_Feature_Set structures
    LTE_RRC_Feature_Set *featureSets = (LTE_RRC_Feature_Set *)malloc(N * sizeof(LTE_RRC_Feature_Set));
    if (!featureSets) {
        printf("Error: Failed to allocate memory for feature set list\n");
        free(offsetArray);
        free(keyArray);
        free(records);
        free(crcIndicationList);
        free(capabilityInfos);
        return;
    }
    // Initialize the features field of each structure with randomly selected values within the given range
    for (int i = 0; i < N; i++) {
        featureSets[i].features.set.size = rand() % 10;
        featureSets[i].features.set.bits = (uint8_t *)malloc(featureSets[i].features.set.size * sizeof(uint8_t));
        if (!featureSets[i].features.set.bits) {
            printf("Error: Failed to allocate memory for feature set\n");
            free(offsetArray);
            free(keyArray);
            free(records);
            free(crcIndicationList);
            free(capabilityInfos);
            free(featureSets);
            return;
        }
        for (int j = 0; j < featureSets[i].features.set.size; j++) {
            featureSets[i].features.set.bits[j] = rand() % 256;
        }
    }

    // Free any unused memory in the list to optimize resource usage
    freeUnusedMemory(offsetArray, keyArray, records, crcIndicationList, capabilityInfos, featureSets);
}

// Define a function to check for and free any unused memory in the lists
void freeUnusedMemory(long *offsetArray, int *keyArray, record *records, NFAPI_CRC_INDICATION_PDU_T *crcIndicationList, LTE_RRC_Capability_Info *capabilityInfos, LTE_RRC_Feature_Set *featureSets) {
    // Check if any memory is unused and free it
    for (int i = 0; i < N; i++) {
        if (!offsetArray[i] || !keyArray[i] || !records[i].offset || !records[i].key || !crcIndicationList[i].crcFlag) {
            free(offsetArray);
            free(keyArray);
            free(records);
            free(crcIndicationList);
            free(capabilityInfos);
            free(featureSets);
        }
    }
}

// Define a function to save the populated list to a file for later use or restoration
void saveToFile(char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        printf("Error: Failed to open file %s\n", filename);
        return;
    }
    // Write the populated lists to the file
    for (int i = 0; i < N; i++) {
        fwrite(&offsetArray[i], sizeof(long), 1, file);
        fwrite(&keyArray[i], sizeof(int), 1, file);
        fwrite(&records[i].offset, sizeof(long), 1, file);
        fwrite(&records[i].key, sizeof(int), 1, file);
        fwrite(&crcIndicationList[i].crcFlag, sizeof(bool), 1, file);
        fwrite(&capabilityInfos[i].identity, sizeof(UE_Identity), 1, file);
        fwrite(&capabilityInfos[i].versions, sizeof(SupportedRRCVersions), 1, file);
        fwrite(&featureSets[i].features.set.size, sizeof(int), 1, file);
    }
    // Close the file
    fclose(file);
}
