// C function that creates and populates a list of LTE PHY layer measurement structures
// Each structure contains valid UE ID, cell ID, and a set of PHY layer metrics (RSRP, RSRQ, SINR)
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Structures for LTE PHY layer measurements
struct Measurement {
    int ue_id;
    int cell_id;
    float rsrp;
    float rsrq;
    float sinr;
};

typedef struct {
    int size; // Size of the list
    int capacity; // Capacity of the list (maximum number of elements it can hold)
    struct Measurement *measurements; // Pointer to an array of measurements
} MeasurementList;

// Function to create and populate a new measurement list
MeasurementList* create_and_populate_list(int capacity, int size) {
    // Allocate memory for the list structure
    MeasurementList *list = (MeasurementList*)malloc(sizeof(MeasurementList));
    if (!list) {
        fprintf(stderr, "Error: Failed to allocate memory for measurement list\n");
        return NULL;
    }

    // Allocate memory for the measurements array
    list->measurements = (struct Measurement*)malloc(capacity * sizeof(struct Measurement));
    if (!list->measurements) {
        fprintf(stderr, "Error: Failed to allocate memory for measurement array\n");
        free(list);
        return NULL;
    }

    // Initialize the list and measurements array
    list->size = 0;
    list->capacity = capacity;
    memset(list->measurements, 0, capacity * sizeof(struct Measurement));

    // Return the newly created measurement list
    return list;
}

// Function to add a new measurement to the list
void add_measurement(MeasurementList* list, int ue_id, int cell_id, float rsrp, float rsrq, float sinr) {
    // Check if the list has reached its capacity
    if (list->size == list->capacity) {
        // Increase the capacity of the list by 10%
        int new_capacity = (int)(list->capacity * 1.1);
        struct Measurement* new_measurements = (struct Measurement*)realloc(list->measurements, new_capacity * sizeof(struct Measurement));
        if (!new_measurements) {
            fprintf(stderr, "Error: Failed to reallocate memory for measurement list\n");
            return;
        }
        list->measurements = new_measurements;
        list->capacity = new_capacity;
    }

    // Add the new measurement to the list
    list->measurements[list->size].ue_id = ue_id;
    list->measurements[list->size].cell_id = cell_id;
    list->measurements[list->size].rsrp = rsrp;
    list->measurements[list->size].rsrq = rsrq;
    list->measurements[list->size].sinr = sinr;
    list->size++;
}

// Function to validate and correct any inconsistencies in UE ID and cell ID mappings within the list
void validate_mapping(MeasurementList* list) {
    // Check if there are any duplicates in the UE ID or cell ID mappings
    for (int i = 0; i < list->size - 1; i++) {
        for (int j = i + 1; j < list->size; j++) {
            if (list->measurements[i].ue_id == list->measurements[j].ue_id &&
                list->measurements[i].cell_id == list->measurements[j].cell_id) {
                // Duplicate found, correct the inconsistency by removing one of the duplicates
                memcpy(&list->measurements[i], &list->measurements[j + 1], sizeof(struct Measurement));
                list->size--;
            }
        }
    }
}

// Function to periodically validate and correct any inconsistencies in UE ID and cell ID mappings within the list
void periodic_validation(MeasurementList* list) {
    // Check if there are any duplicates in the UE ID or cell ID mappings every 10 seconds
    struct timespec current;
    clock_gettime(CLOCK_REALTIME, &current);
    if (current.tv_sec % 10 == 0) {
        validate_mapping(list);
    }
}

// Function to log any errors or warnings during the measurement process
void log_errors(MeasurementList* list) {
    // Check if there are any errors or warnings in the list
    for (int i = 0; i < list->size; i++) {
        if (list->measurements[i].rsrp == -1 || list->measurements[i].rsrq == -1 || list->measurements[i].sinr == -1) {
            // Error or warning found, log it and remove the measurement from the list
            fprintf(stderr, "Error: Invalid measurement detected (UE ID = %d, cell ID = %d)\n", list->measurements[i].ue_id, list->measurements[i].cell_id);
            memcpy(&list->measurements[i], &list->measurements[i + 1], sizeof(struct Measurement));
            list->size--;
        }
    }
}

// Function to query historical measurement data within a specified time range
MeasurementList* get_historical_data(MeasurementList* list, int start_time, int end_time) {
    // Create a new list for the historical data
    MeasurementList *historical_list = create_and_populate_list(100000, 0);
    if (!historical_list) {
        fprintf(stderr, "Error: Failed to allocate memory for historical measurement list\n");
        return NULL;
    }

    // Iterate over the existing measurements and add them to the historical list if they fall within the specified time range
    for (int i = 0; i < list->size; i++) {
        if (list->measurements[i].timestamp >= start_time && list->measurements[i].timestamp <= end_time) {
            add_measurement(historical_list, list->measurements[i].ue_id, list->measurements[i].cell_id, list->measurements[i].rsrp, list->measurements[i].rsrq, list->measurements[i].sinr);
        }
    }

    // Return the historical measurement data
    return historical_list;
}
