void remove_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_LIST_T *list, int index) {
    // Check if the index is valid
    if (index < 0 || index >= list->count) {
        printf("Error: Invalid index in CRC indication list\n");
        return;
    }

    // Remove the element from the list
    for (int i = index; i < list->count - 1; i++) {
        list->list[i] = list->list[i + 1];
    }
    list->count--;
}

// Define a function to free the memory allocated for the list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_list(NFAPI_CRC_INDICATION_PDU_LIST_T *list) {
    if (list == NULL) {
        return;
