#include <pthread.h>

// Structure definitions
typedef struct LTE_PDCP_PDU {
    UE_Information_Tag tag;
    PDCP_SN sn;
    PDCP_Control_PDU pdu;
} LTE_PDCP_PDU_T;

typedef struct LTE_UE_Information {
    int id;
    char *tag;
} LTE_UE_Information_T;

// Function prototypes
LTE_UE_Information_T* get_ue_information(int ue_id);
void free_ue_information(LTE_UE_Information_T *info);

// Global variables
static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static LTE_PDCP_PDU_T **list = NULL;
static int list_size = 0;

LTE_PDCP_PDU_T* create_pdcp_pdu(UE_Information_Tag tag, PDCP_SN sn) {
    // Allocate memory for the structure
    LTE_PDCP_PDU_T *pdu = (LTE_PDCP_PDU_T *)malloc(sizeof(LTE_PDCP_PDU_T));
    if (!pdu) {
        return NULL;
    }

    // Set the tag and SN fields
    pdu->tag = tag;
    pdu->sn = sn;

    // Randomly set the SN_REORDER_FLAG field
    pdu->pdu.SN_REORDER_FLAG = (rand() % 2 == 0);

    return pdu;
}

void add_pdcp_pdu(UE_Information_Tag tag, PDCP_SN sn) {
    // Acquire the list mutex to ensure thread-safe access
    pthread_mutex_lock(&list_mutex);

    // Allocate memory for the new element in the list
    LTE_PDCP_PDU_T *pdu = create_pdcp_pdu(tag, sn);
    if (!pdu) {
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    // If the list is empty, allocate memory for it
    if (list == NULL) {
        list = (LTE_PDCP_PDU_T **)malloc(sizeof(LTE_PDCP_PDU_T *) * 10);
        if (!list) {
            free(pdu);
            pthread_mutex_unlock(&list_mutex);
            return;
        }
    }

    // If the list is full, resize it by a factor of two
    if (list_size == 10) {
        LTE_PDCP_PDU_T **new_list = (LTE_PDCP_PDU_T **)realloc(list, sizeof(LTE_PDCP_PDU_T *) * list_size * 2);
        if (!new_list) {
            free(pdu);
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        list = new_list;
    }

    // Add the new element to the end of the list
    list[list_size++] = pdu;

    // Release the list mutex
    pthread_mutex_unlock(&list_mutex);
}

void remove_pdcp_pdu(UE_Information_Tag tag, PDCP_SN sn) {
    // Acquire the list mutex to ensure thread-safe access
    pthread_mutex_lock(&list_mutex);

    // Find the element with the matching tag and SN in the list
    int index = 0;
    for (int i = 0; i < list_size; i++) {
        LTE_PDCP_PDU_T *pdu = list[i];
        if (pdu->tag == tag && pdu->sn == sn) {
            index = i;
            break;
        }
    }

    // If the element was found, remove it from the list and free its memory
    if (index != 0) {
        free(list[index]);
        list[index] = NULL;
        list_size--;
    }

    // Release the list mutex
    pthread_mutex_unlock(&list_mutex);
}

LTE_UE_Information_T* get_ue_information(int ue_id) {
    // Acquire the list mutex to ensure thread-safe access
    pthread_mutex_lock(&list_mutex);

    // Find the element with the matching UE ID in the list
    int index = 0;
    for (int i = 0; i < list_size; i++) {
        LTE_PDCP_PDU_T *pdu = list[i];
        if (pdu->tag.UE_ID == ue_id) {
            index = i;
            break;
        }
    }

    // If the element was found, return its information
    if (index != 0) {
        LTE_UE_Information_T *info = malloc(sizeof(LTE_UE_Information_T));
        info->id = ue_id;
        info->tag = pdu->tag;
        return info;
    }

    // Release the list mutex and return NULL if no matching element was found
    pthread_mutex_unlock(&list_mutex);
    return NULL;
}

void free_ue_information(LTE_UE_Information_T *info) {
    // Acquire the list mutex to ensure thread-safe access
    pthread_mutex_lock(&list_mutex);

    // Find the element with the matching UE ID in the list and free its memory
    int index = 0;
    for (int i = 0; i < list_size; i++) {
        LTE_PDCP_PDU_T *pdu = list[i];
        if (pdu->tag.UE_ID == info->id) {
            free(info);
            free(pdu);
            list[i] = NULL;
            list_size--;
            break;
        }
    }

    // Release the list mutex and return NULL if no matching element was found
    pthread_mutex_unlock(&list_mutex);
}
