#include <stdio.h>
#include "NFAPI_CRC_INDICATION_PDU_T.h"

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    void* data;
} list_node_t;

list_node_t* create_crc_indication_pdu(const char* rx_ue_information, const char* rnti) {
    // Allocate memory for the NFAPI_CRC_INDICATION_PDU_T structure
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T\n");
        return NULL;
    }

    // Initialize the structure with default values
    memset(pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Set the RX_UE_INFORMATION_TAG and RNTI
    pdu->rx_ue_information = rx_ue_information;
    pdu->rnti = atoi(rnti);

    // Generate a random CRCFLAG value for the CRC_INDICATION_REL8_TAG
    srand((unsigned int)time(NULL));
    pdu->crc_indication_rel8.crcflag = rand() % 2;

    // Allocate memory for the data field
    size_t data_size = strlen(rx_ue_information);
    pdu->data = malloc(data_size * sizeof(char));
    if (!pdu->data) {
        fprintf(stderr, "Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T.data\n");
        free(pdu);
        return NULL;
    }

    // Copy the RX_UE_INFORMATION_TAG to the data field
    strcpy((char*)pdu->data, rx_ue_information);

    // Create a list node for the new PDU
    list_node_t* node = (list_node_t*)malloc(sizeof(list_node_t));
    if (!node) {
        fprintf(stderr, "Memory allocation failed for list node\n");
        free(pdu->data);
        free(pdu);
        return NULL;
    }

    // Initialize the list node with the new PDU and data
    node->pdu = pdu;
    node->data = pdu->data;

    return node;
}

void populate_crc_indication_list(list_node_t* head, const char* rx_ue_information) {
    // Iterate over the UE information list and create a new PDU for each RNTI value
    for (int i = 0; i < strlen(rx_ue_information); i++) {
        // Extract the RNTI value from the current position in the UE information string
        char rnti[10];
        sprintf(rnti, "%c", rx_ue_information[i]);

        // Create a new PDU for the current RNTI value and append it to the list
        list_node_t* node = create_crc_indication_pdu(rx_ue_information, rnti);
        if (!node) {
            fprintf(stderr, "Failed to create CRC indication PDU for RNTI %s\n", rnti);
            continue;
        }

        // Append the new node to the list
        if (head == NULL) {
            head = node;
        } else {
            list_node_t* current = head;
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = node;
        }
    }
}

void sort_crc_indication_list(list_node_t* head) {
    // Bubble sort the list based on the RNTI values in ascending order
    bool sorted = false;
    while (!sorted) {
        sorted = true;
        for (int i = 0; i < strlen(head->data); i++) {
            if (head[i].rnti > head[i+1].rnti) {
                // Swap the RNTI values and associated data
                int temp_rnti = head[i].rnti;
                head[i].rnti = head[i+1].rnti;
                head[i+1].rnti = temp_rnti;

                char* temp_data = (char*)head[i].data;
                head[i].data = head[i+1].data;
                head[i+1].data = temp_data;

                sorted = false;
            }
        }
    }
}

list_node_t* create_crc_indication_pdu_list(const char* rx_ue_information) {
    // Create a new list head
    list_node_t* head = NULL;

    // Populate the list with CRC indication PDUs for each RNTI value in the UE information string
    populate_crc_indication_list(head, rx_ue_information);

    // Sort the list based on the RNTI values in ascending order
    sort_crc_indication_list(head);

    return head;
}
