}

// Function to add a new LTE MAC Layer PDU to the list
void add_lte_mac_pdu(struct lte_mac_pdu_list *list, uint8_t type, int16_t tpc, int8_t mcs) {
    // Check if the list is full
    if (list->count == SIZE_MAX / sizeof(struct lte_mac_pdu)) {
        printf("Error: List is full\n");
        return;
    }

    // Allocate memory for the new PDU
    struct lte_mac_pdu *new_pdu = malloc(sizeof(struct lte_mac_pdu));
    if (!new_pdu) {
        printf("Error: Failed to allocate memory for LTE MAC PDU\n");
        return;
    }

    // Set the new PDU's type, TPC, and MCS values
    new_pdu->type = type;
    new_pdu->tpc = tpc;
    new_pdu->mcs = mcs;

    // Add the new PDU to the list
    list->pdu[list->count++] = *new_pdu;
}

// Function to validate the integrity of the LTE MAC Layer PDUs in the list
