        if (!(pdu->type == UL_SCH || pdu->type == DL_SCH || pdu->type == BCH)) {
            printf("Error: PDU %zu has an invalid type\n", i);
            return false;
        }
        if (pdu->tpc < -128 || pdu->tpc > 127) {
            printf("Error: PDU %zu has an invalid TPC value\n", i);
            return false;
        }
        if (pdu->mcs < 0 || pdu->mcs > 15) {
            printf("Error: PDU %zu has an invalid MCS value\n", i);
            return false;
        }
    }

