int create_crc_indication_pdu_list(NFAPI_CRC_INDICATION_PDU_T** list, uint16_t n) {
    if (n < MIN_N || n > MAX_N) {
        return -1;
    }

    // Allocate memory for the list
    *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * n);
    if (*list == NULL) {
        printf("Memory allocation failed\n");
        return -2;
    }

    // Populate the list with valid RX_UE_INFORMATION_TAG and RNTI values
    for (uint16_t i = 0; i < n; i++) {
        (*list)[i].rx_ue_information_tag = generate_rx_ue_information_tag();
        strncpy((*list)[i].rnti, generate_rnti(), RNTI_SIZE);
        (*list)[i].crc_indication_rel8_tag = generate_crc_indication_rel8_tag();
    }

    return 0;
}

uint16_t generate_rx_ue_information_tag() {
