['```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_NFAPI_CRC_INDICATION_PDU 1000
#define RX_UE_INFORMATION_TAG_MIN 1
#define RX_UE_INFORMATION_TAG_MAX 65535
#define CRCFLAG_MIN 0
#define CRCFLAG_MAX 1
#define CACHE_SIZE 100

typedef struct {
    uint16_t rnti;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

static int cache[CACHE_SIZE];
static int cache_index = 0;
static int cache_size = 0;

int create_nfapi_crc_indication_pdu(int num) {
    if (num > MAX_NFAPI_CRC_INDICATION_PDU) {
        return -1;
    }

    int i, j;
    for (i = 0; i < num; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            return -1;
        }

        pdu->rnti = RX_UE_INFORMATION_TAG_MIN + rand() % (RX_UE_INFORMATION_TAG_MAX - RX_UE_INFORMATION_TAG_MIN);
        pdu->crcflag = CRCFLAG_MIN + rand() % (CRCFLAG_MAX - CRCFLAG_MIN);

        if (cache_size < CACHE_SIZE) {
            cache[cache_index] = pdu->rnti;
            cache_index = (cache_index + 1) % CACHE_SIZE;
            cache_size++;
        } else {
            int remove_idx = (cache_index - 1) % CACHE_SIZE;
            free(cache[remove_idx]);
            cache[remove_idx] = NULL;
            cache_index--;
        }
    }

    return num;
}
