#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <pthread.h>

// Define the structure for LTE UE context
struct lte_ue_context {
    int id; // Unique ID for each UE
    long rnti; // Random Network Temporary Identity
    bool srb1_status; // Status of SRB1 (active or not)
    unsigned long pdcp_sn; // PDCP Sequence Number (randomly set)
    char *user_data; // Optional user data field
};

// Define the list for LTE UE contexts
struct lte_ue_context_list {
    struct lte_ue_context **contexts; // Array of LTE UE context structures
    int num_contexts; // Number of elements in the array
    pthread_mutex_t lock; // Mutex for thread safety
};

// Function to create and initialize a list of LTE UE contexts
struct lte_ue_context_list *create_ue_context_list() {
    struct lte_ue_context_list *list = malloc(sizeof(struct lte_ue_context_list));
    if (!list) {
        printf("Error: Out of memory!\n");
        return NULL;
    }
    list->contexts = malloc(1000 * sizeof(struct lte_ue_context *)); // Allocate space for 1000 contexts
    if (!list->contexts) {
        printf("Error: Out of memory!\n");
        free(list);
        return NULL;
    }
    list->num_contexts = 0;
    pthread_mutex_init(&list->lock, NULL); // Initialize mutex for thread safety
    return list;
}

// Function to insert a new LTE UE context into the list
void insert_ue_context(struct lte_ue_context_list *list, int id, long rnti, bool srb1_status) {
    pthread_mutex_lock(&list->lock); // Lock mutex for thread safety
    if (list->num_contexts >= 1000) {
        printf("Error: List is full!\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    struct lte_ue_context *context = malloc(sizeof(struct lte_ue_context)); // Allocate memory for new context
    if (!context) {
        printf("Error: Out of memory!\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    context->id = id;
    context->rnti = rnti;
    context->srb1_status = srb1_status;
    unsigned long pdcp_sn = rand(); // Randomly set PDCP SN
    context->pdcp_sn = pdcp_sn;
    context->user_data = NULL; // Initialize optional user data field to NULL
    list->contexts[list->num_contexts++] = context; // Add new context to the list
    pthread_mutex_unlock(&list->lock); // Unlock mutex for thread safety
}

// Function to delete a LTE UE context from the list
void delete_ue_context(struct lte_ue_context_list *list, int id) {
    pthread_mutex_lock(&list->lock); // Lock mutex for thread safety
    struct lte_ue_context **context = find_context(list, id); // Find the context with the given ID
    if (context == NULL) {
        printf("Error: Context not found!\n");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    free(*context); // Free memory for the context
    list->num_contexts--; // Decrement number of contexts in the list
    *context = NULL; // Set deleted context to NULL
    pthread_mutex_unlock(&list->lock); // Unlock mutex for thread safety
}

// Function to find a LTE UE context in the list by ID
struct lte_ue_context **find_context(struct lte_ue_context_list *list, int id) {
    pthread_mutex_lock(&list->lock); // Lock mutex for thread safety
    for (int i = 0; i < list->num_contexts; i++) {
        if (list->contexts[i]->id == id) {
            struct lte_ue_context **context = &(list->contexts[i]); // Return pointer to the context
            pthread_mutex_unlock(&list->lock); // Unlock mutex for thread safety
            return context;
        }
    }
    printf("Error: Context not found!\n");
    pthread_mutex_unlock(&list->lock); // Unlock mutex for thread safety
    return NULL;
}

// Function to print all LTE UE contexts in the list
void print_ue_context_list(struct lte_ue_context_list *list) {
    pthread_mutex_lock(&list->lock); // Lock mutex for thread safety
    printf("List of LTE UE contexts:\n");
    for (int i = 0; i < list->num_contexts; i++) {
        struct lte_ue_context *context = list->contexts[i];
        printf("\tID: %d, RNTI: %ld, SRB1 status: %s, PDCP SN: %lu\n", context->id, context->rnti, (context->srb1_status ? "active" : "inactive"), context->pdcp_sn);
    }
    pthread_mutex_unlock(&list->lock); // Unlock mutex for thread safety
}
