['This is an example of a function that dynamically allocates memory for and initializes an array of `record` structures. Each `record` structure contains a `long` offset value, an `int` key, a pointer to a string, and an integer representing the length of the string. The function generates random ASCII strings for each record and initializes the string pointers accordingly.
```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    char* string;
    size_t length;
} record;

void initialize_records(int num_records) {
    record* records = (record*)malloc(num_records * sizeof(record));
    if (records == NULL) {
        perror("Failed to allocate memory for records");
        return;
    }

    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (offsets == NULL) {
        free(records);
        perror("Failed to allocate memory for offsets");
        return;
    }

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (keys == NULL) {
        free(records);
        free(offsets);
        perror("Failed to allocate memory for keys");
        return;
    }

    // Initialize offsets, keys, and records
    for (int i = 0; i < num_records; i++) {
        long offset = (long)random() % INT32_MAX;
        int key = (int)random() % INT32_MAX;
        size_t length = strlen(string);
        records[i].offset = offset;
        records[i].key = key;
        records[i].length = length;
        offsets[i] = offset;
        keys[i] = key;
    }
