```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_REQUESTS_PER_SECOND 100
#define MAX_CRC_INDICATION_PDU_T_STRUCTURES 5000
#define RX_UE_INFORMATION_TAG 0x02
#define RNTI_LENGTH 8
#define CRC_INDICATION_REL8_TAG 0x10
#define CRCFLAG_LENGTH 1
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_WARNING 3
#define LOG_LEVEL_ERROR 4

typedef struct {
    uint8_t rx_ue_information_tag;
    uint64_t rnti;
    uint8_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
unsigned int num_structures = 0;
time_t last_request_timestamp = time(NULL);

void set_crcflag(NFAPI_CRC_INDICATION_PDU_T *pdu, uint8_t crcflag) {
    if (crcflag < 2) {
        pdu->crcflag = crcflag;
    } else {
        printf("Invalid CRCFLAG value: %d\n", crcflag);
    }
}

void add_structure(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&lock);
    if (num_structures >= MAX_CRC_INDICATION_PDU_T_STRUCTURES) {
        printf("Maximum number of structures reached\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    num_structures++;
    pthread_mutex_unlock(&lock);
    pdu->rx_ue_information_tag = RX_UE_INFORMATION_TAG;
    pdu->crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG;
    set_crcflag(pdu, (rand() % 2) ? 1 : 0); // randomly set CRCFLAG
}

void create_structures(int num_requests, int max_requests_per_second) {
    time_t current_timestamp = time(NULL);
    if (current_timestamp - last_request_timestamp < 1) {
        printf("Rate limit exceeded\n");
        return;
    } else if (num_requests > max_requests_per_second) {
        printf("Maximum number of requests per second reached\n");
        return;
    }
    last_request_timestamp = current_timestamp;
    for (int i = 0; i < num_requests; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        add_structure(&pdu);
    }
}

void destroy_structures() {
    pthread_mutex_lock(&lock);
    num_structures = 0;
    last_request_timestamp = time(NULL);
    pthread_mutex_unlock(&lock);
}

