    for (i = 0; i < cooldownPeriod; i++) {
        attackNum = rand() % 2;
        if (attackNum == 0) {
            printf("Selected attack number: %d\n", attackNum);
        } else {
            printf("Selected attack number: %d\n", attackNum + 1);
        }
    }
}

// Function to calculate the cooldown period based on the character's current state and available resources
int calculateCooldownPeriod(uint16_t currentState, uint32_t availableResources) {
    // Declare variables
