    // Calculate the cooldown period based on the character's current state and available resources
    if (currentState == 1 && availableResources >= 50) {
        cooldownPeriod = rand() % 2 + 3; // Randomly generate a value between 3 and 4
    } else if (currentState == 2 && availableResources >= 75) {
        cooldownPeriod = rand() % 3 + 6; // Randomly generate a value between 6 and 8
    } else {
        cooldownPeriod = rand() % 4 + 10; // Randomly generate a value between 10 and 12
    }

    return cooldownPeriod;
}
