SSL_CTX* create_ssl_ctx(const char* options) {
    // Initialize the OpenSSL library
    ERR_load_crypto_strings();
    OpenSSL_add_all_algorithms();
    SSL_library_init();

    // Create an SSL/TLS context based on the given command line options
    SSL_CTX* ctx = SSL_CTX_new(TLS_method());
    if (!ctx) {
        printf("Error: unable to create SSL/TLS context\n");
        ERR_print_errors_fp(stderr);
        return NULL;
    }

