    if (strcmp(options, "--no-protocols") == 0) {
        // Disable all protocols
        SSL_CTX_set_options(ctx, SSL_OP_NO_TLSv1 | SSL_OP_NO_TLSv1_1 | SSL_OP_NO_TLSv1_2);
    } else if (strcmp(options, "--no-ciphers") == 0) {
