#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

// Define a custom memory pool for allocating LTE UE Context structures
struct MemoryPool {
    void *data;
    size_t size;
};

// Define the LTE UE Context structure
struct LTEUEContext {
    uint32_t ue_id;
    bool radio_link_status;
    float measurement_results[];
};

// Define a list of LTE UE Context structures
struct LTEUEContextList {
    struct MemoryPool pool;
    size_t size;
    struct LTEUEContext *data;
};

// Initialize the memory pool for allocating LTE UE Context structures
void init_memory_pool(struct MemoryPool *pool, size_t size) {
    pool->data = malloc(size);
    if (!pool->data) {
        fprintf(stderr, "Failed to allocate memory for memory pool\n");
        exit(EXIT_FAILURE);
    }
    pool->size = size;
}

// Allocate a new LTE UE Context structure from the custom memory pool
struct LTEUEContext *alloc_lteuecontext(struct MemoryPool *pool) {
    struct LTEUEContext *ctx = (struct LTEUEContext *)pool->data;
    size_t offset = ctx - (struct LTEUEContext *)pool->data;
    if (offset >= pool->size) {
        fprintf(stderr, "No more memory available in the memory pool\n");
        return NULL;
    }
    memset(&ctx[1], 0, sizeof(struct LTEUEContext));
    return &ctx[0];
}

// Create and populate a list of LTE UE Context structures
void create_lteuecontextlist(struct LTEUEContextList *list) {
    // Initialize the memory pool for allocating LTE UE Context structures
    init_memory_pool(&list->pool, 1024); // Use a fixed size of 1024 bytes for now
    list->size = 0;
    list->data = NULL;
}

// Add a new LTE UE Context structure to the list
void add_lteuecontext(struct LTEUEContextList *list, uint32_t ue_id, bool radio_link_status, float measurement_results[]) {
    pthread_mutex_lock(&list->pool.mutex); // Lock the mutex to ensure thread safety
    struct LTEUEContext *ctx = alloc_lteuecontext(&list->pool);
    if (ctx) {
        ctx->ue_id = ue_id;
        ctx->radio_link_status = radio_link_status;
        memcpy(ctx->measurement_results, measurement_results, sizeof(float) * 10); // Store up to 10 measurement results
        list->data[list->size++] = ctx;
    }
    pthread_mutex_unlock(&list->pool.mutex); // Unlock the mutex after adding the new LTE UE Context structure
}

// Periodically prune the list based on age to maintain efficiency
void prune_lteuecontextlist(struct LTEUEContextList *list, size_t max_age) {
    pthread_mutex_lock(&list->pool.mutex); // Lock the mutex to ensure thread safety
    struct LTEUEContext *ctx = list->data;
    for (size_t i = 0; i < list->size; i++) {
        if ((ctx - (struct LTEUEContext *)list->pool.data) > max_age) { // Prune the context based on age
            struct LTEUEContext *tmp = ctx;
            memcpy(tmp, tmp + 1, sizeof(struct LTEUEContext) * (list->size - i - 1));
            list->size--;
        } else {
            ctx++;
        }
    }
    pthread_mutex_unlock(&list->pool.mutex); // Unlock the mutex after pruning the list
}
```
This implementation uses a custom memory pool to optimize performance and reduce fragmentation by allocating memory in large chunks. The `add_lteuecontext` function locks the mutex before adding a new LTE UE Context structure to ensure thread safety when accessed by multiple threads simultaneously. The `prune_lteuecontextlist` function periodically prunes the list based on age to maintain efficiency while balancing between keeping context information relevant and minimizing unnecessary overhead.']

