int read_csv(const char* filepath, record** keys, record** offsets) {
    // Open the CSV file for reading
    FILE* fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error: Failed to open file %s\n", filepath);
        return -1;
    }

    // Read the number of entries in the CSV file
    int num_entries = 0;
    while (fscanf(fp, "%*[^,]") != EOF) {
        num_entries++;
    }
    rewind(fp);

    // Allocate memory for the arrays
    *keys = malloc(num_entries * sizeof(int));
    *offsets = malloc(num_entries * sizeof(long));
    if (*keys == NULL || *offsets == NULL) {
        printf("Error: Failed to allocate memory for arrays\n");
        fclose(fp);
        return -1;
    }

    // Initialize the arrays with random values within the given range
    srand(time(NULL));
    int min_value = 1000, max_value = 9999;
    for (int i = 0; i < num_entries; i++) {
        (*keys)[i] = rand() % (max_value - min_value + 1) + min_value;
        (*offsets)[i] = rand() % max_value;
    }

    // Read the key-value pairs from the CSV file and store them in the arrays
    while (!feof(fp)) {
        int key, value;
        fscanf(fp, "%d,%d", &key, &value);
        if (key == EOF) {
            break;
        }
        (*keys)[i] = key;
        (*offsets)[i] = value;
    }

    // Close the CSV file and return the number of entries read
    fclose(fp);
    return num_entries;
}

