        printf("Error: Failed to read input file\n");
        return -1;
    }

    // Print the contents of the arrays
    for (int i = 0; i < num_entries; i++) {
        printf("%d, %ld\n", keys[i], offsets[i]);
    }

    // Free the allocated memory for the arrays
    free(keys);
    free(offsets);
    return 0;
}
