void addToCache(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&lock);

    // Check if there is space in the cache for another entry
    if (cache->used < cache->size) {
        // Add the new entry to the end of the cache
        cache->cache[cache->used++] = pdu;

        // Update the cache size if necessary
        if (cache->used >= cache->size / 2) {
            cache->size *= 2;
        }
    } else {
        // If there is no space in the cache, remove the oldest entry first
        for (uint32_t i = 0; i < cache->size - 1; i++) {
            cache->cache[i] = cache->cache[i + 1];
        }

        // Add the new entry to the end of the cache
        cache->cache[cache->size - 1] = pdu;
    }

    pthread_mutex_unlock(&lock);
}

// Retrieve a CRC indication from the cache if possible, or fetch it from the external data source otherwise
NFAPI_CRC_INDICATION_PDU_T *getCrcIndication(RNTI rnti) {
