        NFAPI_CRC_INDICATION_PDU_T *pdu = cache->cache[i];

        if (pdu->rnti == rnti) {
            // If there is an entry in the cache, return it
            pthread_mutex_unlock(&lock);
            return pdu;
        }
    }

    // If there is no entry in the cache, fetch the CRC indication from the external data source
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fetchData(pdu);

    // Add the new entry to the cache if there is space
    addToCache(pdu);

