typedef struct {
    NFAPI_RX_UE_INFORMATION_TAG rx_ue_info;
    NFAPI_CRC_INDICATION_REL8_TAG crc_indication;
} nfapi_rx_ue_crc_data_t;

// Function to generate CRC indications for a given number of RNTIs
NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(int N) {
    // Allocate memory for the list of RX UE information and CRC indication data structures
    nfapi_rx_ue_crc_data_t *rx_ue_crc_list = (nfapi_rx_ue_crc_data_t*)malloc(N * sizeof(nfapi_rx_ue_crc_data_t));
    if (!rx_ue_crc_list) {
        printf("Error: Failed to allocate memory for RX UE CRC list\n");
        return NULL;
    }

    // Generate random numbers for the RNTIs and CRC flags
    srand(time(NULL));
    int i;
    for (i = 0; i < N; ++i) {
        rx_ue_crc_list[i].rx_ue_info.rnti = rand();
        rx_ue_crc_list[i].crc_indication.crcFlag = (rand() & 0x1);
    }

    // Ensure that each RNTI is unique within the list
    for (i = 0; i < N - 1; ++i) {
        int j;
        for (j = i + 1; j < N; ++j) {
            if (rx_ue_crc_list[i].rx_ue_info.rnti == rx_ue_crc_list[j].rx_ue_info.rnti) {
                printf("Error: Duplicate RNTI detected in CRC indications\n");
                free(rx_ue_crc_list);
                return NULL;
            }
        }
    }

    // Return a pointer to the allocated list of RX UE information and CRC indication data structures
    return rx_ue_crc_list;
}
